BEGIN;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"f4589963-bf40-4340-99af-b6a0d10a2805": {"definition": "The process of readying music files before a set: analyzing tempo and beatgrids, setting cue and loop points, checking key, tagging metadata, and organizing tracks into crates or playlists within DJ software such as rekordbox or Serato DJ.", "plain_english": "Getting your songs ready before you play. You scan each track, mark good start points, and sort it into folders so it loads fast.", "purpose_function": "It ensures tracks load with accurate beatgrids, cue points, and tags so the DJ can find and mix music quickly and reliably during a live performance.", "practical_application": "Before a gig a DJ imports new tracks, runs software analysis, sets hot cues at the intro, breakdown, and drop, corrects any misaligned beatgrids, and files tracks by genre, energy, or key.", "category": "Track Preparation", "related_terms": ["Beatgrid", "Hot cue", "Memory cue", "BPM analysis", "Cue point", "Crate"], "common_mistakes": ["Trusting automatic beatgrid analysis without checking it, leaving grids misaligned on tracks with live or shifting tempo", "Not setting cue points in advance, forcing slow searching during a live set", "Skipping key or BPM tagging, which makes harmonic and tempo-matched selection harder", "Leaving the library disorganized so tracks are hard to find under pressure"], "scenario_contexts": ["Analyzing and beatgridding a batch of newly bought tracks in rekordbox the night before a club gig", "Setting hot cues at the intro, breakdown, and drop of each track for fast mixing", "Exporting a prepared library to a USB drive for a Pioneer CDJ setup", "Organizing tracks into energy-based playlists for a festival set"]}, "f222a253-23ba-49e1-8e77-6ed89a13ce2e": {"definition": "A DJ who uses turntables and a mixer as musical instruments to manipulate recorded sound through scratching, beat juggling, cutting, and related hand techniques, rather than simply playing records in sequence; the practice is called turntablism.", "plain_english": "A DJ who plays the turntable like an instrument. They scratch and juggle records by hand to make new rhythms and sounds, not just play songs.", "purpose_function": "Turntablism treats the turntable and mixer as a performance instrument, letting the DJ create original rhythms, sounds, and musical phrases from existing records.", "practical_application": "A turntablist performs or battles using two turntables, a scratch mixer, and often scratch records or a digital vinyl system, executing techniques like scratching, beat juggling, and crossfader cutting.", "category": "Performance Roles", "related_terms": ["Scratching", "Beat juggling", "Crossfader", "Cutting", "Backspin", "Scratch mixer"], "common_mistakes": ["Confusing a turntablist with any DJ; turntablism specifically means manipulating sound by hand as an instrument", "Thinking scratching is the only turntablist skill, ignoring beat juggling and cutting", "Assuming turntablism requires vinyl only, when digital vinyl systems with control records are also used"], "scenario_contexts": ["Competing in a DMC or Red Bull 3Style battle using scratches and beat juggles", "Performing a live scratch routine over a backing beat", "Using a digital vinyl system with control vinyl to scratch digital files", "Building a routine that combines cutting and crossfader techniques"]}, "39a1d81e-c83d-4b8d-b380-3e192a013c2a": {"definition": "A recurring section of a song's structure that carries the main lyrical and narrative content, typically alternating with the chorus; successive verses usually share the same melody but set different lyrics.", "plain_english": "The part of a song that tells the story. Verses often use the same tune but change the words each time, then lead into the chorus.", "purpose_function": "The verse develops a song's lyrics and builds toward the chorus; for a DJ, recognizing verses helps time transitions and effects to the track's structure.", "practical_application": "A DJ identifies verses when phrasing a mix, cueing transitions or effects to section boundaries so the two tracks align musically and vocals do not clash.", "category": "Track Structure", "related_terms": ["Chorus", "Phrase", "Intro", "Outro", "Breakdown", "Bar"], "common_mistakes": ["Confusing the verse with the chorus; the chorus repeats the same lyric hook while verses change lyrics", "Ignoring song structure and mixing out mid-verse, causing a clash of vocals or phrases", "Assuming every track follows a strict verse-chorus form when many electronic tracks do not"], "scenario_contexts": ["Phrasing a transition so the incoming track's verse lines up with the outgoing track's structure", "Dropping a filter sweep or effect at the end of a verse before the chorus", "Analyzing a track's arrangement to plan where to bring in the next song", "Teaching a beginner to count bars within a verse for on-phrase mixing"]}, "9cbbea50-e9e6-4ee7-be57-53755792d4c0": {"definition": "A DJ who plays the opening portion of an event, before the headline or peak-time act, whose role is to gradually build energy and prepare the crowd rather than play the biggest tracks; also called an opening DJ.", "plain_english": "The DJ who plays first at an event. Their job is to slowly build the mood and warm up the crowd. They save the biggest songs for later.", "purpose_function": "The warm-up DJ sets the atmosphere and gradually raises energy so the crowd is ready for the headliner, keeping tempo and intensity below peak-time levels.", "practical_application": "An opening DJ reads the early crowd, starts with lower-energy or slower tracks, and builds tempo and intensity across the set without peaking too soon or upstaging the headliner.", "category": "Performance Roles", "related_terms": ["Peak time", "Headliner", "Set construction", "Track selection", "Reading the crowd", "Open-format DJ"], "common_mistakes": ["Playing peak-time anthems too early, leaving nowhere for the headliner to build", "Starting at full tempo and energy instead of gradually rising", "Treating the warm-up slot as unimportant rather than shaping the whole night's arc", "Ignoring the promoter's or venue's brief for the opening sound"], "scenario_contexts": ["Opening a club night before the headline DJ, starting with slower, deeper tracks", "Building energy across a two-hour early set at a festival stage", "Being briefed by a promoter to keep the BPM and intensity down until the main act", "Reading a sparse early crowd and choosing accessible, mood-setting music"]}, "5bb410b0-54ff-4ca9-ac0f-ef5c5327e525": {"definition": "A white label is a vinyl record, usually a 12-inch single, pressed with a plain, unprinted (typically white) centre label that carries little or no printed information. The format is used for promotional advance or pre-release copies serviced to DJs and radio, for pressing-plant test pressings, and for anonymous or pseudonymous unofficial and bootleg releases, where the blank label deliberately withholds artist and title details.", "plain_english": "A white label is a record with a plain, blank centre label and no printed name or title. Record labels send them to DJs early to test new tracks. Some are also secret or unofficial releases that hide who made them.", "purpose_function": "It lets a track circulate as an early promo, a factory test copy, or an anonymous release before or without full commercial packaging and artist identification.", "practical_application": "A DJ receives white labels as advance promos to road-test unreleased tracks in club sets, and often identifies them by matrix or runout codes, hand-stamps, or by ear because the label prints no title.", "category": "Record Collecting", "related_terms": ["Dubplate", "Test pressing", "Acetate", "Bootleg", "Digging"], "common_mistakes": ["Assuming every plain white-label record is a rare bootleg, when many are ordinary promotional or test copies", "Thinking a white label always means an unofficial or illegal release, when most are legitimate label promos", "Believing a blank label means the music is unfinished or unreleased, when white labels also carry finished, licensed tracks"], "scenario_contexts": ["A DJ is serviced a pre-release white-label 12-inch to test an unreleased track on the dancefloor before its official release date", "A collector identifies a white label by its runout or matrix codes or hand-stamp because the centre label prints no title or artist", "A pressing plant supplies a white-label test pressing so the label can check audio quality before authorising the full run"]}, "26c06dcf-7806-4dad-bc63-057073ded6c1": {"definition": "In event and touring production, an access requirement is any condition that must be met for personnel, vehicles, or equipment to enter and move through a venue, including loading-dock dimensions and hours, vehicle parking, security credentials or passes, key or escort access, and a clear path of travel from the dock to the stage. Access requirements are identified and confirmed during the advance.", "plain_english": "An access requirement is what you need to get into and around a venue. It can mean dock times, parking, passes, or a clear route to the stage. The crew checks these before the show. That way nothing blocks the load-in.", "purpose_function": "It defines how crew, vehicles, and gear physically reach the stage, so load-in runs smoothly and nobody is stopped by locked doors, missing passes, or a blocked route.", "practical_application": "During the advance a tour or production manager confirms dock height, truck parking, security passes, and the route from dock to stage, then briefs the crew on the site's access requirements.", "category": "Production Workflow", "related_terms": ["Advance", "Advancing the show", "Load-in", "Credential", "Path of travel"], "common_mistakes": ["Assuming every venue has a loading dock, when some sites need a long carry or a lift instead", "Forgetting to arrange passes ahead of time, so crew are turned away at the door", "Overlooking truck parking and route restrictions, which causes delays at load-in"], "scenario_contexts": ["Confirming loading-dock height and hours before a truck arrives", "Arranging security credentials so crew can reach restricted backstage areas", "Checking a clear path of travel from dock to stage for heavy cases"]}, "b331b543-0832-421b-a3c8-8acffecc772a": {"definition": "An act change (changeover) is the transition between consecutive performers on a shared bill, during which the stage crew strike the outgoing act's backline, microphones, and monitors and then set, patch, and line-check the incoming act's equipment, usually within a fixed time window. On festivals and multi-act shows it is scheduled to keep the programme running to time.", "plain_english": "An act change is the switch between one band and the next on the same stage. The crew clear the first act's gear and set up the next. They work fast to a set time so the show stays on schedule.", "purpose_function": "It resets the stage for the next performer's needs, such as backline, mics, and monitor mixes, in a controlled and timed sequence so a multi-act show flows without long gaps.", "practical_application": "During an act change the crew roll risers on and off, swap backline, repatch inputs, and run a quick line check before the next act starts, often against a tight festival clock.", "category": "Stage Operations", "related_terms": ["Changeover", "Line check", "Backline", "Riser", "Stage plot"], "common_mistakes": ["Underestimating how long a changeover takes, so the running schedule slips", "Failing to label or pre-set inputs, which makes the line check slow and error-prone", "UNSAFE: Rushing to move heavy backline or risers with too few crew or poor lifting technique, risking back injury or dropped loads"], "scenario_contexts": ["A festival crew performing a 15-minute act change between bands", "Rolling a pre-set drum riser on during a changeover to save time", "Repatching the stage box and line-checking inputs for the incoming act"]}, "f8129c0d-5da4-4ac1-8cfa-ece29612e030": {"definition": "An active direct box (active DI) is a direct-injection interface that uses powered, active circuitry, supplied by phantom power, an internal battery, or an external supply, to convert a high-impedance, unbalanced instrument-level signal into a low-impedance, balanced, mic-level signal for a mixing console input. Its active input stage presents a very high input impedance suited to piezo and passive magnetic pickups, avoiding the loading and high-frequency loss a passive transformer DI can introduce.", "plain_english": "An active direct box connects an instrument like a bass or keyboard to a mixer. It runs on power, such as phantom power or a battery. This lets it send a clean, strong signal down a long cable without losing tone.", "purpose_function": "It matches an instrument's output to a console's microphone input, converting an unbalanced high-impedance signal to a balanced low-impedance one so it travels long cable runs without noise or level loss. Its powered circuit gives a high input impedance that preserves the tone of passive pickups.", "practical_application": "A stage tech plugs a bass guitar or keyboard into an active DI, feeds it phantom power from the console or a battery, and sends the balanced output over a mic line to front-of-house.", "category": "Signal Interface", "related_terms": ["Passive direct box", "Phantom power", "Balanced signal", "Impedance", "Stage box"], "common_mistakes": ["Assuming an active DI always sounds better than a passive DI, when the best choice depends on the source; passive DIs handle very hot signals without clipping", "Forgetting that an active DI needs power, then getting no signal because phantom power is off or the battery is dead", "Confusing the ground-lift switch, which lifts the signal ground to reduce hum, with a mains earth connection"], "scenario_contexts": ["Plugging an active bass with an onboard preamp into a DI at a front-of-house input", "Running a keyboard's output through an active DI to reach the stage box over a long multicore", "Choosing an active DI for a passive piezo acoustic-guitar pickup to keep high frequencies bright"]}, "a060bfd2-87d3-46e7-ad26-d4a544eb4dc6": {"definition": "In touring and event production, the advance is the pre-production process of exchanging and confirming all logistical and technical information between the touring party and the venue or promoter before the show date, covering the schedule, stage and power specifications, rigging, backline, catering, crew calls, and access details. The word also refers collectively to that gathered and agreed information.", "plain_english": "The advance is all the planning done before a show reaches town. The tour and the venue swap details ahead of time. They agree on the schedule, gear, power, and how the crew gets in. This avoids surprises on show day.", "purpose_function": "It exists to prevent day-of problems by confirming every logistical and technical detail beforehand, so the venue is ready and the crew's needs are met when the trucks arrive.", "practical_application": "A tour or production manager phones and emails the venue days or weeks ahead to lock down load-in times, power, rigging points, and hospitality, recording it all on an advance sheet.", "category": "Production Workflow", "related_terms": ["Advancing the show", "Access requirement", "Technical rider", "Load-in", "Production manager"], "common_mistakes": ["Thinking the advance is just confirming the date, when it covers power, rigging, schedule, backline, and access in detail", "Leaving the advance too late, so the venue cannot meet a technical or rigging requirement in time", "Failing to write the agreed details down, which leads to disputes on show day"], "scenario_contexts": ["A production manager advancing power and rigging capacity with a venue before a tour arrives", "Confirming load-in and soundcheck times during the advance", "Discovering during the advance that a venue lacks the amperage a rig needs, so a generator is arranged"]}, "479b4aa4-258b-4777-8321-ec28f45ff1bf": {"definition": "Advancing the show is the practice of contacting the venue, promoter, or local crew before the performance to confirm and coordinate every technical and logistical detail of the engagement, such as load-in and soundcheck times, stage dimensions, power and rigging provisions, backline, local crew calls, and site access, so both parties arrive prepared.", "plain_english": "Advancing the show means sorting out the details before you get to the venue. You call or email ahead and check the schedule, gear, power, and access. Then everyone is ready when show day comes.", "purpose_function": "It ensures the touring crew and the venue share the same plan, so equipment, power, staffing, and timing all line up before the trucks arrive, reducing costly day-of surprises.", "practical_application": "A production or tour manager works through an advance checklist with the venue days ahead, confirming times, power, rigging, and hospitality, then shares the final schedule with the crew.", "category": "Production Workflow", "related_terms": ["Advance", "Access requirement", "Technical rider", "Load-in", "Production manager"], "common_mistakes": ["Believing advancing only means confirming the date and set time, when it covers technical and logistical details too", "Advancing too close to the show, leaving no time to fix a shortfall in power or rigging", "Not passing the advance details on to the crew who actually need them"], "scenario_contexts": ["A tour manager advancing a run of dates so each venue knows the crew size and load-in time", "Advancing a festival slot to confirm changeover time and shared backline", "Catching a power shortfall while advancing, so a distro or generator is booked ahead"]}, "c62da3ab-6c4c-446a-82f9-5be54dd52446": {"definition": "In equipment specifications and bid documents, an 'approved equal' is a substitute product, not the specific make or model named, that the specifying engineer or consultant has reviewed and accepted as meeting the stated performance, quality, and feature requirements. The qualifying phrase 'or approved equal' in a specification permits such a substitution only with the specifier's prior approval.", "plain_english": "'Approved equal' means a different brand or model allowed in place of the one listed. It must be checked and okayed as just as good. This lets a crew or installer swap in gear that meets the same requirements.", "purpose_function": "It gives a specification flexibility, letting a suitable alternative be used when the exact named product is unavailable or costlier, while protecting quality by requiring the specifier's approval first.", "practical_application": "When a named console or speaker cannot be sourced, an integrator proposes an alternative and obtains the consultant's written approval that it qualifies as an approved equal before ordering.", "category": "Specifications", "related_terms": ["Technical rider", "Specification", "Substitution", "Bid document", "System integration"], "common_mistakes": ["Assuming any similar product counts as an approved equal, when it must be reviewed and accepted by the specifier first", "Substituting gear without written approval, then facing rejection during commissioning", "Treating 'or equal' as permission to use the cheapest option regardless of the stated performance requirements"], "scenario_contexts": ["An installer proposing a substitute amplifier as an approved equal on a construction bid", "A consultant reviewing a requested substitution against the specification's performance requirements", "Sourcing an approved-equal loudspeaker when the specified model has a long lead time"]}, "ce26cc03-abdb-40fe-a8d2-1a9d475d3bc4": {"definition": "An array technician (array tech, sometimes called a PA tech) is the crew member responsible for assembling, flying or stacking, and maintaining a loudspeaker array, typically a line array, including building the frame and enclosures, setting inter-cabinet splay angles from the manufacturer's rigging data, connecting amplification and network cabling, and verifying the system before the audio crew tunes it. When arrays are flown, the role works under the rigging crew and applicable rigging standards.", "plain_english": "An array technician builds and looks after the main speaker arrays. They assemble the cabinets, set the angles, and hook up the power and cabling. When the speakers hang overhead, they work with the rigging crew to do it safely.", "purpose_function": "The role puts one skilled person in charge of building the loudspeaker array correctly and safely, so the system hangs at the right angles and coverage and works reliably before it is tuned.", "practical_application": "An array tech assembles each line-array hang on the ground, sets splay angles from the manufacturer's prediction software, oversees the motors lifting it, and checks every cabinet and amplifier channel.", "category": "Crew Role", "related_terms": ["Line array", "Rigging", "Splay angle", "System engineer", "Amplifier", "Motor (chain hoist)"], "common_mistakes": ["Confusing the array tech with the system engineer; the array tech builds and rigs the boxes while the system engineer tunes the sound", "UNSAFE: Flying an array without following the manufacturer's rigging limits and a competent rigger's inspection; flown loudspeakers are overhead rigging governed by ANSI/ESTA and manufacturer standards, and ignoring them risks a dropped load", "Setting splay angles by guesswork instead of the manufacturer's prediction data, which ruins coverage"], "scenario_contexts": ["Assembling and flying main line-array hangs during load-in", "Setting inter-cabinet angles from manufacturer software before the array is lifted", "Coordinating with riggers and motor operators to raise an array to trim height"]}, "925a6e57-76de-4619-ad30-1e0a6959da2a": {"definition": "An assistant recording engineer (also called a second engineer) is the junior member of a recording session's technical team who supports the lead recording engineer. Typical duties include setting up and patching microphones, cables and outboard gear, documenting takes and session paperwork, managing recording media and track sheets, and maintaining signal flow so the lead engineer and producer can focus on capturing the performance.", "plain_english": "An assistant recording engineer is the helper for the main studio engineer. They set up microphones and cables and keep notes on each take. This lets the lead engineer focus on the recording.", "purpose_function": "The role exists to keep a session running smoothly by handling setup, patching and documentation, so the lead engineer and producer can concentrate on sound and performance. It is also the usual training path toward becoming a lead engineer.", "practical_application": "During a session an assistant sets up and line-checks the microphones, labels tracks, logs takes and file names, and troubleshoots signal problems as they arise.", "category": "Studio role", "related_terms": ["Recording engineer", "Tracking session", "Patchbay", "Signal flow", "Track sheet", "Producer"], "common_mistakes": ["Thinking the assistant only runs errands; in practice they handle critical microphone setup, patching and session documentation.", "Failing to keep accurate take and track-sheet notes, which makes it hard to find the right take during mixing.", "Not line-checking every input before the session, so faults appear during a take instead of before it."], "scenario_contexts": ["Setting up and patching a drum kit's microphones before a tracking session.", "Logging take numbers and comments as a band records multiple passes.", "Managing session files and backups so nothing recorded is lost."]}, "65945d77-91b1-48ea-b8a3-805b3fa85b07": {"definition": "An audio advance is the pre-show process in which a touring or production audio team confirms the technical details of an upcoming date with the venue or promoter ahead of time. It typically covers the available PA and console, power and patch, input list and stage plot, monitor requirements, load-in times and local crew, so any gaps between the tour's needs and the venue's provision are resolved before show day.", "plain_english": "An audio advance is a check-in with the venue before show day. The sound team confirms what gear, power, and stage details will be ready. Sorting this out early avoids surprises when the crew arrives.", "purpose_function": "It exists to match the tour's audio requirements to what a venue actually provides, so problems are solved on paper rather than during a rushed load-in. This protects both the schedule and the show.", "practical_application": "A monitor or systems engineer contacts the venue days ahead to confirm the console, PA, patch, power and load-in time, and sends the input list and stage plot.", "category": "Production workflow", "related_terms": ["Advance", "Input list", "Stage plot", "Technical rider", "Load-in", "Patch list"], "common_mistakes": ["Assuming the venue's PA and console match the rider without confirming, then discovering gaps on show day.", "Advancing only the front-of-house gear and forgetting monitors, power, or local crew needs.", "Not sending an updated input list and stage plot, so the local crew pre-patches incorrectly."], "scenario_contexts": ["Confirming the house console and PA model before a one-off festival date.", "Arranging power and patch details with a venue a week before load-in.", "Checking how many local audio hands will be available for load-in."]}, "23cc8c60-69a2-458a-b009-eca59cb16d89": {"definition": "The audio crew is the group of technicians responsible for the sound system on a production or tour, including front-of-house and monitor engineers, systems (PA) technicians, RF and playback techs, and audio hands. They set up, operate, maintain and strike all audio equipment for the show.", "plain_english": "The audio crew is the team in charge of sound at a show. It includes the mixing engineers and the techs who rig speakers and run cables. Together they build, run, and pack down the sound system.", "purpose_function": "The audio crew exists to deliver reliable, high-quality sound for every performance, from load-in through the show to strike. Splitting the work across specialised roles keeps a large system manageable.", "practical_application": "On a show day the audio crew loads in the PA, flies and tunes the system, sets up consoles and monitors, runs the show, then strikes and loads out.", "category": "Crew structure", "related_terms": ["Audio crew chief", "Front-of-house engineer", "Monitor engineer", "Systems engineer", "Audio hand", "Audio department"], "common_mistakes": ["Confusing the touring audio crew with the local (house) crew; the tour carries its own specialists while the venue supplies local labour.", "Assuming everyone on the audio crew mixes; most handle rigging, cabling, RF, or system setup instead."], "scenario_contexts": ["A touring audio crew arriving to fly the PA and set up consoles for a concert.", "The audio crew coordinating with riggers and the local crew during load-in.", "Dividing front-of-house, monitor, and systems duties among the audio crew for a festival set."]}, "23c4a611-5ed7-4503-b299-12a363388ffd": {"definition": "The audio crew chief is the lead of the audio crew who directs and coordinates the department's technicians during load-in, setup, show and strike. They assign tasks, manage local crew and the schedule for audio, liaise with the production manager and other department heads, and take responsibility for the audio system being ready and safe on time.", "plain_english": "The audio crew chief is the boss of the sound team on site. They hand out jobs and keep the sound crew on schedule. Their goal is a working sound system that is ready and safe on time.", "purpose_function": "The role exists to give the audio department a single point of leadership and accountability, so work is organised and coordinated with other departments. It keeps a busy load-in running to schedule.", "practical_application": "At load-in the crew chief directs where the PA and cables go, assigns local hands to tasks, and reports audio's progress to the production manager.", "category": "Crew role", "related_terms": ["Audio crew", "Audio department head", "Production manager", "Systems engineer", "Local crew", "Load-in"], "common_mistakes": ["Confusing the crew chief with the front-of-house engineer; the chief leads setup and the crew, while the front-of-house engineer mixes the show.", "Thinking the crew chief does the physical work alone rather than directing and coordinating the crew."], "scenario_contexts": ["Directing the order of PA rigging and cable runs during a fast load-in.", "Assigning local audio hands to help set up monitors and coil cable at strike.", "Coordinating audio's power and rigging needs with the production manager."]}, "288acd3d-a649-46a1-84d7-c872c09379a8": {"definition": "The audio department is the organisational unit on a production or tour that covers everything to do with sound, including its personnel, equipment and budget. It sits alongside other departments such as lighting, video, staging and rigging under the production manager.", "plain_english": "The audio department is the sound section of a production. It covers the people, gear, and budget for sound. It works next to other teams like lighting and video.", "purpose_function": "Organising a show into departments lets each area, including audio, be planned, budgeted and staffed on its own, then coordinated by the production manager. This keeps a complex production manageable.", "practical_application": "A production manager deals with the audio department as one unit when planning power, space, budget and schedule for a show.", "category": "Crew structure", "related_terms": ["Audio department head", "Audio crew", "Lighting department", "Production manager", "Technical rider", "Load-in"], "common_mistakes": ["Confusing the audio department (the whole sound area) with the audio crew (the people working it on a given day).", "Forgetting that the audio department includes budget and planning, not just show-day gear and staff."], "scenario_contexts": ["Allocating stage power and space to the audio department during production planning.", "The audio department submitting its equipment and crew needs in the technical rider.", "Coordinating audio, lighting and video departments at a production meeting."]}, "9b0c3f1a-5053-42ee-9979-53d97555a852": {"definition": "The audio department head is the person with overall responsibility for the audio department on a production or tour, covering its staffing, equipment, budget and technical decisions. They plan the audio system, hire or assign crew, and represent audio to the production manager and other department heads.", "plain_english": "The audio department head is in charge of everything about sound on a show. They plan the gear, pick the crew, and manage the sound budget. They speak for the sound team in planning meetings.", "purpose_function": "The role exists to give the audio department clear leadership and accountability for planning, budget and technical choices. It ensures audio's needs are represented in overall production planning.", "practical_application": "A department head specifies the PA and console package, builds the audio crew and budget, and negotiates power, space and schedule with the production manager.", "category": "Crew role", "related_terms": ["Audio department", "Audio crew chief", "Production manager", "Technical rider", "Systems engineer", "Front-of-house engineer"], "common_mistakes": ["Confusing the department head (overall planning and budget) with the crew chief (on-site, day-to-day crew leadership).", "Assuming the department head always mixes the show; larger productions separate planning from mixing duties."], "scenario_contexts": ["Choosing the PA system and console package for a tour.", "Setting the audio budget and hiring the touring audio crew.", "Negotiating stage power and rigging points with the production manager."]}, "2bd7a231-efc7-43d8-825f-f920d5882015": {"definition": "An audio hand is a crew member who provides general labour and assistance for the audio department, typically during load-in, setup and strike, rather than operating the mix. Duties include carrying and placing cases, running and coiling cable, assembling and rigging PA components, and helping the engineers as directed.", "plain_english": "An audio hand is a helper on the sound crew. They carry gear, run and coil cables, and help set up the speaker system. They do the hands-on work rather than mixing the show.", "purpose_function": "The role exists to supply the extra people and muscle a sound system needs during the heavy work of load-in and strike. It frees the engineers to focus on setup and tuning.", "practical_application": "At load-in an audio hand helps move cases, build PA stacks and run cable, then coils and packs everything at strike.", "category": "Crew role", "related_terms": ["Audio crew", "Audio crew chief", "Stagehand", "Local crew", "Load-in", "Audio strike"], "common_mistakes": ["Assuming an audio hand mixes or operates gear; the role is general labour and assistance, not running the show.", "UNSAFE: Lifting heavy cases or amp racks alone instead of using team lifts, correct lifting technique or mechanical aids, which risks back and crush injuries.", "UNSAFE: Leaving cable runs uncovered or untaped across walkways, creating trip hazards for crew and performers."], "scenario_contexts": ["Helping move cases and build PA stacks during a concert load-in.", "Running and coiling cable across the stage under the crew chief's direction.", "Providing extra labour to the audio crew during a fast strike."]}, "3cbe2cd2-1b6e-4d94-8efc-3244d7137a8c": {"definition": "An audio strike is the teardown of the audio system at the end of an event, in which the audio crew powers down, disconnects, dismantles, coils and packs all audio equipment for load-out. It is the audio department's part of the overall production strike that returns the venue to its original state.", "plain_english": "An audio strike is packing down the sound system after a show. The crew powers off the gear, unplugs and coils the cables, and packs the speakers and mixers. It is the sound team's part of tearing the whole show down.", "purpose_function": "The strike exists to remove and pack the audio system safely and quickly, so it can be loaded out and moved to the next date or returned. Working in the right order protects both the gear and the schedule.", "practical_application": "After the show the audio crew powers down amplifiers and consoles, coils and labels cables, breaks down the PA, and packs everything into cases for load-out.", "category": "Production workflow", "related_terms": ["Strike", "Load-out", "Audio crew", "Audio hand", "Load-in", "Road case"], "common_mistakes": ["Starting to strike before amplifiers and the system are fully powered down, risking loud transients through the PA and gear damage.", "Coiling and packing cables carelessly, causing damage and slow, tangled setup at the next show.", "UNSAFE: Beginning to lower or dismantle flown PA and truss before the rigging is secured and controlled, and without fall protection for overhead work, which risks dropped loads and falls."], "scenario_contexts": ["Powering down and packing consoles and amplifiers immediately after a concert.", "Coiling and casing cable while local hands break down monitors at strike.", "Lowering a flown PA under rigger control before loading out."]}, "cfc84c1b-69b7-4b0d-a9e3-651846603129": {"definition": "The senior member of the sound crew who oversees the audio department for a production or tour, coordinating engineers and technicians, equipment, and workflow so the sound system is installed, operated, and maintained correctly. The role carries responsibility for planning, crew supervision, and liaison with the production and other departments.", "plain_english": "The audio supervisor is the boss of the sound crew. They plan the setup and guide the other sound workers. They make sure the whole sound system is built and run correctly.", "purpose_function": "It gives the sound department a single point of leadership, so audio work is planned, staffed, and delivered to the production's standard.", "practical_application": "On a large show a technician reports to the audio supervisor, who assigns tasks, checks the rig, and resolves problems between departments.", "category": "Crew Role", "related_terms": ["Audio technician", "Band engineer", "Backline tech", "Front of house engineer", "Monitor engineer"], "common_mistakes": ["Confusing the audio supervisor, who leads the department, with the engineer who operates the console", "Assuming the supervisor mixes every show, when much of the role is planning and crew management", "Thinking the title means the same thing on every production, when duties vary by show size and sector"], "scenario_contexts": ["Leading the sound crew on a large touring production", "Coordinating audio setup and crew across a multi-day festival", "Liaising with the production manager over power, timing, and stage layout"]}, "056f2220-30d4-4329-b131-2ee2e6767d17": {"definition": "A crew member who sets up, connects, tests, operates, and maintains audio equipment such as microphones, cabling, mixing consoles, signal processing, and loudspeaker systems for a production. The technician generally works under a supervisor or engineer and handles the hands-on rigging, patching, and troubleshooting of the sound system.", "plain_english": "An audio technician sets up and looks after the sound gear. They run cables, place mics, and test the system. They also fix faults so the show sounds right.", "purpose_function": "It provides the skilled hands-on labour that turns a sound design into a working, reliable system on site.", "practical_application": "A technician loads in, patches the stage, rings out microphones, and troubleshoots faults during setup and the show.", "category": "Crew Role", "related_terms": ["Audio supervisor", "Backline tech", "Band engineer", "Front of house engineer", "Line check"], "common_mistakes": ["Confusing an audio technician with the audio supervisor who leads the crew", "UNSAFE: Working close to a live PA at high sound levels without hearing protection, ignoring occupational noise exposure limits", "Assuming the technician only mixes, when most of the job is setup, patching, and maintenance"], "scenario_contexts": ["Patching the stage and testing microphones during load-in", "Troubleshooting a dead channel during soundcheck", "Coiling and storing cables and equipment during load-out"]}, "4a32bca0-6a8c-4f1b-9e11-a5aa73248076": {"definition": "The changeover of backline equipment on stage between acts, in which one act's instruments and amplifiers are struck and the next act's backline is set in position, connected, and line-checked. It is a scheduled part of a multi-act show's turnaround.", "plain_english": "A backline change is swapping one band's gear for the next band's gear. The crew clear the first band's amps and drums. Then they set up and test the next band's equipment.", "purpose_function": "It resets the stage for the next act quickly and correctly, so each band plays on its own instruments and amps with minimal delay.", "practical_application": "Between sets at a festival, the crew rolls off one drum riser, rolls on the next, repatches the backline, and line-checks before the next act.", "category": "Stage Operations", "related_terms": ["Backline", "Backline tech", "Backline riser", "Changeover", "Line check"], "common_mistakes": ["Confusing a backline change, which swaps instruments and amps, with a full PA or console changeover", "Underestimating the time a backline change needs, which delays the show", "Failing to line-check the new backline before the act starts"], "scenario_contexts": ["Swapping backline between the support act and the headline act", "Rolling risers on and off to speed a festival changeover", "Resetting amps and drums during a multi-band club night"]}, "118c0838-393c-4a5d-b705-ed1cbcc5b7a2": {"definition": "A raised platform placed on stage to elevate a section of backline equipment, most commonly a drum kit (a drum riser) or keyboards, so it is visible to the audience and can be pre-set and moved as a unit. Such risers are often wheeled or modular to speed changeovers.", "plain_english": "A backline riser is a low stage platform for a band's gear. It lifts the drums or keyboards up so the crowd can see them. It can often roll on and off to save time.", "purpose_function": "It raises and groups backline so it is visible, and lets crew pre-set and move a whole section quickly during changeovers.", "practical_application": "A drum kit is built on a wheeled riser offstage, then rolled into place during the changeover and cabled up.", "category": "Staging", "related_terms": ["Backline", "Drum riser", "Backline change", "Backline tech", "Riser"], "common_mistakes": ["UNSAFE: Exceeding the riser's rated load capacity, or using it before checking it is stable, level, and locked", "Confusing a backline riser for instruments with a general staging or seating riser", "Forgetting to lock or chock the wheels, so a rolling riser moves during use"], "scenario_contexts": ["Pre-building a drum kit on a rolling riser for a fast changeover", "Raising keyboards on a riser to improve stage sightlines", "Rolling a backline riser into position during a festival set change"]}, "d5b11d5c-7df0-488d-bb90-91c12abd15a3": {"definition": "A crew member responsible for the setup, tuning, maintenance, and stage-side support of a band's backline, meaning the instruments and amplifiers such as guitar and bass rigs, drums, and keyboards. The role covers preparing gear before the show, handling instrument changes and faults during the performance, and striking the backline afterward, and is often specialised as a guitar, bass, or drum tech.", "plain_english": "A backline tech looks after a band's own instruments and amps. They tune guitars, set up the drums, and fix gear fast during the show. Big acts have separate guitar, bass, and drum techs.", "purpose_function": "It keeps the band's instruments and amps ready and working, so musicians can play without dealing with setup or technical faults.", "practical_application": "A guitar tech restrings and tunes spares, hands the player a fresh guitar between songs, and swaps a failed amp during the set.", "category": "Crew Role", "related_terms": ["Backline", "Backline technician", "Backline change", "Backline riser", "Drum tech"], "common_mistakes": ["Confusing a backline tech, who handles instruments and amps, with the audio technician who handles the PA and console", "Assuming one tech covers every instrument, when large tours use separate guitar, bass, and drum techs", "Forgetting to prepare and check spare instruments and strings before the show"], "scenario_contexts": ["Tuning and handing off guitars during a live set", "Setting up and line-checking a drum kit before soundcheck", "Swapping a failed amplifier quickly during a performance"]}, "d6edbb04-aea4-4188-9096-ff8c50198454": {"definition": "The full title for the crew member responsible for the setup, tuning, maintenance, and stage-side support of a band's backline, meaning its instruments and amplifiers such as guitar and bass rigs, drums, and keyboards. The role covers preparing gear before the show, handling instrument changes and faults during the performance, and striking the backline afterward, and is often specialised as a guitar, bass, or drum technician.", "plain_english": "A backline technician looks after a band's own instruments and amps. They tune guitars, set up drums, and fix gear fast during the show. It is the full name for a backline tech.", "purpose_function": "It keeps the band's instruments and amps ready and working, so musicians can perform without handling setup or technical faults themselves.", "practical_application": "A backline technician preps and tunes instruments, sets amp settings, and swaps failed gear quickly so the act keeps playing.", "category": "Crew Role", "related_terms": ["Backline", "Backline tech", "Backline change", "Backline riser", "Guitar tech"], "common_mistakes": ["Confusing a backline technician, who handles instruments and amps, with the audio technician who handles the PA and console", "Assuming one technician covers every instrument, when large tours use separate guitar, bass, and drum techs", "Forgetting to prepare and check spare instruments and strings before the show"], "scenario_contexts": ["Preparing and tuning a band's instruments before doors", "Handing a musician a spare instrument during the set", "Diagnosing and swapping a faulty amplifier mid-show"]}, "f7b41693-1c39-434e-b04a-8b639dce5d07": {"definition": "A sound engineer employed by or touring with a specific act rather than the venue, responsible for mixing that act's sound, typically at front of house or monitors, and for knowing the band's show and preferences. The band engineer works with each venue's house crew and system across the tour.", "plain_english": "A band engineer travels with one band and mixes their sound. They know the band's songs and settings well. At each venue they work with the local house crew.", "purpose_function": "It gives the act a consistent mix and a familiar operator from show to show, independent of which venue or house engineer is present.", "practical_application": "The band engineer arrives with the tour, loads the show file onto the venue console, soundchecks the act, and mixes their set each night.", "category": "Crew Role", "related_terms": ["House engineer", "Front of house engineer", "Monitor engineer", "Audio supervisor", "Backline tech"], "common_mistakes": ["Confusing the band engineer, who travels with the act, with the house engineer, who works for the venue", "Assuming the band engineer knows every venue's system, when they must adapt to each house rig", "Thinking every act brings its own engineer, when smaller acts often rely on the house engineer"], "scenario_contexts": ["Mixing front of house for a touring act at a different venue each night", "Loading a saved show file onto a venue's console before soundcheck", "Coordinating with the house engineer over the PA and stage patch"]}, "952fa29b-f511-4815-97f9-223dd664ef6b": {"definition": "A person who creates programmed drum, percussion, and other rhythmic or sequenced parts using drum machines, samplers, or software, rather than recording a live drummer. In popular, hip-hop, and electronic music this role builds a track's rhythmic foundation through step or MIDI sequencing.", "plain_english": "A beat programmer builds drum and rhythm parts using machines or software. They do not record a live drummer. Instead, they enter the beats step by step to make the groove.", "purpose_function": "The role exists to create precise, repeatable rhythm tracks that are easy to edit, which suits styles built on programmed beats and supports reliable live playback.", "practical_application": "A beat programmer prepares the drum and sequenced parts in a DAW before a tour, so they can be triggered or played back consistently at each show.", "category": "Production Roles", "related_terms": ["Drum machine", "Sequencer", "MIDI", "Sampler", "Playback (tracks)", "Click track"], "common_mistakes": ["Thinking programmed beats must sound robotic, when programmers use velocity and timing changes to add feel", "Confusing a beat programmer with a live drummer or with a DJ", "Assuming the parts cannot change, when programmed patterns are easy to edit and rearrange"], "scenario_contexts": ["Building a song's drum pattern in a DAW with a step sequencer", "Preparing programmed tracks for playback on a live tour", "Layering sampled percussion under a live band's performance"]}, "3f232ec0-a39e-479d-ac2f-28fd61ff5157": {"definition": "On a live stage, bleed (also called spill) is unwanted sound from one source that is picked up by a microphone intended for a different source, such as drums leaking into a vocal microphone. It reduces isolation between channels and can cause tonal colouration, comb filtering, and feedback problems in the mix.", "plain_english": "Bleed is when a mic picks up sound it was not meant to catch. For example, the drums leak into the singer's mic. This makes each channel harder to control on its own.", "purpose_function": "Understanding bleed matters because it sets how much separate control an engineer has over each source, which in turn guides microphone choice, placement, and stage layout.", "practical_application": "Engineers reduce bleed by using directional microphones, placing mics close to their source, applying noise gates, and arranging the stage so open mics reject nearby instruments.", "category": "Live Sound", "related_terms": ["Isolation", "Gate (noise gate)", "Cardioid pattern", "Feedback", "Comb filtering", "Stage plot"], "common_mistakes": ["Assuming a directional mic removes bleed entirely, when it only reduces sound arriving from off-axis", "Confusing bleed with feedback; bleed is spill between sources, while feedback is a mic-to-speaker loop", "Gating too aggressively to cut bleed, which chops off the wanted sound's natural decay"], "scenario_contexts": ["Drum spill entering the lead vocal mic during a loud song", "A guitar amp bleeding into nearby drum overhead mics", "Using noise gates on tom mics to reduce bleed between drums"]}, "510193cf-5475-4a5f-adf2-21b3a46e8d38": {"definition": "The practice of marking a cable with matching identifiers at both of its connector ends, so the run can be identified at either end without tracing it. The label typically records the cable's channel or destination, and both ends carry identical information to speed patching and fault-finding.", "plain_english": "Both-end labeling means putting the same label on each end of a cable. Then you can tell what a cable is from either end. This saves time when patching or fixing faults.", "purpose_function": "It exists so crews can identify, patch, and troubleshoot cables quickly, because a label at only one end forces you to trace the whole run to find the other end.", "practical_application": "During load-in a crew labels every multicore tail and mic line at both ends, so any cable can be located and repatched fast if a fault appears during the show.", "category": "Cable Management", "related_terms": ["Multicore (snake)", "Patch bay", "Cable management", "Load-in", "Stage box"], "common_mistakes": ["Labeling only one end, which forces you to trace the cable to identify the other end", "Using paper or tape labels that fall off under heat and handling instead of durable cable markers", "Writing different information on each end, so the two labels do not match"], "scenario_contexts": ["Labeling both ends of every line on a stage snake during load-in", "Finding a faulty channel quickly by reading the label at the patch bay", "Repatching a cable at the stage box using its matching end label"]}, "503224fd-8e91-4113-b02b-dadb49e8d755": {"definition": "An audio engineer responsible for mixing a live event's sound for transmission or recording to broadcast or stream, as distinct from the front-of-house mix heard in the venue. The broadcast mix is optimised for viewers at home and typically balances the performance against commentary, crowd, and effects.", "plain_english": "A broadcast mix engineer mixes the sound that goes out on TV or a stream. This is separate from the mix played in the room. They balance the show for people watching at home.", "purpose_function": "The role exists because the home audience hears through small speakers in a quiet room, so the sound needs a different balance from the loud live mix in the venue.", "practical_application": "Working from a broadcast truck, the engineer takes a signal split of the stage sources and builds a separate mix feed for transmission or the stream.", "category": "Crew Roles", "related_terms": ["Front-of-house engineer", "Monitor engineer", "Split (signal split)", "Outside broadcast (OB)", "Stem"], "common_mistakes": ["Assuming the broadcast mix is just the front-of-house mix sent to air, when it is a separate, differently balanced mix", "Forgetting that home speakers need clearer vocals and dialogue than a loud venue mix", "Confusing the broadcast mix engineer with the front-of-house engineer, who mixes for the live room"], "scenario_contexts": ["Mixing a festival's live stream from a broadcast truck", "Balancing crowd, commentary, and music for a televised concert", "Taking an isolated signal split so the broadcast mix does not affect front-of-house"]}, "15f5e0e2-d033-4cbc-976f-e233a2648831": {"definition": "In touring and event production, the build (also called the get-in or load-in build) is the coordinated process of unloading, assembling, and erecting the staging, set, rigging, audio, and lighting systems at a venue so the show is ready for rehearsal and performance. It is the construction phase that precedes the show and is reversed at load-out during the strike.", "plain_english": "The build is when the crew puts the whole show together at the venue. They unload the trucks and set up the stage, rig, lights, and sound. It is the opposite of tearing it all down after the gig.", "purpose_function": "It turns a truckload of gear into a working, safe show system, and it sets an order to assembly so rigging and power go in before the systems that depend on them.", "practical_application": "Crew follow the build schedule so rigging, power, audio, and lighting are installed in the right sequence and ready in time for soundcheck.", "category": "Load-in / Load-out", "related_terms": ["Load-in", "Load-out", "Strike", "Build-up", "Rigging"], "common_mistakes": ["Confusing the build with soundcheck; the build is the physical assembly that must finish before soundcheck can begin", "Assuming build order does not matter, when rigging and power must go in before the systems that hang from or feed off them", "UNSAFE: Working under or near a rig that is still being flown or is not yet secured, instead of staying clear until the rigging crew signals it is safe"], "scenario_contexts": ["A festival crew doing a fast morning build so the first act can soundcheck by midday", "A touring crew building the same rig city after city using a repeatable plan", "A production manager sequencing the build so rigging and power finish before audio and lighting go up"]}, "644acf36-57f5-4447-964c-c9953888c707": {"definition": "Chiefly in UK live-event and exhibition practice, the build-up is the scheduled period before an event opens during which crews install and erect the stage, set, rigging, and technical systems. It is the counterpart to the breakdown, or get-out, that removes them after the event.", "plain_english": "Build-up is the setup time before an event opens. Crews use it to put up the stage, rig, and gear. It is the opposite of breakdown, when everything comes down again.", "purpose_function": "It reserves defined time in the schedule for safe, orderly installation, so all systems are built and tested before doors open to the public.", "practical_application": "Crews book build-up days into the venue schedule and work through them to install rigging, power, audio, and lighting before the event starts.", "category": "Load-in / Load-out", "related_terms": ["Build", "Load-in", "Breakdown", "Get-in", "Strike"], "common_mistakes": ["Confusing build-up, which is setting up, with breakdown, which is tearing down, since the two are opposites", "Underestimating how much build-up time a rig needs, leaving no margin before doors open", "UNSAFE: Rushing build-up by skipping rigging checks or overhead-work exclusion zones instead of following the safe assembly sequence"], "scenario_contexts": ["An exhibition crew given two build-up days to install stands and technical systems", "A festival build-up week erecting stages and rigs before the public arrives", "A production planning build-up hours around a venue's access and curfew limits"]}, "26d1cf48-3477-46f9-9d51-fc09a3193419": {"definition": "On a bussed tour, the bus call is the scheduled time at which the tour bus or buses will depart the venue or hotel; band and crew must be aboard by that time or risk being left behind. It is set to respect the driver's legal driving hours and to meet the next city's arrival needs.", "plain_english": "Bus call is the set time the tour bus leaves. If you are not on board, the bus goes without you. It is planned around the driver's legal drive hours and the next show.", "purpose_function": "It gives the whole touring party one firm departure time, so travel fits the driver's legal hours and the bus reaches the next city on schedule.", "practical_application": "The tour manager posts bus call on the day sheet, and crew finish load-out, clean up, and board the bus before that time.", "category": "Tour Logistics", "related_terms": ["Day sheet", "Load-out", "Tour manager", "Get-in", "Advance"], "common_mistakes": ["Treating bus call as a rough suggestion rather than a hard deadline, and missing the bus", "Forgetting that bus call is driven by the driver's legal hours, not by how the crew feels", "Confusing bus call with lobby call or load-out time, which are separate scheduled times"], "scenario_contexts": ["A tour manager setting a bus call soon after load-out to reach the next city overnight", "A crew member checking the day sheet for tonight's bus call time", "A driver's legal rest requirement forcing an earlier bus call"]}, "e39d7253-35d7-4a3f-93a9-a95e910a77c1": {"definition": "The cable path is the planned route that cables and multicores follow between equipment positions across a stage, venue, or site. It is chosen to reach every device by the safest, most efficient run while avoiding traffic lanes, heat, water, and sources of electrical interference.", "plain_english": "The cable path is the route the crew runs cables along. A good path keeps cables tidy and out of walkways. It also keeps them away from heat, water, and things that cause noise.", "purpose_function": "It organises cable runs so gear connects reliably and safely, keeping cables clear of walkways and away from interference and damage.", "practical_application": "Crew plan the cable path during load-in, then run, dress, and protect the cables along it, using ties, matting, and ramps where they cross walkways.", "category": "Cabling", "related_terms": ["Cable pull", "Cable ramp", "Multicore", "Dressing cables", "Cable technician"], "common_mistakes": ["UNSAFE: Running cables straight across a walkway or doorway without ramps or matting, creating a trip hazard", "Routing signal cables in long parallel runs beside mains power, which can induce hum and noise", "Choosing the shortest path over the safest one, forcing cables through doorways or high-traffic areas"], "scenario_contexts": ["Planning a cable path from stage to the front-of-house mix position across a public floor", "Choosing a cable path that avoids crossing a fire exit or emergency route", "Routing a cable path away from dimmer racks and heat sources to protect the insulation"]}, "20076d26-be49-46e9-9eb5-3fffbc0780a4": {"definition": "A cable pull is the task of running (pulling) cable and multicore runs into position during load-in, laying them along the planned cable path from source to destination. The term also covers physically drawing cable through conduit, cable trays, or tight architectural routes.", "plain_english": "A cable pull is when the crew runs cables into place during setup. They lay each cable from one end to the other along its route. Sometimes they pull it through pipes or tight gaps.", "purpose_function": "It gets every signal and power cable from its source to where it is needed, forming the interconnections the whole system depends on.", "practical_application": "During load-in, crew do the cable pull first for long runs such as the front-of-house multicore, then dress and connect the ends.", "category": "Cabling", "related_terms": ["Cable path", "Multicore", "Cable technician", "Load-in", "Dressing cables"], "common_mistakes": ["Pulling cable without labelling both ends, which makes later patching slow and error-prone", "UNSAFE: Dragging cable over sharp edges or pulling it by its connectors, which damages conductors and strain reliefs", "Leaving too little slack at each end, so connectors are strained or cannot reach"], "scenario_contexts": ["Pulling the front-of-house multicore from stage to the mix position at the start of load-in", "Two crew coordinating a long cable pull through a venue's under-stage trays", "Pulling feeder or data runs into place before the rest of the system goes up"]}, "11df3244-2ebe-4a0e-904d-27d09af827da": {"definition": "A cable technician (also cable tech or cabler) is a crew member responsible for the routing, running, dressing, connection, testing, and maintenance of cabling on a production. They work under the audio, lighting, or video department to keep signal and power interconnections reliable.", "plain_english": "A cable technician is the crew member who looks after the cables. They run, tidy, connect, and test them, and fix any that fail. This keeps signal and power flowing across the show.", "purpose_function": "The role concentrates responsibility for cabling in one person, so runs are installed correctly and faults are found and fixed quickly.", "practical_application": "On load-in the cable technician runs and dresses the cable runs, then during the show troubleshoots any cable or connector fault.", "category": "Crew Roles", "related_terms": ["Cable pull", "Cable path", "Cable trunk", "Multicore", "Load-in"], "common_mistakes": ["Assuming the cable technician only coils cables, when the role also covers routing, testing, and fault-finding", "UNSAFE: Working on or near live power connections without lockout/tagout and correct personal protective equipment", "Skipping cable testing before the show, so faults surface during the performance"], "scenario_contexts": ["A cable technician running and labelling all audio runs during a festival load-in", "A cable technician tracing and replacing a faulty data run during a lighting fault", "A cable technician coiling cables back into their trunks correctly at load-out"]}, "d56ac58d-28ec-4ab6-aa93-f4e4b2932d51": {"definition": "A cable trunk is a large wheeled road case built to store and transport cables, multicores, and related connectors between shows. It protects them in transit and keeps a department's cabling organised and ready to run.", "plain_english": "A cable trunk is a big rolling case for cables. It protects the cables while they travel between shows. It also keeps them sorted so the crew can find and run them fast.", "purpose_function": "It protects cables from damage in transit and storage, and keeps a department's runs organised so load-in and load-out are faster.", "practical_application": "Crew pull cables from the cable trunk during load-in and coil them neatly back into it at load-out.", "category": "Road Cases", "related_terms": ["Cable pull", "Cable path", "Cable technician", "Multicore", "Road case"], "common_mistakes": ["UNSAFE: Overloading a cable trunk beyond a safe weight, then lifting or moving it without help or a proper team lift", "Coiling cables badly into the trunk, causing tangles and kinks that damage conductors", "Not labelling the trunk or its contents, which slows down load-in"], "scenario_contexts": ["Wheeling cable trunks off the truck to each department's position at load-in", "Coiling and packing all runs back into their cable trunks at load-out", "Labelling cable trunks by department so they reach the right stage area"]}, "7a6edc35-c50b-49b2-b483-12cb59b65870": {"definition": "Cans is professional audio and stage-crew jargon for headphones, covering both the closed-back monitoring headphones used at consoles and the headsets worn on a wired or wireless intercom (party-line comms) system. To be 'on cans' means a crew member is wearing and actively monitoring the intercom headset.", "plain_english": "Cans is crew slang for headphones. On a show, crew often wear them to hear the mix or to talk on the intercom. So if someone says 'get on cans,' they mean put your headphones on.", "purpose_function": "Cans let crew and operators hear a dedicated feed — a monitor mix, a click, or intercom talk — isolated from the loud room. They exist so team members can listen critically or communicate reliably during a show.", "practical_application": "A monitor engineer checks a wedge or in-ear mix on cans, while stage crew wear intercom cans to take cues during the performance.", "category": "Crew equipment", "related_terms": ["Intercom (comms)", "Party line", "Belt pack", "Monitor mix", "In-ear monitors", "Headset"], "common_mistakes": ["Assuming 'cans' always means the same thing — it can mean monitoring headphones or intercom headsets, so confirm which is meant.", "Thinking being 'on cans' means only listening, when it usually means you must also answer cues on the intercom.", "UNSAFE: Running cans at high volume for long stretches, which risks hearing damage; keep levels moderate and follow hearing-conservation practice."], "scenario_contexts": ["A monitor engineer checks an in-ear mix on cans before doors.", "A stage manager calls the show 'on cans' over the intercom.", "A backline tech listens to a click track on cans during the set."]}, "9ce64817-f0bc-4d3e-8385-db98a6f38a70": {"definition": "In stage and touring crews, a carpenter (or stage carpenter) is the crew member responsible for constructing, installing, maintaining, and operating scenery, stage decking, platforms, and other structural stage elements. The head carpenter supervises the deck crew, oversees load-in and load-out of scenic pieces, and runs scene changes during a performance.", "plain_english": "A carpenter is the crew member who builds and sets up the stage and scenery. They lay the stage floor, put sets together, and fix them if they break. During the show they may move scenery between scenes.", "purpose_function": "The carpenter exists to build and maintain the physical stage and scenery so a performance runs safely and looks as designed. They turn the designer's drawings into solid, movable, secure structures.", "practical_application": "At load-in a carpenter lays and levels the stage deck and assembles set pieces, then stands by to shift scenery and make repairs during the run.", "category": "Crew role", "related_terms": ["Deck crew", "Head carpenter", "Stagehand", "Rigger", "Load-in", "Deck"], "common_mistakes": ["Confusing the stage carpenter with a general woodworker; the role centers on scenery, decking, and stage structures, not furniture-making.", "Assuming the carpenter only works before the show, when they also run scene changes and make live repairs during the run.", "UNSAFE: Loading gear or standing on decking that is not fully assembled, leveled, and secured; staging must be built and secured before any load-bearing use."], "scenario_contexts": ["A carpenter lays and levels the stage deck at load-in.", "The head carpenter runs a scene change during a performance.", "A carpenter repairs a damaged platform between shows."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"e320ba4a-523e-4a53-a8e8-7734164a6e4e": {"definition": "A changeover is the transition period between two acts sharing a stage, during which one act's backline, instruments, and stage gear are struck and the next act's are set, positioned to marks, patched, and line-checked. It is a scheduled, time-critical operation common at festivals and multi-act concerts, often run to a fixed time limit to keep the show on schedule.", "plain_english": "A changeover is the switch between two acts on the same stage. The crew clears the first act's gear and sets up the next act fast. It happens at festivals and multi-band shows to keep things on time.", "purpose_function": "The changeover exists to reset a shared stage from one act to the next as quickly and accurately as possible. It keeps a multi-act event running to schedule without long gaps for the audience.", "practical_application": "At a festival the crew rehearses and times each changeover, rolling risers on and off and re-patching inputs so the next band can line-check within its slot.", "category": "Show operations", "related_terms": ["Changeover crew", "Backline", "Line check", "Stage plot", "Strike", "Riser"], "common_mistakes": ["Thinking a changeover is just 'the next band setting up,' when it is a timed operation of strike, set, patch, and line check.", "Not working from the stage plot and input list, which causes patching errors and eats up the line-check time.", "UNSAFE: Rushing heavy risers and backline without teamwork or clear routes, risking manual-handling and struck-by injuries; keep cable runs and paths clear."], "scenario_contexts": ["A festival stage runs a 20-minute changeover between bands.", "Crew rolls the next act's drum riser on during a changeover.", "The next act line-checks its inputs at the end of a changeover."]}, "e70ddf10-1270-40bf-873c-4ee7c6aeb67e": {"definition": "A changeover crew is the team of stagehands and technicians assigned to perform changeovers — striking one act's equipment and setting, patching, and line-checking the next act's gear in the scheduled interval between performances. The crew works to a prepared plan and stage plots so each transition is completed within its allotted time.", "plain_english": "The changeover crew is the team that swaps gear between acts. They pull off one band's equipment and set up the next band's gear quickly. Their speed keeps a festival running on schedule.", "purpose_function": "The changeover crew exists to make fast, accurate act-to-act transitions on a shared stage. Their coordinated work protects the event schedule and lets each act start on time.", "practical_application": "Between sets, the changeover crew strikes the previous backline, wheels the next act's risers to marks, and re-patches and line-checks inputs before the act begins.", "category": "Crew role", "related_terms": ["Changeover", "Stagehand", "Backline", "Strike", "Stage plot", "Local crew"], "common_mistakes": ["Assuming any spare person can just jump in; the crew works to assigned roles and a plan so nothing is missed.", "Failing to label and route cables during a fast changeover, which slows the next line check.", "UNSAFE: Lifting heavy cases and gear alone or with poor technique during a rushed changeover; use team lifts and safe manual-handling practice."], "scenario_contexts": ["The changeover crew strikes a band's backline right after their set.", "A changeover crew wheels risers to marks between acts.", "The changeover crew re-patches inputs before the next line check."]}, "72832d06-3dbc-4a56-9633-ff4afd99db2a": {"definition": "A rapid line check carried out during the changeover between acts, confirming that each input channel (microphones, DI boxes, playback feeds) passes signal and is correctly patched before the next act begins.", "plain_english": "A quick test of every mic and cable while one band swaps out for the next. The crew makes sure each input works before the new act plays.", "purpose_function": "It verifies signal flow and patching within the short changeover time, so the incoming act can start on schedule with no dead or mispatched channels.", "practical_application": "During a festival changeover, a tech speaks into or taps each mic and DI while watching the console meters, fixing any bad lines before the set starts.", "category": "Soundcheck", "related_terms": ["Changeover window", "Line check", "Soundcheck", "Patch bay", "DI box"], "common_mistakes": ["Confusing a line check with a full soundcheck; a line check only confirms signal and patching, not the mix balance.", "Skipping inputs the next act will use, leaving dead channels that surface mid-set.", "Not coordinating with monitor world, so the stage foldback is left unchecked before the act begins."], "scenario_contexts": ["A festival main stage where several bands share the day and each gets only minutes to swap.", "A support act finishing while the crew line-checks the headliner's inputs during the gap.", "A house engineer confirming a guest performer's playback feeds before switching sources."]}, "213d0d1d-6254-441e-8d67-0aeb7e60cbbf": {"definition": "The scheduled block of time allotted to strike one act's equipment and set up the next act on the same stage, including line checking, before the following performance must begin.", "plain_english": "The set amount of time the crew has to swap one band's gear for the next. It works like a pit stop, with a strict clock running.", "purpose_function": "It bounds the turnaround between acts so a multi-act show or festival stays on schedule and within curfew.", "practical_application": "A stage manager holds the crew to the changeover window, calling the time so the next act's setup, line check, and stage clear all finish before the set time.", "category": "Show scheduling", "related_terms": ["Changeover line check", "Strike", "Load-in", "Stage manager", "Curfew"], "common_mistakes": ["Assuming the window includes a full soundcheck when usually only a line check fits.", "Under-planning labor, so the swap runs long and pushes the whole schedule back.", "Ignoring curfew, since an overrunning changeover can trigger fines or a cut set."], "scenario_contexts": ["A festival with twenty-minute changeover windows between bands on one stage.", "A co-headline tour where each act needs its own backline swapped in a fixed gap.", "A corporate event switching from a keynote speaker to a live band during a short break."]}, "678bac35-e4d2-429d-9c92-74de27e9ed2f": {"definition": "A test of an audio signal path in which sound is deliberately introduced, by speaking, tapping, or playing into a source, to confirm the channel is live, correctly patched, and at a usable level.", "plain_english": "Making a sound into a mic or input to prove it works. The crew listens or watches the meters to see the signal come through.", "purpose_function": "It confirms a source reaches the console and outputs before it is needed, catching dead mics, bad cables, or wrong patches early.", "practical_application": "An engineer asks a performer to check a vocal mic, then watches the meter and sets gain while listening for signal and noise.", "category": "Soundcheck", "related_terms": ["Line check", "Soundcheck", "Gain", "Signal flow", "Changeover line check"], "common_mistakes": ["Confusing a check of one input with a full soundcheck of the whole mix.", "Setting gain from a quiet check, then clipping when the performer plays at full level.", "Calling a channel good after a check without confirming it from the correct source position."], "scenario_contexts": ["A tech walking the stage and tapping each mic to check inputs before a show.", "A monitor engineer asking a singer to check their vocal into the wedges.", "Checking a DI from a keyboard before the line check moves to the next input."]}, "fab93223-3cad-4423-b45e-20ad60f80e91": {"definition": "The senior recording engineer who leads a facility's or session's technical team, responsible for the technical quality of recordings, upkeep of equipment, and supervision of assistant engineers.", "plain_english": "The lead recording engineer in charge of the technical side. They run the gear, guide junior engineers, and make sure recordings sound right.", "purpose_function": "The role centralizes technical responsibility and mentorship, so sessions run to a consistent standard and equipment stays reliable.", "practical_application": "On a large session the chief recording engineer sets up signal chains, solves technical problems, and directs assistants on mic placement and patching.", "category": "Crew role", "related_terms": ["Recording engineer", "Assistant engineer", "Front of house engineer", "Monitor engineer", "Tracking"], "common_mistakes": ["Confusing the chief recording engineer with the producer, who guides the creative and musical direction.", "Assuming the title means personally operating every session rather than overseeing the technical team.", "Treating the role as live-sound focused when it is centered on the recording facility."], "scenario_contexts": ["A large commercial studio where one senior engineer oversees all technical operations.", "A broadcast or film-scoring facility with a chief engineer heading the recording staff.", "A remote recording truck where the lead engineer supervises assistants during a live capture."]}, "5e12a34e-1feb-4f77-8bba-85f55fe5f029": {"definition": "A communications call confirming that a person, path, or area is unobstructed and safe, or that a task or transmission is complete, signaling that it is safe to proceed.", "plain_english": "A word crew use to say an area or path is empty and safe. It can also mean someone has finished a job or a radio message.", "purpose_function": "It gives a short, unambiguous confirmation that a hazard is gone or an action is done, so the next step can begin safely.", "practical_application": "Before a fly move or a truck backing in, a crew member calls 'clear' once people and gear are out of the path.", "category": "Stage comms", "related_terms": ["Clear stage", "Clear the deck", "Standby", "Go", "Clear-comms path"], "common_mistakes": ["UNSAFE: Calling 'clear' before you have actually confirmed the whole path or area is empty of people.", "Using 'clear' loosely on comms so no one knows what is actually clear.", "Assuming 'clear' means go; it confirms safe, but a separate 'go' cues the action."], "scenario_contexts": ["A rigger calling 'clear' below before a motor lifts a truss overhead.", "A stagehand confirming a wing is clear before scenery tracks offstage.", "A spotter calling 'clear' as a truck reverses toward the loading dock."]}, "781b962e-2038-4bc1-8871-33fb1cf23792": {"definition": "A stage-management command directing all non-essential personnel and equipment to leave the stage, typically before a scenery move, fly cue, set change, or opening the house to the audience.", "plain_english": "An order for everyone not needed to get off the stage. It is called before big moves so no one is in danger.", "purpose_function": "It removes people and clutter from the stage so moves, flying, or the performance can happen safely and without obstruction.", "practical_application": "The stage manager calls 'clear stage' over comms before flying in scenery, and crew confirm the deck is empty before the move proceeds.", "category": "Stage command", "related_terms": ["Clear the deck", "Clear", "Standby", "Fly cue", "Stage manager"], "common_mistakes": ["UNSAFE: Flying or moving scenery before confirming the stage is actually clear of people.", "Leaving cases, cables, or tools on the deck after the call.", "Treating it as optional during rehearsal, which builds an unsafe habit for the show."], "scenario_contexts": ["A stage manager clearing the stage before a heavy fly-in during a set change.", "Clearing the stage before opening the house to the audience.", "A crew chief clearing the deck before a stage-wide focus of automated lighting."]}, "2f764631-14bc-448a-af3f-60f53ad5472d": {"definition": "A command to remove all people, tools, cases, and loose equipment from the stage floor (the 'deck'), leaving it clear for a move, a performance, or the next crew task.", "plain_english": "An order to get everything and everyone off the stage floor. 'Deck' is crew slang for the stage floor itself.", "purpose_function": "It resets the stage floor to a safe, empty state before a scenery move, an act, or a changeover step.", "practical_application": "After load-in, a crew chief calls 'clear the deck' so empty cases and cables are removed before the line check and set.", "category": "Stage command", "related_terms": ["Clear stage", "Deck", "Clear", "Strike", "Changeover"], "common_mistakes": ["UNSAFE: Starting a fly or automation move while cases or people are still on the deck.", "Pushing gear into wings or fire lanes instead of properly clearing it away.", "Confusing it with a full strike; it clears the floor, not necessarily all gear."], "scenario_contexts": ["Clearing empty road cases off the deck after load-in.", "A crew chief clearing the deck before a scene change during a musical.", "Removing cabling and tools from the stage floor before the audience is let in."]}, "2cdf3cec-166f-4fa8-9e92-88fafbc02445": {"definition": "An established, unobstructed intercom link between crew positions, free of dropouts, cross-talk, or blocked channels, so instructions and cues pass reliably during a show.", "plain_english": "A working intercom link between crew that comes through clearly. No dropouts or crossed channels get in the way of cues.", "purpose_function": "Reliable communication keeps cues, safety calls, and coordination flowing between positions such as front of house, monitors, and the deck.", "practical_application": "Before a show, the crew line-checks headsets and beltpacks to confirm a clear-comms path between the stage manager and every position.", "category": "Crew comms", "related_terms": ["Intercom", "Beltpack", "Clear", "Standby", "Front of house"], "common_mistakes": ["Assuming comms work without testing every position and channel before the show.", "UNSAFE: Running safety-critical cues, such as fly moves, without a confirmed clear-comms path.", "Overloading one channel so urgent calls get lost in the chatter."], "scenario_contexts": ["A stage manager confirming headset comms to all positions before curtain.", "Setting up a wireless intercom so a spotlight operator stays in contact.", "Troubleshooting a noisy beltpack to restore a clear path to monitor world."]}, "eefcaf3e-a1eb-42e3-8d4b-a9d6c86755ff": {"definition": "Replacing a device or component while the affected system is fully powered down, in contrast to a hot swap performed with power applied. On a show this means shutting off the affected gear (for example an amplifier, processor, or console) before removing it and fitting the replacement.", "plain_english": "Swapping out a piece of gear after turning its power off. This is safer for the equipment than changing it while it is still running.", "purpose_function": "It avoids the electrical stress, signal glitches, and damage that can occur when connections are made or broken under power, so the exchange is safe for both the equipment and the technician.", "practical_application": "When a rack amplifier fails mid-tour, the tech powers down that unit, performs a cold swap for a spare, then brings it back up during a set break.", "category": "Maintenance", "related_terms": ["Hot swap", "Console swap", "Redundant system", "Backup", "Signal flow"], "common_mistakes": ["Confusing a cold swap with a hot swap; a cold swap requires the device to be powered down first.", "UNSAFE: Pulling or inserting powered connectors to save time, risking arcing, equipment damage, or electric shock.", "Forgetting to recall the correct settings or show file after the replacement, so the swapped unit behaves differently."], "scenario_contexts": ["A failed amplifier in a touring PA rack that must be replaced during a set break.", "Swapping a crashed signal processor when no redundant unit is patched in.", "Replacing a power supply that is not rated for hot swapping."]}, "fbf6bb2a-db55-45d0-aba4-2ae6d961d5b3": {"definition": "A crew member responsible for specifying, installing, operating, and maintaining a production's communications systems, including wired and wireless party-line and matrix intercom, IFB, and program or two-way radio links between departments.", "plain_english": "The crew member who runs the headset and radio system for a show. They make sure every department can talk to each other clearly.", "purpose_function": "The role exists to keep reliable, low-latency communication among stage, front of house, lighting, video, and stage management, which is essential for cueing and safety.", "practical_application": "The comms tech deploys beltpacks, base stations, and antennas, assigns channels, and troubleshoots interference so directors and operators stay in contact throughout the show.", "category": "Crew roles", "related_terms": ["Console technician", "Intercom", "IFB", "Beltpack", "Stage manager"], "common_mistakes": ["Assuming any radio or wireless channel is free; the comms tech must coordinate frequencies to avoid interference.", "Confusing intercom (crew talkback) with IFB, which feeds cues or program audio to on-air talent.", "Underestimating battery and antenna planning for wireless comms coverage across a large venue."], "scenario_contexts": ["A touring production coordinating cues across FOH, monitors, lighting, and video.", "A broadcast or festival needing IFB feeds to presenters and camera operators.", "Setting up wireless intercom coverage across a large arena or outdoor site."]}, "c326f49e-570a-4ed5-9923-61683c87a079": {"definition": "The exchange of one mixing console for another at a shared control position, typically during a changeover so an incoming act can use its own or preferred desk, or to replace a console that has failed.", "plain_english": "Trading one mixing desk for another at the same spot. Bands on a festival bill often swap consoles between sets.", "purpose_function": "It lets different acts run their own console programming, or restores mixing when a desk fails, without rebuilding the whole signal path to the stage.", "practical_application": "At a festival, crew roll the outgoing act's console off the FOH riser and patch the next act's desk to the shared stage box during the changeover window.", "category": "Changeover", "related_terms": ["Changeover window", "Console technician", "Stage box", "Patch", "Control changeover"], "common_mistakes": ["Not confirming the shared digital snake or stage box is compatible before swapping desks.", "Forgetting to save or load the correct show file, losing the incoming act's settings.", "UNSAFE: Swapping with outputs live and unmuted, risking loud transients that can damage drivers or hearing."], "scenario_contexts": ["A multi-act festival where each headliner brings its own FOH console.", "Replacing a console that has crashed mid-show with a backup desk.", "A support act using the house console while the headliner patches in a touring desk."]}, "9f71b436-3fec-44c5-b805-7c9ca6e59528": {"definition": "A technician responsible for the setup, patching, configuration, and upkeep of a production's mixing console(s), supporting the mix engineer and keeping the desk and its I/O working across load-in, show, and load-out.", "plain_english": "The crew member who looks after the mixing desk. They set it up, patch it, and fix problems so the engineer can just mix.", "purpose_function": "The role frees the mix engineer to concentrate on the mix while a specialist handles console networking, show files, I/O, and maintenance.", "practical_application": "The console tech loads the show file, patches inputs to the stage box, updates firmware, and stands by to reboot or reconfigure the desk if problems arise.", "category": "Crew roles", "related_terms": ["Communications technician", "Console swap", "Show file", "Stage box", "Control package"], "common_mistakes": ["Thinking the console tech mixes the show; they support the desk, not the artistic mix.", "Skipping a saved backup of the show file before making changes.", "Not verifying I/O patching between the console and stage racks before soundcheck."], "scenario_contexts": ["A large touring act with a dedicated tech per console at FOH and monitors.", "Rebuilding a show file and patch after a console reboot.", "Supporting a guest engineer unfamiliar with the touring desk."]}, "429cc45d-ec62-4dc6-9d3e-89f8d8190b18": {"definition": "The transfer of operational control of a system from one control position or console to another, for example handing lighting or audio control from a main desk to a backup, or between control locations, so operation continues without interruption.", "plain_english": "Handing control of a show from one desk or booth to another. It is done so the show keeps running if a desk fails or a plan changes.", "purpose_function": "It provides continuity and redundancy, letting a backup or alternate control point take over when the primary fails or when responsibility moves between operators.", "practical_application": "If the main lighting console locks up, the operator performs a control changeover to a tracking backup desk that has been mirroring the show in real time.", "category": "Changeover", "related_terms": ["Console swap", "Control package", "Console technician", "Redundant system", "Changeover window"], "common_mistakes": ["Assuming the backup is ready; a tracking backup must mirror the main desk in real time to take over cleanly.", "Not rehearsing the changeover, so the handover fails under real show pressure.", "Confusing a control changeover (transfer of control) with a console swap (physical exchange of the desk)."], "scenario_contexts": ["Switching to a tracking backup lighting console after a primary desk failure.", "Handing audio control between front of house and a broadcast truck.", "Transferring control between two operators during a long event."]}, "eef63874-67e7-4259-88ab-787d9cbef858": {"definition": "The bundled set of control equipment supplied for a show or tour, typically the console(s), control surfaces, processors, networking devices, and cabling that operate a system such as audio or lighting from the control position.", "plain_english": "The kit of gear used to run a show from the control spot. It usually means the mixing or lighting desk plus its processors and cables.", "purpose_function": "Packaging the control gear together makes it easy to specify, rent, transport, and set up as one working control system for a production.", "practical_application": "A rental company ships the lighting control package (console, backup, node boxes, and cabling) as one order that the tech unpacks and networks at the control position.", "category": "Equipment", "related_terms": ["Control changeover", "Console swap", "Console technician", "Rack", "Networking"], "common_mistakes": ["Thinking the control package includes speakers or dimmers; it is the control gear, not the output system.", "Overlooking spare or backup control gear when specifying the package.", "Forgetting cabling and networking, which are part of a complete control package."], "scenario_contexts": ["Renting a full audio control package for a one-off corporate show.", "Specifying a lighting control package with a tracking backup for a tour.", "Unpacking and networking the control package at front of house during load-in."]}, "d9aa9d1b-d5bf-4a71-a1f5-f0a3cf135fa3": {"definition": "The location within a venue from which the front-of-house engineer operates the main mixing console, sited in the audience area so the engineer hears a mix representative of what the crowd hears. It houses the FOH console, processing, and control gear for the performance.", "plain_english": "The spot out in the crowd where the sound engineer runs the main mixing desk. It sits among the audience so the engineer hears what they hear.", "purpose_function": "It places the engineer and console where the mix can be judged from the audience's perspective, so level and tone decisions match what listeners actually hear.", "practical_application": "A crew builds the control position mid-house, runs the snake to it, and sets up the console, drive rack, and talkback there before soundcheck.", "category": "Mix Position", "related_terms": ["Front of house", "FOH console", "Copper snake", "Monitor world", "Soundcheck"], "common_mistakes": ["Placing the control position under a balcony or against a wall, where the acoustics misrepresent the mix.", "Confusing the control position with monitor world, which mixes the stage foldback rather than the house.", "Assuming any spot works, when sightlines, power, and cable runs all constrain the location."], "scenario_contexts": ["A touring FOH engineer setting up the console at a mid-house control position before doors.", "A festival where the control position sits in a tent or on a riser out in the audience.", "A crew negotiating with the venue for a control position that removes some sellable seats."]}, "b1b08cf6-a058-4eec-8650-ce3bb996c5c8": {"definition": "An analog multicore audio cable, or 'snake', whose signal conductors are copper wire, used to carry many microphone and line signals between the stage and the mix position. The term distinguishes it from a digital or fiber-optic snake.", "plain_english": "A thick cable that carries many audio lines at once using copper wire. Crews say 'copper' to tell it apart from newer fiber cables.", "purpose_function": "It consolidates many separate audio runs into one manageable cable, carrying analog signals over copper between stage and console.", "practical_application": "A crew rolls out the copper snake from stage to the control position, connects stage boxes to its fan-out, and patches returns at the console end.", "category": "Cabling", "related_terms": ["Digital snake", "Stage box", "Control position", "Multicore", "Cable run"], "common_mistakes": ["Assuming any snake is digital; a copper snake carries analog signal and adds no conversion or network latency of its own.", "Coiling a heavy copper snake too tightly, which strains its many internal conductors and connectors.", "UNSAFE: Running a copper snake across a walkway without cable ramps or matting, creating a trip-and-fall hazard."], "scenario_contexts": ["A club with a permanent copper snake wired from the stage to the booth.", "A crew choosing a copper snake over fiber for a short analog stage run.", "Troubleshooting a dead channel by testing an individual pair inside the copper snake."]}, "4de0d651-d70e-453a-b2ae-12839cf44556": {"definition": "The scheduled time at which the working crew must report to the venue to begin load-in or their assigned duties; the 'call time' for crew, as distinct from the calls for performers or other departments.", "plain_english": "The time the crew has to show up and start work. It is their official start time for the day, like clocking in.", "purpose_function": "It sets a common start time so all crew arrive together and load-in, setup, or a shift can begin on schedule.", "practical_application": "A production or stage manager posts the crew call on the day sheet, and hands report at that time ready to unload the trucks.", "category": "Scheduling", "related_terms": ["Load-in", "Bus call", "Stage manager", "Day sheet", "Curfew"], "common_mistakes": ["Confusing crew call with door time or show time; crew call is usually much earlier.", "Arriving exactly at crew call rather than a few minutes early and ready to work.", "Overlooking that different departments can have staggered calls on the same day."], "scenario_contexts": ["A day sheet listing an 8 a.m. crew call for a one-day festival build.", "A local stagehand crew reporting at crew call to help load in a tour.", "A production manager moving crew call earlier when the schedule tightens."]}, "9e12a9b4-6610-4837-a9a5-7d8d1a7c1a76": {"definition": "The practice of one production or rental company renting equipment in from, or out to, another company to fulfill a job when its own inventory is insufficient or unavailable; also called sub-rental.", "plain_english": "When a rental company borrows gear from another company to finish a job. It is like a shop ordering stock from a rival when its own shelf is empty.", "purpose_function": "It lets a company take on work that exceeds its own stock, covering shortfalls without buying gear it would rarely use.", "practical_application": "A rental shop short two line-array boxes cross-rents them from a nearby vendor to complete a client's system.", "category": "Rental Logistics", "related_terms": ["Sub-rental", "Rental house", "Dry hire", "Backline", "Production manager"], "common_mistakes": ["Confusing cross-rental with buying gear; the equipment is only borrowed for the job and returned.", "Failing to check cross-rented gear during prep, then discovering faults on site.", "Not tracking insurance and liability for equipment rented in from another company."], "scenario_contexts": ["A rental house cross-renting extra subwoofers for an unusually large one-off show.", "A regional vendor cross-renting a specific console a client requests but does not own.", "A tour picking up a cross-rental locally to replace a failed amplifier rack."]}, "e5806eda-26a4-4751-b704-1dd5e050a4cc": {"definition": "A cable run routed across the width of the stage, from one side to the other, to connect equipment or feed signal between stage-left and stage-right positions.", "plain_english": "A cable that runs all the way across the stage from one side to the other. Crews use it to link gear on opposite wings.", "purpose_function": "It carries signal or power between the two sides of the stage, connecting positions that a straight upstage or downstage run cannot reach.", "practical_application": "A cable tech lays a cross-stage run under the deck or along the back wall, then covers it with matting where it crosses traffic paths.", "category": "Cabling", "related_terms": ["Cable run", "Copper snake", "Cable ramp", "Stage left", "Stage right"], "common_mistakes": ["UNSAFE: Leaving a cross-stage run uncovered across a walkway or crossover, creating a trip-and-fall hazard.", "Routing the run by the most direct path rather than the safest, most protected one.", "Not allowing enough cable length for the full stage width, leaving the run short."], "scenario_contexts": ["Feeding a stage-right amp rack from a stage-left power source via a cross-stage run.", "Linking two backline positions on opposite wings during a festival build.", "Running a talkback or comms line across the stage to reach a far-side tech."]}, "155abcfd-fcd5-4c79-9ab4-34462300c243": {"definition": "A fixed time, often set by local ordinance, permit, or venue contract, by which amplified sound or the performance must cease; overrunning it can incur fines or a forcibly cut set.", "plain_english": "The set time by which the music must stop. It is usually a local law or venue rule, and going past it can mean fines.", "purpose_function": "It caps how late a show can run to limit noise for the surrounding area, and it drives the day's schedule backward from that deadline.", "practical_application": "A stage manager watches the clock against curfew and may signal the act to wrap up so the show ends legally on time.", "category": "Show scheduling", "related_terms": ["Changeover window", "Set time", "Stage manager", "Crew call", "Load-out"], "common_mistakes": ["Treating curfew as flexible; many are legally enforced with real fines.", "Planning changeovers so tightly that any delay pushes the headliner past curfew.", "Confusing curfew, the hard stop, with set time, when an act is scheduled to begin."], "scenario_contexts": ["An outdoor festival with an 11 p.m. curfew set by the city permit.", "A headliner asked to shorten an encore to stay inside curfew.", "A production manager building the running order backward from the curfew time."]}, "ac2f1a33-7cda-41f6-bdde-7df213fa86c3": {"definition": "Crew shorthand for the AKG D12, a large-diaphragm cardioid dynamic microphone voiced for low-frequency sources such as kick drum and bass cabinets; the widely used AKG D112 is its modern successor.", "plain_english": "A nickname for the AKG D12 microphone, made to capture deep, low sounds. Crews reach for it on kick drums and bass amps.", "purpose_function": "It provides a rugged dynamic microphone with a low-frequency-tailored response, so bass-heavy sources are captured cleanly at high sound levels.", "practical_application": "A stage tech places a D12 inside the kick drum, aiming it near the beater for a punchy low end during input patching.", "category": "Microphone", "related_terms": ["Dynamic microphone", "Cardioid", "DI box", "Line check", "Control position"], "common_mistakes": ["Confusing the D12 with the newer D112, which is its descendant, not the same model.", "Placing the mic without regard to beater position, which changes the attack and tone captured.", "Assuming any dynamic mic gives the same low-end voicing as a purpose-built kick microphone."], "scenario_contexts": ["A monitor tech asking for a D12 on the kick during input patching.", "A crew stocking a D12 in the mic case for bass-heavy stage sources.", "Comparing a D12 to a D112 when choosing a kick drum microphone."]}, "2474db69-2b33-49a0-9548-06055600dd8c": {"definition": "A DAW operator is the crew member who runs a Digital Audio Workstation (DAW) during a production, handling playback of backing tracks, click, and timecode, and often multitrack recording or virtual soundcheck. The role manages session files, cueing, and reliable delivery of pre-recorded elements to the console.", "plain_english": "A DAW operator runs the computer audio software during a show. They play backing tracks, click tracks, and other recordings for the band. They also often record the show for later.", "purpose_function": "The role exists to deliver pre-recorded audio and timing signals reliably during live performance and to capture multitrack recordings, freeing the mix engineers to focus on the live mix.", "practical_application": "A DAW operator loads the show session, checks playback, routing, and timecode before doors, then fires tracks and click on cue while recording the multitrack during the set.", "category": "Crew role", "related_terms": ["Playback operator", "Backing track", "Timecode", "Virtual soundcheck", "Front of house engineer", "Click track"], "common_mistakes": ["Confusing the DAW operator with the front-of-house engineer; the operator supplies playback and recording, not the live mix.", "Assuming one unchecked session file will just work, instead of verifying playback, routing, and timecode before the show.", "Running the show from a single machine with no redundant backup, so a crash silences playback mid-set."], "scenario_contexts": ["A pop tour where the DAW operator fires backing tracks and click to the band's in-ears.", "A broadcast performance recorded to multitrack by the DAW operator for later mixing.", "A virtual soundcheck where the operator plays back a previous show's multitrack for the engineers."]}, "b723cc16-1cef-46cf-ba18-9e315f2c90cf": {"definition": "To de-case is to remove equipment from its road case (flight case) at load-in, unpacking gear so it can be assembled, positioned, and connected. The emptied cases are then cleared to a storage area for the duration of the show.", "plain_english": "To de-case means to take gear out of its road case. Crews do this during load-in so the equipment can be set up. The empty cases are then moved out of the way.", "purpose_function": "De-casing gets equipment out of protective transport cases and ready for setup, and clears the working area of bulky cases before the show.", "practical_application": "At load-in a stagehand de-cases speakers, stands, and cabling, then wheels the empty cases to the case storage area.", "category": "Load-in", "related_terms": ["Load-in", "Road case", "Flight case", "Strike", "Load-out", "Empties"], "common_mistakes": ["Confusing de-casing with load-in as a whole; de-casing is only the unpacking step within load-in.", "Leaving empty cases in walkways or the working area instead of clearing them to storage.", "UNSAFE: Lifting heavy or awkward gear out of a case alone or with poor technique; use team lifts and safe manual-handling practice."], "scenario_contexts": ["A crew de-cases the PA and rigging hardware at the start of load-in.", "A backline tech de-cases and assembles a drum kit before soundcheck.", "Empty cases are wheeled to a storage area after gear is de-cased."]}, "11dfa755-b89c-4a9b-844f-150e3d96895a": {"definition": "The deck crew is the team of stagehands who work on the stage floor (the 'deck') during load-in, the performance, and strike, handling scenery, backline, props, and equipment moves and running scene or set changes. They operate at stage level, typically under a head carpenter or deck chief, as distinct from crew on the fly floor or at front of house.", "plain_english": "The deck crew are the stagehands who work on the stage floor. They move scenery, gear, and props, and handle set changes during the show. 'Deck' is crew slang for the stage floor itself.", "purpose_function": "The deck crew handles the hands-on work at stage level, so scenery and gear are set, moved, and struck safely and on cue during a production.", "practical_application": "During a show the deck crew stands by in the wings, then shifts scenery and backline to marks on cue during scene changes and changeovers.", "category": "Crew role", "related_terms": ["Deck", "Carpenter", "Stagehand", "Head carpenter", "Wings", "Scene change"], "common_mistakes": ["Confusing the deck crew with the fly crew; the deck crew works at stage level, not on the fly floor.", "Assuming deck crew only load in and out, when they also run moves and changes during the performance.", "UNSAFE: Moving heavy scenery or gear on the deck without clear paths, team lifts, and confirmation the area is clear of people."], "scenario_contexts": ["The deck crew shifts scenery to marks during a scene change.", "A deck crew moves backline on and off during a festival changeover.", "The deck crew clears the stage floor of cases and cable after load-in."]}, "ffb1059f-b583-4559-8bc4-8e963e8ade5a": {"definition": "Deck left is touring and stage-crew shorthand for the left-hand side of the stage floor from the performer's viewpoint while facing the audience - the same orientation as stage left. Crews use it to place and call gear, scenery, and positions on the deck.", "plain_english": "Deck left means the left side of the stage. It is judged from the performer's point of view, looking out at the crowd. That is the same as stage left.", "purpose_function": "It gives crew a shared, unambiguous way to name the left side of the stage, so gear and positions are placed and called consistently.", "practical_application": "A stage manager tells the crew to set the guitar amp deck left, meaning stage left, so everyone places it on the correct side.", "category": "Stage geography", "related_terms": ["Deck right", "Stage left", "Deck", "Stage right", "Wings", "Stage manager"], "common_mistakes": ["Reading deck left from the audience's viewpoint; like stage left, it is taken from the performer's perspective facing the crowd.", "Assuming every venue or crew uses the term identically; confirm the reference perspective if in doubt.", "Confusing deck left (a stage-floor side) with a fly-floor or house position."], "scenario_contexts": ["A stage plot marking the keyboard rig deck left.", "A crew chief calling for a riser to be pushed deck left.", "Placing a monitor wedge deck left to match the stage plot."]}, "5b70b7f5-7b4d-4140-a2af-46017aae88e7": {"definition": "Deck right is touring and stage-crew shorthand for the right-hand side of the stage floor from the performer's viewpoint while facing the audience - the same orientation as stage right. Crews use it to place and call gear, scenery, and positions on the deck.", "plain_english": "Deck right means the right side of the stage. It is judged from the performer's point of view, looking out at the crowd. That is the same as stage right.", "purpose_function": "It gives crew a shared, unambiguous way to name the right side of the stage, so gear and positions are placed and called consistently.", "practical_application": "A stage manager tells the crew to set the drum riser deck right, meaning stage right, so it lands on the correct side.", "category": "Stage geography", "related_terms": ["Deck left", "Stage right", "Deck", "Stage left", "Wings", "Stage manager"], "common_mistakes": ["Reading deck right from the audience's viewpoint; like stage right, it is taken from the performer's perspective facing the crowd.", "Assuming every venue or crew uses the term identically; confirm the reference perspective if in doubt.", "Confusing deck right (a stage-floor side) with a fly-floor or house position."], "scenario_contexts": ["A stage plot marking the drum riser deck right.", "A crew chief calling for an amp to be pushed deck right.", "Placing a monitor wedge deck right to match the stage plot."]}, "b2b99526-133a-46bc-92ee-4b6a250d0ea1": {"definition": "A department call is a scheduled report time issued to one specific department of the crew - such as audio, lighting, rigging, or wardrobe - rather than to the whole company. It sets when that department must be present and ready to work, allowing departments to be staggered across a work day.", "plain_english": "A department call is a start time given to just one crew department. For example, audio might be called earlier than lighting. It lets each team arrive when its work begins.", "purpose_function": "It lets production schedule each department's labor to when it is actually needed, controlling costs and avoiding crew standing idle.", "practical_application": "A production schedule might set a rigging department call at 7 a.m. and an audio department call at 9 a.m., so each team arrives as its part of load-in begins.", "category": "Show scheduling", "related_terms": ["Call time", "Company call", "Load-in", "Crew call", "Production schedule", "Department head"], "common_mistakes": ["Confusing a department call with a company call, which brings in the entire crew at once.", "Missing that a department call applies only to your department's report time, not everyone's.", "Assuming all departments share one call, when they are often staggered through the day."], "scenario_contexts": ["A rigging department call set hours before the general crew call.", "An audio department call timed to the start of PA build.", "A wardrobe department call ahead of a matinee performance."]}, "c5c57223-228e-406f-beb5-142b46d5a422": {"definition": "A label identifying where a cable, connector, or road case terminates or belongs: the destination end of a cable run, or the stage location a case is routed to. In two-end cable labeling it names the far end, distinguishing it from the source label.", "plain_english": "A tag that says where a cable or case is meant to end up. Crews read it so every line lands in the right spot on stage.", "purpose_function": "It lets crew rebuild the same signal paths and case layout at every venue quickly, without tracing each cable by hand.", "practical_application": "During load-in a tech reads the destination label on a snake tail to plug it into the correct stage box or amplifier input.", "category": "Cabling", "related_terms": ["Source label", "Snake", "Stage box", "Road case", "Cable management"], "common_mistakes": ["Labeling only one end of a cable, so the destination is unknown once it is disconnected.", "Writing a vague destination that does not match the patch sheet or stage plot.", "Confusing the source label with the destination label and patching the run backward."], "scenario_contexts": ["A monitor tech tracing a wedge feed back to the correct output by its destination label.", "Crew re-rigging a multicore in a new venue and matching each tail to its labeled destination.", "A stagehand routing road cases to their labeled destination positions on the deck."]}, "234bba5a-10ba-4062-930f-c82a259e89f5": {"definition": "DI (direct injection or direct input) is the technique or device for connecting a high-impedance, unbalanced instrument-level source, such as an electric bass or keyboard, to a console's low-impedance, balanced microphone input. A DI box performs the impedance conversion and balancing and often provides ground isolation.", "plain_english": "DI is a way to plug an instrument like a bass straight into the mixer. A small box changes the signal so it travels cleanly down a long cable.", "purpose_function": "It matches an instrument's signal to a mic input's impedance and balance, so the sound stays clean over long cable runs and avoids hum and level loss.", "practical_application": "A stagehand puts a bass guitar or keyboard through a DI so front of house gets a balanced feed on a mic line.", "category": "Signal Interface", "related_terms": ["Direct box", "DI'd", "Balanced signal", "Impedance", "Ground lift", "Stage box"], "common_mistakes": ["Thinking DI just means 'plug it in directly' rather than an impedance and balancing conversion.", "Feeding a loud speaker-level output into an instrument-level DI input not rated for it, risking damage.", "Forgetting DI boxes are passive or active, and that active units need phantom power or a battery."], "scenario_contexts": ["Sending an acoustic-electric guitar to the console through a DI at a live show.", "Splitting a keyboard so one feed goes to stage amps and a DI feed goes to the mixer.", "Taking a DI feed off a bass amp's line output for reinforcement or recording."]}, "9ba3ff77-57b7-4707-85b7-6abe92382c0c": {"definition": "Road-crew shorthand meaning a source has been captured through a DI (direct box) instead of, or in addition to, a microphone; for example, 'the bass is DI'd' means its signal is taken by a direct box.", "plain_english": "'DI'd' means an instrument is plugged into the mixer through a direct box, not picked up by a mic. Crews say a bass is 'DI'd' when its signal comes straight off a box.", "purpose_function": "The term quickly tells the crew a channel's signal comes from a direct box, which affects patching, gain, and whether phantom power is needed.", "practical_application": "A monitor engineer notes the keys are DI'd, so they patch those channels to DI inputs and set gain for a line-level feed.", "category": "Signal Interface", "related_terms": ["DI", "Direct box", "Balanced signal", "Phantom power", "Stage box"], "common_mistakes": ["Assuming a DI'd channel needs a mic; it takes its signal from the direct box instead.", "Forgetting an active DI'd source may need phantom power or a working battery.", "Patching a DI'd source without a DI box, causing hum, level loss, or impedance mismatch."], "scenario_contexts": ["An input list marking the bass as DI'd and the guitar as miked.", "A tech telling front of house the keyboard is DI'd, so no mic stand is set for it.", "Deciding whether an acoustic guitar is DI'd, miked, or both during soundcheck."]}, "156b07ae-5448-4acf-a9a6-551766dacb1d": {"definition": "A direct box (DI box) is an interface device that converts a high-impedance, unbalanced instrument-level signal to a low-impedance, balanced mic-level signal suitable for a console's microphone input over a standard XLR cable. Passive types use a transformer; active types use powered circuitry needing phantom power or a battery.", "plain_english": "A direct box is a small unit that lets an instrument plug into a mixer's mic input. It changes the signal so it runs cleanly down a long stage cable.", "purpose_function": "It matches an instrument to a mic input, allowing long balanced cable runs without hum or signal loss, and often helps break ground loops.", "practical_application": "A stagehand connects a bass to a direct box, then runs an XLR from the box to the stage box, giving front of house a clean balanced feed.", "category": "Signal Interface", "related_terms": ["DI", "DI'd", "Balanced signal", "Impedance", "Ground lift", "Phantom power"], "common_mistakes": ["Confusing passive and active direct boxes; active units need phantom power or a battery.", "Plugging a speaker-level output into a direct box input not rated for it, risking damage.", "Assuming the ground-lift switch lifts mains safety earth; it lifts audio ground only, to fight hum."], "scenario_contexts": ["Sending a keyboard to the console through a direct box at a live gig.", "Using a direct box to break a hum-causing ground loop between backline and the PA.", "Taking a laptop's playback output to the console through a stereo direct box."]}, "eb6e3375-c1c0-4956-b6a9-c269755b04df": {"definition": "A distro (distribution) cart is a mobile, rack- or cart-mounted portable power distribution unit that takes a large feeder input, commonly three-phase via cam-lock single-pole connectors, and splits it into multiple overcurrent-protected branch circuits and receptacles for stage, audio, lighting, and video equipment. It typically includes metering and, where required, ground-fault (GFCI) protection.", "plain_english": "A distro cart is a rolling box that takes one big power feed and splits it into many smaller outlets. It works like a heavy-duty breaker panel on wheels for the show.", "purpose_function": "It divides a single high-current feeder into many breaker-protected circuits, so all the show's gear runs from one supply with overcurrent and fault protection.", "practical_application": "A qualified electrician ties the distro cart's feeder into the venue's company switch, then runs branch circuits from it to audio, lighting, and video positions.", "category": "Crew equipment", "related_terms": ["Company switch", "Cam-lock", "Feeder cable", "GFCI", "Three-phase power", "Overcurrent protection"], "common_mistakes": ["UNSAFE: Connecting or disconnecting cam-lock feeder ends while energized; feeders must be de-energized before connection, with ground and neutral connected first and phases last, by a qualified person.", "UNSAFE: Overloading branch circuits past their breaker rating, or bypassing GFCI protection to stop nuisance trips.", "Assuming any crew member may tie in feeder; portable power tie-in is work for a qualified electrician."], "scenario_contexts": ["Powering a festival stage's audio and lighting from a distro cart fed by a generator.", "An electrician distributing power from a venue company switch through a distro cart to multiple positions.", "Rolling a distro cart near the amplifier world so branch-circuit runs stay short."]}, "1e8371d7-fa59-4a5c-971d-4ce900b50bb1": {"definition": "The loading dock: the area of a venue, usually a raised platform with roll-up doors, where trucks back in so equipment can be loaded into and out of the building at or near truck-bed height.", "plain_english": "The dock is the spot where trucks back up to a venue to unload gear. It is often a raised platform level with the truck floor.", "purpose_function": "It provides a truck-height loading point so heavy cases roll on and off trucks quickly and safely during load-in and load-out.", "practical_application": "Crew stage road cases at the dock, then push them through dock doors or down ramps onto the deck during load-in.", "category": "Load-in / Load-out", "related_terms": ["Dock door", "Dock boss", "Dock call", "Load-in", "Load-out"], "common_mistakes": ["Blocking the dock with staged cases, so trucks cannot back in or crew cannot pass.", "UNSAFE: Standing or working in the gap between a truck and the dock edge, risking a crush or fall injury.", "Assuming every venue has a truck-height dock; some need a liftgate or a ramp instead."], "scenario_contexts": ["Trucks backing into the dock at load-in so crew can unload the tour's cases.", "A production manager scheduling truck arrivals at a single shared dock.", "Load-out staging where all cases return to the dock in packing order."]}, "f6dc423c-b4b2-4e2e-9bf7-2f1422a4e4c4": {"definition": "The dock boss is the crew member responsible for managing the loading dock during load-in and load-out: directing truck backing and sequencing, controlling the flow of road cases on and off trucks, and organizing case staging and truck packing.", "plain_english": "The dock boss is the person in charge of the loading dock. They direct trucks and control how cases move on and off during load-in and load-out.", "purpose_function": "The role keeps the dock orderly and safe, so cases flow in the right order and trucks pack efficiently without bottlenecks or accidents.", "practical_application": "At load-out the dock boss calls which cases roll to the truck next and directs the pack so everything fits and comes off in order at the next stop.", "category": "Crew role", "related_terms": ["Dock", "Dock door", "Truck pack", "Load-out", "Stagehand"], "common_mistakes": ["Confusing the dock boss with the production or stage manager; the dock boss runs the dock, not the whole show.", "Letting cases reach the dock out of packing order, slowing the truck load.", "UNSAFE: Directing a truck to back in without a clear spotter or sightline, risking crew being struck."], "scenario_contexts": ["A dock boss sequencing multiple trucks at a festival load-out.", "Directing which department's cases load first so the truck packs correctly.", "Coordinating with the truck driver and crew during a tight load-in."]}, "cd2ff092-3333-4757-abe3-d866c65ab2e1": {"definition": "The dock call is the scheduled time at which crew must report to the loading dock to begin load-in or load-out; it is the call time specific to dock work.", "plain_english": "The dock call is the time crew has to show up at the loading dock. It is the start time for loading gear in or out.", "purpose_function": "It sets a fixed start time for dock labor, so trucks, crew, and equipment come together and the load-in or load-out runs on schedule.", "practical_application": "A stagehand checks the day sheet for an 8 a.m. dock call and arrives ready to start unloading trucks.", "category": "Load-in / Load-out", "related_terms": ["Dock", "Call time", "Load-in", "Load-out", "Day sheet"], "common_mistakes": ["Confusing the dock call with show call or door time; the dock call is when loading starts.", "Arriving at the dock call without gloves or PPE ready, which delays the unload.", "Missing the dock call, since a short-handed dock crew can push the whole schedule back."], "scenario_contexts": ["A day sheet listing a 7 a.m. dock call for the local crew.", "Crew reporting at the dock call to unload the tour trucks.", "A production manager setting an early dock call to fit a tight load-in."]}, "a96fb6d3-d31d-4d46-acb4-38e91c521571": {"definition": "A dock door is the large roll-up or overhead door at a venue's loading dock through which equipment passes between the trucks or dock and the building interior.", "plain_english": "A dock door is the big roll-up door at a loading dock. Crew push gear through it between the trucks and inside the building.", "purpose_function": "It provides a large opening sized for road cases and equipment to move between the dock and the venue, and it secures the building when closed.", "practical_application": "Crew roll cases through the dock door onto the deck at load-in, and a tech notes its height and width to be sure the largest cases fit.", "category": "Load-in / Load-out", "related_terms": ["Dock", "Dock boss", "Load-in", "Ramp", "Road case"], "common_mistakes": ["Assuming every case fits; some dock doors are too short or narrow for the largest cases or a forklift.", "Blocking or parking cases in the dock door, choking the flow of gear.", "UNSAFE: Standing under a partly open overhead dock door as it is operated, risking a crush injury."], "scenario_contexts": ["Advancing a venue to confirm the dock door height for oversized cases.", "Rolling cases through the dock door onto the stage during load-in.", "Closing and securing the dock door after load-out."]}, "c5d3e8e6-cb96-40ac-ad92-3bb37d5b6213": {"definition": "The vertical height of a loading dock platform above the surrounding ground, built close to the cargo-floor height of a truck or trailer so equipment can be rolled directly across between the vehicle and the building.", "plain_english": "How high a loading dock sits off the ground. It is built near truck-bed height so gear rolls straight from the truck into the building.", "purpose_function": "It lets crew roll heavy cases between truck and venue on the level, speeding load-in and load-out and cutting down on lifting and ramps.", "practical_application": "When advancing a show, a production manager checks whether a venue has a dock-height loading bay or only ground-level access needing a liftgate or ramp.", "category": "Load-in logistics", "related_terms": ["Load-in", "Load-out", "Liftgate", "Ramp", "Loading dock", "Backline"], "common_mistakes": ["Assuming every venue has a dock-height bay; many have only ground-level or stair access that needs a ramp or liftgate.", "UNSAFE: Working near an open, unguarded dock edge, where a fall from dock height can cause serious injury.", "Confusing dock height with the door or ceiling height of the bay, which limits case and truck size separately."], "scenario_contexts": ["A production manager advancing a tour to learn whether trucks can back straight up to a dock.", "Crew rolling road cases across a dock leveler from the trailer into the venue.", "A venue with only ground-level access, forcing use of a truck liftgate at load-in."]}, "37d4dadf-32c6-4ab7-80ed-4bbdbcecb5eb": {"definition": "The scheduled time at which a venue opens its doors to admit the ticketed audience, marking the point by which all stage, sound, and safety preparation must already be complete.", "plain_english": "The time the venue lets the audience in. Once doors open, all the setup and safety checks must already be finished.", "purpose_function": "It sets a hard deadline in the show schedule, driving when load-in, setup, soundcheck, and stage clearing all have to be done.", "practical_application": "A crew works back from 'doors at 7' to schedule load-in and soundcheck, and clears the stage before the house opens.", "category": "Show scheduling", "related_terms": ["Load-in", "Soundcheck", "Curfew", "Changeover window", "House", "Clear stage"], "common_mistakes": ["Confusing doors with show time; doors is when the audience enters, not when the act starts.", "Failing to clear the stage and secure cabling before doors, leaving hazards where the public can reach them.", "Treating the doors time as flexible, when it is usually fixed by the venue and the box office."], "scenario_contexts": ["A stage manager holding the crew to 'doors at 7, show at 8' on the day sheet.", "A production team clearing and securing the stage just before the house opens.", "A support act soundchecking well before doors so the room is ready for the public."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"3340a0ef-cdb5-4bef-9af9-0d477717544c": {"definition": "To route, bundle, and secure cabling neatly along a planned path, using ties, tape, or clamps, so runs are tidy, protected from damage, and kept clear of walkways and moving equipment.", "plain_english": "To lay out and tie cables neatly along a set path. Tidy runs are safer, easier to trace, and less likely to trip people or get damaged.", "purpose_function": "Neat, secured cable runs prevent trip hazards and cable damage, and make it faster to trace and fix a fault during a show.", "practical_application": "After patching, a stagehand dresses the cables along the truss and stage edge, taping runs down and tying them off at regular points.", "category": "Cable management", "related_terms": ["Cable run", "Cable ramp", "Gaffer tape", "Loom", "Snake", "Strain relief"], "common_mistakes": ["UNSAFE: Running undressed cables across walkways or exits, which creates trip hazards and can block egress.", "Taping cables so tightly, or with the wrong tape, that connectors or jackets are damaged on strike.", "Coiling or kinking cable against its natural lay, which stresses the conductors and shortens its life."], "scenario_contexts": ["A stagehand dressing mic and DI lines along the downstage edge before a show.", "Running and taping a power and signal loom across a walkway using cable ramps.", "Tidying and tying off amplifier and speaker cabling inside an equipment rack."]}, "84eb2735-d264-40ec-ac0a-cc288148c22b": {"definition": "A rack of signal-processing equipment sitting between the mixing console and the power amplifiers, holding the loudspeaker-management processing, such as crossover, equalization, limiting, and delay, that conditions the signal sent to drive the PA system.", "plain_english": "The rack of processors between the mixing desk and the amps. It shapes and guards the sound signal before it feeds the loudspeakers.", "purpose_function": "It centralizes system tuning and protection, so the signal to each amplifier and loudspeaker is correctly filtered, time-aligned, equalized, and limited.", "practical_application": "A system tech patches the console output into the drive rack, then sets crossover, delay, and limiter values before the signal reaches the amplifiers.", "category": "System processing", "related_terms": ["Loudspeaker management", "Crossover", "System processor", "Power amplifier", "Line array", "Limiter"], "common_mistakes": ["Confusing the generic drive rack with one specific product; any system-processing rack that drives the amps can be called a drive rack.", "Bypassing or misconfiguring the limiter, which removes the protection that guards drivers from being overpowered.", "Assuming settings transfer between venues, when delay and EQ must be retuned to each room and rig."], "scenario_contexts": ["A system engineer tuning a line array through the drive rack during setup.", "Patching console outputs into the drive rack, then out to the amplifier racks.", "Recalling a drive-rack preset for a known PA, then fine-tuning it to the room."]}, "515102f4-2a48-4a59-b967-44e16fa3ec79": {"definition": "A backline technician who specializes in a drummer's kit: setting up, tuning, maintaining, and repairing the drums, hardware, and percussion, and handling quick fixes and swaps during a performance.", "plain_english": "The crew member who looks after the drummer's kit. They set it up, tune it, and fix problems fast during the show.", "purpose_function": "The role keeps the drum kit playable and consistent night to night, freeing the drummer to perform and handling failures the moment they happen.", "practical_application": "A drum tech builds and tunes the kit before soundcheck, tapes down rugs and stands, and runs on to fix a broken head or pedal mid-set.", "category": "Crew role", "related_terms": ["Drum technician", "Backline", "Backline technician", "Guitar tech", "Stagehand", "Soundcheck"], "common_mistakes": ["Confusing the drum tech with the monitor or front-of-house engineer, who mix sound rather than maintain the kit.", "Assuming the drum tech only sets up; the role also covers tuning and live emergency repairs.", "Overlooking securing rugs, stands, and risers, letting the kit creep or a stand fall during play."], "scenario_contexts": ["A drum tech tuning heads and setting up the kit to its marks before soundcheck.", "Running on stage to swap a broken snare or kick pedal between songs.", "Packing and maintaining the drum hardware during load-out for the next show."]}, "4900f2b1-9db4-4f8d-8ea0-ae8368f92046": {"definition": "The full title for a drum tech: a backline technician responsible for setting up, tuning, maintaining, and repairing a drummer's kit, hardware, and percussion, including rapid repairs and swaps during a performance.", "plain_english": "The full name for a drum tech. This crew member sets up, tunes, and repairs the drummer's kit before and during the show.", "purpose_function": "It names the specialist responsible for the drum kit's condition and reliability, so the drummer can focus on playing.", "practical_application": "Listed on the crew sheet as drum technician, this person builds and tunes the kit and stands by to fix any failure on stage.", "category": "Crew role", "related_terms": ["Drum tech", "Backline technician", "Backline", "Guitar tech", "Stagehand", "Monitor engineer"], "common_mistakes": ["Treating 'drum technician' as a different job from 'drum tech'; they are the formal and informal names for the same role.", "Assuming the role is only about tuning, when it also covers setup, maintenance, and live repairs.", "Confusing the drum technician with the drummer or with a percussionist who performs."], "scenario_contexts": ["A tour crew list naming the drum technician among the backline staff.", "The drum technician maintaining and repairing kit hardware across a tour.", "Building the kit to the drummer's exact marks and tunings before each show."]}, "d1a72750-f9db-44d4-9976-1d5479255af8": {"definition": "The rental of equipment on its own, without any operators, crew, technical services, or consumables supplied by the rental company, leaving the hirer responsible for transport, operation, and safe use.", "plain_english": "Renting just the gear, with no crew or operators included. You collect it, run it yourself, and are responsible for using it safely.", "purpose_function": "It lets a client or production rent equipment at lower cost when they already have the skills and crew to run it themselves.", "practical_application": "A small production dry-hires a PA and lighting rig from a rental house, then supplies its own crew to transport, rig, and operate it.", "category": "Equipment rental", "related_terms": ["Wet hire", "Rental house", "Cross-hire", "Backline", "Load-in", "Production manager"], "common_mistakes": ["Confusing dry hire with wet hire; wet hire includes an operator or crew, while dry hire is gear only.", "UNSAFE: Dry-hiring rigging or electrical gear without competent, qualified crew to install and operate it safely.", "Forgetting that the hirer, not the rental house, is responsible for transport, operation, and returning the gear intact."], "scenario_contexts": ["A band dry-hiring a backline package and moving it in their own van.", "A venue dry-hiring extra loudspeakers to supplement its house system for one show.", "A production company cross-hiring gear on a dry basis to cover a shortfall on a busy weekend."]}, "057dfdec-f80d-4f21-b5e6-cadb481397f0": {"definition": "DS is the standard stage-geography abbreviation for downstage, the area of the stage nearest the audience. The convention comes from historically raked stages that sloped downward toward the front, so moving downstage meant moving toward the lower, audience-facing edge. It is used with US (upstage), SL (stage left), and SR (stage right) as the reference terms crews use to place gear and describe positions.", "plain_english": "DS is short for downstage, the part of the stage closest to the crowd. The name comes from old stages that sloped down toward the front. Crews use DS along with US (upstage), SL (stage left), and SR (stage right) to say where gear goes.", "purpose_function": "It gives the crew a short, shared word for the front area of the stage. That lets gear placement and cues be described quickly and without confusion.", "practical_application": "A stage plot may mark a monitor wedge or a mic position as DS, telling the crew to set it near the front edge of the stage.", "category": "Stage Geography", "related_terms": ["Upstage", "Stage left", "Stage right", "Stage plot", "Marks"], "common_mistakes": ["Reading DS as 'up' toward the back, when downstage is actually the front, nearest the audience", "Confusing stage directions with the audience's point of view; DS, US, SL, and SR are always from the performer's view facing the crowd", "Treating DS as one exact spot rather than the whole front zone of the stage"], "scenario_contexts": ["A stage plot marking a vocal mic position as DS center", "A stage manager telling crew to move a wedge further DS", "Setting a riser US and the guitar amps DS during load-in"]}, "42b3e4ba-6d20-420e-b5e6-2066f32fe649": {"definition": "Ears is live-sound and stage-crew jargon for in-ear monitors (IEMs), small sealed earphones (often custom-moulded) that feed each performer a personal monitor mix instead of, or alongside, floor wedges. A performer said to be 'on ears' is listening to their monitor mix through in-ear monitors rather than stage wedges.", "plain_english": "Ears is crew slang for in-ear monitors. These are small earphones that give a performer their own mix on stage. Being 'on ears' means listening through them instead of floor speakers.", "purpose_function": "In-ear monitors give each performer a clear, consistent personal mix and seal out stage noise, which lets the performer set their own listening level and can lower overall stage volume.", "practical_application": "A monitor engineer builds and rings out each performer's ears mix, and a musician may switch from wedges to ears to get a cleaner, quieter personal monitor feed.", "category": "Crew equipment", "related_terms": ["In-ear monitors", "Monitor mix", "Monitor engineer", "Wedge", "Cans", "Belt pack"], "common_mistakes": ["Assuming ears always means custom-moulded models, when the term also covers universal-fit in-ear monitors", "Thinking ears remove the need for a monitor engineer, when the personal mix still has to be built and balanced", "UNSAFE: Turning the in-ear level up too high to beat crowd noise, which risks hearing damage; keep levels moderate and follow hearing-conservation practice"], "scenario_contexts": ["A singer asking for more vocal in their ears during soundcheck", "A monitor engineer switching a drummer from a wedge to ears to cut stage volume", "A guitarist losing one earpiece and asking the crew to check the belt pack"]}, "f6ecba2b-6e3c-4bc7-a4c6-5a015302253f": {"definition": "Empty cases are the road cases left over once their gear has been unpacked and set during load-in. For the duration of the show they are wheeled clear of the working area and stored together (an area often called the boneyard), then brought back to repack the gear at load-out.", "plain_english": "Empty cases are the road boxes left after the gear is unpacked. During the show the crew rolls them out of the way. They are brought back to pack everything up at the end.", "purpose_function": "Grouping empty cases out of the work area keeps the stage and wings clear and safe during the show. It also keeps the cases ready and organised for a fast load-out.", "practical_application": "After load-in the crew wheels all empty cases to a storage area off stage, then retrieves them to repack each department's gear at load-out.", "category": "Load-in / Load-out", "related_terms": ["Road case", "Boneyard", "Load-in", "Load-out", "Cable trunk", "Strike"], "common_mistakes": ["UNSAFE: Leaving empty cases in walkways, fire exits, or the wings, which blocks paths and creates trip and struck-by hazards; keep egress and work routes clear", "Losing case lids or foam inserts, so gear cannot be safely repacked at load-out", "Mixing up cases between departments, which slows down repacking"], "scenario_contexts": ["Rolling empty cases to the boneyard after load-in", "Keeping fire exits and cable paths clear of empty cases during the show", "Matching empty cases back to each department's gear at load-out"]}, "b6b793b3-13f1-4917-959e-9c3eca950b88": {"definition": "An encore is an additional piece or set performed after the planned programme has ended, given in response to sustained audience applause; by extension the word also names the audience's demand for that repeat performance. On a touring show the encore is usually pre-planned, so crew and operators treat the 'encore break' as a scripted pause before a known final segment.", "plain_english": "An encore is an extra song or set played after the main show, when the crowd keeps cheering. On most tours it is planned in advance. The crew treats the encore break as a short, scripted pause before the last part.", "purpose_function": "The encore lets the artists respond to the crowd and end on a high point. Because it is usually planned, it also gives the crew a known cue to reset and prepare the final segment.", "practical_application": "During the encore break the crew may swap an instrument, reset a mark, or prep an effect, then run the encore as rehearsed.", "category": "Show operations", "related_terms": ["Set list", "Encore break", "Show caller", "Cue", "Load-out"], "common_mistakes": ["Assuming every encore is spontaneous, when on tours it is normally planned and rehearsed", "Starting load-out or striking gear before the encore, when the show is not actually over", "Missing the encore's cues because the break is treated as downtime rather than a scripted reset"], "scenario_contexts": ["A crew resetting a guitar and mic during the encore break", "A show caller cueing lights and video for a planned encore", "A stage manager holding load-out until after the encore"]}, "57dd2983-8cc0-4cd0-8f1d-afd973e49c76": {"definition": "Equivalent substitution is the practice of supplying a product other than the one specifically named in a rider, specification, or purchase order, on the basis that it meets the same performance, quality, and feature requirements. It is normally permitted only where the document allows an 'or equal' substitution and, where required, the substitute is approved by the specifier or client in advance.", "plain_english": "Equivalent substitution means using a different make or model in place of the one that was asked for. The swap is only okay if the new item does the same job just as well. Often it must be approved first.", "purpose_function": "It gives flexibility when the exact named item is unavailable, delayed, or too costly. At the same time it protects quality by requiring the substitute to truly match the stated requirements.", "practical_application": "When a rider calls for a specific console that a venue does not own, the audio crew offers an equivalent model and confirms it is acceptable before the show.", "category": "Specifications", "related_terms": ["Approved equal", "Technical rider", "Specification", "Substitution", "Backline"], "common_mistakes": ["Assuming any similar-looking item qualifies, when it must actually meet the stated performance and feature requirements", "Swapping in a substitute without getting the required approval first, then having it rejected", "Treating equivalent substitution as a chance to supply the cheapest option regardless of the spec"], "scenario_contexts": ["Offering an equivalent console when the rider's exact model is unavailable", "A production manager approving an equivalent wireless system before load-in", "Sourcing an equivalent amplifier when the specified model has a long lead time"]}, "bc8c47e2-c57e-4ea1-ad2f-5630492caf7e": {"definition": "A false start is a take or performance that is begun and then aborted almost immediately, because of a count-in error, a wrong tempo or key, a technical fault, or a mistake, so the piece is stopped and restarted from the top. In both live shows and recording sessions, a false start means the run did not really begin and must be reset and run again.", "plain_english": "A false start is when a song or take begins and then stops right away. It might be a bad count-in, a wrong tempo, or a technical fault. The piece is reset and started again from the top.", "purpose_function": "Naming a false start tells everyone that the run did not count. That lets the crew, operators, and performers reset cleanly and start over instead of pushing on from a broken take.", "practical_application": "In a session the engineer logs a false start and rolls back to record a fresh take, while at a show the crew resets cues and marks so the number can start again.", "category": "Show operations", "related_terms": ["Take", "Count-in", "Line check", "Cue", "Set list"], "common_mistakes": ["Confusing a false start with a full take or performance, when a false start does not count and must be redone", "Failing to reset cues, marks, or the recording before restarting after a false start", "Blaming the performers, when a false start is often caused by a technical or monitor fault"], "scenario_contexts": ["A band stopping a few bars in and restarting after a false start", "A recording engineer logging a false start and punching in a new take", "A monitor fault causing a false start that the crew must fix before the retry"]}, "c4eb5aad-4509-406a-87c1-4923c62c7500": {"definition": "A feeder trunk is a large wheeled road case built to store and transport feeder cable, the heavy portable power cable (commonly single-conductor, cam-lock-terminated) that carries mains power from a supply tie-in or disconnect to the show's power distribution. The trunk protects the cable in transit and keeps the runs coiled, organised, and ready to deploy at load-in.", "plain_english": "A feeder trunk is a big rolling case for feeder cable. Feeder cable is heavy power cable that carries mains power from the supply to the show's power distribution (the distro). The case protects the cable and keeps it sorted.", "purpose_function": "It protects heavy, costly power cable from damage and keeps each run organised. That lets the electrics crew deploy and recover the feeder quickly and in order.", "practical_application": "At load-in the electrician pulls feeder from the trunk to run from the tie-in to the distro, then coils it back into the trunk at load-out.", "category": "Road Cases", "related_terms": ["Feeder cable", "Cam-lock", "Power distribution", "Cable trunk", "Tie-in", "Distro"], "common_mistakes": ["UNSAFE: Connecting or disconnecting cam-lock feeder ends while the supply is energized; the source must be de-energized, verified dead, and connections made in the correct sequence before feeder is handled", "UNSAFE: Overloading a feeder trunk and then lifting or moving it without a team lift or proper handling, risking manual-handling injury", "Coiling feeder badly into the trunk, which kinks and damages the conductors and slows the next load-in", "Assuming any road case is a feeder trunk, when feeder cable's size and weight need a case built and rated for it"], "scenario_contexts": ["Pulling feeder from the trunk to run from the disconnect to the distro at load-in", "An electrician coiling feeder back into its trunk at load-out", "Labelling feeder trunks by run so they reach the right tie-in point"]}, "c3d7b6ab-4833-4750-9f40-1067452bb482": {"definition": "A festival changeover is the fast, time-limited transition between two acts on a shared festival stage, in which one act's backline and stage gear are struck and the next act's are set to marks, patched, and line-checked within a fixed slot. Because a festival stage runs many acts back to back, the changeover is tightly rehearsed and run against the clock to keep the day on schedule.", "plain_english": "A festival changeover is the quick switch between two bands on the same stage. The crew clears one act's gear and sets up the next within a set time. It is timed tightly so the festival stays on schedule.", "purpose_function": "It resets a shared festival stage from one act to the next as fast and accurately as possible. That keeps a packed line-up of bands running to time without long gaps for the crowd.", "practical_application": "The stage crew works the changeover from stage plots and input lists, rolling risers on and off and re-patching so the next act can line-check inside its slot.", "category": "Show operations", "related_terms": ["Changeover", "Changeover crew", "Backline", "Stage plot", "Line check", "Riser"], "common_mistakes": ["Treating a festival changeover as a relaxed set-up rather than a timed strike, set, patch, and line-check run", "Not working from the stage plot and input list, which causes patch errors that eat the short slot", "UNSAFE: Rushing heavy risers and backline without teamwork or clear routes, risking manual-handling and struck-by injuries; keep paths and cable runs clear"], "scenario_contexts": ["A festival stage running a 15-to-20-minute changeover between bands", "Rolling the next act's drum riser on during a festival changeover", "The next band line-checking its inputs at the end of a festival changeover"]}, "13f7ca3a-409b-4434-bf70-c651927f820a": {"definition": "A festival console is the large-format mixing console provided as the shared house desk on a festival stage, worked by successive acts' engineers or by a house engineer across the day. It is configured for rapid changeovers, typically using stored scenes or snapshots so each act's settings can be recalled quickly between short line checks.", "plain_english": "A festival console is one big mixing desk that many bands share at a festival. Each act has settings that are saved and recalled fast between sets. This lets a new band start with little setup time.", "purpose_function": "It lets many acts share one house desk on a tight schedule, using saved scenes so each band's mix can be recalled in the short gap between sets.", "practical_application": "A house engineer loads or recalls each act's scene on the festival console during changeover, then runs a quick line check before the set.", "category": "Consoles", "related_terms": ["Snapshot", "Line check", "Changeover", "Festival patch discipline", "Festival input list"], "common_mistakes": ["Assuming the festival console can be fully reconfigured per act, when the shared patch and input list must stay consistent for fast changeovers", "Forgetting to save or recall the correct scene, so the next act starts from the previous band's settings", "Treating the festival console like a private touring desk and rewiring the patch, which breaks the shared setup"], "scenario_contexts": ["A house engineer recalling each band's scene on the festival console during a ten-minute changeover", "A visiting engineer loading a saved show file onto the festival console before a set", "Several acts sharing one festival console across a long festival day"]}, "73f46495-4948-4aa9-a23e-c5eabde201f4": {"definition": "A festival gain strategy is a deliberate approach to setting input gain (preamp trim) and overall gain structure for a festival stage where many acts share one system with minimal line-check time. It favours conservative, consistent preamp levels and saved settings so channels keep adequate headroom and stable gain-before-feedback across unfamiliar acts.", "plain_english": "A festival gain strategy is a plan for setting input levels when many bands share one system. The engineer keeps levels safe and steady so nothing distorts or feeds back. Saved settings speed up each quick soundcheck.", "purpose_function": "It keeps input levels safe and repeatable across many acts with little check time, protecting headroom and reducing the risk of clipping or feedback.", "practical_application": "An engineer sets conservative preamp gain and saves it per channel, then trims quickly during each act's short line check.", "category": "Gain Structure", "related_terms": ["Gain structure", "Headroom", "Line check", "Gain before feedback", "Festival console"], "common_mistakes": ["Setting gain too hot to chase level, leaving no headroom and risking clipping when a louder act plays", "Rebuilding the whole gain structure for every act, which wastes the little check time available", "Confusing input gain with channel fader level, and trying to fix a level problem in the wrong place"], "scenario_contexts": ["An engineer setting conservative preamp gain before a day of fast festival changeovers", "Trimming gain during a two-song line check without a full soundcheck", "Keeping consistent gain structure so saved scenes recall predictably for each act"]}, "0861cef8-f20f-4209-bf93-4b471a800f7a": {"definition": "A festival input list is a consolidated master list of all input channels for a festival stage, combining the requirements of every scheduled act into one superset. It defines channel numbers, sources, microphone or DI types, and placement notes so a single shared patch can serve all acts.", "plain_english": "A festival input list is one master list of every input a stage needs for the day. It combines what all the bands ask for into a single plan. The crew uses it to wire one patch that works for everyone.", "purpose_function": "It merges every act's input needs into one shared plan, so the stage can be patched once and reused for all acts with minimal re-patching.", "practical_application": "The stage crew builds the shared patch from the festival input list, then each act maps onto the agreed channels during changeover.", "category": "Documentation", "related_terms": ["Input list", "Patch", "Festival patch discipline", "Stage plot", "Festival console"], "common_mistakes": ["Treating each act's list separately instead of merging them into one shared superset", "Leaving out mic, DI, or stand details, so the patch cannot be built from the list alone", "Not numbering channels consistently, which breaks the shared patch during changeovers"], "scenario_contexts": ["A stage manager compiling every act's inputs into one festival input list before the event", "Crew wiring the shared stage patch from the consolidated festival input list", "An act mapping its inputs onto the agreed channels from the festival input list"]}, "50bc4c56-af11-437c-8805-b681fb200a19": {"definition": "Festival patch discipline is the practice of keeping the input patch on a shared festival stage strict, consistent, and documented so it stays predictable across many acts. Channels are not re-patched arbitrarily; each act maps onto the agreed shared assignments defined by the festival input list.", "plain_english": "Festival patch discipline means keeping the stage wiring the same for every band. Nobody re-plugs channels on a whim. This keeps the shared setup predictable so changeovers stay fast and mistakes stay rare.", "purpose_function": "It keeps the shared patch stable so any act's inputs land on known channels, which speeds changeovers and prevents patch errors during a busy day.", "practical_application": "Stage crew hold the patch to the agreed layout and label it clearly, so each act's inputs land on the same channels without rewiring.", "category": "Stage Management", "related_terms": ["Patch", "Festival input list", "Festival console", "Line check", "Stage plot"], "common_mistakes": ["Re-patching channels for one act's convenience, which breaks the shared layout for everyone after them", "Failing to label the patch, so the next crew cannot tell what is plugged where", "Assuming a quick unlabelled change will be remembered, then losing track during a fast changeover"], "scenario_contexts": ["Crew holding a consistent stage patch across a dozen acts on one festival day", "Labelling every channel so any engineer can read the shared patch at a glance", "Refusing an ad-hoc re-patch request to protect the shared festival layout"]}, "f54c662b-84c7-4252-a70f-e98ecc2e6e5a": {"definition": "A fiber run is a length of fiber-optic cable installed to carry digital audio, network, or video signals between positions such as the stage and the front-of-house or broadcast area. Because it carries light rather than electrical current, it transports many channels over long distances, is immune to electromagnetic interference, and needs no shielding or ground reference.", "plain_english": "A fiber run is a fiber-optic cable laid between two points, like the stage and the mixing spot. It sends signals as light, not electricity. So it can carry many channels a long way without picking up electrical noise.", "purpose_function": "It moves large amounts of digital signal over long distances without interference or grounding problems, replacing many heavy copper cables with one light-carrying line.", "practical_application": "Crew run a fiber line from stage to front of house for a digital audio network such as MADI or Dante, then protect and terminate it carefully at each end.", "category": "Cabling", "related_terms": ["Multicore", "MADI", "Dante", "Cable path", "Cable pull"], "common_mistakes": ["Kinking or over-bending the fiber past its minimum bend radius, which cracks the glass and breaks the link", "Leaving connector ends uncapped, so dust or dirt on the ferrule causes signal loss", "Assuming any fiber suits any distance, when single-mode and multimode fit different run lengths"], "scenario_contexts": ["Running a fiber line from stage to front of house to carry a digital audio network", "Using a fiber run for a long throw to a broadcast truck where copper would be too lossy", "Protecting a fiber run across a cable path so it is not crushed or over-bent"]}, "24e852ed-d324-4667-80da-0486bdc272c9": {"definition": "A file compatibility check is the step of confirming that a saved show, session, or scene file will load correctly on the target device and its software or firmware version before it is relied on. On digital consoles and DAWs it verifies that the file's format and version match the system that must open it, so settings recall as intended.", "plain_english": "A file compatibility check makes sure a saved show file will open on the gear you will use. You confirm the file matches the console or software version first. This avoids nasty surprises when settings fail to load.", "purpose_function": "It catches format or version mismatches before showtime, so a saved show, session, or scene file loads and recalls correctly instead of failing when it is needed.", "practical_application": "Before a show, an engineer loads the show file onto the actual console and firmware version to confirm it opens and recalls settings correctly.", "category": "Workflow", "related_terms": ["Show file", "Festival console", "Snapshot", "Firmware", "Line check"], "common_mistakes": ["Assuming a show file opens on any console model or firmware, when versions can differ and fail to load", "Checking the file only at showtime, leaving no time to fix a mismatch", "Not keeping a backup in a widely compatible format, so one failed load has no fallback"], "scenario_contexts": ["Loading a show file onto the venue's console and firmware version during setup to confirm it opens", "Checking a session opens on the studio's DAW version before a client arrives", "Confirming a festival console's firmware matches a visiting engineer's saved show file"]}, "31d8445a-b697-4a76-b666-f6bd7dd7a42f": {"definition": "The act of loading a previously saved show or session file into a digital mixing console or control system, restoring its stored settings, patching, scenes and parameters ready for a performance.", "plain_english": "Loading a saved settings file into a digital mixing desk. It brings back the whole setup from a past show, so the crew does not build it again from scratch.", "purpose_function": "It restores a complete, known-good configuration quickly, so a show is set up the same way every time instead of rebuilding each setting by hand.", "practical_application": "At load-in a systems engineer loads the tour's show file onto the front-of-house console, checking that the firmware and file version match before recalling scenes.", "category": "Console operation", "related_terms": ["Show file", "Scene recall", "Firmware mismatch", "Console", "Patching"], "common_mistakes": ["Loading a file saved under a different firmware version, which can misload settings or crash the console.", "Assuming a loaded file still matches the physical patch when inputs may have been moved.", "Not saving a fresh backup before loading, so the wrong file overwrites current work."], "scenario_contexts": ["A touring engineer recalling the band's show file at each new venue.", "A support act loading its own file onto a shared house console during changeover.", "A tech restoring a backup file after a console reboot mid-show."]}, "a454bf1c-adde-4821-bd01-afbf173d117e": {"definition": "A condition in which two or more interconnected devices, such as a console and its stageboxes, networked audio nodes, or wireless transmitters and receivers, run incompatible firmware versions, causing failed communication, missing features, or unstable operation.", "plain_english": "When two pieces of gear run different software versions that do not agree. Like apps that will not talk until both are updated, the devices may fail to connect or act strangely.", "purpose_function": "Naming this fault class helps technicians fix the root cause, by aligning firmware versions, rather than chasing the symptoms.", "practical_application": "When a stagebox will not link to the console, a tech checks both firmware versions and updates them to a matching, tested release before the show.", "category": "Troubleshooting", "related_terms": ["Firmware", "File load", "Digital snake", "Dante", "Show file"], "common_mistakes": ["Updating one device to the latest firmware but not its partners, which creates the mismatch.", "Blaming cables or the network for a fault that is really a version conflict.", "Updating firmware on-site right before doors, leaving no time to recover if it fails."], "scenario_contexts": ["A console and stagebox from the same maker refusing to connect after one was updated.", "Wireless mics losing sync because transmitters and receivers run different firmware.", "A networked audio device dropping off after a partial system update."]}, "375116fd-9572-4079-b946-ba131299e785": {"definition": "The rapidly evolving front-of-house mix during the opening song of a set, when the engineer first hears the system at full performance level with the audience present and quickly adjusts balances, gain structure and effects toward the intended sound.", "plain_english": "The mix the sound engineer dials in during the first song. The full crowd and real volume finally show how it sounds. So the engineer makes fast changes to get it right.", "purpose_function": "It reflects that a soundcheck cannot predict a full, warm room, so the opening song is when the engineer settles the true working mix.", "practical_application": "An FOH engineer rides faders hard through the opener, correcting vocal level and low-end buildup that only appear once the room is packed.", "category": "Mixing", "related_terms": ["Front of house", "Soundcheck", "Line check", "Gain structure", "Mix"], "common_mistakes": ["Expecting the soundcheck mix to translate unchanged to a full, loud room.", "Over-processing during the first song instead of making small, reversible moves.", "Judging the mix only from the console position rather than checking other spots."], "scenario_contexts": ["A club engineer fixing feedback and vocal balance as the headliner opens.", "A festival FOH engineer adapting fast when a guest act skips soundcheck.", "A monitor engineer refining stage foldback during the band's first number."]}, "7599649e-ddd0-4933-a47d-cfeeb73228e7": {"definition": "A standard time call given by stage management warning performers and crew that the performance, or its resumption after an interval, will begin in about five minutes; it is part of the sequence of calls leading to 'places'.", "plain_english": "A warning that the show starts in about five minutes. Stage managers call it so everyone gets ready and moves to their spots.", "purpose_function": "It puts cast and crew on a shared countdown, so the show can start on time with everyone in position and ready.", "practical_application": "The stage manager calls 'five minutes' over the backstage intercom, prompting the crew to clear the stage and take their show positions.", "category": "Stage calls", "related_terms": ["Places", "Half hour", "Cue", "Stage manager", "Curfew"], "common_mistakes": ["Treating 'five minutes' as exact rather than an approximate warning call.", "Missing the call because in-ear monitors or ear protection block the intercom.", "Confusing the backstage crew calls with the audience front-of-house calls."], "scenario_contexts": ["A theatre stage manager giving the calls before curtain up.", "A touring crew called five minutes before the headliner's downbeat.", "A stage manager calling five minutes to resume after an interval."]}, "412a1264-3b78-4050-a18f-09634be35a69": {"definition": "A rugged, reinforced transport case, typically built from plywood or composite panels with extruded aluminium edging, ball corners, recessed latches and handles, and a foam-lined interior, made to protect audio, lighting or instrument equipment during repeated touring and shipping.", "plain_english": "A tough padded box for moving gear on tour. Its hard shell, metal corners and foam inside guard equipment against knocks and rough handling.", "purpose_function": "It shields fragile, costly equipment from impact, vibration and dust in transit, and standardises packing so gear loads and unloads quickly.", "practical_application": "Crew wheel racked amplifiers in flight cases off the truck at load-in, then strike and repack the same cases at load-out.", "category": "Transport", "related_terms": ["Road case", "Rack", "Load-in", "Load-out", "Truck pack"], "common_mistakes": ["Overloading a case beyond a safe handling weight, risking dropped gear or injury.", "UNSAFE: Lifting a heavy flight case alone instead of using a team lift or handling aids, which risks back injury.", "Not latching every catch before wheeling, so the lid or gear can fall out."], "scenario_contexts": ["A tour packing consoles and racks into flight cases for truck transport.", "A fly date shipping band backline in cases as air cargo.", "A rental house prepping cased systems for a one-off corporate event."]}, "a94357f8-91f9-4e18-8d3a-e52493d2ce6e": {"definition": "A crew member who is not fixed to one department or position but moves between tasks as needed across load-in, the show and load-out, supplying extra hands wherever the work demands.", "plain_english": "A crew member with no single fixed job. They move around and help wherever an extra pair of hands is needed.", "purpose_function": "It gives a production flexible labour to absorb bottlenecks, so busy departments get help without over-staffing every position.", "practical_application": "A stage manager sends a floater to help push cases, then reassigns them to the audio crew once the truck is unloaded.", "category": "Crew roles", "related_terms": ["Local crew", "Stagehand", "Load-in", "Load-out", "Runner"], "common_mistakes": ["Assuming a floater knows a specialist task without a proper briefing.", "Leaving a floater idle instead of directing them where help is needed.", "UNSAFE: Sending a floater into a rigging or electrical task they are not trained and qualified for."], "scenario_contexts": ["A festival moving floaters to whichever stage is running behind.", "A load-in where a floater carries cases, then assists the department that needs it most.", "A corporate event keeping a floater on hand for last-minute setup changes."]}, "896ef7bf-6610-4766-851f-88e4885990b4": {"definition": "In an overhead rigging or fly system, the act of lowering a flown load, such as a batten, scenery piece, PA, or lighting truss, down toward the stage deck into its working ('in') position.", "plain_english": "Lowering rigged gear down toward the stage. In fly-system talk, 'in' means down at stage level, where the piece is used.", "purpose_function": "It moves a suspended load from its stored overhead height down to the working position needed for setup, focus, or the performance.", "practical_application": "A rigger calls the move as a lighting truss is flown in to a low trim so technicians can focus the fixtures from a lift.", "category": "Rigging", "related_terms": ["Flying out", "Fly system", "Trim", "Rigging", "Truss"], "common_mistakes": ["Confusing the fly convention: 'in' means down to the deck, not up.", "UNSAFE: Standing or working under a moving flown load instead of staying clear until it is trimmed and secured.", "UNSAFE: Flying a load without a trained rigger, inspected hardware, and rated capacity."], "scenario_contexts": ["Lowering a lighting truss to focus fixtures before flying it back to show trim.", "Bringing a flown backdrop down to the deck for a scene.", "Trimming a flown PA down into its final position during setup."]}, "c25b1250-8d99-473e-a3c7-76ce25792aea": {"definition": "In an overhead rigging or fly system, the act of raising a flown load up and away from the stage into the overhead space (fly loft or grid), clearing it from the deck and from the audience's sightlines into its stored ('out') position.", "plain_english": "Raising rigged gear up above the stage, out of sight. In fly-system talk, 'out' means high up and away from the deck.", "purpose_function": "It lifts a suspended load clear of the stage so it can be stored overhead, hidden from view, or moved out of the way of other work.", "practical_application": "After focusing, the crew flies the truss out to show trim, lifting it clear of the performers below.", "category": "Rigging", "related_terms": ["Flying in", "Fly system", "Trim", "Rigging", "Grid"], "common_mistakes": ["Confusing the fly convention: 'out' means up into the loft, not toward the audience.", "UNSAFE: Flying a load out over people without clearing the area and warning the crew first.", "UNSAFE: Exceeding the rated capacity of the rigging point, line set, or hoist when flying a load."], "scenario_contexts": ["Raising a backdrop out of view between scenes.", "Flying a lighting truss out to show trim after focus.", "Clearing a flown element up and away to make room for a set change."]}, "dcec2277-7eb4-485f-b06f-973dd788b8c5": {"definition": "The practice of suspending the main loudspeaker system overhead from certified rigging points, hoists, or truss, rather than stacking it on the ground, so the arrays hang above and in front of the audience.", "plain_english": "Hanging the main speakers up in the air instead of stacking them on the floor. They hang from rigging points high above the crowd so the sound reaches everyone.", "purpose_function": "Flying the PA raises the loudspeakers for even coverage and long throw across the audience, and it clears sightlines and floor space at stage level.", "practical_application": "A rigging crew attaches the line-array frame to rated motors and truss, then lifts the array to trim height while ground crew keep the area below clear.", "category": "PA rigging", "related_terms": ["Line array", "Rigging point", "Chain hoist", "Truss", "Ground stack", "Flyman"], "common_mistakes": ["UNSAFE: Flying loudspeakers from points or hardware not rated and certified for the load, or without a secondary safety attachment where required.", "UNSAFE: Standing or working directly beneath a suspended array during a lift instead of keeping the area clear.", "Ignoring the manufacturer's rigging manual for permitted frame angles, array size, and load limits.", "Confusing flying the PA with a ground stack; a flown array hangs from rigging while a ground stack sits on the deck or subs."], "scenario_contexts": ["A touring line array flown from motors under a festival stage roof.", "An arena show hanging main and side-hang arrays from house rigging points.", "A crew choosing to fly the PA to clear floor space and improve coverage in a theater."]}, "d478e7fc-f9ce-4ca1-a0b3-69a198dd06f8": {"definition": "A stage crew member who operates the fly system, raising and lowering scenery, drapes, lighting battens, or other loads suspended above the stage from the fly floor or grid.", "plain_english": "The crew member who raises and lowers scenery and curtains hung above the stage. They work the ropes and counterweights from the side or high up.", "purpose_function": "The flyman executes fly cues so overhead loads move safely and on time during a performance or set change.", "practical_application": "On a theatrical show the flyman loads counterweight to balance a batten, then flies drops in and out on the stage manager's cues.", "category": "Crew role", "related_terms": ["Fly system", "Counterweight", "Batten", "Fly cue", "Rigger", "Grid"], "common_mistakes": ["UNSAFE: Operating a counterweight line set that is out of balance, which can cause a runaway batten or arbor.", "UNSAFE: Flying a load before the deck is confirmed clear of people below.", "Assuming any stagehand can fly cues without training on that specific rigging system."], "scenario_contexts": ["A theater flyman flying in a backdrop during a scene change.", "Loading counterweight to balance a lighting batten before a show.", "Working the grid to fly out borders and legs during a strike."]}, "1f035b9e-1a9c-4440-bcba-40698c7bda45": {"definition": "The audio engineer responsible for the front-of-house mix, the sound the audience hears, operating the main mixing console at the front-of-house position and controlling the main loudspeaker system.", "plain_english": "The engineer who mixes the sound the audience hears. They run the main mixing desk out in the crowd and control the big speakers.", "purpose_function": "The FOH engineer balances all sources into one mix for the room, so the audience hears a clear, well-leveled blend during the show.", "practical_application": "At a concert the FOH engineer sets gains, EQ, and effects at the house console, then rides faders through the set to keep the mix balanced.", "category": "Crew role", "related_terms": ["Front-of-house mix", "Front of house", "Monitor engineer", "Mixing console", "Line array", "Soundcheck"], "common_mistakes": ["Confusing the FOH engineer with the monitor engineer, who mixes what performers hear on stage.", "Assuming the FOH engineer always runs monitors too; larger tours split the two roles.", "UNSAFE: Mixing at damaging sound levels for long periods without hearing protection or level monitoring."], "scenario_contexts": ["A touring FOH engineer mixing a headline set from the house position.", "A festival FOH engineer taking over the house console for a guest act.", "A house engineer mixing front of house for a local venue's events."]}, "08629c8e-b84c-4494-a352-5f9215cfff46": {"definition": "A route or area at a venue that is sized, cleared, and load-rated to allow a forklift to reach, lift, and move palletized or heavy equipment during load-in and load-out.", "plain_english": "A path or space wide and strong enough for a forklift to get through. It lets crew move heavy gear on pallets in and out of the venue.", "purpose_function": "Forklift access lets crews move heavy staging, cases, and pallets quickly and safely, reducing manual lifting during load-in and load-out.", "practical_application": "A production manager checks a venue for forklift access when advancing a show, confirming door widths, floor loading, and a clear route to the stage.", "category": "Load-in / Load-out", "related_terms": ["Load-in", "Freight path", "Loading dock", "Flight case", "Production manager"], "common_mistakes": ["UNSAFE: Allowing untrained or uncertified staff to operate a forklift, contrary to powered-industrial-truck operator training rules.", "UNSAFE: Exceeding the floor's rated loading or the forklift's rated capacity when moving heavy gear.", "Assuming a doorway or elevator is wide or strong enough without measuring it and checking its ratings."], "scenario_contexts": ["Advancing an arena show to confirm forklift access from the dock to the stage.", "Using a forklift to move palletized line-array cases during load-in.", "A venue with narrow doors that blocks forklift access, forcing manual handling."]}, "724077db-c35a-4737-89b0-bafb341c394d": {"definition": "A sound engineer who works independently on a per-project, per-tour, or per-day basis for multiple clients, rather than as a salaried employee of one venue, studio, or production company.", "plain_english": "A sound engineer who works for themselves, hired job by job. They move between tours, venues, or studios instead of having one steady employer.", "purpose_function": "Freelancing lets a production bring in specialist skills only when needed, and lets engineers work across many acts and venues.", "practical_application": "A freelance engineer books work through contacts or an agent, invoices per show or per week, and carries their own tools and knowledge of common consoles.", "category": "Crew role", "related_terms": ["FOH engineer", "Monitor engineer", "Systems engineer", "Production manager", "Tour"], "common_mistakes": ["Assuming a freelance engineer is less skilled than staff; many are highly experienced specialists.", "Confusing freelance with casual day labor; a freelance engineer is an independent professional.", "Overlooking that freelancers manage their own contracts, insurance, and tax."], "scenario_contexts": ["A band hiring a freelance FOH engineer for a summer tour.", "A studio calling in a freelance engineer for a specific recording session.", "A festival contracting freelance engineers to cover multiple stages."]}, "94cb5c22-c16d-4425-ac33-c2320ac36b08": {"definition": "The designated route through a venue, from the loading dock or truck to the stage or storage area, along which flight cases and equipment are moved during load-in and load-out.", "plain_english": "The planned route for moving gear from the trucks to the stage. Crew keep this path clear so heavy cases can roll through easily.", "purpose_function": "A clear freight path speeds load-in and load-out and keeps heavy rolling loads away from people and obstructions.", "practical_application": "A crew chief walks and clears the freight path before the trucks arrive, checking ramps, tight corners, and doors wide enough for the largest cases.", "category": "Load-in / Load-out", "related_terms": ["Load-in", "Forklift access", "Loading dock", "Flight case", "Freight elevator"], "common_mistakes": ["UNSAFE: Blocking the freight path with cables, cases, or people so heavy carts cannot pass safely.", "Failing to check that doors, ramps, and elevators along the path fit the largest cases.", "Confusing the freight path with public or emergency exit routes, which must stay clear."], "scenario_contexts": ["Planning a freight path from a rear dock through corridors to the stage.", "A theater with a tight freight path that limits usable case size.", "Clearing the freight path before a fast load-out after the show."]}, "5c201d0e-9c8f-4a15-904c-f782fddc83d9": {"definition": "The improved, less fatigued listening perception regained after a rest from monitoring, used to re-evaluate a mix or recording more objectively; also the practice of taking such a break.", "plain_english": "Ears that have had a rest, so they hear a mix clearly again. After long listening your ears get tired, so a break helps you judge sound better.", "purpose_function": "Taking fresh ears counters listening fatigue, which dulls judgment of balance and tone, helping an engineer catch problems they had stopped noticing.", "practical_application": "An engineer steps away from a long mix session, then returns with fresh ears to spot level or EQ issues that had blended into the background.", "category": "Monitoring", "related_terms": ["Listening fatigue", "Mix", "Monitoring", "Reference monitor", "A/B comparison"], "common_mistakes": ["Pushing through fatigue instead of resting, then making poor mix decisions.", "Assuming fresh ears means turning up louder; louder listening actually speeds fatigue.", "UNSAFE: Monitoring at high sound levels for long stretches, which risks noise-induced hearing loss."], "scenario_contexts": ["A mix engineer taking a break, then returning with fresh ears for a final check.", "Coming back the next morning to review a mix before sending it.", "Bringing in a colleague's fresh ears for a second opinion on a mix."]}, "3b9189b5-1038-490f-9dda-8f7b46c08b57": {"definition": "In live production, the part of a venue on the audience side of the stage, and specifically the mix position within the audience area where the main sound (and often lighting) is controlled; in theater, the public areas of the building.", "plain_english": "The audience side of a venue, and the mix spot out among the crowd. It is where the engineer sits to control the main sound for the room.", "purpose_function": "Placing control at front of house puts the engineer in the audience's acoustic space, so they hear and mix what the crowd actually hears.", "practical_application": "A crew reserves a front-of-house position in the audience, runs a multicore to it, and sets up the main console there for the show.", "category": "Live Sound", "related_terms": ["Front-of-house mix", "FOH engineer", "Mix position", "Monitor world", "Multicore", "Stage"], "common_mistakes": ["Confusing front of house with backstage; front of house is the audience side.", "Placing the front-of-house position off to the side or under a balcony, where it does not represent the room.", "In theater, forgetting that front of house also means the public areas run by the house manager."], "scenario_contexts": ["Setting up the front-of-house console in the middle of an arena floor.", "A theater house manager preparing front of house before doors open.", "Running a signal snake from the stage to front of house."]}, "527b2092-c091-4845-990d-2cf6cac7fa7a": {"definition": "The main audio mix created for the audience and reproduced through the main (front-of-house) loudspeaker system, combining all sources into one balance for the room, as distinct from the monitor mixes sent to performers.", "plain_english": "The main mix the audience hears through the big speakers. It blends every instrument and voice into one balance for the whole room.", "purpose_function": "The front-of-house mix presents the whole performance to the audience as a single balanced blend suited to the room's acoustics.", "practical_application": "The FOH engineer builds the front-of-house mix at soundcheck, setting levels, EQ, and effects, then adjusts it live as the room fills and the set changes.", "category": "Mixing", "related_terms": ["Front of house", "FOH engineer", "Monitor mix", "Main loudspeaker system", "Mix", "Soundcheck"], "common_mistakes": ["Confusing the front-of-house mix with the monitor mix, which serves the performers on stage.", "Mixing to an empty room and not adjusting once the audience changes the acoustics.", "UNSAFE: Building the front-of-house mix at excessive sound-pressure levels that risk hearing damage to crowd and crew."], "scenario_contexts": ["An engineer refining the front-of-house mix during a headline set.", "Setting a front-of-house mix at soundcheck before the doors open.", "Adjusting the front-of-house mix for a support act with a different instrument lineup."]}, "c1c46fdf-33f5-427b-8a2a-fbd1451dbb64": {"definition": "The front-of-house (FOH) position is the location within the audience area from which the main sound system, and often lighting, is mixed and controlled during a performance. It houses the FOH console and outboard and is placed so the operator hears the mix as the audience does, typically centrally and on-axis with the main loudspeakers.", "plain_english": "The front-of-house position is where the main mixing desk sits out in the audience. The engineer works here so they hear the show the way the crowd does. It is usually placed in the middle of the room.", "purpose_function": "It puts the mixing controls where the operator can hear the real audience experience, so mix decisions match what the crowd hears rather than what is heard on stage.", "practical_application": "During load-in the crew reserves and cables the FOH position, then the engineer mixes the show from there through soundcheck and the performance.", "category": "Mix Positions", "related_terms": ["Front-of-house technician", "Front-of-house riser", "Monitor position", "Multicore", "Console"], "common_mistakes": ["Confusing the front-of-house position with the stage or monitor world; FOH mixes for the audience, not the performers", "Placing the FOH position off to the side or under a balcony, where the mix does not represent what most of the audience hears", "UNSAFE: Running the multicore and power to the FOH position across walkways without cable ramps or matting, creating a trip hazard"], "scenario_contexts": ["Setting up the FOH position centrally in the audience during load-in", "An engineer mixing a concert from the FOH position through soundcheck and the show", "A venue with a fixed FOH position built into the room at the rear of the stalls"]}, "e992c89e-1fd5-4a7d-bbd0-7b8ffdf48fda": {"definition": "A front-of-house riser is a raised platform built at the FOH position to lift the mixing console and operator above the surrounding audience floor. It improves the engineer's sightline to the stage and separates the mix area from the standing or seated crowd.", "plain_english": "A front-of-house riser is a small raised stage for the mixing desk out in the crowd. It lifts the engineer up so they can see the stage clearly. It also keeps the mix area apart from the audience.", "purpose_function": "It raises the console and operator for a clear sightline to the stage and marks off the mix area, protecting the gear and engineer from the crowd.", "practical_application": "The crew builds and levels the FOH riser during load-in, then sets the console, monitors, and outboard on it before soundcheck.", "category": "Mix Positions", "related_terms": ["Front-of-house position", "Front-of-house technician", "Riser", "Deck", "Console"], "common_mistakes": ["Assuming every FOH position needs a riser; many venues mix from floor level and only add a riser when sightlines or crowd separation require it", "UNSAFE: Building a FOH riser without guard rails, edge protection, or safe access steps where it reaches a height that requires fall protection", "UNSAFE: Overloading an under-rated riser deck with heavy consoles and racks beyond its rated load"], "scenario_contexts": ["Building a FOH riser so the engineer can see over a standing festival crowd", "Adding guard rails and a step to a tall FOH riser during load-in", "A general-admission show where a riser separates the mix position from the audience"]}, "5addf844-ac9b-4949-bd74-f679053d77a9": {"definition": "A front-of-house technician, or FOH engineer, is the crew member who operates the main sound system from the FOH position, mixing the performance for the audience. They set input gain, balance, equalisation, dynamics, and effects, and manage the FOH console and system through soundcheck and the show.", "plain_english": "The front-of-house technician is the engineer who mixes the sound for the audience. They control the levels, tone, and effects on the main desk. They run the show sound from setup through to the last song.", "purpose_function": "The role puts one skilled operator in charge of the audience mix, so the balance, tone, and level the crowd hears are controlled by a single responsible person.", "practical_application": "The FOH technician patches and gain-stages inputs at soundcheck, then mixes levels and effects live from the FOH console throughout the performance.", "category": "Crew Roles", "related_terms": ["Front-of-house position", "Monitor engineer", "Systems engineer", "Gain ownership", "Console"], "common_mistakes": ["Assuming the FOH technician also mixes the performers' stage monitors; that is the separate monitor engineer's job", "Confusing the FOH technician with the systems technician who tunes and maintains the loudspeaker rig", "UNSAFE: Mixing at damaging sound levels for long periods without hearing protection or level monitoring, risking noise-induced hearing loss"], "scenario_contexts": ["A FOH technician mixing a band for a theatre audience", "A FOH technician gain-staging and building a show file during soundcheck", "A FOH technician working with the monitor engineer to share preamp gain on a common stage rack"]}, "e55c0906-4ede-4475-8a5b-711f731d181d": {"definition": "Gain ownership is the arrangement, on systems where two or more consoles share the same analog microphone preamps (head amps), that designates which console controls the actual analog gain of each shared preamp. The owning (master) console sets the head-amp gain, while other consoles hold their level with digital trim and gain compensation so a gain change by the owner does not disturb their mix.", "plain_english": "Gain ownership decides which mixing desk controls the real mic preamp gain. It matters when two desks share one stage box. Only the owner can change that gain. The other desk adjusts on its own to keep its mix steady.", "purpose_function": "It stops two operators from fighting over one physical preamp by giving a single console control of the analog gain, while gain compensation lets the other keep a stable mix.", "practical_application": "With shared FOH and monitor racks, or a shared festival stage box, the crew agrees which console owns each preamp's gain and enables gain compensation on the other so a gain move does not shift its levels.", "category": "Console Operation", "related_terms": ["Front-of-house technician", "Monitor engineer", "Gain staging", "Head amp", "Stage rack"], "common_mistakes": ["Thinking both consoles can freely change the shared analog gain; only the owning console controls it, others use digital trim", "Forgetting to enable gain compensation on the non-owning console, so the owner's gain changes shift that engineer's mix", "Assuming digital trim on a non-owning console changes the analog preamp; it only adjusts that console's own level"], "scenario_contexts": ["FOH and monitor consoles sharing one digital stage rack and agreeing gain ownership at setup", "A festival where each visiting console must know which desk owns the shared preamp gain", "An engineer enabling gain compensation so the owning console's changes do not affect the mix"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"e021bf9d-7481-42af-914c-d3b806c880ba": {"definition": "In UK and European live-event and theatre practice, the get-in is the process, and the scheduled period, of unloading equipment from the transport and moving it into the venue at the start of a production. It is the equivalent of the North American load-in and is reversed by the get-out at the end.", "plain_english": "The get-in is when the crew unloads the trucks and brings the gear into the venue. It is the first big job of the day. British crews say 'get-in' where American crews say 'load-in'.", "purpose_function": "It moves all of a production's equipment from the transport into the building in an orderly way, so assembly can begin on schedule.", "practical_application": "Crew work the get-in to a schedule, unloading the truck in build order so rigging and heavy gear reach their positions first.", "category": "Load-in / Load-out", "related_terms": ["Get-out", "Load-in", "Load-out", "Build", "Strike"], "common_mistakes": ["Confusing the get-in, which brings gear in, with the get-out, which takes it out; they are opposite ends of the job", "Unloading in the wrong order, so items needed first are buried at the back of the truck", "UNSAFE: Lifting or carrying heavy cases alone instead of using a team lift, trolley, or mechanical aid, risking back injury"], "scenario_contexts": ["A theatre crew doing a morning get-in before a technical rehearsal", "A touring crew running the get-in to the day sheet schedule", "Unloading flight cases during the get-in in the order they are needed on stage"]}, "59d3a412-330b-4ef1-a31e-fedd84e1bdd0": {"definition": "In UK and European practice, the get-out is the process, and the scheduled period, of dismantling the production, packing equipment, and loading it back onto the transport at the end of an event. It is the counterpart of the get-in and equates to the North American load-out or strike.", "plain_english": "The get-out is when the crew takes everything down and packs it back onto the trucks. It happens after the last show. British crews say 'get-out' where American crews say 'load-out'.", "purpose_function": "It clears the venue by striking, packing, and loading all equipment safely and quickly, often against a tight curfew or handover deadline.", "practical_application": "After the final performance the crew works the get-out, striking the rig, coiling cables, and loading cases back onto the truck in a planned order.", "category": "Load-in / Load-out", "related_terms": ["Get-in", "Load-out", "Strike", "Load-in", "Build"], "common_mistakes": ["Confusing the get-out, which is packing down, with the get-in, which is setting up; they are opposites", "Rushing the get-out and packing gear into the wrong cases, causing problems at the next get-in", "UNSAFE: Working a long get-out while fatigued and lifting heavy cases without team lifts or mechanical aids, risking injury"], "scenario_contexts": ["A crew doing a late-night get-out after the show to clear the venue by curfew", "Striking and packing the rig during the get-out in reverse build order", "A festival get-out loading several trucks once the audience has left"]}, "71dedc76-f7e8-42ae-9ccd-075ac29a09a7": {"definition": "A gig is a booked engagement to perform, or to provide technical services, for a single show, session, or event; by extension, in crew usage, any individual job or work call. The term is used across live music, theatre, and touring for one discrete booking.", "plain_english": "A gig is a single booked job or show. For a musician it is one performance. For a crew member it is one work call, like doing sound for tonight's concert.", "purpose_function": "The word gives crew and performers a simple name for one discrete booking, separating a single show or work call from a whole tour or run.", "practical_application": "A freelance technician takes gigs day by day, checking each gig's call time, venue, and role on the booking or day sheet.", "category": "General Terms", "related_terms": ["Gig bag", "Day sheet", "Call time", "Load-in", "Tour"], "common_mistakes": ["Using 'gig' to mean a whole tour; a gig is normally one show or one work call", "Assuming a gig always means a musical performance, when crew also call any single job a gig"], "scenario_contexts": ["A freelance engineer booking several one-off gigs in a week", "A musician travelling to tonight's gig at a local club", "A crew member checking the call time for tomorrow's gig"]}, "485beedc-3cd8-42fe-b763-cca32c296ce7": {"definition": "A gig bag is a soft, usually padded carrying case, typically of fabric or synthetic material with carry handles and shoulder straps, used to transport and lightly protect an instrument or piece of equipment. It is lighter and less protective than a hard case or flight case, favouring portability over impact protection.", "plain_english": "A gig bag is a soft, padded bag for carrying an instrument or gear. It has handles and shoulder straps so you can carry it easily. It is lighter than a hard case but protects less.", "purpose_function": "It gives a light, easy-to-carry way to move and lightly protect gear, trading the heavy impact protection of a hard case for portability.", "practical_application": "A player or tech uses a gig bag to carry an instrument or small gear to local gigs, choosing a hard case instead when items ship in a truck or fly.", "category": "Cases & Bags", "related_terms": ["Gig", "Road case", "Flight case", "Cable trunk", "Load-in"], "common_mistakes": ["Trusting a gig bag to protect gear like a hard case; its soft shell gives far less impact protection", "Using a gig bag for heavy touring transport, where a flight case is needed to survive stacking and rough handling", "UNSAFE: Overloading a gig bag and carrying it on one shoulder for long periods, risking strain; balance the load or use a trolley"], "scenario_contexts": ["A guitarist carrying a guitar in a gig bag to a local club gig", "A tech using a padded gig bag for a laptop or small mixer between short trips", "Choosing a flight case over a gig bag when gear must travel in a truck"]}, "aed0dc4e-3fe9-4752-97ed-f2af3a1b9a3a": {"definition": "In show cueing, the executive command given by the caller (stage manager or show caller) that instructs an operator or crew member to execute a specific cue at that instant; it is the action word in the 'standby / go' sequence and is placed last so the action begins on the word itself.", "plain_english": "The word that tells a crew member to run a cue right now. It comes after a 'standby' warning, and the action starts the moment 'go' is said.", "purpose_function": "It gives one agreed action word so cues fire at an exact, shared moment, keeping operators in sync during a show.", "practical_application": "The caller says 'Lights, standby... lights, go,' and the board operator runs the lighting cue on the word 'go'.", "category": "Cue call", "related_terms": ["Standby", "Cue", "Clear", "Good to go", "Stage manager"], "common_mistakes": ["UNSAFE: Calling 'go' for a fly, automation, or pyro cue before 'standby' is acknowledged and the area is confirmed clear.", "Putting more words after 'go', so the operator fires late; 'go' must be the last word of the call.", "Using 'go' loosely on comms, so operators cannot tell a real cue from chatter."], "scenario_contexts": ["A stage manager calling lighting and sound cues from a prompt book during a musical.", "A show caller cueing a video roll and a pyro hit on the downbeat of a song.", "A crew chief giving a 'go' for a coordinated truss move once all riggers stand by."]}, "5fdbe787-871c-4bc3-8296-5769138d3726": {"definition": "A radio/intercom acknowledgment confirming that the receiving station heard and understood the preceding transmission clearly; 'copy' denotes reception of a message, and 'good copy' affirms it was received without error.", "plain_english": "A way to say 'I heard you and understood.' 'Copy' is radio talk for getting a message, so 'good copy' means it came through clearly.", "purpose_function": "It closes a communication loop with a short confirmation, so the sender knows the message was received correctly before moving on.", "practical_application": "When the stage manager passes a cue change over comms, a crew member replies 'good copy' to confirm they got it.", "category": "Crew comms", "related_terms": ["Copy", "Good to go", "Standby", "Clear-comms path", "Intercom"], "common_mistakes": ["Saying 'good copy' out of habit without actually understanding the message.", "Using it on a busy channel where a read-back of the details is expected instead.", "Confusing 'copy' (message received) with agreement or with a 'go' to act."], "scenario_contexts": ["A monitor engineer confirming a mix change requested over the intercom.", "A rigger acknowledging a load-in instruction relayed by two-way radio.", "A spotlight operator confirming a cue change passed by the caller."]}, "c3e4e35b-3838-4e8e-a83a-5511c08c4d59": {"definition": "A crew confirmation that a person, system, or task is fully prepared and cleared to proceed, signaling readiness with no outstanding issues; it functions as a positive 'ready' status on comms, distinct from the executive cue 'go'.", "plain_english": "A quick way to say 'everything is ready, we can start.' The crew uses it to confirm nothing is left to do before the next step.", "purpose_function": "It gives a clear all-ready signal so the show or task moves ahead only once a position confirms it is prepared.", "practical_application": "After a line check passes, the front-of-house engineer calls 'good to go' so the stage manager can start the set.", "category": "Crew comms", "related_terms": ["Good copy", "Standby", "Go", "Line check", "Clear"], "common_mistakes": ["Calling 'good to go' before actually finishing checks, so a fault surfaces mid-show.", "Confusing readiness ('good to go') with the executive cue ('go') to act now.", "Assuming one position's 'good to go' means every position is ready."], "scenario_contexts": ["An engineer confirming inputs are ready after a soundcheck.", "A monitor tech confirming wedges and in-ears are set before doors.", "A crew chief confirming a stage is fully rigged and ready for the act."]}, "cc8dea38-a8e1-42d3-a90a-bea858783fc4": {"definition": "Input channels on a console or stage patch that are reserved or allocated for a guest act, support band, or visiting performer, kept separate from the resident act's channels so a guest's inputs can be patched and mixed without disturbing the main setup.", "plain_english": "Spare console inputs set aside for a visiting act. The crew patches the guest's mics and instruments here without touching the main band's setup.", "purpose_function": "They isolate a guest's inputs from the resident channel layout, so a support act or sit-in can be added quickly and removed cleanly.", "practical_application": "At a festival, the engineer patches a guest singer's mic into pre-labeled guest channels rather than repatching the headliner's inputs.", "category": "Console setup", "related_terms": ["Guest console", "Guest engineer handoff", "Patch bay", "Input list", "Mic split"], "common_mistakes": ["Not labeling guest channels, so their inputs get confused with the main act's during a fast changeover.", "Forgetting to mute or clear guest channels after the guest's set, leaving open mics.", "Assuming guest channels share the resident act's processing instead of setting them up fresh."], "scenario_contexts": ["A support act's inputs patched into reserved guest channels on the house console.", "A guest musician sitting in for one song, patched into spare channels.", "A festival stage keeping a block of channels open for each rotating act."]}, "5a03be4b-3970-4fe7-8205-20c4f41759da": {"definition": "A mixing console brought in by, or provided for, a visiting guest engineer or act and connected to the house system, typically via a stagebox/mic split or shared audio network, so the guest can mix on their own desk alongside or in place of the resident console.", "plain_english": "A separate mixing desk for a visiting act or engineer. It plugs into the house system so the guest can mix on gear they know.", "purpose_function": "It lets a touring or support engineer mix on a familiar console with their own settings, without reprogramming the resident house desk.", "practical_application": "At a festival, a support act's engineer patches their guest console to the mic split, runs their show file, then hands back to the house console.", "category": "Console setup", "related_terms": ["Guest channels", "Guest engineer handoff", "Front of house", "Mic split", "Digital snake"], "common_mistakes": ["Assuming a guest console can share the house desk's inputs without a proper signal split.", "Forgetting to use a split or gain-sharing so both consoles get usable signal from each source.", "Not confirming the guest console's outputs and levels before it feeds the PA."], "scenario_contexts": ["A festival where each act's engineer brings a guest console to the mix position.", "A support act mixing on a guest desk fed from the same stage split as the house console.", "A visiting broadcast mixer patched in as a guest console for a live capture."]}, "b9f2e654-fe6f-4e67-b387-9d518d2a9479": {"definition": "The structured transfer of control of the sound system to, or back from, a visiting guest engineer, including passing over the console or split and confirming the input list/patch, gain structure, outputs, and system limits, so the guest can mix without a gap in coverage or risk to the PA.", "plain_english": "The steps for handing the sound system over to a visiting engineer. The crew passes on the patch, levels, and limits so the guest can mix safely.", "purpose_function": "It ensures a smooth, safe transfer between engineers, so the guest inherits a known-good setup and the system stays protected.", "practical_application": "Before a support set, the house engineer walks the guest through the patch, system limits, and limiter settings, then hands over the console.", "category": "Show workflow", "related_terms": ["Guest console", "Guest channels", "Front of house engineer", "System tech", "Gain structure"], "common_mistakes": ["UNSAFE: Handing over without communicating system limits or limiter settings, risking driver damage or unsafe sound levels.", "Skipping a patch and input-list check, so the guest hits wrong or dead channels.", "Not agreeing a plan to hand control back, causing confusion at the changeover."], "scenario_contexts": ["A house engineer handing front of house to a touring support engineer for one set.", "Passing monitor control to a guest monitor engineer at a festival.", "Handing the system back to the house engineer after a guest's performance."]}, "cb423916-df41-43af-a206-3a5c20039fb5": {"definition": "A specialist backline crew member responsible for the setup, tuning, maintenance, and stage-side support of a guitarist's (and often bassist's) instruments and rig, including changing strings, managing spare instruments, setting up amplifiers and pedalboards, and handling instrument swaps during the show.", "plain_english": "The crew member who looks after a guitarist's instruments and gear. They tune the guitars, change strings, fix faults, and hand over spares during the show.", "purpose_function": "The role keeps the guitarist's instruments in tune and working, so the player can focus on performing while the tech handles setup, repairs, and swaps.", "practical_application": "A guitar tech tunes and stages each instrument, then hands the player a freshly tuned guitar between songs and troubleshoots any rig fault mid-set.", "category": "Crew role", "related_terms": ["Guitar technician", "Backline", "Backline tech", "Stage tech", "Monitor engineer"], "common_mistakes": ["Confusing the guitar tech with the general backline tech; the guitar tech specializes in guitars and their rigs.", "Assuming the role is only tuning, when it also covers repairs, spare instruments, and rig setup.", "UNSAFE: Defeating or ignoring proper equipment grounding on amps and rigs, leaving a shock hazard between an instrument and a grounded microphone."], "scenario_contexts": ["A guitar tech tuning and staging instruments before a rock show.", "Swapping a broken string mid-set by handing the player a spare guitar.", "Troubleshooting a dead amp channel or pedalboard fault during soundcheck."]}, "5ede4d12-9262-409b-9f02-b47f5e62ae27": {"definition": "The full title for the specialist backline crew member responsible for the setup, tuning, maintenance, and stage-side support of a guitarist's (and often bassist's) instruments and rig, including string changes, spare-instrument management, amplifier and pedalboard setup, and instrument swaps during a performance.", "plain_english": "The full job title for the person who looks after a guitarist's instruments and gear. They tune, restring, repair, and hand over spare guitars during the show.", "purpose_function": "The role centralizes care of the guitar rig, so the musician can perform while the technician keeps instruments tuned, working, and ready to swap.", "practical_application": "A guitar technician preps and tunes each instrument before doors, then handles restrings, swaps, and rig faults throughout the set.", "category": "Crew role", "related_terms": ["Guitar tech", "Backline", "Backline tech", "Stage tech", "Monitor engineer"], "common_mistakes": ["Treating 'guitar technician' as a different role from 'guitar tech'; they are the full and short names for the same job.", "Assuming the role is only tuning, when it also covers repairs, spare instruments, and rig setup.", "UNSAFE: Defeating or ignoring proper equipment grounding on amps and rigs, leaving a shock hazard between an instrument and a grounded microphone."], "scenario_contexts": ["A guitar technician preparing and tuning a touring guitarist's instruments before a show.", "Handing a player a spare guitar after a string breaks mid-song.", "Diagnosing an amplifier or pedalboard fault during soundcheck."]}, "d4080423-677d-4e60-aa95-d4e2d27a3a6b": {"definition": "A fixed, non-negotiable time at which a performance, work call, or event must end regardless of progress, typically imposed by a venue curfew, local noise ordinance, union rule, or contractual limit.", "plain_english": "A hard out is a set end time that cannot move. The show or work must stop by then, no matter what. It often comes from a curfew or a contract.", "purpose_function": "It gives everyone a firm deadline so the schedule, overtime costs, and legal limits like curfews and noise laws are respected.", "practical_application": "A stage manager plans load-out and encores backward from the hard out, warning crew and the act so the last note and final truck leave on time.", "category": "Show scheduling", "related_terms": ["Curfew", "Load-out", "Changeover window", "Soft out", "Stage manager"], "common_mistakes": ["Confusing a hard out with a soft, flexible target time; a hard out does not move.", "Failing to plan load-out against the hard out, causing costly overtime or curfew fines.", "Not warning the act, so the set overruns and the final numbers get cut."], "scenario_contexts": ["An outdoor festival with a strict local-authority curfew as the hard out.", "A venue booked for a later event, forcing an early hard out for the strike.", "A union crew whose contracted work call ends at a fixed hard out."]}, "d841ad33-a12f-481e-a82a-782fda02a8e9": {"definition": "A changeover between acts carried out by physically re-patching stage inputs and outputs at a patch panel or stage box, rather than by recalling a stored soft-patch, snapshot, or scene on a digital console.", "plain_english": "This is a swap between acts done by moving real cables at a patch panel. The crew re-plugs the inputs by hand instead of changing routing on a screen.", "purpose_function": "It reassigns which stage sources feed which console channels during a changeover, letting a new act's inputs reach the desk when digital recall is not used or not shared.", "practical_application": "During a festival changeover with a shared stage box, a tech re-patches the incoming act's mics and DIs at the panel so they land on the console channels that engineer expects.", "category": "Signal routing", "related_terms": ["Patch bay", "Soft patch", "Changeover window", "Stage box", "Line check"], "common_mistakes": ["Not labeling the new patch, so channels arrive on the wrong strips and confuse the line check.", "Forgetting to update the patch sheet, leaving the next crew guessing what is plugged where.", "Assuming a stored digital scene will fix a physical mispatch; the hard patch must be corrected at the panel."], "scenario_contexts": ["A festival stage where several acts share one stage box and inputs are re-patched between sets.", "An analog patch bay swap when a guest act brings its own input list.", "Repatching a submix or matrix output to a different destination during a tight changeover."]}, "e7cee916-678d-4aee-9fd8-8bb3f21e5078": {"definition": "A shouted safety warning, 'Heads!', alerting everyone below that an object is falling, has been dropped, or is being lowered from overhead, cueing them to move clear and protect themselves.", "plain_english": "'Heads!' is a shout that warns something is falling from above. When you hear it, move out of the way and protect your head.", "purpose_function": "It gives an instant, recognized alarm for a falling-object hazard so people below can react fast and avoid being struck.", "practical_application": "A rigger who drops a wrench from a truss immediately shouts 'Heads!' so anyone on the deck below can clear the area.", "category": "Safety call", "related_terms": ["Heads up", "Hold", "Clear", "Overhead rigging", "Hard hat"], "common_mistakes": ["UNSAFE: Looking straight up when you hear 'Heads!'; move clear and shield your head instead of exposing your face.", "UNSAFE: Working under an active overhead rig without a hard hat, relying on the shout alone for protection.", "Saying 'Heads' casually so the real warning loses its urgency."], "scenario_contexts": ["A rigger dropping a tool from the grid and shouting the warning to the deck below.", "Crew lowering a lighting bar and calling out as it comes down over a work area.", "A load-in where gear is passed from a truck at height above people on the ground."]}, "fa8565e1-49ee-4cee-8fbb-8634be7c37a5": {"definition": "A verbal warning call telling people to be alert to an imminent hazard, most often an overhead danger, a moving load, or something approaching; also used more generally to give advance notice of a change.", "plain_english": "'Heads up!' is a call telling people to pay attention to a danger. It often warns of something overhead or coming toward them. It can also just mean advance notice.", "purpose_function": "It quickly raises awareness of a hazard or a coming change so people can react safely before it reaches them.", "practical_application": "A crew member pushing a heavy case through a busy backstage calls 'heads up' so people clear the path before it arrives.", "category": "Safety call", "related_terms": ["Heads", "Clear", "Hold", "Standby", "Load-in"], "common_mistakes": ["UNSAFE: Treating 'heads up' as optional chatter and not moving clear of a moving load or overhead work.", "Using it so often for trivial things that crew stop reacting to the real warnings.", "Assuming everyone heard it in a loud room instead of confirming the path is clear."], "scenario_contexts": ["Warning people before a heavy road case is wheeled through a crowded corridor.", "Alerting the deck that a lighting bar or truss is about to move overhead.", "Giving a crew advance notice that a schedule or cue is about to change."]}, "9b0fb357-4105-4f5b-97cd-9c13c3ed4642": {"definition": "A command to stop and freeze all action immediately, maintaining current positions, used to pause a cue, a rehearsal, or a moving element, commonly to address a problem or hazard before action resumes.", "plain_english": "'Hold' means stop and freeze right where you are. Crew use it to pause a move fast. It is often called to keep people safe.", "purpose_function": "It gives one clear word to halt everything at once, so a fault or danger can be checked before anyone or anything moves again.", "practical_application": "If a rigger spots a fouled line during a fly move, anyone can call 'hold' and the operator stops the move until it is cleared.", "category": "Stage command", "related_terms": ["Standby", "Go", "Clear", "Heads", "Fly cue"], "common_mistakes": ["UNSAFE: Continuing a rigging or automation move after 'hold' is called instead of stopping at once.", "Confusing 'hold' with 'standby'; standby readies a cue, while hold stops action.", "Resuming after a hold without a clear 'go', so people move before it is safe."], "scenario_contexts": ["A crew member calling 'hold' when a performer strays into a moving scenery path.", "Stopping a fly cue mid-move because a line has fouled.", "Pausing a technical rehearsal to fix a problem before the next cue."]}, "6378f2df-d34d-4ed4-b65d-477ac8749cc4": {"definition": "Describing a conductor, circuit, cable, or channel that is energized or live, carrying mains voltage or an active audio signal, and therefore to be treated as active and potentially hazardous; in mains wiring it denotes the ungrounded (line) conductor.", "plain_english": "'Hot' means a cable, circuit, or channel is live and active. It may carry power or an audio signal. Treat anything hot as unsafe to touch until proven dead.", "purpose_function": "The word flags that a path is energized so crew handle it with care, confirm power is off before working, and avoid shock or unwanted noise.", "practical_application": "A tech warns that a power feed is hot before others touch it, and treats a channel as hot when its fader or mic is open and live in the mix.", "category": "Electrical safety", "related_terms": ["Hot swap", "Ground", "Neutral", "Live", "Lockout/tagout"], "common_mistakes": ["UNSAFE: Assuming a circuit is dead without testing; verify de-energized and use lockout/tagout before working on it.", "UNSAFE: Handling a 'hot' mains conductor or connector as if only signal-level voltage were present.", "Confusing the audio sense (an open, live channel) with the electrical sense (an energized power conductor)."], "scenario_contexts": ["Warning crew that a distro feed or cable is hot before anyone handles it.", "Identifying the ungrounded (hot) conductor when wiring or testing a power connector.", "Calling a mic or channel hot when it is open and live in the mix."]}, "c06f412e-a5e4-4480-8a82-1fa5053d3b24": {"definition": "The replacement or insertion of a component or module while the host system remains powered and operating, without shutting it down or interrupting service, relying on hardware and connectors specifically designed to be hot-swappable.", "plain_english": "A hot swap means changing a part while the gear stays powered on. You do not shut the system down first. Only parts built for this should be swapped live.", "purpose_function": "It lets crew replace a failed or spare part, such as a redundant power supply, without a total shutdown, keeping a show or system running.", "practical_application": "When one of a console's redundant power supplies fails mid-show, a tech pulls it and slides in a spare, since the units are designed to be hot-swapped.", "category": "Maintenance", "related_terms": ["Hot", "Redundancy", "Redundant power supply", "Uninterruptible power supply", "Failover"], "common_mistakes": ["UNSAFE: Hot-swapping a component or connector that is not rated for it, risking arcing, shock, or equipment damage.", "Assuming any module is hot-swappable; confirm the manufacturer's technical documentation first.", "Confusing hot swap with hot plug of signal cables, which can still cause damaging transients on some gear."], "scenario_contexts": ["Replacing a failed redundant power supply in a console or amplifier during a show.", "Swapping a drive or network module in a media or playback server without downtime.", "Changing a redundant unit in a rack while the primary keeps the system running."]}, "95514c7a-6828-4863-a9cb-2fca31cb6362": {"definition": "The console input channels provided and controlled by the venue (the 'house'), such as house microphones, playback, paging, and walk-in music, as distinct from the touring or visiting act's own input channels.", "plain_english": "House channels are the inputs run by the venue, not the visiting band. They cover things like house mics, paging, and walk-in music before the show.", "purpose_function": "They give the venue permanent inputs for announcements, background music, and house mics that stay available no matter which act is using the room.", "practical_application": "A house engineer keeps the walk-in music and a paging mic on the house channels, then adds the touring act's inputs alongside them for the show.", "category": "Signal routing", "related_terms": ["House engineer", "Front of house", "Walk-in music", "Playback", "Input list"], "common_mistakes": ["Overwriting or repatching house channels for the act, then losing paging or walk-in music capability.", "Assuming house channels are free to reassign without checking with the venue's house engineer.", "Confusing house channels with the act's touring channels on a shared console."], "scenario_contexts": ["A venue keeping walk-in music and announcements on dedicated house channels.", "A house engineer reserving channels for a paging or 'voice of god' mic.", "A touring engineer patching an act's inputs around the venue's fixed house channels."]}, "cc2a00c0-7253-42e5-b680-ccac5b2531b3": {"definition": "A front-of-house status meaning the auditorium (the \"house\") is not yet open to patrons; the audience is held out of the seating area while crew finish pre-show preparation and safety checks.", "plain_english": "\"House closed\" means the audience still waits in the lobby. The crew are getting the seats and stage ready.", "purpose_function": "It reserves the seating area for crew, so setup and safety checks can finish without patrons present.", "practical_application": "The stage manager keeps the house closed until checks pass, then clears the house crew to open the doors.", "category": "House Management", "related_terms": ["House open", "House crew", "House to half", "House out", "Front of house"], "common_mistakes": ["Thinking \"house closed\" means the venue is shut for the night, rather than the pre-show hold on audience seating", "Letting patrons into the seats before the stage manager has actually cleared the house"], "scenario_contexts": ["A stage manager announcing \"house is closed\" so crew can finish a stage reset", "Front-of-house staff holding patrons in the lobby during a delayed sound check"]}, "dd973645-57c8-42d4-a025-cf7b82e93f38": {"definition": "The local technical staff employed by or contracted to the venue, distinct from the touring (road) crew that travels with the production; they handle load-in/out, operate house systems, and know the building.", "plain_english": "The house crew are the local workers who belong to the venue. They help the touring crew set up and tear down.", "purpose_function": "It provides skilled local labour and building knowledge, so a touring show can load in, run, and load out safely.", "practical_application": "A tour manager coordinates with the house crew for stagehands, riggers and operators supplied under the venue contract at each stop.", "category": "Crew Roles", "related_terms": ["Touring crew", "House handoff", "Load-in", "Stagehand", "House desk"], "common_mistakes": ["Confusing the house crew (local, venue-based) with the touring crew that travels with the act", "Assuming the house crew know the show; they know the building, not the production's cues"], "scenario_contexts": ["A tour arriving at a theatre and meeting the house crew for load-in", "A local house crew operating the venue's rigging and power during a one-off concert"]}, "24362f3b-0201-473c-9f0f-6a2b73e21edc": {"definition": "The venue's front-of-house mixing console — the main audience-mix desk placed out in the house — as opposed to a console the touring act brings; it can also refer to the front-of-house mix position generally.", "plain_english": "The house desk is the venue's own mixing board out in the audience area. Visiting engineers may use it instead of bringing their own.", "purpose_function": "It provides the permanent audience-mix control point, so acts without their own console can still mix front-of-house sound.", "practical_application": "A visiting engineer checks the house desk's make and channel count in the tech spec before deciding whether to carry a touring console.", "category": "Venue Equipment", "related_terms": ["Front of house", "House rig", "House package", "Monitor desk", "House crew"], "common_mistakes": ["Confusing the house desk (front-of-house audience mix) with the monitor desk (stage performer mixes)", "Assuming every venue's house desk matches your show file; console make and layout vary widely"], "scenario_contexts": ["A support act mixing on the house desk because only the headliner carries a console", "An engineer reviewing the venue's house desk model during the advance"]}, "b7fb561a-fd2c-4294-b3be-ec5eb7b7be82": {"definition": "The transfer of responsibility for venue systems and the workspace between the house crew and the touring crew — typically house crew to touring crew at load-in and back at load-out — covering power, rigging points, and house equipment.", "plain_english": "A house handoff is when the local crew passes control of the venue's gear to the touring crew. It can also mean handing it back. It sets who is responsible for what.", "purpose_function": "It marks a clear point where responsibility, access, and safety for house systems pass between crews, avoiding confusion over who controls equipment.", "practical_application": "At load-in the house crew walks the touring crew through power, rigging points and house gear, formally handing off the space.", "category": "Crew Workflow", "related_terms": ["House crew", "Touring crew", "Load-in", "Load-out", "House rig"], "common_mistakes": ["Treating the handoff informally and skipping a walk-through of power, rigging points and house gear", "UNSAFE: Working on or energising house electrical or rigging systems before a clear handoff establishes who controls them and their lockout status"], "scenario_contexts": ["A house electrician handing off power and distro responsibility to the touring crew at load-in", "Returning control of the house rig to venue staff during load-out"]}, "e2eaa2bb-6761-49f7-9420-4bc19b354d31": {"definition": "A stage-management call declaring the auditorium open to the audience; patrons may now enter and be seated, marking the transition from pre-show setup to admitting the house.", "plain_english": "\"House open\" means the doors are open and the audience can come in and sit down.", "purpose_function": "It signals that the stage and seating area are ready and safe, so front-of-house staff can admit patrons.", "practical_application": "The stage manager tells front-of-house \"the house is open,\" and ushers begin seating the audience.", "category": "House Management", "related_terms": ["House closed", "House to half", "House out", "House crew", "Front of house"], "common_mistakes": ["Opening the house before the stage manager gives the call, cutting short crew setup", "Confusing \"house open\" (admitting the audience) with \"house up\" (raising the house lights)"], "scenario_contexts": ["A stage manager calling \"house is open\" thirty minutes before curtain", "Front-of-house staff waiting for the house-open call before unlocking auditorium doors"]}, "ba4d18c4-8f64-444d-b8a6-548823c7ec45": {"definition": "A lighting cue or call to take the house lights (the auditorium's audience lighting) fully out to zero, typically as a performance begins.", "plain_english": "\"House out\" means turn the audience lights all the way off. It usually happens right as the show starts.", "purpose_function": "It darkens the seating area so audience attention shifts to the stage and the performance can begin.", "practical_application": "On the cue \"house out,\" the board operator fades the house lights to zero as the first stage look comes up.", "category": "House Lighting Cue", "related_terms": ["House to half", "House up", "House open", "Blackout", "House lights"], "common_mistakes": ["Snapping the house lights out instantly when a smooth fade is expected, startling the audience", "Confusing \"house out\" with a full stage blackout; house out affects audience lighting, not the stage"], "scenario_contexts": ["A board op taking the house out as the show's opening cue fires", "A stage manager calling \"house to half... house out\" to start Act One"]}, "06c80965-1f59-4b01-9b4e-cae32528155f": {"definition": "The set of production equipment a venue offers for hire — often the installed PA, lighting rig, and sometimes staging — bundled as a \"house package\" so an act need not bring its own.", "plain_english": "A house package is the gear a venue rents out together, like its sound and lights. Acts can use it instead of trucking in their own.", "purpose_function": "It lets smaller or fly-in acts perform using venue-supplied systems, reducing the equipment they must transport.", "practical_application": "A promoter books the house package so a support act or fly date can play on the venue's PA and lights.", "category": "Venue Equipment", "related_terms": ["House rig", "House desk", "House crew", "Front of house", "Tech spec"], "common_mistakes": ["Assuming the house package covers everything; consumables, specials, or backline are often extra", "Not checking the house package's specification against the show's needs during the advance"], "scenario_contexts": ["A fly-in act using the venue's house package instead of a full touring production", "A promoter comparing the house package against a band's rider requirements"]}, "83877dfe-9830-4519-a5aa-ad7fb1d33efe": {"definition": "The venue's permanently installed production system — chiefly its house lighting rig and/or PA hung in the building — available for productions to use instead of, or alongside, touring equipment.", "plain_english": "The house rig is the sound and lighting gear built into the venue. It stays there for shows to use.", "purpose_function": "It provides a ready-installed system, so productions can light and amplify a show without hanging their own rig.", "practical_application": "A lighting designer plots to the house rig when the budget or schedule does not allow a touring rig.", "category": "Venue Equipment", "related_terms": ["House package", "House desk", "House crew", "Front of house", "Rig"], "common_mistakes": ["Assuming the house rig matches your plot; fixture types, positions and counts vary by venue", "Treating the house rig as free extras; use, refocus and re-patch may need house crew time"], "scenario_contexts": ["A designer adapting a lighting plot to the venue's existing house rig", "A support act using the house rig while the headliner flies its own"]}, "afafa682-6647-4357-af67-74e2f1d8977a": {"definition": "A stage-management call, given shortly before a performance begins, to bring the house lights down to roughly half intensity, signalling the audience to settle before the house goes fully out.", "plain_english": "\"House to half\" means dim the audience lights to about halfway. It quietly warns the crowd the show is about to start.", "purpose_function": "It cues the audience to settle and quiet down, giving a gentle pre-show warning before the house lights go fully out.", "practical_application": "The stage manager calls \"house to half,\" the operator dims the house, then follows with \"house out\" as the show starts.", "category": "House Lighting Cue", "related_terms": ["House out", "House up", "House open", "House lights", "Standby"], "common_mistakes": ["Taking the house straight to out and skipping the half, losing the audience's settle warning", "Reading \"half\" as an exact 50% level rather than an approximate, feel-based dim"], "scenario_contexts": ["A stage manager giving \"house to half\" as the two-minute warning before curtain", "A board op dimming the house to half as the pre-show announcement plays"]}, "bf9db506-6cb4-4879-be5b-9068f26457cd": {"definition": "A final walk-through and visual sweep of a work area — stage, wings, dressing rooms, or bus bays — made after packing, to catch any gear, tools, or personal items left behind before the crew departs.", "plain_english": "An idiot check is one last look around after packing up. It makes sure nobody left any gear or tools behind.", "purpose_function": "It gives a last-chance sweep that catches forgotten items, so costly gear and tools are not left at the venue.", "practical_application": "After the trucks are loaded, a crew chief walks the empty stage and rooms doing an idiot check before declaring load-out complete.", "category": "Crew Workflow", "related_terms": ["Last look", "Load-out", "Load-in", "Junk case", "Stagehand"], "common_mistakes": ["Skipping the idiot check when running late, then leaving tools or backline at the venue", "Treating it as one person's job rather than checking every area each department used"], "scenario_contexts": ["A crew chief sweeping the stage and wings after load-out to catch forgotten gear", "A backline tech doing an idiot check of the dressing room before the bus rolls"]}, "d1dbff8c-22aa-44b7-b9eb-07851ec396f8": {"definition": "Slang for carrying out audio production — mixing, processing, and often recording — entirely within a digital audio workstation (DAW) on a computer, using software plug-ins rather than external hardware; abbreviated ITB.", "plain_english": "\"In the box\" means doing all the mixing inside the computer. You use software instead of separate hardware gear.", "purpose_function": "It describes a workflow that keeps the signal in the digital domain, so all processing, recall, and automation live in software.", "practical_application": "An engineer working in the box mixes a show file entirely with plug-ins, keeping total recall without patching outboard gear.", "category": "Audio Workflow", "related_terms": ["DAW", "Plug-in", "Outboard", "Total recall", "Front of house"], "common_mistakes": ["Assuming \"in the box\" means lower quality; the term describes the workflow, not the result", "Confusing \"in the box\" (all software) with a hybrid setup that still uses outboard hardware"], "scenario_contexts": ["A mix engineer running a full show mix in the box with plug-in processing", "A recordist tracking and mixing entirely in the box on a laptop rig"]}, "464abd3b-fdaf-4a35-a116-21b9500b360e": {"definition": "A touring crew member responsible for the setup, tuning, maintenance, and stage-side readiness of a performer's musical instruments — such as guitars, drums, or keyboards — and their associated backline.", "plain_english": "An instrument technician looks after a band's instruments on tour. They set them up, tune them, and fix problems fast.", "purpose_function": "It exists so performers reach instruments that are tuned, working, and ready, with quick swaps if something fails mid-show.", "practical_application": "An instrument technician restrings and tunes guitars before doors, then hands off backups during the set if a string breaks.", "category": "Crew Roles", "related_terms": ["Backline", "Guitar tech", "Keyboard tech", "Drum tech", "Roadie"], "common_mistakes": ["Assuming the instrument tech only tunes; they also maintain, repair, and stage the backline", "Confusing the instrument tech with the general backline tech role, which can overlap or differ by tour"], "scenario_contexts": ["An instrument technician preparing and tuning a guitar rig during soundcheck", "A tech swapping a failed instrument for a backup mid-song"]}, "61b128e6-18b0-4fdb-b941-345da2f2bcea": {"definition": "A road case set aside for miscellaneous, loose, or odd items — spare cables, hardware, tools, tape, and consumables — that do not belong to a specific labeled case.", "plain_english": "A junk case is a road case for random spare stuff. It holds loose cables, tape, and small odds and ends.", "purpose_function": "It gives loose bits and spares a single home, so miscellaneous gear travels safely and can be found quickly.", "practical_application": "A tech loads leftover cable, gaffer tape, and spare hardware into the junk case at load-out so nothing loose rides free in the truck.", "category": "Road Cases", "related_terms": ["Road case", "Cable trunk", "Idiot check", "Load-out", "Backline"], "common_mistakes": ["Letting the junk case become a disorganised dump, so nothing can be found under pressure", "Storing valuable or fragile gear loose in the junk case instead of a proper padded case"], "scenario_contexts": ["A crew loading spare cables and hardware into the junk case at the end of the night", "A tech grabbing gaffer tape and adapters from the junk case during setup"]}, "6863a59e-73f4-4016-b92a-1433779f75ba": {"definition": "The touring technician responsible for a keyboard player's rig — synthesizers, digital pianos, controllers, sound modules, and their audio, MIDI, and power connections — including patching, program recall, and troubleshooting.", "plain_english": "A keyboard tech sets up and looks after a band's keyboards and synths. They fix any problems during the show.", "purpose_function": "It ensures the keyboard rig is patched, powered, loaded with the right sounds, and stays working through the performance.", "practical_application": "A keyboard tech boots the synth rig, confirms MIDI and audio routing, and loads the show's patches before soundcheck.", "category": "Crew Roles", "related_terms": ["Instrument technician", "Backline", "MIDI", "Drum tech", "Guitar tech"], "common_mistakes": ["Assuming the keyboard tech only plugs in gear; they manage patches, MIDI routing, and program changes", "Overlooking backup power or spare controllers, leaving no recovery if a unit fails mid-set"], "scenario_contexts": ["A keyboard tech loading and checking synth patches during soundcheck", "A tech recovering a crashed keyboard rig between songs"]}, "2b8e6084-43e1-4aa1-ba73-04c98b606a5d": {"definition": "An imperative crew command to immediately stop or switch off something — an audio source, a light, a signal, a machine, or power — as in \"kill it,\" meaning shut it down now.", "plain_english": "\"Kill it\" means turn it off right now. It could mean the sound, a light, or the power.", "purpose_function": "It gives a fast, unambiguous order to cut something off quickly, often to stop noise, a fault, or a hazard.", "practical_application": "When feedback howls, the engineer shouts \"kill it\" and the operator mutes the channel or cuts the offending source.", "category": "Crew Communication", "related_terms": ["Mute", "Blackout", "Kill switch", "Standby", "Cue"], "common_mistakes": ["Assuming \"kill it\" refers to what you are watching rather than what the caller actually means", "UNSAFE: Cutting power on \"kill it\" before confirming the target, which can drop powered hoists or interrupt systems that must stay live"], "scenario_contexts": ["A front-of-house engineer calling \"kill it\" to stop sudden feedback", "A stage manager telling an operator to kill a light that fires on a wrong cue"]}, "4a7b7bb7-7575-46b1-b3b8-d1c4c28a0f69": {"definition": "The scheduled report time and requested number of local stagehands (labor) booked to work a load-in, show, or load-out, as arranged between the production and the venue or labor provider.", "plain_english": "A labor call is when local stagehands are told to show up, and how many are needed. It sets the crew for load-in or load-out.", "purpose_function": "It commits the right number of local workers at the right time, so load-in, the show, and load-out are properly staffed.", "practical_application": "A production manager advances a labor call of, say, twelve hands at 8 a.m., and the venue supplies them for load-in.", "category": "Crew Scheduling", "related_terms": ["Load-in", "Load-out", "House crew", "Stagehand", "Call time"], "common_mistakes": ["Confusing the labor call (crew numbers and report time) with an individual's personal call time", "Under-booking the labor call, leaving too few hands to load in safely and on schedule"], "scenario_contexts": ["A production manager setting a labor call for the number of stagehands needed at load-in", "A steward assigning the called labor to departments when the crew arrives"]}, "44ac38a3-9efe-433b-b163-ae33cb59d90c": {"definition": "Short for a lapel (lavalier) microphone: a small, clip-on microphone attached to a performer's clothing near the chest or collar, typically an omnidirectional or directional electret condenser used for hands-free speech pickup.", "plain_english": "A lapel is a tiny clip-on microphone. It fastens to clothing so someone can talk with their hands free.", "purpose_function": "It captures a voice hands-free at a fairly steady distance, so presenters and actors can move without holding a mic.", "practical_application": "An A2 clips a lapel to a presenter's collar, dresses the cable, and connects it to a bodypack transmitter before the show.", "category": "Microphones", "related_terms": ["Lavalier", "Bodypack", "Wireless microphone", "Headset mic", "Windscreen"], "common_mistakes": ["Placing the lapel too low or under clothing, dulling the voice and causing clothing rustle", "Assuming every lapel is omnidirectional; a directional lapel must be aimed carefully at the mouth"], "scenario_contexts": ["An audio tech fitting a lapel mic to a keynote speaker before a conference", "A theatre sound crew rigging lapel mics on actors for a musical"]}, "d06cb10d-1817-4c58-aa3e-f86430208cb5": {"definition": "A final review or visual check made immediately before an action or transition — such as a last scan of the stage, set, or work area before doors open, a cue fires, or the crew departs — to confirm everything is correct and safe.", "plain_english": "A last look is a final check right before something happens. Crew scan the stage or gear to catch anything wrong.", "purpose_function": "It provides a final verification step, so problems are caught before doors, a cue, or departure, when fixing them is harder.", "practical_application": "Before opening the house, the stage manager takes a last look at the set and deck to confirm props and safety are in place.", "category": "Crew Workflow", "related_terms": ["Idiot check", "Preset", "Standby", "House open", "Load-out"], "common_mistakes": ["Treating the last look as a formality and rushing it, so a missed hazard or wrong preset slips through", "Confusing a last look (final check before an action) with a full pre-show inspection done earlier"], "scenario_contexts": ["A stage manager taking a last look at the deck before calling house open", "A crew doing a last look at the stage before a scene change goes live"]}, "a0159c24-3be8-4b73-a922-5cdbb4232c32": {"definition": "The team of technicians responsible for a production's stage and show lighting: hanging (rigging) and cabling the fixtures, focusing them, and operating the lighting instruments and control desk, typically under a lighting director or head electrician.", "plain_english": "The lighting crew are the people who set up and run the show lights. They hang the fixtures, aim them, and control them during the show.", "purpose_function": "It supplies the skilled labour to rig, power, focus and operate the lighting rig, so a production has safe, correct illumination and lighting effects.", "practical_application": "On load-in day the lighting crew hangs and cables the rig, then focuses each fixture before the operator programmes and runs the lighting cues.", "category": "Crew Roles", "related_terms": ["Lighting director", "Gaffer", "Rigging", "Load-in", "Focus", "Dimmer"], "common_mistakes": ["Assuming the lighting crew only wire dimmers; they also rig, focus and operate the fixtures and control desk", "UNSAFE: Standing or working directly beneath an overhead lighting rig while fixtures are being hung, instead of clearing the area below and wearing head protection"], "scenario_contexts": ["A lighting crew hanging and focusing a moving-light rig during a concert load-in", "A touring lighting crew coordinating with the house crew to power and fly the lighting truss"]}, "15775240-2b9e-4f86-81e2-d557b8bfa221": {"definition": "The control or action that mutes (silences) a specific signal line or channel, stopping it from passing audio to the mix, output bus or intercom while leaving the physical connection otherwise intact.", "plain_english": "Line mute switches off the sound on one channel or line. The cable stays plugged in, but no audio gets through until you unmute it.", "purpose_function": "It lets an operator silence one source instantly without unplugging it, keeping noise, feedback or an unwanted signal out of the output.", "practical_application": "An engineer hits line mute on an unused input to keep hiss or bleed out of the mix, then unmutes it when that source is needed.", "category": "Signal Control", "related_terms": ["Mute", "Channel", "Fader", "Cut", "Solo", "Talkback"], "common_mistakes": ["Forgetting a line is muted and troubleshooting the source when the mute is the real cause of no audio", "Muting the wrong line and cutting a needed source during the show"], "scenario_contexts": ["An engineer muting a DI line between songs to stop hum reaching the PA", "A comms operator muting a talkback line so side conversations do not go out to all stations"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"d7e1e8c1-f75c-43d4-91ac-b72a6dcdee98": {"definition": "The point in show preparation when the technician who has completed the line check - verifying that every input line/channel is connected and passing signal - formally transfers control of the checked system to the mixing engineer who will run the show.", "plain_english": "A line check tests that every input is plugged in and working. The handoff is when the tech who did that check passes the ready system to the show engineer.", "purpose_function": "It confirms every input works and transfers responsibility cleanly, so the show engineer starts with a fully checked, known-good signal path.", "practical_application": "After ringing out each channel, the systems tech tells the incoming engineer which lines are good and any problems, then hands over the console for the show.", "category": "Soundcheck", "related_terms": ["Line check", "Soundcheck", "Front of house", "Patch", "Stage box", "Ring out"], "common_mistakes": ["Treating a line check as a full soundcheck; a line check confirms signal is present, not the band's mix balance", "Handing off without noting which lines had problems, so the show engineer is caught out mid-show"], "scenario_contexts": ["A monitor tech completing a line check and handing the desk to the monitor engineer before doors", "A festival changeover where each act's systems tech line-checks then hands off to the incoming FOH engineer"]}, "4b7f03c7-37a5-4e84-aaf3-ba6dbdabd803": {"definition": "In production, 'live' describes anything energized or currently active: an electrical conductor connected to a source of voltage (electrically live parts), a microphone, channel or fader that is open and passing signal, or a performance taking place in real time before an audience.", "plain_english": "Live means switched on and active. A live cable carries electricity. A live mic is open and hears everything. A live show happens in real time. Always treat anything live as hot.", "purpose_function": "The label warns crew that a conductor, signal path or performance is active, so they handle it correctly and avoid shocks, feedback or open-mic mistakes.", "practical_application": "A technician confirms whether a cable or channel is live before touching it, patching it, or speaking near an open microphone.", "category": "Signal Status", "related_terms": ["Hot", "Dead", "Energized", "Open mic", "Front of house", "Feedback"], "common_mistakes": ["UNSAFE: Assuming a cable or circuit is dead and handling it without testing; a live conductor can deliver a serious or fatal shock", "Talking or making noise near a live (open) microphone, believing it is off", "Confusing an acoustically 'live' (reverberant) room with an electrically live circuit"], "scenario_contexts": ["A crew member testing whether a mains cable is live before disconnecting it", "An engineer reminding talent that the microphone is live before the broadcast starts"]}, "710e71d8-45ef-4b82-b49b-5a21b7711b46": {"definition": "A loader is a crew member, usually hired local labour, whose job is to load and unload the production's trucks at load-in and load-out, moving cased equipment between the vehicles and the loading dock or stage. Loaders typically work under a head loader, crew chief, or the stage manager and often specialise in packing the truck tightly and in the correct order.", "plain_english": "A loader is a worker who loads and unloads the show's trucks. They move the heavy equipment cases on and off the vehicles. They are often hired locally just for that day.", "purpose_function": "The role exists to move gear quickly and safely between trucks and the venue, and to pack trucks tightly and in order so all the equipment fits and rides securely to the next stop.", "practical_application": "At load-out a loader receives rolling cases from the stage crew and stacks them into the truck in a planned pack order so the load is full and stable for transport.", "category": "Crew role", "related_terms": ["Local crew", "Load-in", "Load-out", "Road case", "Truck pack", "Crew chief"], "common_mistakes": ["UNSAFE: Lifting or dragging heavy cases alone instead of using teamwork, ramps, or handling aids, which risks back and crush injuries.", "Thinking a loader just throws gear in the truck; efficient, ordered truck packing is a skilled part of the job.", "Confusing a loader with a full touring crew member; loaders are usually local hires for the load-in and load-out only."], "scenario_contexts": ["A local loader unloading tour trucks in the early morning before a concert load-in.", "Loaders stacking road cases into a trailer in a set pack order at load-out.", "A crew chief directing loaders to keep fire lanes and ramps clear while working."]}, "51947571-35af-4e6c-8688-9d55ed1d0bc2": {"definition": "A loading ramp is an inclined surface, either built into a loading dock or a portable/truck-mounted plate, that bridges the height difference between ground or dock level and a truck bed or stage so wheeled road cases can be rolled across. It provides a continuous rolling path for heavy cased equipment during load-in and load-out.", "plain_english": "A loading ramp is a slope that connects the ground or dock to a truck or stage. Crews roll heavy equipment cases up and down it. It saves lifting the cases by hand.", "purpose_function": "It exists to let crews roll heavy cases between different heights, avoiding manual lifting and speeding up the loading and unloading of trucks.", "practical_application": "At load-out a technician wheels road cases down the venue's dock ramp or a truck's ramp plate, keeping firm control of each case so it does not run away on the slope.", "category": "Load-in / Load-out", "related_terms": ["Road case", "Loading dock", "Load-in", "Load-out", "Loader", "Truck pack"], "common_mistakes": ["UNSAFE: Losing control of a heavy rolling case on a ramp; keep every case controlled, use a spotter, and never let it run free down a slope.", "UNSAFE: Exceeding a portable ramp's rated load capacity, which can cause the ramp to fail or collapse under a heavy case.", "Assuming any ramp angle is fine; a ramp that is too steep makes heavy cases hard to control going down and hard to push up."], "scenario_contexts": ["Rolling amplifier racks up a truck ramp into the trailer at load-out.", "Using a venue's loading dock ramp to bring cases up to stage level.", "Placing a portable ramp to bridge a curb or step for wheeled cases."]}, "92919af0-94eb-4ea6-ac77-275ce47b43ee": {"definition": "Local crew are stagehands and technicians hired at each venue or city to supplement the touring crew for load-in, the running of the show, and load-out, rather than travelling with the production. They are commonly supplied through a local labour provider or stagehand union and work under the direction of the touring department heads.", "plain_english": "Local crew are workers hired in each city to help with the show. They are not part of the travelling tour crew. They mainly help load in, run the show, and load out.", "purpose_function": "They exist to provide the extra hands and local knowledge each venue needs, so a small touring crew can move and run a large show without carrying dozens of extra staff.", "practical_application": "A touring audio technician briefs the local crew assigned to sound, showing them where the speakers, cases, and cables go during load-in.", "category": "Crew Roles", "related_terms": ["Loader", "Touring crew", "Stagehand", "Load-in", "Crew call", "Crew chief"], "common_mistakes": ["Assuming local crew already know this specific show; touring department heads must brief and supervise them each day.", "Confusing local crew with the touring crew; local crew are hired per venue and usually leave after load-out.", "UNSAFE: Treating all local crew as interchangeable for any task; rigging and other specialist safety work still requires qualified, ticketed personnel."], "scenario_contexts": ["Local stagehands hired through the union to push cases and build the stage at load-in.", "Local crew split into lighting, audio, and video departments under each touring head.", "A production manager ordering a set number of local crew for the load-in and load-out calls."]}, "a3fe7005-352d-4fb0-81fe-f99a41ba743c": {"definition": "A radio or intercom readability confirmation stating that a transmission is being received at good volume and with full intelligibility, reporting both adequate signal strength ('loud') and clarity free of distortion or noise ('clear'). It is the positive counterpart to reports such as 'weak', 'broken', or 'unreadable'.", "plain_english": "Loud and clear means someone can hear your radio message well. The sound is strong enough and easy to understand. It confirms the comms link between crew is working.", "purpose_function": "It exists to quickly confirm on comms that a channel is working well, so crew know their messages are getting through before they rely on the link during a show.", "practical_application": "During a radio check a technician keys the mic and hears 'loud and clear' back, confirming the intercom or two-way radio path is good before doors open.", "category": "Crew comms", "related_terms": ["Good copy", "Radio check", "Comms", "Intercom", "Clear", "Good to go"], "common_mistakes": ["Confusing 'loud and clear' (a report on reception quality) with 'good to go' (a report of readiness to proceed).", "Saying 'loud and clear' out of habit without actually judging whether the signal was strong and clear.", "Assuming a good radio check means coverage everywhere; a signal can still drop out in RF-shadowed parts of the venue."], "scenario_contexts": ["A radio check before doors where each department confirms it hears 'loud and clear'.", "A monitor engineer confirming the intercom link to front of house is loud and clear.", "Testing two-way radios across a large festival site to check readability."]}, "0e5f3093-8d63-42bd-a6ce-ef0fde1f50fe": {"definition": "A loudspeaker technician (PA tech or speaker tech) is the sound-crew member responsible for the loudspeaker system, including assembling, stacking or flying the arrays, running speaker and signal cabling, and assisting the system engineer with the physical setup and checks. The role handles the mechanical and electrical deployment of the PA rather than the mixing.", "plain_english": "A loudspeaker technician sets up and looks after the PA speakers. They build the speaker stacks or hang the arrays and run the cables. They work under the system engineer, not the mixer.", "purpose_function": "The role exists to get the loudspeaker system safely rigged, cabled, and working so the system engineer can tune it and the mix engineers can use it.", "practical_application": "At load-in the loudspeaker technician assembles the line-array cabinets, helps fly or stack them, connects the amplifier and speaker cabling, and checks each box works.", "category": "Crew role", "related_terms": ["System engineer", "Line array", "PA system", "Amplifier rack", "Rigging", "Monitor engineer"], "common_mistakes": ["UNSAFE: Flying loudspeaker arrays without a qualified rigger, inspected hardware, and following the manufacturer's rigging manual and its rated limits.", "Confusing the loudspeaker technician with the system engineer; the tech deploys and cables the PA, while the engineer tunes it.", "Skipping a check of every cabinet and cable run, so a dead box or a bad cable is only found during soundcheck."], "scenario_contexts": ["A speaker tech building and flying the main line arrays at a concert load-in.", "A loudspeaker technician tracing a dead cabinet to a faulty speaker cable before soundcheck.", "The PA tech coiling and packing all the loudspeaker cabling at load-out."]}, "560d8ea1-3cd6-402b-bae7-9ad9e58ddb4e": {"definition": "A designated staging area, usually just outside or near a venue's loading dock, where trucks, forklifts, and equipment cases are organised and sequenced before being brought inside during load-in; vehicles are held here until called forward to the dock.", "plain_english": "A marshalling area is a holding spot near the loading dock. Trucks and gear wait there until the crew is ready to bring them in.", "purpose_function": "It keeps waiting trucks and cases orderly and out of the way, so load-in flows in the right sequence without dock congestion or misplaced gear.", "practical_application": "A production or transport manager parks arriving trucks in the marshalling area and calls them to the dock one at a time as the crew are ready.", "category": "Load-in Logistics", "related_terms": ["Load-in", "Loading dock", "Road case", "Truck pack", "Advance"], "common_mistakes": ["Confusing the marshalling area with the loading dock itself; the marshalling area is where vehicles wait, not where they unload", "Leaving cases disorganised in the marshalling area, so crew cannot pull gear in the load-in order", "UNSAFE: Standing or working in the truck and forklift lanes of a marshalling area, where moving vehicles create a struck-by hazard"], "scenario_contexts": ["Arena trucks lining up in a parking-lot marshalling area before a staggered load-in", "A stage manager holding lighting trucks in the marshalling area until the audio cases are unloaded first"]}, "0991ab92-45b4-4631-b21b-d9e8dc2f0a23": {"definition": "A junior studio role that supports a mastering engineer by preparing session files, documenting settings, managing recall and archiving, handling revisions, and readying the room and gear, while learning the craft toward working as a mastering engineer.", "plain_english": "A mastering assistant helps the mastering engineer put the final polish on a record. They prep the files, take notes, and keep the session neat.", "purpose_function": "It frees the mastering engineer to focus on critical listening and decisions, while the assistant handles setup, files, and paperwork.", "practical_application": "In a mastering house, the assistant loads the mixes, logs the processing and levels, exports the masters and DDP files, and prepares recall for later revisions.", "category": "Studio Roles", "related_terms": ["Mastering engineer", "Mix engineer assistant", "DDP", "Recall", "Studio session"], "common_mistakes": ["Thinking a mastering assistant makes the final tonal and loudness decisions; those belong to the mastering engineer", "Confusing the mastering assistant with the mixing assistant, who works on the earlier mix stage"], "scenario_contexts": ["A mastering assistant preparing a client's mixes and reference tracks before a session", "An assistant generating and checking a DDP master for a CD replication order"]}, "f5dbb0e1-cf2a-43e8-9e35-c99d7195216d": {"definition": "A large road case, typically a lidded, wheeled trunk with fitted foam or dividers, used to transport and store a production's microphones — often with their clips, mounts, and windscreens — protecting them in transit and organising them for setup.", "plain_english": "A mic trunk is a padded road case on wheels for a show's microphones. It protects the mics while travelling and keeps them sorted for setup.", "purpose_function": "It shields fragile microphones from shock, dust, and moisture in transit, and keeps a set of mics organised so crew can deploy them quickly.", "practical_application": "The audio crew opens the mic trunk at load-in, checks the mic inventory against the input list, and returns each mic to its foam slot at load-out.", "category": "Road Cases", "related_terms": ["Road case", "Microphone package", "Microphone technician", "Input list", "Load-in"], "common_mistakes": ["Returning microphones to the wrong foam slots, so the next inventory check does not match the input list", "Packing damp or dusty mics into the trunk instead of drying and cleaning them first"], "scenario_contexts": ["A mic tech drawing vocal and drum mics from the mic trunk during stage setup", "Counting mics back into the trunk at load-out to confirm none are lost"]}, "c861d970-2aa0-4365-b97e-4853cf6bb07c": {"definition": "The complete complement of microphones specified and carried for a production or tour — chosen to cover every input on the input list — commonly including the associated stands, clips, mounts, and cabling needed to deploy them.", "plain_english": "A microphone package is the full set of mics a show carries. It covers every instrument and voice that needs to be picked up.", "purpose_function": "It ensures every source on the input list has a suitable microphone, so the production can capture or reinforce all the instruments and voices.", "practical_application": "An engineer builds the microphone package from the input list and rider, then packs it in the mic trunk for the tour.", "category": "Audio Equipment", "related_terms": ["Mic trunk", "Input list", "Microphone technician", "Technical rider", "Stage plot"], "common_mistakes": ["Building the package without checking the input list, so an instrument arrives with no suitable mic", "Forgetting the stands, clips, and cables that the package needs to actually deploy the mics"], "scenario_contexts": ["A tour carrying its own microphone package so each venue sounds consistent", "An engineer adding spare mics to the package to cover breakages on a long tour"]}, "bed4c2b1-826e-4221-9bba-79a4399c5c53": {"definition": "An audio crew member responsible for a production's microphones — selecting, placing, cabling, testing, and maintaining them and managing the mic package; on wireless-heavy shows the role often overlaps with the RF technician.", "plain_english": "A microphone technician sets up and looks after all the mics for a show. They place the mics, plug them in, and fix any that fail.", "purpose_function": "It puts one skilled person in charge of mic choice, placement, and upkeep, so every source is captured cleanly and reliably during the show.", "practical_application": "At setup the mic tech rigs mics to the stage plot, tests each channel with the console engineer, and swaps failed mics or batteries during the show.", "category": "Crew Roles", "related_terms": ["Mic trunk", "Microphone package", "RF technician", "Stage plot", "Input list"], "common_mistakes": ["Assuming the mic tech only places mics; they also test, maintain, and troubleshoot them throughout the show", "Skipping a line check, so a dead or misrouted mic is only found once the act is on stage"], "scenario_contexts": ["A mic tech taping lavalier mics to actors before a musical", "A mic tech replacing a failed wireless handheld between songs"]}, "28c1f5fe-155a-4f23-9a5b-780bde153cb2": {"definition": "A junior studio role that supports a mixing engineer by setting up sessions, organising and labelling tracks, managing recall and revisions, running the room and outboard gear, and handling documentation, while learning the craft toward mixing independently.", "plain_english": "A mix engineer assistant helps the mixing engineer combine all the recorded tracks. They set up the session, keep tracks tidy, and take notes.", "purpose_function": "It handles setup, file management, and recall, so the mixing engineer can concentrate on balancing the tracks and making creative choices.", "practical_application": "The assistant imports and labels the multitrack, sets up the console or DAW template, and saves recall sheets so a mix can be revised later.", "category": "Studio Roles", "related_terms": ["Mixing engineer", "Mastering assistant", "Recall", "Multitrack", "Studio session"], "common_mistakes": ["Thinking the assistant makes the main balance and creative mix decisions; those belong to the mixing engineer", "Failing to save a clear recall, so a requested revision cannot match the original mix"], "scenario_contexts": ["An assistant prepping and labelling a multitrack before the mixing engineer arrives", "An assistant recalling a saved session to make a client's mix revision"]}, "0c202c79-d1d6-4d8e-8280-cf75761b9752": {"definition": "A front-of-house situation in which the mix position sits beneath a balcony overhang; the overhang shadows the position from the main system's high frequencies and reverberant field, producing dull, uneven sound that misrepresents what most of the audience hears.", "plain_english": "Mixing under a balcony means the mix desk sits below the balcony's overhang. The overhang blocks the highs, so the sound there is dull and misleading.", "purpose_function": "The term flags a compromised listening spot, so engineers know their mix judgement is unreliable there and can check the open room or relocate.", "practical_application": "An engineer forced to mix under a balcony walks the open house to hear the real sound, and leans on measurement tools rather than trusting the dull position.", "category": "Mix Position", "related_terms": ["Front of house", "Mix position", "Comb filtering", "Coverage", "Reverberant field"], "common_mistakes": ["Trusting the dull sound under the balcony and adding high-frequency boost, which makes the mix harsh everywhere else", "Assuming the whole room sounds like the under-balcony position, instead of checking the open seating"], "scenario_contexts": ["A festival front-of-house tent tucked under a stadium balcony overhang", "A club where the only mix spot is beneath a low mezzanine, shadowed from the mains"]}, "e5c7cb44-cd06-4e15-b96e-11a18fea4a11": {"definition": "The complete set of stage-monitoring equipment supplied for a show or tour: the monitor console, wedge loudspeakers and/or in-ear monitor (IEM) systems, plus the associated processing, amplification and cabling used to give performers their own foldback mixes.", "plain_english": "The monitor package is all the gear that lets a band hear itself on stage. It includes the monitor desk, the floor speakers and any in-ear systems.", "purpose_function": "It groups every piece needed to build performers' on-stage mixes into one specified inventory, so a venue or rental house can supply the right foldback rig for the act.", "practical_application": "A monitor technician checks the incoming monitor package against the rider, then patches the console, wedges and IEMs before line check.", "category": "Monitoring", "related_terms": ["Monitor technician", "Wedge", "In-ear monitor", "Foldback", "Rider"], "common_mistakes": ["Confusing the monitor package with the front-of-house (FOH) package; the monitor package serves the performers on stage, not the audience", "Assuming every package includes in-ear systems, when some provide only floor wedges"], "scenario_contexts": ["A rental company quoting a monitor package to match an artist's technical rider", "A monitor tech unloading and patching the monitor package during load-in"]}, "18f0bcb4-2a70-4bcc-a89a-6071742d557a": {"definition": "The audio engineer — also called the monitor technician — responsible for the stage-monitoring system, who mixes and maintains the foldback that performers hear through floor wedges and in-ear monitors, usually working from a dedicated monitor console at the side of the stage.", "plain_english": "The monitor technician mixes the sound the band hears on stage. They work from a desk at the side of the stage and control the floor speakers and in-ears.", "purpose_function": "It exists so performers get clear, stable on-stage mixes tailored to each person, freeing the front-of-house engineer to focus on the audience mix.", "practical_application": "During the show the monitor tech builds a separate mix for each performer and responds fast to talkback or hand signals asking for 'more vocal' or 'less guitar'.", "category": "Crew Roles", "related_terms": ["Monitor package", "Monitor console", "Wedge", "In-ear monitor", "Front of house", "Foldback"], "common_mistakes": ["Confusing the monitor engineer with the front-of-house engineer; they mix for different listeners", "Thinking one mix serves everyone, when each performer usually needs their own mix"], "scenario_contexts": ["A monitor tech ringing out wedges to control feedback before a performance", "A monitor engineer switching a singer from a floor wedge to in-ear monitors mid-tour"]}, "61fa8d94-30f2-4414-ab72-04eca0e55162": {"definition": "The electrical control system used to operate electric chain hoists (motors) in entertainment rigging, providing direction (up/down) and, on some units, variable speed for one or more hoists, with safety features such as an emergency stop and protection against uncontrolled or reversed-phase movement.", "plain_english": "Motor control is the box and buttons that raise and lower rigging motors. It sends the up and down commands and has an emergency stop button.", "purpose_function": "It lets a rigger move overhead loads precisely and stop them instantly, which is essential for safely flying trusses, PA and lighting.", "practical_application": "A rigger uses the motor control pendant or console to bring hoists to trim, and hits the emergency stop the moment a load binds or hangs up.", "category": "Rigging", "related_terms": ["Chain hoist", "Motor point", "Truss", "Rigging point", "Trim"], "common_mistakes": ["UNSAFE: Running a motor while people are working under or near the suspended load, instead of clearing the area first", "UNSAFE: Reversing supply phases so a hoist travels opposite to its controls, causing an unexpected direction of movement", "Confusing fixed-speed control with variable-speed control, which start and stop loads differently"], "scenario_contexts": ["A rigger flying a lighting truss to trim using a variable-speed motor controller", "A crew chief hitting the emergency stop when a chain motor jams during load-in"]}, "fe04a08f-900f-43d5-be0e-059f0b9a4833": {"definition": "An overhead location in a venue's structure from which a single electric chain hoist (motor) is rigged to fly a load such as truss, PA or lighting; each motor point is planned so the load stays within the rated capacity of the hoist, its rigging hardware and the supporting structure.", "plain_english": "A motor point is one spot overhead where a rigging motor hangs to lift gear. Each point is planned so the weight stays within safe limits for the motor and the building.", "purpose_function": "Motor points let a production spread the weight of flown systems across the structure at planned, load-rated positions.", "practical_application": "A rigger reads the rigging plot, then installs steel and a hoist at each marked motor point before the motors are used to fly the trusses.", "category": "Rigging", "related_terms": ["Motor control", "Chain hoist", "Rigging point", "Bridle", "Working load limit"], "common_mistakes": ["UNSAFE: Hanging more weight at a motor point than the hoist, hardware or structure is rated for, instead of checking the load against its limits", "UNSAFE: Rigging to a structural member that has not been approved for the intended load", "Confusing a motor point (a rated overhead attachment location) with the chain hoist itself"], "scenario_contexts": ["A production rigger and house rigger agreeing the number and position of motor points a show needs", "A venue confirming the safe working load available at each motor point"]}, "5b3abe6a-e6b6-4cd4-a42e-bffeb5b133a4": {"definition": "A person who engages and organizes musicians on behalf of a producer for a recording session, film or television score, or live engagement — booking the required players, confirming instrumentation, and handling union paperwork and payments; under AFM agreements a contractor must be employed when a set number of musicians (twelve or more musicians on a sound-recording session) are used.", "plain_english": "A music contractor hires the musicians a producer needs and sorts out the paperwork. For big sessions the musicians' union requires one to be on hand.", "purpose_function": "It gives a producer a single expert to find, book and manage qualified players, so a session or show has the right people under the correct union terms.", "practical_application": "A film composer tells the music contractor the instrumentation and dates; the contractor books the players, arranges the studio call, and files the AFM paperwork.", "category": "Production Roles", "related_terms": ["Session musician", "Leader", "Music director", "Rider"], "common_mistakes": ["Confusing the music contractor (who hires and manages the players) with the conductor or music director (who leads the performance)", "Assuming musicians can always be booked informally, when union sessions require a contractor and proper paperwork"], "scenario_contexts": ["A music contractor assembling a string section for a film-score recording date", "A contractor filing AFM reports and pay after a large recording session"]}, "0948c2ec-3600-49cb-a8cb-e9debf9b1c8a": {"definition": "A limit, set by a venue's licence or a local ordinance, on when amplified sound must stop or drop below a stated level; it fixes a cut-off time (and sometimes level limits) that a show, and often its load-out, must respect to comply with community noise regulation.", "plain_english": "A noise curfew is a set time when the sound has to stop or get much quieter. It is set by the venue's licence or local law so shows do not disturb neighbours.", "purpose_function": "It protects the surrounding community from late or excessive noise and keeps the event within its licence, so the promoter avoids fines or losing the venue.", "practical_application": "The production manager schedules the set so the headliner finishes before the noise curfew, and warns the crew that even load-out noise may be limited.", "category": "Regulations", "related_terms": ["Sound pressure level", "Load-out", "Production manager", "Rider"], "common_mistakes": ["Thinking the curfew only limits the music, when it can also restrict noisy load-out afterwards", "Confusing a noise curfew (a legal or licence limit) with a house sound-level policy set by the venue"], "scenario_contexts": ["A festival cutting a headliner's encore to meet a strict local noise curfew", "A touring crew keeping load-out quiet because the venue licence sets a night-time curfew"]}, "07f924d3-4583-48c7-a192-b3d00e5fc32c": {"definition": "A road-crew load-out instruction to load all cased and palletized production gear back into the tour trucks at the end of a show, following a planned pack order and tight arrangement that fits the available space, protects equipment, distributes weight, and reverses correctly for the next load-in.", "plain_english": "Pack the truck means loading all the show gear back into the trucks after the show. The crew stacks the cases in a set order. That way everything fits and comes out ready for the next show.", "purpose_function": "It gets every piece of gear off the stage and safely into transport in an order that fills the truck efficiently and speeds the next day's load-in.", "practical_application": "At load-out the crew chief calls to pack the truck, and stagehands roll cases to the dock and stack them by the truck pack plan under the truck boss.", "category": "Load-in / Load-out", "related_terms": ["Load-out", "Load-in", "Truck pack", "Dock", "Road case", "Truck boss"], "common_mistakes": ["Loading cases in a random order instead of the pack plan, so weight is uneven and the next load-in is slow", "Packing gear before cases are latched or foam is replaced, letting equipment shift and take damage in transit", "UNSAFE: Lifting or stacking heavy cases by hand instead of using ramps, lifts, and team lifting, risking crush and back injuries"], "scenario_contexts": ["Loading the tour trucks in the correct pack order at the end of a show", "Stacking road cases tightly so a full rig fits the available truck space", "Reversing the pack so the first cases needed are the last ones loaded"]}, "9c750bea-dd52-4dca-bba4-73c0e1ca8e15": {"definition": "An instruction to engage an attenuation pad, a fixed or switchable resistive attenuator on a microphone, direct box, or console/preamp input, to reduce a signal's level (commonly by 10, 15, or 20 dB) ahead of the input stage so a hot source does not overload and clip the preamp.", "plain_english": "Pad it means switching on a pad, which lowers a loud signal before it hits the input. It stops a very strong source from overloading the gear and distorting. Think of it like sunglasses that cut bright light down to a safe level.", "purpose_function": "A pad attenuates a signal that is too strong for an input stage, restoring headroom so a loud source can be captured cleanly without clipping the preamp.", "practical_application": "When a close-miked kick drum or a hot keyboard output distorts the channel, the engineer flips the mic's or channel's pad switch to drop the level before gain is applied.", "category": "Gain Structure", "related_terms": ["Attenuator", "Gain structure", "Headroom", "Clipping", "Preamp", "Direct box"], "common_mistakes": ["Leaving a pad engaged after the loud source is gone, then cranking gain and adding noise because the signal is now too weak", "Confusing a pad, which attenuates the whole input signal, with a high-pass filter or a trim control", "Assuming a pad changes tone; a well-designed pad only lowers level, not frequency response"], "scenario_contexts": ["Engaging a microphone's pad on a close kick-drum mic that is clipping the channel", "Padding a keyboard's line-level output feeding a DI or a mic input", "Switching in a console input pad when a guest sends a hot signal during a changeover"]}, "a44022d8-5a56-4f71-a852-f7bcc919148b": {"definition": "A passive direct box (passive DI) is a direct-injection interface built around an audio transformer that, without any power, converts a high-impedance, unbalanced instrument-level signal into a low-impedance, balanced, mic-level signal for a console input. The transformer also provides galvanic isolation between source and console, helping break ground loops, and the passive design tolerates very hot signals without clipping.", "plain_english": "A passive direct box connects an instrument, like a bass or keyboard, to a mixer. It uses a transformer and needs no power at all. It turns the signal into a balanced one that travels far without hum. It also handles very loud signals well.", "purpose_function": "It matches an instrument's output to a console's mic input and balances the signal so it runs long cables quietly, while its transformer isolates the two grounds to stop hum from ground loops.", "practical_application": "A stage tech plugs a hot keyboard, DJ mixer, or active bass into a passive DI, then sends its balanced output over a mic line to the stage box, with no phantom power needed.", "category": "Signal Interface", "related_terms": ["Active direct box", "DI", "Phantom power", "Balanced signal", "Ground loop", "Impedance"], "common_mistakes": ["Feeding phantom power to a passive DI expecting it to help; a passive DI is transformer-based and does not use phantom power", "Using a passive DI on a weak passive piezo pickup, where its lower input impedance can dull the high end; an active DI often suits that source better", "Confusing the ground-lift switch, which lifts the signal ground to reduce hum, with a mains earth connection"], "scenario_contexts": ["DI'ing a keyboard or DJ mixer whose hot, AC-powered output would overload an active DI", "Plugging an active bass with an onboard preamp straight into a passive DI at front of house", "Using the ground-lift on a passive DI to kill hum from a ground loop between backline and console"]}, "e822455e-d62b-4edf-90b4-1df1315be6a3": {"definition": "The point in a changeover or crew shift when one technician formally transfers responsibility for the stage patch, the mapping of sources to stage-box inputs and console channels, to another, communicating any changes, shared or spare lines, and known faults so signal routing continues without error.", "plain_english": "A patch handoff is when one tech hands the wiring plan of the stage to another. They walk through which input goes where and flag any problems. This keeps every channel working when a new crew or act takes over.", "purpose_function": "It passes clear, complete knowledge of the input patch between people so no channel is lost, mislabelled, or misrouted when responsibility changes at a changeover or crew swap.", "practical_application": "At a festival changeover the outgoing patch tech hands the incoming tech the patch list, points out shared lines and spares, and confirms which stage-box inputs are live.", "category": "Signal routing", "related_terms": ["Patch tech", "Patch list", "Stage box", "Changeover", "Input list", "Patch mute protocol"], "common_mistakes": ["Handing off verbally without an updated patch list, so the next tech works from stale documentation", "Failing to flag shared or borrowed lines, causing a channel to disappear when the other act needs it", "Skipping a line check after the handoff, so a bad patch is not caught until the act is on stage"], "scenario_contexts": ["Passing the stage patch to the next patch tech during a multi-band festival changeover", "Handing over the input patch at a crew shift change on a long load-in", "Transferring patch responsibility from the touring tech to the house tech for a support act"]}, "9a40809d-665a-48d6-afd1-70c22c8dd0bb": {"definition": "The agreed procedure for muting the affected console channels, groups, or the whole system before making or changing input patches at the stage box or console, so that plugging, unplugging, or repatching does not send loud pops, thumps, or feedback through the PA and monitors.", "plain_english": "A patch mute protocol is the rule to mute channels before you change any patch. Plugging or unplugging a live line can make a loud bang. Muting first protects the speakers, the show, and people's ears.", "purpose_function": "It prevents the loud transients created by connecting or disconnecting live inputs from reaching amplifiers and loudspeakers, protecting drivers, avoiding startling the audience, and guarding hearing.", "practical_application": "Before repatching a mic or DI during a changeover, the tech mutes that channel at the desk (or calls for the mutes), makes the change, then unmutes and line-checks it.", "category": "Signal routing", "related_terms": ["Patch tech", "Patch handoff", "Mute", "Stage box", "Changeover", "Line check"], "common_mistakes": ["UNSAFE: Hot-patching a live input with channels open, sending a loud transient through the PA that can damage loudspeaker drivers and expose crew and audience to a hazardous sound spike", "Muting only one channel while a shared group or matrix stays open, so the pop still gets through", "Forgetting to unmute and line-check after patching, so the source is silent when the act starts"], "scenario_contexts": ["Muting a channel before unplugging a live vocal mic during a changeover", "Following the desk's mute protocol while repatching the stage box between acts", "Muting the system before a large repatch so no thump reaches the flown array"]}, "9313a45a-d584-4dc1-96d5-c9881259b3b7": {"definition": "A patch technician (patch tech) is the audio crew member responsible for the stage-end input patch: connecting each source to the correct stage-box input, labelling and dressing the lines, working from the input list, and coordinating patch changes and line checks with the monitor and front-of-house engineers.", "plain_english": "A patch tech is the crew member who wires the stage inputs. They plug each mic and DI into the right spot on the stage box. They label the lines and fix patching problems during the show.", "purpose_function": "The role puts one person in charge of getting every source onto the correct channel reliably, so the monitor and front-of-house engineers receive the inputs they expect.", "practical_application": "A patch tech builds the stage patch from the input list at load-in, then handles repatches and troubleshoots dead channels at the stage box during changeovers and the show.", "category": "Crew role", "related_terms": ["Patch handoff", "Patch mute protocol", "Stage box", "Input list", "Monitor engineer", "Line check"], "common_mistakes": ["Patching from memory instead of the current input list, so channels land on the wrong inputs", "Not labelling both ends of a line, making a dead-channel fault slow to trace", "UNSAFE: Repatching live inputs without muting first, risking a loud transient into the PA that can damage drivers and hearing"], "scenario_contexts": ["Building the stage-box patch from the input list during load-in", "Troubleshooting a dead channel at the stage box mid-set", "Handling repatches between bands at a festival changeover"]}, "bdf794ec-bad6-4477-831d-f0b9091b181e": {"definition": "A Pelican case is a rugged, injection-moulded protective transport case made by Pelican Products, and the term is used generically for a hard, watertight equipment case. The Protector line is IP67-rated (dust-tight and protected against temporary immersion per IEC 60529), sealed by an O-ring lid with an automatic pressure-equalisation valve, and is commonly fitted with customisable pluck-foam interiors to protect sensitive gear such as microphones, wireless systems, and in-ear monitors.", "plain_english": "A Pelican case is a tough, sealed plastic case for carrying delicate gear. It is dust-tight and keeps water out, even for a short dip. Foam inside is cut to hold each item. So fragile kit like radio mics and in-ears survives rough travel.", "purpose_function": "It protects sensitive electronics from impact, dust, and water during transport and storage, using a sealed shell and shaped foam so gear arrives undamaged.", "practical_application": "A tech stores and ships wireless receivers, microphones, or in-ear packs in a foam-lined Pelican case, relying on its seal and foam to survive baggage handling and the road.", "category": "Road Cases", "related_terms": ["Flight case", "Road case", "Gig bag", "Cable trunk", "In-ear monitor"], "common_mistakes": ["Assuming any hard plastic case is watertight; only a properly closed, undamaged O-ring seal keeps water and dust out to the IP67 rating", "Blocking or removing the automatic pressure-equalisation valve, which lets the lid open easily after altitude or temperature changes", "Overloading a small case beyond its foam support, letting gear shift and take impact"], "scenario_contexts": ["Shipping radio-mic receivers and handhelds in a foam-lined Pelican case as tour freight", "Carrying in-ear monitor packs and bodypacks in a padded Pelican case", "Storing fragile measurement mics or audio interfaces protected from the weather at an outdoor show"]}, "b0d2c711-bca3-443c-acc2-a428d3c0a6a7": {"definition": "A piano technician is a specialist who tunes, regulates, voices, and repairs pianos: tuning sets each string to correct pitch, regulation adjusts the mechanical action for even and responsive touch, and voicing shapes the hammer felt for tone. In the Piano Technicians Guild the examined professional credential is the Registered Piano Technician (RPT); on a show this person prepares and maintains the piano for performance.", "plain_english": "A piano technician tunes and fixes pianos. Tuning sets each string to the right pitch. They also adjust the moving parts so the keys feel even. They shape the hammers to get a good tone. On a show, they get the piano ready to play.", "purpose_function": "The role keeps a piano at correct pitch and in good mechanical and tonal condition, so it plays evenly and in tune for rehearsal, recording, or performance.", "practical_application": "Before a show a piano technician tunes the piano to the required pitch (commonly A440), checks the action and pedals, and touches up tuning after temperature and humidity shift on stage.", "category": "Crew role", "related_terms": ["Backline tech", "Concert pitch", "A440", "Tuning", "Backline"], "common_mistakes": ["Confusing a piano technician with a piano mover; tuning and regulation are separate skilled work from transport", "Expecting a piano to hold tune after being moved or after a large temperature or humidity change without a touch-up", "Assuming any keyboard tech can tune an acoustic piano; aural and lever tuning of a piano is a distinct trained skill"], "scenario_contexts": ["Tuning the grand piano to A440 before soundcheck", "Re-tuning and checking the action after a piano is moved onto a hot outdoor stage", "Regulating and voicing a house piano before a recording session or concert"]}, "40b569f4-3545-4aac-a4e9-ec3aed331f0b": {"definition": "A pigtail is a short length of wire or cable used as a jumper or adapter. In wiring it is a short conductor spliced to connect a device or ground to the circuit conductors, such as a grounding pigtail in a box. In stage power distribution it commonly means a short lead that breaks out a connector, for example a short Edison-type receptacle tail from a distribution box.", "plain_english": "A pigtail is a short piece of cable used as an adapter or jumper. On a stage it often means a short lead that gives you an outlet off a power box. In wiring it is a short wire that links a device or ground to the main wires.", "purpose_function": "It provides a short, standard connection point, adapting or breaking out a connector or safely joining a device or ground to circuit conductors, where a full cable run is unnecessary.", "practical_application": "A stage electrician plugs backline into short Edison pigtails coming off a distro, or makes up a grounding pigtail so a single device ties cleanly to the circuit ground.", "category": "Cabling", "related_terms": ["Distro", "Edison connector", "Cam-lok", "Adapter cable", "Ground"], "common_mistakes": ["Using the word pigtail loosely; confirm whether someone means a power breakout lead, an adapter, or a spliced wiring conductor", "UNSAFE: Making up or splicing a power pigtail without the correct wire gauge, connectors, strain relief, and grounding required by the electrical code, which risks overheating, shock, or fire", "Undersizing a breakout pigtail for the load it feeds, so it overheats under current"], "scenario_contexts": ["Plugging backline amplifiers into Edison pigtails coming off a stage distribution box", "Using a short adapter pigtail to convert one connector type to another at the stage", "Landing a grounding pigtail so a device bonds to the circuit ground in a junction box"]}, "39debda3-0d2d-440e-995a-db8b47becbf2": {"definition": "Road-crew slang for driving a signal or control to its maximum so a level meter is \"pinned\" hard against its top end-stop (or a control is turned fully up); it signals overload and the likelihood of clipping and distortion.", "plain_english": "\"Pinning it\" means pushing a level so high the meter slams to the very top. It warns that the sound is about to overload and distort.", "purpose_function": "The phrase quickly flags that a level is maxed out, so the operator can pull it back before the signal clips or gear is damaged.", "practical_application": "Hearing distortion, an engineer sees the input meter pinned in the red and lowers the gain to restore headroom.", "category": "Signal Level", "related_terms": ["Clipping", "Gain", "Headroom", "Metering", "Overload", "Hot"], "common_mistakes": ["Assuming a pinned meter is acceptable because it is \"loud enough,\" and ignoring the clipping it signals", "UNSAFE: Running amplifiers or a PA pinned at maximum, risking hearing damage to crew and audience and blown drivers"], "scenario_contexts": ["An engineer noticing the front-of-house meters pinned during a loud chorus and trimming the gain", "A monitor tech warning \"you're pinning it\" when a vocal mic input overloads the channel"]}, "164f5822-1797-4693-98cf-930f85c68f1e": {"definition": "A stage-management call directing performers and crew to move to their assigned starting positions in readiness for a show or scene to begin; the standard form of the call is \"places, please.\"", "plain_english": "\"Places\" is the call telling everyone to go to their starting spots. It means the show or scene is about to begin.", "purpose_function": "It puts cast and crew into position at the same moment, so the performance can start cleanly and on cue.", "practical_application": "The stage manager calls \"places, please\" a few minutes before curtain, and performers move to their opening positions.", "category": "Show Call", "related_terms": ["Standby", "Go", "Cue", "House to half", "Stage manager", "Curtain"], "common_mistakes": ["Waiting for a second reminder instead of moving to position on the first \"places\" call", "Confusing \"places\" (starting positions for a show or scene) with a general summons to the stage"], "scenario_contexts": ["A stage manager calling \"places, please\" five minutes before curtain", "A cast returning to places after intermission before Act Two begins"]}, "194e86c0-93fb-4ac7-b535-6e755f429c06": {"definition": "A touring or event crew member responsible for the playback system that reproduces pre-recorded audio (backing tracks and samples), and usually click and timecode, in sync with the live performance.", "plain_english": "A playback technician runs the recorded backing tracks during a show. They make sure those tracks play in time with the band.", "purpose_function": "The role provides reliable, in-sync playback of tracks, click and timecode, so recorded parts line up with the live band and other departments.", "practical_application": "During the show the playback technician launches each song's tracks and feeds click to the drummer and timecode to lighting.", "category": "Crew Roles", "related_terms": ["Playback/DAW operator", "Click track", "Timecode", "Backing track", "Monitor engineer"], "common_mistakes": ["Confusing the playback technician with the monitor engineer; playback supplies the tracks, monitors mix them to performers", "Not carrying a redundant playback rig, so a single computer failure stops the tracks mid-show"], "scenario_contexts": ["A playback technician firing backing tracks and click for a pop tour", "A playback tech running redundant laptops so a crash does not halt the show"]}, "8e1a010d-4abd-4b37-9f23-caba5af7d87e": {"definition": "The crew member who operates the digital audio workstation (DAW) used for show playback — starting, stopping and cueing backing tracks, click and timecode from the software during the performance.", "plain_english": "This operator runs the computer software that plays a show's tracks. They start and stop each song's audio on cue.", "purpose_function": "It puts one person in control of the playback software, so tracks, click and timecode fire accurately at the right moments.", "practical_application": "The DAW operator arms the next song in the session and hits play on the stage manager's or musical director's cue.", "category": "Crew Roles", "related_terms": ["Playback technician", "DAW", "Click track", "Timecode", "Backing track", "Cue"], "common_mistakes": ["Assuming the DAW operator also mixes the show; they run playback, not the front-of-house mix", "Leaving the session running without a backup machine, so a software crash loses the show file"], "scenario_contexts": ["A DAW operator cueing tracks in the session for each number in the set", "An operator switching to a backup machine when the primary DAW freezes"]}, "a0a46a72-46e6-485a-96e6-41158e1f3c0c": {"definition": "The electrical supply a device or an entire production needs to operate — its voltage, current draw (amperage), phase configuration and total load — used to plan adequate, safe power distribution at a venue.", "plain_english": "Power requirement is how much electricity your gear needs to run. It covers the voltage and the current the equipment draws.", "purpose_function": "Knowing the power requirement lets crew supply enough current on correctly rated circuits and distribution, avoiding overloads and unsafe wiring.", "practical_application": "During the advance a crew chief totals the show's power requirement and requests the right electrical service and distro from the venue.", "category": "Power and Electrical", "related_terms": ["Distro", "Amperage", "Three-phase", "Load-in", "Power distribution", "Tech spec"], "common_mistakes": ["Adding up wattage but ignoring inrush current and phase balance when estimating the power requirement", "UNSAFE: Overloading a circuit or generator beyond its rated capacity to meet demand, risking overheating and fire", "UNSAFE: Connecting to venue power without first confirming voltage, phase and correct grounding/bonding"], "scenario_contexts": ["A production manager listing the show's power requirement in the technical rider", "A crew comparing the show's power requirement against a venue's available electrical service during the advance"]}, "8002ebea-6548-4deb-8c52-f6de56fff988": {"definition": "A patch — the routing of signals between inputs, outputs and equipment — set up in advance of a session or show, either physically on a patch bay or stagebox or as a stored routing configuration, so connections are ready before line check.", "plain_english": "A prepatch is the signal wiring set up before a show. It gets all the connections ready ahead of time.", "purpose_function": "It prepares and stores routing early, so setup and line check go faster and the connections stay consistent each day of a run.", "practical_application": "The system tech prepatches the stagebox to the console the night before, so the band can line-check quickly at soundcheck.", "category": "Signal Routing", "related_terms": ["Patch bay", "Prewire", "Line check", "Stagebox", "Input list", "Console"], "common_mistakes": ["Prepatching from an outdated input list, so channels land on the wrong console strips", "Assuming a prepatch removes the need to line-check every input before the show"], "scenario_contexts": ["A system tech prepatching a festival stagebox to match the input list before doors", "Recalling a saved prepatch on a digital console at the start of load-in"]}, "65a65a6a-da31-4a46-ac0d-c561f86e503e": {"definition": "To install cabling and connectors in advance of the equipment or the main build — running and terminating cable runs ahead of time — so systems can be connected quickly once the gear arrives.", "plain_english": "To prewire is to run the cables before the gear shows up. Then everything can be plugged in fast on the day.", "purpose_function": "It gets the cabling infrastructure in place early, so the final build and connection go faster and with less time pressure.", "practical_application": "The crew prewires cable runs to each stage position overnight, so the morning build just drops the equipment into place.", "category": "Cabling", "related_terms": ["Prepatch", "Cable run", "Load-in", "Multicore", "Stagebox", "Rigging"], "common_mistakes": ["Prewiring without labelling both ends, so cables cannot be identified when it is time to connect", "UNSAFE: Running prewired mains and signal cable across walkways without cable ramps or matting, creating a trip hazard"], "scenario_contexts": ["A crew prewiring a stage overnight ahead of a next-day equipment load-in", "An installer prewiring conduit and cable in a new venue before the racks are delivered"]}, "df3a167b-cad9-4363-a6b1-775b2c726a1d": {"definition": "A crew member responsible for operating Avid Pro Tools on a production, running the software for tasks such as multitrack recording, virtual soundcheck playback, and firing backing tracks or timecode during the show.", "plain_english": "The Pro Tools operator runs the recording and playback software for a show. They record the band, play back extra tracks, and fire cues on time.", "purpose_function": "The role gives a show a dedicated specialist for recording and playback, so multitracks, virtual soundchecks, and backing tracks run reliably alongside the live mix.", "practical_application": "On tour, the Pro Tools operator records each night's multitrack for virtual soundcheck the next day and plays back sequenced tracks locked to the band's click.", "category": "Crew Roles", "related_terms": ["Playback", "Virtual soundcheck", "Backing track", "Multitrack recording", "Front of house", "Monitor engineer"], "common_mistakes": ["Confusing the Pro Tools operator with the front-of-house engineer; this role manages recording and playback, not the audience mix", "Not building redundancy into playback, so a single computer or drive failure can stop the backing tracks mid-show"], "scenario_contexts": ["Recording a live multitrack each night so engineers can line-check on it the next day", "Firing sequenced backing tracks and timecode locked to the band's click during a set"]}, "88e2cbda-8e69-4f85-ae15-3996e351394c": {"definition": "A senior crew member who oversees the technical production of a show, event, or tour, coordinating departments, crew, schedule, and logistics so the staging, sound, lighting, and video come together safely and on time.", "plain_english": "The production supervisor is in charge of putting the show together. They coordinate the crew, the schedule, and the gear so everything is ready and safe.", "purpose_function": "The role gives one person clear responsibility for coordinating all technical departments and the schedule, so a complex build runs smoothly and safely.", "practical_application": "The production supervisor builds the day's schedule, assigns crew calls, and keeps the sound, lighting, and video departments on track through load-in, show, and load-out.", "category": "Crew Roles", "related_terms": ["Production manager", "Stage manager", "Crew chief", "Tour manager", "Load-in", "Load-out"], "common_mistakes": ["Confusing the production supervisor with the stage manager, who calls the show rather than overseeing the build", "Assuming the role is only paperwork; it also means active on-site coordination and safety oversight"], "scenario_contexts": ["Coordinating multiple departments during a festival build to hit the load-in schedule", "Overseeing crew calls, logistics, and safety through a tour's load-in and load-out"]}, "846d1ce0-e277-4464-bcb6-da9914ef8294": {"definition": "An electronic sound system used to amplify and distribute speech, music, and announcements to an audience or across an area; commonly abbreviated PA, it spans small paging systems to large concert sound-reinforcement rigs.", "plain_english": "Public address, or PA, is a system that makes sound loud enough for a crowd to hear. It sends speech, music, and announcements out over speakers.", "purpose_function": "It raises sound to a level and coverage that reaches everyone in a space, so speech and music stay clear and intelligible for a large audience.", "practical_application": "A technician sets up and tunes the public address system so announcements and the band are heard clearly and evenly across the whole venue.", "category": "Sound reinforcement", "related_terms": ["Public-address package", "Public-address technician", "Sound reinforcement", "Loudspeaker", "Amplifier", "Front of house"], "common_mistakes": ["Confusing public address (the whole amplification system) with a single loudspeaker or microphone", "Assuming louder is better; poor tuning and excess level harm intelligibility and audience comfort", "UNSAFE: Exposing crew or audience to sustained high sound levels without regard to OSHA hearing-exposure limits and hearing protection"], "scenario_contexts": ["Amplifying speech and music so a concert or event audience can hear clearly", "Making paging announcements audible across a large venue or transport terminal"]}, "7faa7386-f388-4778-8244-d9a75d83a520": {"definition": "The bundled set of loudspeakers, amplifiers, processing, cabling, and often a console supplied together as a complete public-address (PA) system for an event or hire, sized as a package to cover a given venue or audience.", "plain_english": "A PA package is a full sound system supplied as one bundle. It has the speakers, amplifiers, cables, and processing, sized to fit the room.", "purpose_function": "Bundling the whole PA as one package lets a promoter or act hire a matched, ready-to-deploy system instead of sourcing each part separately.", "practical_application": "A sound company sends a PA package rated for the room's size, and the crew flies and tunes it to cover the audience evenly.", "category": "Venue Equipment", "related_terms": ["Public address", "Public-address technician", "House package", "Sound reinforcement", "Line array", "Front of house"], "common_mistakes": ["Choosing a PA package by headline power alone rather than by coverage and headroom for the room", "Assuming the package includes everything; consoles, microphones, or power distro may be quoted separately"], "scenario_contexts": ["A promoter hiring a PA package matched to a venue's capacity", "A sound company specifying a package's speaker and amplifier count for a tour"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"27b2d77e-0544-49d7-89ec-932d395ce9b6": {"definition": "A technician who installs, operates, and maintains public-address (PA) systems, setting up loudspeakers, amplifiers, cabling, and processing, and troubleshooting the system so it delivers clear, even coverage.", "plain_english": "A PA technician sets up and looks after the sound system. They rig the speakers, run the cables, and fix problems so the crowd hears clearly.", "purpose_function": "The role provides the hands-on expertise to deploy and keep a PA working correctly, so speech and music reach the audience reliably and safely.", "practical_application": "The PA technician assembles and cables the loudspeaker system, checks each amplifier and processor, and solves faults during load-in and the show.", "category": "Crew Roles", "related_terms": ["Public address", "Public-address package", "Sound reinforcement", "System tech", "Loudspeaker", "Front of house"], "common_mistakes": ["Confusing the PA technician with the mix engineer; this role deploys and maintains the system rather than mixing the show", "UNSAFE: Rigging or flying loudspeakers overhead without following manufacturer rigging data and ANSI/ESTA rigging practice"], "scenario_contexts": ["Assembling, cabling, and testing a loudspeaker system during load-in", "Troubleshooting an amplifier or processing fault in the PA before doors"]}, "e514e0d9-aa4f-420e-a53b-7ada40691adb": {"definition": "A rapid change of a performer's costume, wig, or makeup completed in a very short time, often during a brief exit or even onstage, usually assisted by a dresser and pre-rigged so the performer can return promptly.", "plain_english": "A quick change is a fast costume swap during a show. A dresser helps the performer change in seconds so they can get back on stage.", "purpose_function": "It lets a performer switch looks within the flow of a show, so the production keeps moving without long gaps for costume changes.", "practical_application": "A dresser pre-sets the next costume in a quick-change area offstage and helps the performer change in the seconds available between scenes.", "category": "Wardrobe", "related_terms": ["Dresser", "Wardrobe", "Quick-change booth", "Preset", "Blackout", "Stage manager"], "common_mistakes": ["Not pre-rigging or pre-setting the costume, so the change runs long and delays the performer's entrance", "Placing the quick-change area too far from the stage or without enough light to work safely"], "scenario_contexts": ["A performer changing costume in seconds during a brief offstage exit", "A dresser running an onstage quick change hidden behind other performers or scenery"]}, "75307042-cda8-4eb1-be8d-531027b2ee24": {"definition": "A standardized frame or enclosure for mounting audio, power, and control equipment, most commonly the 19-inch rack defined by EIA-310/IEC 60297, with vertical mounting rails drilled on a fixed hole pattern; height is measured in rack units (U), each 1.75 inches (44.45 mm).", "plain_english": "A rack is a metal frame that holds gear in a neat stack. Standard racks are 19 inches wide. Height is counted in units called U.", "purpose_function": "A rack standardizes mounting so equipment from many makers fits, stacks, and travels together, kept protected, organized, and easy to wire and service.", "practical_application": "A technician bolts amplifiers, processors, and power into a rack, wires it once, and moves the whole rack as a unit between truck and stage.", "category": "Equipment housing", "related_terms": ["Rack unit", "Rackmount", "Patch bay", "Amplifier", "Signal processor", "Road case"], "common_mistakes": ["Confusing the 19-inch rack width with rack-unit (U) height; the width is fixed while height is counted in 1.75-inch units", "Supporting a heavy unit only by its front rack ears instead of adding rear support or a shelf", "UNSAFE: Overloading a rack or making it top-heavy so it can tip, and lifting a fully loaded rack without mechanical aid or a team lift"], "scenario_contexts": ["Building a touring amplifier or effects rack that ships inside a road case", "Mounting processors and a patch bay in a studio equipment rack"]}, "6c7635b7-ff71-4dc4-9e60-dfdfd02867b7": {"definition": "A junior studio engineer who supports the lead recording engineer by setting up and patching equipment, placing microphones, and managing session files and documentation, handling routine technical tasks so the engineer and producer can concentrate on the recording.", "plain_english": "A helper in a recording studio. They set up mics and gear and keep the session organized so the main engineer can focus on the sound.", "purpose_function": "The role exists to keep sessions running smoothly and efficiently, freeing the lead engineer from setup, patching, and paperwork so the creative team can focus on capturing performances.", "practical_application": "An assistant arrives early to set up the control room and mic the room, logs takes and settings during the session, then tears down and backs up the files afterward.", "category": "Crew role", "related_terms": ["Recording producer", "Remote engineer", "Recording engineer", "Tracking session", "Mic placement"], "common_mistakes": ["Confusing the recording assistant with the recording producer; the producer guides the creative direction while the assistant handles technical support", "Assuming the role needs no skill; assistants must know signal flow, patching, and session software well", "Treating documentation as optional; failing to log takes, mic positions, and settings can make a session impossible to recall or recreate"], "scenario_contexts": ["Setting up the control room and patching outboard gear before a tracking session begins", "Logging take numbers, comments, and microphone choices in a session sheet during recording", "Backing up and organizing session files at the end of a day so nothing is lost"]}, "e1bc85ca-788c-48d6-baa2-4b8f7cf6e7d5": {"definition": "The person who oversees and guides a recording project, shaping arrangements, performances, sound, and song selection, coaching the artist, and making the final creative decisions needed to realize the intended artistic and commercial vision of the recording.", "plain_english": "The person in charge of how a recording turns out. They guide the artist and the sound and make the big creative calls to get the best result.", "purpose_function": "The producer exists to translate an artist's vision into a finished recording, taking responsibility for creative direction, quality, budget, and schedule across the whole project.", "practical_application": "A producer plans the sessions, coaches performances take by take, decides which takes to keep, and works with the engineer to shape the final sound.", "category": "Crew role", "related_terms": ["Recording assistant", "Recording engineer", "Remote engineer", "Tracking session", "Mixdown"], "common_mistakes": ["Confusing the producer with the engineer; the engineer captures and manipulates sound technically, while the producer directs the creative outcome", "Assuming the producer must operate the console; many producers focus on performance and arrangement and leave technical operation to the engineer", "Believing the producer only matters at mixing; producer decisions shape a project from pre-production through final delivery"], "scenario_contexts": ["Deciding song arrangements and running order during pre-production", "Choosing the best vocal take from several passes during tracking", "Directing the engineer on the overall sound and balance during mixing"]}, "01144325-20c8-4d93-99cd-7a7766d830e9": {"definition": "An audio engineer who records or broadcasts outside a fixed studio, at concerts, events, or on location, typically working from a mobile or remote recording rig or truck and handling capture, monitoring, and much of the technical logistics of location work.", "plain_english": "An engineer who records sound away from the studio. They work at concerts or events, often from a truck full of gear, to capture a live performance.", "purpose_function": "The role exists to bring studio-quality capture to live and location settings where a permanent studio is unavailable, managing the added challenges of power, environment, and logistics.", "practical_application": "A remote engineer sets up a multitrack rig at a venue, takes isolated splits of every input from the stage, and captures all channels for later mixing.", "category": "Crew role", "related_terms": ["Recording engineer", "Recording assistant", "Recording producer", "Multitrack", "Front of house"], "common_mistakes": ["Confusing remote recording with simply plugging into the front-of-house mixer; remote engineers usually take isolated splits of every input", "Underestimating location logistics such as securing clean power and cable runs, which can cause noise or lost recordings", "Forgetting redundancy; location work has no second chance, so backup recorders and media are standard practice"], "scenario_contexts": ["Recording a live concert to multitrack from a mobile truck", "Capturing a location feed for a televised or streamed event", "Setting up isolated splits from a live console to record each channel separately"]}, "2de4e013-6b58-45bf-a82a-e51f863c9910": {"definition": "The act of returning a stage, set, or equipment to its predetermined starting configuration, repositioning scenery, props, instruments, and gear to their marks so that a performance, act, or take can begin again from a known, repeatable state.", "plain_english": "Putting the stage back the way it started. Crew move props, gear, and set pieces to their marked spots so the next act or take can begin.", "purpose_function": "A reset exists to guarantee a consistent, repeatable starting point, so each performance or take runs the same way and nothing is missing or out of place.", "practical_application": "Between two bands, the crew resets the stage, clearing the first act's gear and placing the next act's risers, mics, and monitors on their marks.", "category": "Stage operations", "related_terms": ["Changeover", "Strike", "Spike mark", "Load-in", "Marks"], "common_mistakes": ["Confusing a reset with a strike; a strike removes and packs everything, while a reset restores the stage to a starting layout", "Skipping the use of marks or spike tape, so items are placed inconsistently and the reset is not repeatable", "Rushing a reset and forgetting to restore console or instrument settings, causing problems when the next act starts"], "scenario_contexts": ["Returning props and set pieces to their marks between two performances of the same show", "Repositioning band gear during a festival changeover between acts", "Restoring the stage to its opening look after rehearsing a scene"]}, "83e0c2b0-9a4d-4d0d-afe1-c8df5ce3ddce": {"definition": "A dedicated equipment rack that houses a production's radio-frequency (wireless) systems, including wireless microphone and in-ear monitor receivers and transmitters, antenna distribution and combiners, and coordination gear, centralizing wireless management at one point in the signal chain.", "plain_english": "A cabinet that holds all the wireless gear. It keeps the wireless mic and in-ear monitor receivers and their antennas together in one place.", "purpose_function": "The RF rack exists to centralize and organize wireless equipment so signals can be distributed cleanly, antennas shared efficiently, and the whole wireless system monitored and coordinated from one location.", "practical_application": "The RF tech patches wireless mic and in-ear systems into the RF rack, connects the remote antennas, and monitors signal strength and frequencies from that rack during the show.", "category": "Equipment", "related_terms": ["RF tech", "RF technician", "Wireless microphone", "In-ear monitor", "Antenna distribution", "Frequency coordination"], "common_mistakes": ["Placing the RF rack far from its antennas with long cable runs, which weakens signals and causes dropouts", "Ignoring frequency coordination, so wireless channels interfere with each other or with local TV broadcasts", "Assuming any rack will do; RF systems need proper antenna distribution to avoid overloading receiver inputs"], "scenario_contexts": ["Housing dozens of wireless microphone and in-ear channels for a large touring show", "Locating the RF rack near the stage to keep antenna cable runs short", "Coordinating and monitoring all wireless frequencies from the RF rack during a performance"]}, "60f9aefe-0b1d-4063-b86c-f1329e155223": {"definition": "The everyday shortened name for the RF technician: the crew member responsible for a production's radio-frequency (wireless) systems, who coordinates and assigns frequencies, deploys antennas, and maintains wireless microphones, in-ear monitors, and intercom so every wireless channel stays interference-free and reliable.", "plain_english": "The crew member who runs all the wireless gear. They pick clear frequencies and keep wireless mics and in-ear monitors working without dropouts.", "purpose_function": "The role exists to manage the crowded, unpredictable radio spectrum at a show, preventing interference and dropouts so performers' wireless mics and monitors stay reliable.", "practical_application": "The RF tech scans the local spectrum, assigns clean frequencies to each wireless unit, places antennas for coverage, and monitors signals from the RF rack during the show.", "category": "Crew role", "related_terms": ["RF technician", "RF rack", "Wireless microphone", "In-ear monitor", "Frequency coordination", "Antenna distribution"], "common_mistakes": ["Skipping a spectrum scan before the show, so assigned frequencies clash with local broadcasts or other systems", "Confusing the RF tech with the monitor engineer; the RF tech manages the wireless links, not the monitor mix", "Ignoring battery management, leading to wireless units dying mid-performance"], "scenario_contexts": ["Scanning and coordinating wireless frequencies before doors open at a venue", "Fitting a performer with a wireless mic pack and belt-pack transmitter backstage", "Tracking signal strength and battery levels for all wireless channels during a show"]}, "c6c0a9a6-ee2b-40cd-b742-cbec5452c9e1": {"definition": "The crew member responsible for a production's radio-frequency (wireless) systems, who coordinates and assigns frequencies, deploys and tunes antennas, and maintains wireless microphones, in-ear monitors, and intercom to keep every wireless channel interference-free and reliable throughout the show.", "plain_english": "The crew member who manages all the wireless gear. They choose clear frequencies and keep wireless mics and in-ear monitors running without dropouts.", "purpose_function": "The role exists to manage the crowded, unpredictable radio spectrum at a show, preventing interference and dropouts so performers' wireless mics and monitors stay reliable.", "practical_application": "The RF technician scans the local spectrum, assigns clean frequencies to every wireless unit, positions antennas for coverage, and monitors all signals from the RF rack during the show.", "category": "Crew role", "related_terms": ["RF tech", "RF rack", "Wireless microphone", "In-ear monitor", "Frequency coordination", "Antenna distribution"], "common_mistakes": ["Skipping a spectrum scan before the show, so assigned frequencies clash with local broadcasts or other systems", "Confusing the RF technician with the monitor engineer; the RF technician manages the wireless links, not the monitor mix", "Ignoring battery management, leading to wireless units dying mid-performance"], "scenario_contexts": ["Scanning and coordinating wireless frequencies before doors open at a venue", "Fitting a performer with a wireless mic pack and belt-pack transmitter backstage", "Tracking signal strength and battery levels for all wireless channels during a show"]}, "53ba6a92-1224-4444-a60c-8ee294d476f1": {"definition": "In touring production, \"the rig\" is the complete assembly of equipment set up for a show, most often the flown (overhead) rigging system of hoists, trusses, and hung lighting, sound, and video, or more broadly the entire staged production package. As a verb, to rig is to install, hang, and secure that equipment.", "plain_english": "\"The rig\" means all the gear set up for a show. Often it means the lights, speakers, and screens hung overhead on metal trusses. To \"rig\" something is to hang it and lock it in place safely.", "purpose_function": "The word lets crew refer to the whole coordinated equipment setup in one term, especially the overhead system that supports and positions production gear above the stage.", "practical_application": "A tech hears \"the rig goes up first\" and knows the overhead trusses and hoists are flown before other departments load in.", "category": "Rigging", "related_terms": ["Rigger", "Rigging crew", "Truss", "Chain hoist", "Load-in", "Flying"], "common_mistakes": ["Thinking \"the rig\" only means the lighting rig, when it can mean the whole flown system or the entire production setup.", "Confusing \"rig\" (the equipment or the verb) with \"rigging\" hardware such as slings and shackles.", "UNSAFE: Treating rigging as general labor anyone can do, when overhead rigging must be installed and checked by qualified, competent riggers."], "scenario_contexts": ["A production manager schedules the rig to fly before lighting and audio load in.", "A crew chief inspects the rig before any load is applied to the hoists.", "A tour advances a venue to confirm the roof can hold the rig's weight."]}, "3b185c1e-ce7d-4726-b552-193332aeefc7": {"definition": "A rigger is the crew specialist who installs, secures, and inspects the overhead rigging that supports flown production equipment, attaching rigging points, hanging chain hoists and trusses, and connecting loads with slings, shackles, and steel. Work is typically split between up-riggers, who work at height in the grid or roof steel, and down-riggers, who assemble and connect loads at floor level. Entertainment riggers are expected to meet the criteria of a qualified, competent person for the rigging performed.", "plain_english": "A rigger is the crew member who hangs heavy gear safely above the stage. Some riggers work high up in the roof, and others work on the floor. They connect trusses, motors, and loads so nothing can fall. It is a skilled, safety-critical job.", "purpose_function": "Riggers exist to get lights, speakers, and video hung safely overhead, placing heavy loads while keeping the people below protected from falling equipment.", "practical_application": "A rigger climbs into the roof steel to set motor points, then signals a down-rigger to connect the truss and hoist below.", "category": "Rigging", "related_terms": ["Rig", "Rigging crew", "Chain hoist", "Truss", "Shackle", "Rigging sign-off"], "common_mistakes": ["Assuming \"rigger\" means only the person working up high, when down-riggers on the floor are equally part of the job.", "UNSAFE: Letting untrained crew do rigging, when overhead rigging must be done by a qualified, competent rigger.", "UNSAFE: Standing or working under a suspended load, when the area below rigging must be kept clear."], "scenario_contexts": ["An up-rigger sets motor points in the arena roof at load-in.", "A down-rigger assembles and connects trusses on deck before they fly.", "A qualified rigger inspects shackles and slings before a load is lifted."]}, "886fa4bc-0b18-44e4-8922-a1e8a40522e9": {"definition": "A rigging call is a scheduled labor call, a specific booked work session with a crew, dedicated to the rigging work at a load-in or load-out, during which riggers install or strike the overhead rigging before the rest of the production is set.", "plain_english": "A rigging call is a booked work time just for the riggers. They come in to hang the overhead gear before other crews start. It happens early at load-in and again at strike.", "purpose_function": "Scheduling rigging as its own call makes sure the overhead system is safely up, or safely down, before other departments work above or below it.", "practical_application": "A tech reads the day sheet, sees the rigging call at 7 a.m., and knows trusses fly before the lighting call begins.", "category": "Crew scheduling", "related_terms": ["Rigging crew", "Rigger", "Load-in", "Call time", "Strike", "Day sheet"], "common_mistakes": ["Thinking a \"call\" means a phone call, when a call is a scheduled work session with a booked crew.", "Confusing the rigging call (rigging only) with the general load-in call for all crew.", "Scheduling other departments during the rigging call, when overhead work should finish before crews work beneath it."], "scenario_contexts": ["A production manager books a rigging call before the main load-in call.", "A local labor provider staffs a rigging call with up-riggers and down-riggers.", "A crew chief times the rigging call so trusses are flown before lighting arrives."]}, "3593143c-d38c-479f-ae6c-ef0e8efc59eb": {"definition": "The rigging crew is the team of riggers responsible for installing, connecting, and striking a show's overhead rigging, usually organized into up-riggers who work at height in the grid or roof steel and down-riggers who assemble and connect loads at floor level.", "plain_english": "The rigging crew is the team that hangs the heavy gear overhead. Some members work high up, and others work on the floor. Together they get the trusses and motors safely in the air. They also bring it all down at the end.", "purpose_function": "The crew exists to safely place and remove heavy flown equipment, splitting the dangerous high work and the ground assembly between specialists.", "practical_application": "The rigging crew flies the motor points and trusses at load-in, then hands off to lighting and audio to hang their gear.", "category": "Rigging", "related_terms": ["Rigger", "Rig", "Rigging call", "Chain hoist", "Truss", "Load-in"], "common_mistakes": ["Forgetting the crew includes both up-riggers and down-riggers, not just those working at height.", "UNSAFE: Assuming any stagehand can join the rigging crew, when rigging requires qualified, competent riggers.", "UNSAFE: Allowing people to stand under the rigging crew's work area while loads are overhead."], "scenario_contexts": ["The rigging crew sets all motor points before other departments load in.", "At strike, the rigging crew lowers and breaks down the overhead system last.", "A crew chief briefs the rigging crew on the venue's rigging points and load limits."]}, "4a03d021-b63e-4826-9007-c844b86f01da": {"definition": "A rigging sign-off is the formal, usually documented approval by a qualified, competent rigger or inspector that the installed rigging has been checked and is safe to load and use, given before any performance load is applied. It confirms that points, hardware, hoists, and connections meet the required standard and stay within working load limits.", "plain_english": "A rigging sign-off is the safety check before gear is trusted overhead. A qualified rigger inspects every point and connection. Only after they approve it can the rig take its full load. It is often written down and signed.", "purpose_function": "The sign-off exists to catch rigging errors before weight is applied, so loads and equipment cannot fail and fall on people.", "practical_application": "Before lighting powers up the hoists, a qualified rigger inspects the points and hardware and gives the rigging sign-off.", "category": "Rigging safety", "related_terms": ["Rigger", "Rigging crew", "Working load limit", "Chain hoist", "Shackle", "Inspection"], "common_mistakes": ["Assuming a verbal \"looks fine\" replaces a proper documented sign-off.", "UNSAFE: Applying load to rigging before it has been inspected and signed off.", "UNSAFE: Treating the sign-off as a formality instead of a real inspection by a qualified person."], "scenario_contexts": ["A qualified rigger inspects all points and gives the sign-off before trim.", "A venue requires a written rigging sign-off before a show can be flown.", "An inspector checks hoists and shackles, then signs off the rigging as safe to load."]}, "4263de70-e4d1-46e3-97cf-c3a4a45669d0": {"definition": "To \"ring it out\" is to test a sound system, most often the stage monitors or the PA, for feedback by slowly raising gain until a frequency begins to ring, then cutting (notching) that frequency on an equalizer to raise the level achievable before feedback; the process is repeated to maximize gain before feedback. In a signal or cabling sense it can also mean to trace or continuity-test a line.", "plain_english": "\"Ringing it out\" means testing monitors or speakers for feedback. You slowly turn up the level until you hear a squeal. Then you cut that pitch on an EQ so it stops. Doing this a few times lets you run louder without feedback.", "purpose_function": "It exists to raise the usable volume of monitors or the PA by finding and taming the frequencies that howl into feedback first.", "practical_application": "Before doors, a monitor engineer rings out each mix, notching ringing frequencies on the graphic EQ until the wedges are stable and loud.", "category": "System tuning", "related_terms": ["Feedback", "Graphic EQ", "Gain before feedback", "Stage monitor", "Notch filter", "Soundcheck"], "common_mistakes": ["Cutting far too wide or too deep on the EQ, which dulls the monitor instead of just taming the feedback.", "Assuming a ring-out done in an empty room stays perfect once a crowd and band change the acoustics.", "UNSAFE: Ringing out at very high levels near the ears without hearing protection, risking hearing damage."], "scenario_contexts": ["A monitor engineer rings out the wedges during soundcheck to prevent feedback.", "A front-of-house tech rings out the mains to lift the room's gain before feedback.", "A tech rings out a suspect mic line to trace its continuity end to end."]}, "f9c68952-4ede-4330-8c81-403561144dba": {"definition": "A riser loom is a pre-made bundle (loom) of cables, typically audio multicore, power, and data lines, dressed and tied together to serve a stage riser, which is a raised platform such as a drum or keyboard riser, letting the platform be connected and disconnected as one tidy harness.", "plain_english": "A riser loom is a bundle of cables tied together for a raised stage platform. It carries the sound, power, and data that platform needs. Because it is one neat bundle, it plugs in and out fast. That speeds up setup and keeps the stage tidy.", "purpose_function": "It bundles the many cables a riser needs into one manageable harness, speeding load-in and keeping the stage neat and free of trip hazards.", "practical_application": "A stagehand drops the drum riser loom into place, connects it to the stage box, and the whole platform is wired in one move.", "category": "Cabling", "related_terms": ["Loom", "Riser", "Multicore (snake)", "Stage box", "Cable management", "Sub-snake"], "common_mistakes": ["Confusing a loom (a bundle of separate cables) with a single multicore snake cable.", "Bundling power and sensitive audio lines too tightly, which can induce hum and noise.", "UNSAFE: Running a riser loom across walkways without ramps or tape, creating a trip hazard."], "scenario_contexts": ["A crew pre-builds a drum riser loom in the shop so setup on site is one connection.", "A stagehand routes the riser loom to the stage box and dresses it out of walkways.", "At strike, the loom is coiled as one bundle to save time."]}, "66b8c2ac-9da7-4406-85bf-f0ccfc60cb75": {"definition": "A road case, or flight case, is a rugged purpose-built protective container for transporting production equipment on tour, typically plywood panels laminated with plastic and edged with extruded aluminum, closed with butterfly latches, and fitted with recessed handles, casters, and shaped foam interiors to protect the contents from shock, dust, and moisture in transit.", "plain_english": "A road case is a tough box for moving gear on tour. It has hard panels, metal edges, strong latches, and wheels. Foam inside holds the equipment so it does not get damaged. It shields gear from bumps, dust, and rain on the road.", "purpose_function": "It exists to protect costly, fragile equipment from the shocks, stacking, and weather of repeated truck transport, and to make heavy gear easy to roll and stack.", "practical_application": "A tech rolls amplifiers in their road case off the truck, opens the lid, and works out of the case at the mix position.", "category": "Transport", "related_terms": ["Load-in", "Load-out", "Caster", "Truck pack", "Flight case", "Dolly"], "common_mistakes": ["Overpacking or ignoring the foam fit, so gear shifts and gets damaged in transit.", "Leaving casters unlocked on a ramp or raked stage, letting a heavy case roll away.", "UNSAFE: Lifting heavy road cases by hand instead of rolling them or using proper team lifting, risking back injury."], "scenario_contexts": ["A crew rolls road cases down the truck ramp during load-in.", "Fragile microphones travel in a foam-lined road case.", "Cases are stacked and strapped in the truck for the next city."]}, "1894d89c-a622-451c-96d2-1918d19ae6e1": {"definition": "A roadie is a member of a touring crew who travels with an act to load in, set up, operate or maintain, and strike and load out the production equipment (sound, lighting, backline, staging) from venue to venue; the term covers a range of specialist roles such as backline techs, audio and lighting crew, and riggers.", "plain_english": "A roadie is a crew member who travels with a band or show. They set up the gear, keep it working during the show, and pack it up after. Then they move to the next town and do it again. Many roadies specialize, such as guitar techs or sound crew.", "purpose_function": "Roadies exist to move, build, run, and maintain a production so the same show can be repeated reliably in a new venue every day of a tour.", "practical_application": "A roadie unloads the truck, sets up the assigned gear, supports the show, then strikes and reloads for the next date.", "category": "Crew roles", "related_terms": ["Load-in", "Load-out", "Backline", "Strike", "Tour manager", "Stagehand"], "common_mistakes": ["Thinking a roadie only carries gear, when many are skilled specialists who tune, program, and repair equipment.", "Confusing a traveling roadie, who tours with the act, with a local stagehand, who works one venue.", "UNSAFE: Skipping team lifting or proper manual handling on heavy gear, risking back and crush injuries."], "scenario_contexts": ["A guitar roadie restrings and tunes instruments and hands them off during the set.", "Roadies load out the truck right after the encore to make the next city.", "A monitor roadie troubleshoots a dead wedge mid-show."]}, "2967696f-3ddd-49b7-94ec-678891f0efbd": {"definition": "A verbal show cue instructing an operator to start immediately the playback or record source that the moment calls for, carried over from the broadcast and film convention of 'rolling' tape or a machine.", "plain_english": "A spoken command that means 'start it now.' The operator hears 'roll it' and begins the playback or recording the cue is about.", "purpose_function": "It gives the operator one short, unmistakable signal to begin a time-critical source on the caller's exact word, keeping the show in sync.", "practical_application": "A show caller says 'roll it' over comms and the playback or media operator presses go on the cued track or clip.", "category": "Cue call", "related_terms": ["Go", "Standby", "Roll playback", "Roll video", "Playback", "Show caller"], "common_mistakes": ["Pressing play on the wrong item because the operator did not confirm the standby before the 'roll it' call.", "Treating 'roll it' as casual talk rather than an executable cue, which causes a late or missed start.", "Anticipating the call and rolling early instead of waiting for the exact word."], "scenario_contexts": ["A show caller cues the intro track by saying 'roll it' as the lights go to black.", "A playback operator starting a backing track on the caller's 'roll it'.", "A video operator rolling an opening clip on the 'roll it' command."]}, "f08b79a5-c4ef-478c-9ad4-37674a0550dc": {"definition": "A show cue directing the playback operator to start the pre-recorded audio material assigned to that moment, such as backing tracks, click, samples, or intro music.", "plain_english": "A command telling the playback operator to start the pre-recorded tracks. These extra tracks, like backing vocals or a click, play along with the band.", "purpose_function": "It launches the timed audio a performance depends on, so backing tracks, click, and samples begin exactly with the band or the caller's cue.", "practical_application": "On the caller's 'roll playback,' the playback tech starts the session or cue, sending tracks to the band's in-ears and the main PA.", "category": "Cue call", "related_terms": ["Playback", "Backing track", "Click track", "Roll it", "Show caller", "In-ear monitors"], "common_mistakes": ["Starting the wrong song or cue because the playback session was not armed and confirmed first.", "Rolling playback before the band is on their in-ear click, so the timing drifts.", "Confusing 'roll playback', which starts audio tracks, with 'roll video', which starts screen content."], "scenario_contexts": ["A caller cues backing tracks for a pop act by saying 'roll playback'.", "A playback tech starting a click and stems for the band on the 'roll playback' call.", "Rolling playback of walk-in music before the first song."]}, "4fa8cae0-7128-402b-88a7-e132ea7c0ca8": {"definition": "A show cue instructing the video or media-server operator to start the screen content cued for that moment, such as an IMAG clip, a playback reel, or a content timeline.", "plain_english": "A command telling the video operator to start the video. It could be a clip, an animation, or footage shown on the big screens.", "purpose_function": "It triggers the screen content a cue depends on, so video on the LED walls or projection begins in step with the music and lighting.", "practical_application": "On 'roll video,' the media-server operator fires the cued clip or timeline to the LED wall, the projectors, or the broadcast feed.", "category": "Cue call", "related_terms": ["IMAG", "Media server", "Playback", "Roll playback", "Show caller", "LED wall"], "common_mistakes": ["Firing the wrong clip because the media-server cue was not pre-selected and previewed.", "Rolling video out of sync with the audio because the two operators did not share a common count.", "Confusing 'roll video', which starts screen content, with 'roll playback', which starts audio tracks."], "scenario_contexts": ["A caller cues an opening film on the LED wall by saying 'roll video'.", "A media-server operator starting a content timeline on the 'roll video' call.", "Rolling a pre-recorded video segment during a costume change."]}, "2f3de7b7-4da8-494a-b36d-22356449847f": {"definition": "A method of switching between acts in which each act's backline and equipment are pre-set on wheeled risers or carts and rolled straight into position, so the swap is fast with minimal reset on the open deck.", "plain_english": "A fast way to swap one band's gear for the next. Each band's equipment sits on wheeled platforms, so the crew rolls the old set off and the new set on.", "purpose_function": "It shortens the gap between acts by pre-building each setup off-stage on wheels, which keeps festivals and multi-act shows on schedule.", "practical_application": "At a festival, the crew rolls the next band's pre-patched riser into place as the previous band's riser rolls off, then makes the final connections.", "category": "Show operations", "related_terms": ["Changeover", "Rolling riser", "Backline", "Festival", "Set change", "Line check"], "common_mistakes": ["Not pre-patching and labeling the riser off-stage, which cancels the time the roll-on was meant to save.", "UNSAFE: Rolling a heavy loaded riser without locking casters at rest or keeping the travel path clear of crew and cables.", "Skipping a fresh line check after the roll-on, so a bad connection is found during the set."], "scenario_contexts": ["A festival using rolling risers to keep changeovers under fifteen minutes.", "A multi-band club night rolling pre-set backline on and off between acts.", "A support-to-headliner swap done as a rolling changeover to protect the schedule."]}, "30727cb9-087b-499a-8b7c-2a06649e3c6e": {"definition": "A rack enclosure or shock-mounted road case fitted with casters that holds rack-mounted equipment, such as amplifiers, processing, power distribution, or networking, so a complete subsystem can be wheeled as one unit and connected quickly.", "plain_english": "An equipment rack on wheels. It holds gear like amps or processors in one case. The crew can roll the whole unit into place and plug it in fast.", "purpose_function": "It keeps a subsystem pre-wired inside one movable enclosure, which speeds load-in, protects the gear in transit, and cuts on-site setup time.", "practical_application": "A tech rolls the amp or drive rack off the truck to its stage position, sets the caster brakes, then connects the power and signal tails.", "category": "Road Cases", "related_terms": ["Rack unit", "Drive rack", "Road case", "Amplifier rack", "Loom", "Load-in"], "common_mistakes": ["Not engaging the caster brakes after positioning, so the rack rolls away when cables are pulled.", "UNSAFE: Tipping or pushing a tall, top-heavy rack on a ramp or incline without help, which risks it falling over.", "Stowing tails poorly so the rack cannot roll without snagging or straining cables."], "scenario_contexts": ["Rolling an amplifier rack from the truck to its position during load-in.", "A pre-wired networking and drive rack rolled into the mix area.", "Stagehands wheeling processing racks off a rolling changeover riser."]}, "5e039eeb-f3fe-4fa4-9e1b-ba628b96637a": {"definition": "A stage platform or deck built on casters, or set into wheeled caster boards, so a pre-set section of the stage, often backline such as drums or keyboards, can be rolled on and off as one complete unit during changeovers.", "plain_english": "A stage platform on wheels. A band's drums or keyboards are set up on it ahead of time. The crew can then roll the whole section on or off the stage.", "purpose_function": "It lets a crew pre-build and store part of the stage off to the side, then roll it into place, which speeds changeovers and keeps setups consistent.", "practical_application": "The drum tech builds the kit on a rolling riser off-stage, then the crew rolls it to its marks, locks the casters, and runs the tails.", "category": "Staging", "related_terms": ["Riser", "Rolling changeover", "Backline", "Deck", "Caster board", "Spike mark"], "common_mistakes": ["UNSAFE: Standing or riding on a rolling riser while it is being moved instead of walking it into position.", "UNSAFE: Leaving casters unlocked once the riser is on its marks, so it can drift under performers.", "Not accounting for the riser's height and edge, which creates a trip or fall hazard at the deck edge."], "scenario_contexts": ["A drum kit pre-built on a rolling riser and rolled on during a festival changeover.", "A keyboard rig on a rolling riser wheeled into place between acts.", "A rolling riser stored in the wings and rolled to its spike marks for the headliner."]}, "b34a54ae-a48c-4043-820e-6be096faa097": {"definition": "A local crew member, usually with a vehicle, hired for the day to run errands for a touring production, such as collecting people, gear, and hires, or fetching catering and supplies, so the core crew can stay on site and on task.", "plain_english": "A local helper with a car or van hired for show day. They drive around doing errands, like airport pickups and supply runs, so the main crew keeps working.", "purpose_function": "The runner handles off-site transport and errands, which frees the touring crew from leaving the venue and keeps the day's schedule moving.", "practical_application": "A production manager gives the runner a list, such as airport pickups, a hardware-store part, and band catering, and the runner works through it.", "category": "Crew role", "related_terms": ["Production manager", "Local crew", "Advance", "Tour manager", "Catering", "Load-in"], "common_mistakes": ["Assuming a runner is a technical crew member rather than a driver hired for errands and transport.", "Not briefing the runner with clear addresses, contacts, and a call time, which causes missed pickups.", "Confusing the runner with a stagehand or a backline tech."], "scenario_contexts": ["A runner collecting the band and crew from the airport on a show day.", "A runner making a hardware-store trip for a part needed during load-in.", "A production manager scheduling a runner to handle catering and supply pickups."]}, "27a2c60b-30db-44fb-894c-4537f2847f09": {"definition": "A session contractor (also called a fixer or music contractor) is the person who hires, books, and organizes the musicians and personnel needed for a recording, film, or live session, negotiates their fees, confirms availability, and administers the contracts, union paperwork, and payments for the players engaged.", "plain_english": "A session contractor is the person who hires the musicians for a session. They find the right players and book them. They agree the pay and handle the paperwork. Think of them as the person who staffs the recording.", "purpose_function": "It gives a producer or client a single point of contact who assembles the right players and handles the booking, contracts, and payment, so the session is properly staffed and compliant.", "practical_application": "A producer needing a string section calls a session contractor, who books qualified players, confirms the call time and fee, and later files the union and payment paperwork.", "category": "Crew role", "related_terms": ["Session musician", "Session coordinator", "Freelance engineer", "Call time", "Musicians' union"], "common_mistakes": ["Confusing the contractor, who hires players, with the coordinator, who handles session logistics", "Assuming the contractor also produces the music, when their role is staffing and paperwork", "Overlooking that the contractor is responsible for correct union filings and player payments"], "scenario_contexts": ["Booking a string or horn section for an album recording session", "Assembling a pickup band for a televised award-show performance", "Staffing musicians for a film scoring session under a union agreement"]}, "ad534bde-7a83-42bb-9955-f6eda2461d05": {"definition": "A session coordinator is the person who organizes and administers the logistics of a recording, broadcast, or production session, including scheduling studio or stage time, arranging personnel, equipment, transport, and catering, distributing call sheets, and keeping the session running to its timetable and budget.", "plain_english": "A session coordinator keeps a session organized and on time. They book the room and the people. They line up gear, travel, and food. They send out the schedule so everyone knows when to arrive.", "purpose_function": "It centralizes the planning and day-to-day logistics of a session so the creative team can focus on the work while scheduling, resources, and communication are handled.", "practical_application": "A session coordinator confirms the studio booking, sends call times to musicians and crew, arranges gear and catering, and tracks the schedule during the session.", "category": "Crew role", "related_terms": ["Session contractor", "Call sheet", "Call time", "Production manager", "Runner"], "common_mistakes": ["Confusing the coordinator, who handles logistics, with the contractor, who hires the musicians", "Assuming the coordinator makes creative or technical decisions, when the role is organizational", "Forgetting to circulate updated call times, so people arrive at the wrong time"], "scenario_contexts": ["Scheduling studio time and personnel for a multi-day album project", "Coordinating call times, gear, and catering for a broadcast recording session", "Keeping a busy session running to its timetable and budget"]}, "2820d747-2dc4-4c71-82ad-5c1fe081db5e": {"definition": "In touring, settlement is the post-show financial reconciliation between the artist's representative (tour manager or tour accountant) and the promoter, in which box-office income is verified against the agreed deal, approved show expenses are deducted, and the balance owed to the artist, whether the guarantee, a percentage split, or the greater of the two, is calculated and paid.", "plain_english": "Settlement is when the money is sorted out after a show. The tour manager and the promoter check ticket sales and costs. Then they work out what the artist is owed and pay it. It usually happens the same night.", "purpose_function": "It ensures the artist is paid correctly for a performance by reconciling actual ticket income and costs against the terms of the booking contract.", "practical_application": "After the show a tour manager sits down with the promoter, reviews the box-office statement and expense receipts, and collects the artist's payment during settlement.", "category": "Production Workflow", "related_terms": ["Guarantee", "Promoter", "Tour manager", "Box office", "Advance", "Rider"], "common_mistakes": ["Confusing the guarantee with the final payment, when a percentage split can pay more", "Accepting a settlement without checking the box-office count and approved expenses", "Assuming settlement always happens by bank transfer, when many shows still settle in cash on the night"], "scenario_contexts": ["A tour manager settling the show with the promoter after doors close", "Verifying ticket counts and deductions against the contract before accepting payment", "Reconciling a percentage deal where income exceeds the guarantee"]}, "297dffd8-c880-48f5-b101-f479c7851e06": {"definition": "In live production, setup is the process of unloading, assembling, positioning, connecting, and configuring the stage, audio, lighting, and backline equipment so it is ready for line check, sound check, and performance; the term also refers to the resulting physical arrangement and signal configuration of that equipment for a given show.", "plain_english": "Setup is getting all the gear ready for a show. The crew moves in the equipment, puts it in place, and connects it. Then they turn it on and check it works. Setup also means how the gear is arranged.", "purpose_function": "It turns transported gear into a working, performance-ready system, giving the crew a known, checked starting point before line check and sound check.", "practical_application": "During load-in the crew follows the stage plot and input list to set risers, backline, mics, and cabling, completing the setup before sound check.", "category": "Stage Operations", "related_terms": ["Load-in", "Line check", "Sound check", "Stage plot", "Strike", "Patch"], "common_mistakes": ["Starting to run cables before the stage plot and input list are confirmed, causing rework", "Skipping a line check after setup, so faults surface during sound check instead", "UNSAFE: Leaving cables loose and untaped across walkways during setup, creating trip hazards for crew and performers"], "scenario_contexts": ["Setting up backline and monitors during load-in before sound check", "Rebuilding the same festival setup identically at each city on a tour", "Following a stage plot to place and connect gear for a one-off event"]}, "d9dfaeb7-0f97-45ac-b597-62ed31bf8943": {"definition": "A shock rack is a road (flight) case built around a 19-inch rack frame that is suspended inside the outer shell on shock-absorbing mounts, typically foam blocks or elastomeric or spring isolators, so impacts and vibration during transport are damped before they reach the mounted equipment. It protects sensitive rack gear such as amplifiers, processors, drives, and computers from shock and road vibration.", "plain_english": "A shock rack is a road case with springy padding inside. The gear sits on a frame that floats on foam or rubber mounts. When the case gets bumped, the padding soaks up the shock. This protects fragile gear on the road.", "purpose_function": "It isolates rack-mounted equipment from the impacts and constant vibration of touring transport, reducing the risk of mechanical failure in amplifiers, processors, drives, and computers.", "practical_application": "A technician racks fragile gear such as amplifiers, network switches, or a playback computer into a shock rack so it survives repeated truck loading and long road transport.", "category": "Transport", "related_terms": ["Flight case", "Road case", "Drive rack", "Rack unit", "Amp rack"], "common_mistakes": ["Assuming a standard rack case gives shock protection, when only a suspended shock rack isolates gear from impact", "Overloading the rack so heavy gear sags and defeats the shock mounts", "Leaving loose items inside the rack that rattle and damage equipment in transit"], "scenario_contexts": ["Transporting amplifier and processing racks between cities on a tour", "Protecting a playback or recording computer from road vibration", "Shipping sensitive networked audio gear as air or truck freight"]}, "29dcfd41-bd07-43c0-a85c-24eafe3abcf3": {"definition": "A readiness state in which all equipment for a production, or for one department, is fully rigged, powered, tested, and confirmed working, so the show can begin or resume with no further setup required.", "plain_english": "\"Show ready\" means the gear is fully set up and tested. It is ready to run the show at any moment.", "purpose_function": "It gives the crew and stage manager a clear, shared go status, confirming that setup and checks are complete before doors or downbeat.", "practical_application": "Department heads report \"show ready\" to the stage manager once their systems pass line checks, confirming the production can proceed.", "category": "Show Status", "related_terms": ["Line check", "Sound check", "Preset", "Doors", "Stage manager"], "common_mistakes": ["Calling \"show ready\" before line checks or safety checks are actually complete", "Assuming show ready is permanent; a later patch change or repair can revoke the status until systems are re-checked"], "scenario_contexts": ["A monitor engineer reporting the stage show ready after finishing line checks", "A lighting operator confirming the rig is show ready before the house opens"]}, "1540b9a4-0e81-47cf-b5b7-fca84f8b566c": {"definition": "A changeover between acts carried out without disruptive sound through the PA — no test tones, feedback, or loud stage noise — by muting outputs, pre-patching, and using prepared labels so the next act's setup is inaudible to the audience.", "plain_english": "A silent changeover swaps one act's gear for the next quietly. The crew keeps loud noise out of the speakers.", "purpose_function": "It keeps the audience experience smooth between acts, so setting up the next band does not send distracting noise through the sound system.", "practical_application": "At festivals with quick turnarounds, engineers mute the main outputs and line-check through headphones or in-ears to keep the changeover silent.", "category": "Stage Operations", "related_terms": ["Changeover", "Line check", "Soft patch changeover", "Mute", "Festival patch"], "common_mistakes": ["Confusing a silent changeover with a fast changeover; the goal is inaudible setup, not only speed", "Forgetting to mute outputs before line-checking, so test signals blast the audience"], "scenario_contexts": ["A festival stage swapping bands in ten minutes without audible test tones", "An engineer line-checking the next act through headphones during a silent changeover"]}, "1522ac83-014b-409e-8156-aeaa2b404fd9": {"definition": "The planned route along which a multicore cable (snake) is laid between the stage and the mixing position, chosen to minimise length, avoid trip and traffic hazards, and keep the cable clear of mains power and public areas.", "plain_english": "The snake path is the route the big multi-cable takes across the venue. It runs from the stage to the mixing desk.", "purpose_function": "It defines a safe, efficient run for the main audio multicore, so signal reaches the console without creating hazards or wasting cable.", "practical_application": "During load-in, crew plan the snake path along a wall or under matting, then tape or ramp it wherever it crosses walkways.", "category": "Cabling", "related_terms": ["Snake run", "Multicore", "Stage box", "Cable ramp", "Front of house"], "common_mistakes": ["UNSAFE: Running the snake straight across a walkway without taping it down or using a cable ramp, creating a trip hazard", "Running the snake alongside mains power cables, which can induce hum and noise into the audio"], "scenario_contexts": ["A crew planning the snake path from the stage-left stage box to the front-of-house position", "Taping and ramping the snake path where it crosses an audience aisle"]}, "219f7a93-4b9f-4418-8f74-7d80f9b1ecc1": {"definition": "The physical length of multicore cable laid out along its path, or the act of laying it; also used for the distance the snake spans between the stage and the console.", "plain_english": "The snake run is the length of multi-cable laid from the stage to the desk. Crew tape it down so no one trips.", "purpose_function": "It carries many audio channels from stage to console in one bundled cable, cutting setup time and clutter compared with running individual lines.", "practical_application": "A crew member walks the snake run from the stage box to front of house, flaking out the cable and securing it along the chosen path.", "category": "Cabling", "related_terms": ["Snake path", "Multicore", "Stage box", "Flaking", "Cable ramp"], "common_mistakes": ["UNSAFE: Leaving a snake run uncovered across audience or crew walkways instead of ramping or taping it down", "UNSAFE: Piling excess snake so it blocks an exit route or fire door"], "scenario_contexts": ["Flaking out a 60-metre snake run from the stage to the mix position during load-in", "Coiling and storing the snake run neatly during load-out"]}, "41bb499a-679c-4a11-8085-3e00f8b2e1ff": {"definition": "A breakout cable that transitions between a 19-pin Socapex multi-circuit connector and several individual single-circuit connectors, letting one multicable carry multiple mains-power circuits (commonly six) to or from separate devices such as lighting fixtures or dimmers.", "plain_english": "A Socapex fanout is a cable that splits one thick power plug into several single outlets. It feeds power to many stage lights at once.", "purpose_function": "It lets one heavy multicable replace several separate power cables, so a lighting rig can be wired and powered faster with fewer runs.", "practical_application": "An electrician plugs a Socapex line from a distro or dimmer into the fanout, then connects each tail to an individual fixture or circuit.", "category": "Power Distribution", "related_terms": ["Multicable", "Power distro", "Dimmer", "Stagepin connector", "Load-in"], "common_mistakes": ["UNSAFE: Connecting or disconnecting a Socapex fanout while the line is energised; de-energise and lock out the circuit before mating or breaking the connector", "UNSAFE: Drawing more current through the fanout than the multicable or its circuits are rated for, which can overheat conductors and start a fire", "Assuming every 19-pin fanout shares the same pin-out or circuit count; verify the wiring standard before interconnecting different systems"], "scenario_contexts": ["Breaking a Socapex line out to individual fixture power tails on a lighting truss", "Connecting a distro's Socapex output to a fanout feeding a row of conventional lights"]}, "7b0dc9e8-9cec-4f7c-b48e-d42c21cf9ee7": {"definition": "A changeover carried out by reassigning input-to-channel (or source-to-output) routing in a console's or lighting desk's software patch, rather than by physically re-plugging cables, so the next act's sources map to the correct channels without touching the stage wiring.", "plain_english": "This means re-routing signals inside the console's software between acts. The crew avoids re-plugging cables by hand.", "purpose_function": "It speeds changeovers and reduces errors, because routing changes happen in software instead of by repatching physical connectors under time pressure.", "practical_application": "On a digital console the engineer recalls or edits the input patch so the incoming act's stage-box channels land on their prepared desk channels.", "category": "Stage Operations", "related_terms": ["Soft patch", "Changeover", "Silent changeover", "Input patch", "Scene recall"], "common_mistakes": ["Confusing a soft patch (software routing) with a hard patch that physically re-plugs connectors", "Recalling the wrong patch or scene, so inputs land on the wrong channels at the top of the next set"], "scenario_contexts": ["Recalling a stored input patch on a digital desk between two bands", "Editing the soft patch so a guest act's inputs map onto the resident channel strips"]}, "3d112a85-4d51-4466-a7f0-4fefbe84079b": {"definition": "A maximum permitted sound level for a performance, expressed as a sound-pressure level (often an A-weighted average over time or a peak limit), set by a venue licence, local noise ordinance, or promoter, and monitored at the mix position or an off-site point.", "plain_english": "A sound limit is the loudest a show is allowed to get. It protects people's hearing and keeps neighbours happy.", "purpose_function": "It caps the level to protect audience and worker hearing and to keep noise within the legal or contractual limits agreed for the venue and its neighbours.", "practical_application": "The engineer watches an SPL meter or a venue noise-limiter display and pulls the mix back if levels approach the agreed sound limit.", "category": "Noise & Hearing", "related_terms": ["SPL", "Noise limiter", "dBA", "Hearing protection", "Mix position"], "common_mistakes": ["UNSAFE: Treating a venue sound limit as full hearing protection; long exposure even below a limit can still damage hearing, so wear earplugs and follow occupational noise limits", "Confusing an A-weighted average limit with an instantaneous peak, and mixing hotter than the agreed measurement method allows"], "scenario_contexts": ["An outdoor festival enforcing an off-site noise limit measured at nearby homes", "A licensed venue whose power trips through an installed limiter when the sound limit is exceeded"]}, "0908be78-ec01-4355-80a0-07c44a42a572": {"definition": "The identifying name assigned to a signal source — such as an input channel, stage-box socket, or cable end — stating what the source is (e.g. \"Kick\", \"Lead Vox\"), applied on the console, patch sheet, or physical tape so signals can be traced and routed correctly.", "plain_english": "A source label is the name given to each input, like \"Kick\" or \"Lead Vocal\". It tells the crew what every channel carries.", "purpose_function": "It lets anyone quickly identify what each input carries, so signals are patched, mixed, and fault-found without tracing cables by ear.", "practical_application": "An engineer names each channel on the digital console and marks the stage box, so labels on the desk match the physical inputs.", "category": "Signal Routing", "related_terms": ["Input patch", "Channel name", "Stage box", "Patch sheet", "Line check"], "common_mistakes": ["Leaving default labels like \"Ch 1\" so no one can tell inputs apart during a fault", "Labelling the desk but not the stage end, so the patch and the physical inputs disagree"], "scenario_contexts": ["Naming console channels \"Kick, Snare, Hat\" during patch so the mix reads clearly", "Writing source labels on stage-box tape to match the input list during line check"]}, "370a381d-4107-4adb-851f-8925a80e7738": {"definition": "A collection of backup parts, consumables, and tools carried by a touring crew — such as spare cables, connectors, adaptors, fuses, lamps, and batteries — kept ready so a failed item can be replaced quickly during setup or the show.", "plain_english": "A spare kit is a stash of backup parts a crew brings on tour. If gear breaks, they grab a replacement fast.", "purpose_function": "It lets the crew fix or swap failed equipment on the spot, so a fault does not stop or delay the show.", "practical_application": "When a mic cable fails during a set, a technician pulls a working cable from the spare kit and swaps it straight away.", "category": "Touring Logistics", "related_terms": ["Consumables", "Spares", "Cable", "Load-in", "Tour case"], "common_mistakes": ["Not restocking the spare kit after a show, so a needed part is missing next time", "Carrying spares that do not match the actual gear on the tour, such as the wrong connectors or fuse ratings"], "scenario_contexts": ["Replacing a blown XLR cable from the spare kit mid-show", "Restocking connectors, adaptors, and batteries in the spare kit during load-out"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"023f7bea-5bf7-4665-8937-83bc126c192f": {"definition": "To mark a position on the stage floor with tape or paint (a \"spike mark\") so a performer, set piece, prop, or piece of equipment can be returned to the exact same spot at each rehearsal and performance.", "plain_english": "To \"spike it\" means to mark a spot on the stage with tape. The mark shows where something goes every time.", "purpose_function": "It records exact positions so performers, scenery, and gear land in the same place each show, keeping blocking, sightlines, and focus consistent.", "practical_application": "A stagehand spikes a monitor wedge or a drum riser with tape during setup, so it is placed identically at every performance.", "category": "Stage Marking", "related_terms": ["Spike mark", "Spike tape", "Blocking", "Set piece", "Marking out"], "common_mistakes": ["Confusing \"spike it\" (marking a floor position) with electrical or signal spikes, which are unrelated meanings", "Using tape that leaves residue or is hard to see, so marks lift or cannot be found in low light"], "scenario_contexts": ["Spiking the positions of set pieces before a scene change", "Marking a performer's start position on the stage floor during rehearsal"]}, "9ad8c4bf-5b32-41c9-b9b9-73d89511ab4f": {"definition": "A rack case housing a microphone splitter, which takes each input signal from the stage and divides it into multiple isolated feeds — typically for the front-of-house console, the monitor console, and often a recording or broadcast feed.", "plain_english": "A split rack holds a mic splitter. It copies each stage signal so several mixers can use the same mics at once.", "purpose_function": "It lets more than one console share the same stage sources without loading down the mics, so front-of-house, monitors, and recording each get a clean feed.", "practical_application": "On a large show, stage mics land in the split rack, which feeds the monitor desk on stage and sends a split to the front-of-house console.", "category": "Signal Routing", "related_terms": ["Microphone splitter", "Stage box", "Front of house", "Monitor console", "Isolation transformer"], "common_mistakes": ["Confusing a split rack (a mic-splitter rack) with a general equipment rack that is simply divided into sections", "Assuming every split output is transformer-isolated; some are direct splits that can pass ground noise between consoles"], "scenario_contexts": ["Patching stage mics into a split rack that feeds both front-of-house and monitor consoles", "Taking a broadcast feed from a spare output on the split rack"]}, "9b217c04-b73e-4f19-a330-565d82bf0a24": {"definition": "A common phrase for the loudspeaker stacks and equipment racks that make up a sound system, or for the task of setting them up — positioning the speaker enclosures and rolling in the racked amplifiers, processors, and related gear.", "plain_english": "\"Stack and rack\" means setting up the speaker stacks and the gear racks. It is the basic build of a PA system.", "purpose_function": "It describes getting the core sound system physically in place — speakers stacked and electronics racked — as the first step of building the audio rig.", "practical_application": "At load-in, the audio crew stack and rack the PA, positioning the speaker enclosures and rolling the amp and processing racks into place.", "category": "PA Setup", "related_terms": ["PA system", "Amp rack", "Loudspeaker stack", "Load-in", "Line array"], "common_mistakes": ["UNSAFE: Ground-stacking loudspeaker enclosures too high or on an uneven, unsecured base, risking a topple onto people below; follow the manufacturer's stacking limits and use straps or outriggers", "Thinking stack and rack is the whole job; the system still needs cabling, powering, and tuning after it is built"], "scenario_contexts": ["Stacking subwoofers and tops and rolling amp racks into position during load-in", "Breaking down the stack and rack at load-out"]}, "96c7a12f-d6d7-46aa-9b6a-753d7b6f0e85": {"definition": "The audio equipment and signals located on or serving the stage itself — including stage microphones, stage boxes, monitor wedges or in-ear systems, and the on-stage monitor mixes — as distinct from the front-of-house system serving the audience.", "plain_english": "Stage audio is the sound gear and signals on the stage. It covers mics, stage monitors, and the mix the performers hear.", "purpose_function": "It groups everything the performers need to hear and be heard, so on-stage sound is managed separately from the audience (front-of-house) system.", "practical_application": "A monitor engineer manages stage audio — the wedges, in-ears, and stage patch — while the front-of-house engineer handles the audience mix.", "category": "Stage Operations", "related_terms": ["Monitor mix", "Stage box", "In-ear monitor", "Wedge", "Front of house"], "common_mistakes": ["Confusing stage audio with the front-of-house system; stage audio serves the performers, front-of-house serves the audience", "UNSAFE: Running stage monitors at excessive levels, exposing performers and nearby crew to hearing-damaging sound"], "scenario_contexts": ["Setting up the stage audio patch and monitors before a soundcheck", "Troubleshooting a dead stage monitor during a line check"]}, "3e767fc2-a1a1-40bb-9822-71ffae8a74d6": {"definition": "A crew member responsible for the audio equipment on stage — setting up and maintaining microphones, stage boxes, monitors, and the stage patch, and supporting the monitor and front-of-house engineers during setup, soundcheck, and the show.", "plain_english": "A stage audio technician looks after the sound gear on stage. They set up mics and monitors and fix problems fast.", "purpose_function": "The role keeps all on-stage audio working and correctly patched, so engineers can mix and performers get reliable microphones and monitoring.", "practical_application": "During soundcheck, the stage audio technician swaps a faulty mic, re-seats a stage-box connector, and confirms each channel with the engineer.", "category": "Crew Roles", "related_terms": ["Stage audio", "Monitor engineer", "Stagehand", "Stage box", "Line check"], "common_mistakes": ["Confusing the stage audio technician with the front-of-house engineer; the technician supports the stage, not the audience mix", "UNSAFE: Spending long shifts near high stage sound levels without hearing protection, risking permanent hearing loss"], "scenario_contexts": ["Patching and testing stage inputs before the band arrives for soundcheck", "Running a spare mic to a performer after a failure during the show"]}, "1bc5794a-ee50-4c0b-a5bd-3b66e5a797c9": {"definition": "The process of assembling the physical stage and its structures at a venue — erecting staging decks, risers, roof or truss structures, barriers, and set elements — carried out at load-in before the technical departments rig their equipment.", "plain_english": "A stage build is putting the stage together at a venue. Crew set up the platforms and risers before gear goes on.", "purpose_function": "It creates the physical platform and structures the show is performed and rigged on, giving every other department a safe, level base to build on.", "practical_application": "The staging crew builds the decks and risers at load-in, then the audio, lighting, and video teams rig once the structure is signed off.", "category": "Staging", "related_terms": ["Load-in", "Riser", "Staging deck", "Truss", "Rigging"], "common_mistakes": ["UNSAFE: Working near or on an unguarded raised stage edge without the guardrails or fall protection required at height", "Rigging equipment onto staging before the build is complete and checked, which can overload or destabilise the structure"], "scenario_contexts": ["Assembling staging decks and risers during the morning load-in", "Signing off a completed stage build before departments begin rigging"]}, "18c7e99c-2fb9-4adc-8a3d-46c86e70e90e": {"definition": "A call or confirmed status meaning the stage — and often the area above and around it — is empty of unnecessary personnel and obstructions, given before a potentially hazardous action such as flying scenery, moving automation, a set change, or operating the fly system.", "plain_english": "\"Stage clear\" means no one is on the stage who should not be. Crew call it before moving heavy or flown gear.", "purpose_function": "It confirms the working area is safe before a hazardous move, so no one is struck or crushed by moving scenery, automation, or a flown load.", "practical_application": "Before flying in a piece of scenery, the stage manager waits for \"stage clear\" from the crew, then calls the move.", "category": "Stage Communication", "related_terms": ["Stage manager", "Flying", "Fly system", "Automation", "Cue call"], "common_mistakes": ["UNSAFE: Moving flown scenery or automation before stage clear is confirmed, risking a strike or crush injury", "Assuming stage clear is permanent; it must be re-confirmed each time before another hazardous move"], "scenario_contexts": ["Confirming stage clear before flying in a backdrop", "Calling stage clear before running an automated set move"]}, "ff246ad4-6c37-4dc7-9355-77ceed40450f": {"definition": "The monitor engineer's working position and equipment cluster located at stage left — the side of the stage to a performer's left when facing the audience. It typically houses the monitor console, stage racks, and processing that feed the performers' floor wedges and in-ear monitors.", "plain_english": "This is the monitor engineer's work spot on the band's left side of the stage. From here they mix the sound the performers hear on stage.", "purpose_function": "It fixes the monitor mixing position and its racks at a known stage-left location, so the engineer can see the performers and manage their on-stage sound close to the source.", "practical_application": "A monitor engineer builds their console and racks at stage left monitor world, patches into the stage racks there, and mixes wedge and in-ear feeds for the band.", "category": "Stage Areas", "related_terms": ["Monitor engineer", "Stage right monitor world", "Stage rack", "Wedge", "In-ear monitor", "Front of house"], "common_mistakes": ["Confusing stage left with house left; stage left is the performer's left facing the audience, which is the audience's right", "Assuming monitor world is always at stage left; its side varies by production and venue"], "scenario_contexts": ["A touring monitor engineer setting up console and racks at stage left before doors", "A stagehand routing the multicore to the stage left monitor world during load-in"]}, "cb2efb53-1d64-4b27-a84e-ca4357ab9a76": {"definition": "The set of physical connections that route microphone, instrument, and line signals from stage sources into the stage rack or stage box inputs, and outputs back to the stage, following a documented input or patch list.", "plain_english": "The stage patch is how the mics and instruments on stage plug into the input boxes. A list shows the crew which cable goes to which input number.", "purpose_function": "It organises and standardises every stage connection so signals reach the correct console channels, making setup repeatable and faults quick to trace.", "practical_application": "Before a show the crew builds the stage patch, connecting each source to its assigned stage-rack input per the patch list.", "category": "Signal Distribution", "related_terms": ["Stage rack", "Stage box", "Input list", "Patch list", "Multicore", "Stage patch technician"], "common_mistakes": ["Patching a source to the wrong input number, so the channel shows up on the wrong fader", "Failing to update the stage patch when the input list changes between acts"], "scenario_contexts": ["A festival crew rebuilding the stage patch for each band's input list", "A tech tracing a dead channel back through the stage patch to a loose connector"]}, "4278ef76-b2ff-44ca-8acc-03cf46424150": {"definition": "A crew member responsible for building, labelling, and maintaining the stage patch — connecting stage sources to the stage racks per the input list and troubleshooting signal faults at the stage end during setup and the show.", "plain_english": "This crew member plugs in and manages all the stage connections. They also fix any cable or input problems on stage during the show.", "purpose_function": "The role makes sure every stage source is correctly and reliably connected, freeing the mixing engineers to focus on the mix while patching issues are handled at the stage.", "practical_application": "The stage patch technician runs and labels cables, connects them to the stage racks, and swaps a faulty line or mic if a channel drops during the show.", "category": "Crew Roles", "related_terms": ["Stage patch", "Stage rack", "Stagehand", "Input list", "Monitor engineer", "Multicore"], "common_mistakes": ["Confusing the stage patch technician with the systems tech; the patch tech focuses on stage-end connections and labelling", "Leaving patched lines unlabelled, which makes faults slow to trace during the show"], "scenario_contexts": ["A stage patch technician labelling every mic line before doors", "A patch tech re-patching a spare line when an input fails mid-set"]}, "5aeb242f-45dc-4d11-b5da-c2361284e1e9": {"definition": "A road-cased rack of equipment placed on or beside the stage that acts as the stage-end input/output hub of a sound system. In a digital system it holds the stage box with mic preamps and A/D–D/A converters, linked to the consoles over a single digital snake.", "plain_english": "A stage rack is a wheeled case of gear on the stage. It collects all the stage signals and sends them to the mixing desks, often down one digital cable.", "purpose_function": "It concentrates stage inputs and outputs in one place and converts them for transport, replacing a heavy analog multicore with a compact digital link to the consoles.", "practical_application": "Engineers patch stage mics and instruments into the stage rack, which streams the audio to the front-of-house and monitor consoles over the digital snake.", "category": "Signal Distribution", "related_terms": ["Stage box", "Stage patch", "Digital snake", "Mic preamp", "Front of house", "Monitor console"], "common_mistakes": ["Using 'stage rack' and 'stage box' as if identical; the stage box is the I/O device that lives inside the stage rack", "UNSAFE: Moving or stacking a heavy stage rack without team lifting or securing it, risking crush or back injury"], "scenario_contexts": ["A crew rolling the stage rack into position and running one digital snake to front of house", "A monitor engineer setting preamp gain on the shared stage rack inputs"]}, "dc63dab6-8a5f-4762-bba0-fcf1eff345e6": {"definition": "The monitor engineer's working position and equipment cluster located at stage right — the side of the stage to a performer's right when facing the audience. It typically houses the monitor console, stage racks, and processing that feed the performers' floor wedges and in-ear monitors.", "plain_english": "This is the monitor engineer's work spot on the band's right side of the stage. From here they mix the sound the performers hear on stage.", "purpose_function": "It fixes the monitor mixing position and its racks at a known stage-right location, so the engineer can see the performers and manage their on-stage sound close to the source.", "practical_application": "A monitor engineer builds their console and racks at stage right monitor world, patches into the stage racks there, and mixes wedge and in-ear feeds for the band.", "category": "Stage Areas", "related_terms": ["Monitor engineer", "Stage left monitor world", "Stage rack", "Wedge", "In-ear monitor", "Front of house"], "common_mistakes": ["Confusing stage right with house right; stage right is the performer's right facing the audience, which is the audience's left", "Assuming monitor world is always at stage right; its side varies by production and venue"], "scenario_contexts": ["A touring monitor engineer setting up console and racks at stage right before doors", "A stagehand routing the multicore to the stage right monitor world during load-in"]}, "ac761a77-1acc-441f-a308-e1df8e618472": {"definition": "A member of the stage crew who carries out the manual and technical labour of a production — loading in and out, assembling staging and sets, moving and positioning equipment, and assisting departments during setup, the show, and strike.", "plain_english": "A stagehand is a crew worker who moves and sets up gear for a show. They help load in, run the show, and pack everything away.", "purpose_function": "Stagehands provide the hands-on labour that gets a production built, run, and struck safely and on schedule.", "practical_application": "During load-in, stagehands unload trucks, roll cases to position, and help each department set up its equipment.", "category": "Crew Roles", "related_terms": ["Load-in", "Load-out", "Strike", "Stage patch technician", "Staging area", "Rigger"], "common_mistakes": ["Assuming stagehands only carry gear; many are skilled in rigging, audio, lighting, or video work", "UNSAFE: Lifting heavy cases alone or with poor technique instead of team lifting and proper manual-handling practice"], "scenario_contexts": ["A local crew of stagehands unloading trucks at load-in", "Stagehands striking the stage and loading cases back into trucks after the show"]}, "6a251c45-8900-4166-a7b1-e5101dfd189a": {"definition": "A designated, cleared space near the loading dock or stage where equipment and cases are gathered, sorted, and organised before being moved to their final positions during load-in, and collected again during load-out.", "plain_english": "A staging area is a set-aside space to gather gear before it goes on stage. Cases wait here in order so the crew can move them out smoothly.", "purpose_function": "It keeps load-in and load-out organised and safe by giving cases a temporary home, so the stage and walkways stay clear and gear moves in the right order.", "practical_application": "The crew rolls cases into the staging area, sorts them by department, then moves each one to its position as that department is ready.", "category": "Venue Areas", "related_terms": ["Load-in", "Load-out", "Stagehand", "Loading dock", "Road case", "Strike"], "common_mistakes": ["UNSAFE: Blocking fire exits, egress routes, or walkways with cases staged in the area", "Leaving cases unsorted or unlabelled, which slows load-in and load-out"], "scenario_contexts": ["A crew staging all audio cases in a marked area off the dock before load-in", "Cases returning to the staging area during strike to be loaded in truck-pack order"]}, "296dd988-ded1-422e-bb7c-495d5422e0da": {"definition": "A wheeled road case built as a large trunk, used to transport and store microphone stands — and sometimes music or lighting stands — together as a unit between venues.", "plain_english": "A stand trunk is a big wheeled case for carrying mic stands. All the stands travel together in one box.", "purpose_function": "It protects stands in transit and keeps them together, so the crew can move and deploy a full set of stands quickly at each venue.", "practical_application": "At load-in the crew opens the stand trunk, hands out mic stands to their positions, then repacks them into the trunk at strike.", "category": "Cases and Transport", "related_terms": ["Road case", "Microphone stand", "Staging area", "Load-in", "Cable trunk", "Strike"], "common_mistakes": ["Overloading the stand trunk so it becomes too heavy to move safely or will not close properly", "UNSAFE: Rolling a heavy stand trunk down a ramp without control, risking a runaway case or crush injury"], "scenario_contexts": ["A crew wheeling the stand trunk to the stage and handing out mic stands", "Repacking all mic stands into the stand trunk during load-out"]}, "75544c4a-69ac-4e08-a310-3997369cef56": {"definition": "A verbal readiness warning given over the comms system before a cue is executed, telling the relevant operators or performers to prepare for an imminent action; it is followed by the executing command 'Go'.", "plain_english": "\"Standby\" is a warning that a cue is about to happen. It tells the crew to get ready, and \"Go\" then means do it now.", "purpose_function": "It primes operators so cues run cleanly and on time, cutting missed or late cues by giving a clear ready signal before the action.", "practical_application": "The stage manager calls \"standby sound cue 12,\" waits for the moment, then calls \"go\" for the operator to fire it.", "category": "Cue Calling", "related_terms": ["Cue", "Go", "Stage manager", "Comms", "Show ready"], "common_mistakes": ["Acting on the standby instead of waiting for 'go'; a standby only means prepare", "Calling the standby too early or too late, so operators are not primed at the right moment"], "scenario_contexts": ["A stage manager calling standbys for lighting, sound, and fly cues before a scene change", "An operator acknowledging a standby and holding until the 'go' command"]}, "a2d8ee49-837f-4036-810e-ca350790df69": {"definition": "A crew member's spoken confirmation, given in reply to a 'standby' warning cue, that they are ready and waiting to execute the next cue or action on the operator's or stage manager's 'go'.", "plain_english": "\"Standing by\" is how a crew member says they are ready. It answers the warning that comes before a go signal. It means: set and waiting to act.", "purpose_function": "It confirms readiness across the crew before a cue fires, so the stage manager knows every department is set and can safely call 'go'.", "practical_application": "When the stage manager calls a standby over comms, each cued operator answers 'standing by' before the 'go' triggers their move.", "category": "Crew comms", "related_terms": ["Standby", "Go", "Cue", "Stage manager", "Cue call"], "common_mistakes": ["Answering 'standing by' before you are actually ready, so a cue fires when you cannot execute it", "Confusing 'standby' (the warning cue) with 'standing by' (the reply that confirms readiness)"], "scenario_contexts": ["A lighting operator answering 'standing by' after the stage manager calls the standby for a blackout cue", "A deck crew member confirming 'standing by' before a scenery move on the next 'go'"]}, "c906f995-15a2-48ce-98d0-8395995d91b0": {"definition": "An emergency call to halt a performance immediately, usually because of a safety hazard to performers, crew, or audience; on the call, cues cease, house lights may be raised, and the situation is made safe before the show resumes.", "plain_english": "\"Stop show\" is an urgent order to halt the performance at once. It is called when something turns dangerous. Safety comes before the show.", "purpose_function": "It gives the crew one clear, unmistakable command to stop everything fast, so a dangerous situation can be dealt with before anyone is hurt.", "practical_application": "If a performer falls or a fire risk appears, the stage manager or a designated crew member calls 'stop show' over comms to halt cues and clear the hazard.", "category": "Safety call", "related_terms": ["Stage manager", "Emergency stop", "House lights", "Standby", "Go"], "common_mistakes": ["UNSAFE: Hesitating to call 'stop show' during a genuine safety emergency for fear of disrupting the performance; safety always comes first", "Calling 'stop show' for a minor artistic or technical glitch that endangers no one, when a quieter fix would do"], "scenario_contexts": ["A stage manager calling 'stop show' after an audience member climbs onto the stage", "Halting a concert with 'stop show' when a lighting truss or rigging fault is spotted"]}, "b6e6fa85-e86b-4d52-8cc0-480734632a24": {"definition": "An audio engineer responsible for creating and mixing a dedicated audio feed for a livestream or online broadcast, kept separate from the front-of-house and monitor mixes and balanced for headphone and small-speaker listeners rather than for the live room.", "plain_english": "A stream mix engineer builds the sound for an online broadcast. It is a separate mix from the one in the room. It is made for people watching at home.", "purpose_function": "It exists because a room mix rarely translates to headphones or phone speakers, so a tailored mix is made for the streaming audience.", "practical_application": "At a streamed gig, the stream mix engineer takes a split or console feed and balances levels, effects, and crowd mics for the broadcast output.", "category": "Crew role", "related_terms": ["Front of house", "Broadcast mix", "Split", "Monitor engineer", "Console"], "common_mistakes": ["Assuming the front-of-house mix will translate to the stream, when headphone and phone listeners need a different balance", "Forgetting to add ambience or crowd mics, leaving the stream sounding dry and lifeless"], "scenario_contexts": ["Mixing a dedicated broadcast feed for a concert livestream", "Creating a separate stream mix for a streamed worship service or corporate webcast"]}, "aa0f2256-33f2-48e8-afa0-99f86d8ba842": {"definition": "An instruction to remove an item, piece of scenery, or equipment from the performance area and hold it just offstage in the wings, rather than clearing it fully out of the stage house.", "plain_english": "This means take something off the stage and put it in the wings. The wings are the hidden areas at the sides. The item stays close, not carried far away.", "purpose_function": "It clears the stage quickly while keeping the item nearby, so it can be reset or brought back without a long trip to storage.", "practical_application": "During a scene change, deck crew strike a set piece to the wings so it is out of sight but ready to return later.", "category": "Stage operations", "related_terms": ["Strike", "Wings", "Scene change", "Deck crew", "Preset"], "common_mistakes": ["UNSAFE: Piling struck items in the wings so they block a crew walkway, exit, or fire lane in the dark", "Confusing 'strike to the wings' (hold just offstage) with a full strike that clears the item out of the building"], "scenario_contexts": ["Deck crew striking a rostrum to the wings during a blackout scene change", "Moving a music stand and stool to the wings after a solo number"]}, "59999672-6222-4f54-860f-2cad3d3a0ef8": {"definition": "An entry-level trainee at a recording studio who assists staff with basic tasks — setup, tear-down, cabling, session prep, cleaning, and errands — while learning studio workflow and etiquette.", "plain_english": "A studio intern is a trainee learning how a recording studio works. They help with simple jobs like setting up and tidying. It is a first step into the industry.", "purpose_function": "It provides hands-on training and support labour, giving newcomers a route into the industry while helping sessions run smoothly.", "practical_application": "An intern arrives early to set up mics and headphones, keeps the control room stocked, and shadows the engineer during sessions.", "category": "Studio Roles", "related_terms": ["Studio technician", "Studio manager", "Assistant engineer", "Session", "Control room"], "common_mistakes": ["Thinking interns should run the console unsupervised; the role is to assist and learn, not to run sessions", "Underestimating studio etiquette, such as staying quiet and not touching gear without being asked"], "scenario_contexts": ["An intern setting up the live room and coiling cables before a session", "A trainee shadowing the assistant engineer to learn the studio's signal routing"]}, "290896b0-0098-4682-b4f6-83d59000fe45": {"definition": "The person responsible for the day-to-day business and operational running of a recording studio, including bookings, scheduling, client relations, staffing, billing, and maintenance coordination, so that sessions run smoothly and the facility stays viable.", "plain_english": "A studio manager runs the daily business of a recording studio. They handle bookings, staff, and bills. Their job keeps sessions running on time.", "purpose_function": "It exists to keep the facility organised and financially healthy, freeing engineers to focus on recording while someone handles the business side.", "practical_application": "The studio manager books sessions into the diary, invoices clients, arranges maintenance, and makes sure staff and rooms are ready each day.", "category": "Studio Roles", "related_terms": ["Studio owner", "Studio intern", "Studio technician", "Session", "Booking"], "common_mistakes": ["Confusing the studio manager (business and scheduling) with the chief engineer (technical and recording)", "Assuming the manager must be a top engineer; the role is primarily organisational and commercial"], "scenario_contexts": ["Scheduling overlapping band sessions across two rooms to avoid clashes", "Handling a client billing query and rebooking a cancelled session"]}, "4885b7d5-a3a2-4644-add3-3b4b33be3fca": {"definition": "The individual or company that owns a recording studio facility and its assets, bearing the financial risk and ultimate responsibility for the business, its equipment, premises, and long-term direction.", "plain_english": "The studio owner owns the recording studio and its gear. They take the money risk and make the big decisions. They may also run it or hire others to.", "purpose_function": "It is the role that provides and owns the facility, carrying the investment and business risk that makes a professional studio available to clients.", "practical_application": "The owner decides on major equipment purchases, sets studio rates, and may hire a studio manager to handle daily operations.", "category": "Studio Roles", "related_terms": ["Studio manager", "Studio technician", "Studio intern", "Session", "Facility"], "common_mistakes": ["Assuming the owner runs every session; many owners hire staff and step back from daily engineering", "Confusing ownership (financial and legal) with management (day-to-day operations)"], "scenario_contexts": ["An owner investing in a new console and treating the room acoustically", "A studio owner hiring a manager and engineers to run the business day to day"]}, "194a0b53-0cf6-4bd0-a308-ee14553551e7": {"definition": "A technical staff member at a recording studio responsible for installing, maintaining, calibrating, and repairing the studio's equipment and infrastructure — consoles, outboard, cabling, patchbays, and computers — so all systems stay reliable and session-ready.", "plain_english": "A studio technician keeps the studio's gear working. They install, test, and fix equipment. Their job means sessions do not stall on faulty kit.", "purpose_function": "It exists to keep the technical systems reliable and calibrated, so engineers can record without downtime from faults or misaligned gear.", "practical_application": "The technician traces a dead patchbay point, recalibrates converters, and services the console before an important session.", "category": "Studio Roles", "related_terms": ["Studio manager", "Studio intern", "Patchbay", "Calibration", "Outboard"], "common_mistakes": ["UNSAFE: Working inside mains-powered equipment without first isolating and locking out the supply and verifying it is dead", "Confusing the technician (maintenance and repair) with the recording engineer (running sessions)"], "scenario_contexts": ["Diagnosing an intermittent fault in a console channel before a session", "Recalibrating converters or tape machines as part of routine studio maintenance"]}, "5f1a473d-10b8-4158-ae61-f24e908c155b": {"definition": "The practice of renting in equipment from another rental company to fulfil a job when a company's own stock is insufficient, already committed, or unavailable; also the item so hired. Also called cross-hire.", "plain_english": "Subhire means renting gear from another company to finish a job. You do it when your own stock runs short. The extra kit is passed on to your client.", "purpose_function": "It lets a supplier take on jobs larger than its own stock, covering shortfalls or specialist gear without buying equipment it rarely needs.", "practical_application": "When a booking needs more line-array boxes than are in stock, the rental company subhires the extra cabinets from another supplier.", "category": "Rental Logistics", "related_terms": ["Rental", "Cross-hire", "Dry hire", "Rider", "Equipment list"], "common_mistakes": ["Failing to check subhired gear on arrival, so faults or wrong items are only found at the venue", "Not tracking subhire costs and returns, leading to lost gear or disputed charges with the other company"], "scenario_contexts": ["Subhiring extra microphones and stands to cover a large festival rider", "Cross-hiring a specialist console the company does not own for a one-off show"]}, "d4266385-2b0a-4077-9787-664be15afbb0": {"definition": "Formal agreement from the artist, production, or their representative to accept a piece of equipment different from the one specified on the technical rider, granted when the exact specified item cannot be supplied.", "plain_english": "It is a yes from the touring party to swap a listed piece of gear for a different one. They agree before the show.", "purpose_function": "It lets a show proceed when the exact specified gear is unavailable, while keeping the touring party in control of what replaces it.", "practical_application": "When a specified console model is out of stock, the provider proposes an alternative and waits for the tour's substitution approval before setting it up.", "category": "Production Logistics", "related_terms": ["Technical rider", "Advancing", "Supplemental equipment", "Production manager", "Backline"], "common_mistakes": ["Swapping in a substitute before the touring party approves it, then having to redo the setup when the change is rejected", "Treating a substitution as equivalent without checking that the alternative meets the rider's specification and channel count"], "scenario_contexts": ["A rental house seeking substitution approval when it cannot source the exact microphone model listed on the rider", "A production manager granting substitution approval for an alternative wireless system on a one-off festival date"]}, "d6d1db86-f2c7-44d7-82c6-4eb34401cd72": {"definition": "Additional equipment supplied beyond the core specification or standard package — such as spares, venue-specific additions, or extra devices requested for a particular performance — provided on top of the items already listed on the rider or contract.", "plain_english": "It is extra gear added on top of the main setup. Crews bring it as spares or to meet a special need.", "purpose_function": "It covers needs the standard package does not, and provides backups, so the crew can handle special requirements or replace failed gear.", "practical_application": "For an outdoor date, a provider adds supplemental equipment such as weather covers, extra subwoofers, and spare cabling to the base package.", "category": "Production Logistics", "related_terms": ["Technical rider", "Substitution approval", "Backline", "Advancing", "Load-in"], "common_mistakes": ["Assuming supplemental equipment is always free; extra items usually add cost and must be agreed in advance", "Failing to list supplemental items on the patch or input/output paperwork, so they are missed during setup"], "scenario_contexts": ["A provider adding extra monitor wedges as supplemental equipment for a large group of performers", "A tour requesting supplemental equipment such as a spare console for a high-profile broadcast date"]}, "9350103c-7161-43a6-8ea6-60b8338ea48b": {"definition": "A versatile crew member not assigned to one fixed department or role, who covers wherever needed — filling in for absent technicians and assisting audio, lighting, video, or staging as the schedule demands.", "plain_english": "A swing tech is a crew member who fills in wherever help is needed. They can cover many jobs, not just one.", "purpose_function": "It gives a production flexible labour, so gaps from illness, breaks, or busy periods are covered without a full extra crew for every department.", "practical_application": "When the lighting crew falls behind at load-in, the swing tech joins them, then moves to help audio coil cables at load-out.", "category": "Crew Roles", "related_terms": ["Local crew", "Stagehand", "Department head", "Load-in", "Load-out"], "common_mistakes": ["Thinking a swing tech is unskilled; the role usually needs broad competence across several departments", "Assuming a swing covers only one department; they float to wherever the day's schedule needs them"], "scenario_contexts": ["A swing tech covering a monitor engineer's break during soundcheck", "A production hiring one swing tech to float between audio, lighting, and video during a busy load-in"]}, "728c7652-7718-4e1d-85a1-66e3fa7018a4": {"definition": "The process of physically assembling and interconnecting a sound (or lighting) system on site — rigging or stacking loudspeakers, running power and signal cabling, and connecting amplifiers, processing, and consoles — to bring the specified system from transport cases to a powered, functioning state.", "plain_english": "System build is putting the whole sound rig together on site. Crews stack the speakers and connect all the cables.", "purpose_function": "It turns a packed-up equipment package into a working, connected system, forming the setup stage before tuning, line checks, and the show.", "practical_application": "During load-in, the audio crew starts the system build by flying the line arrays and running power and signal to the amplifier racks.", "category": "System Setup", "related_terms": ["Load-in", "Line array", "Amplifier rack", "System engineer", "Line check"], "common_mistakes": ["UNSAFE: Rigging or flying loudspeakers during the system build without verifying rigging hardware and rated load limits, risking a dropped array", "Powering the system before the build and connections are checked, which can send damaging signal or noise through the rig"], "scenario_contexts": ["A PA crew completing the system build before the system engineer tunes the room", "A lighting crew running the system build of trusses, fixtures, and data lines at load-in"]}, "1d849398-c090-42b3-8bfb-9d6f7452cd00": {"definition": "The audio crew member responsible for the loudspeaker system itself — specifying, deploying, aligning, and maintaining the PA — who plans coverage, sets amplifier and processor parameters, and tunes the system to the room so the front-of-house engineer can mix on a predictable, even platform.", "plain_english": "The system engineer sets up and tunes the main speaker system. They make the sound even across the whole audience.", "purpose_function": "It exists to make the loudspeaker system deliver consistent, accurate coverage everywhere, giving the front-of-house engineer a reliable starting point to mix on.", "practical_application": "After the system build, the system engineer uses measurement software and a microphone to align the arrays and tune the room before soundcheck.", "category": "Crew Roles", "related_terms": ["Front of house engineer", "System build", "Line array", "Systems technician", "Measurement microphone"], "common_mistakes": ["Confusing the system engineer with the front-of-house engineer; one tunes and maintains the PA, the other mixes the show", "UNSAFE: Setting system gain or limiters recklessly high, which can damage drivers and expose crew and audience to unsafe sound levels"], "scenario_contexts": ["A system engineer flying and aligning line arrays, then tuning the room with dual-channel FFT measurement", "A system engineer walking the venue during soundcheck to check coverage and correct problem seats"]}, "1194b4da-2b59-40db-bf5b-eecd2271a25b": {"definition": "A control that silences the entire sound system at once, muting all outputs (or a master mute group) from the console or processor so no signal reaches the loudspeakers, used to stop all sound instantly without altering individual channel settings.", "plain_english": "A system mute silences the whole sound system at once. It is like one big off switch for all the speakers.", "purpose_function": "It gives one fast, reversible way to kill all output — for emergencies, feedback, or safe power-up and power-down — without touching each channel.", "practical_application": "Before powering amplifiers up or down, the engineer engages the system mute so start-up thumps do not reach the loudspeakers.", "category": "System Operations", "related_terms": ["Mute", "Mute group", "Master fader", "Amplifier rack", "Line check"], "common_mistakes": ["Forgetting the system mute is engaged and troubleshooting a silent PA that is simply muted", "Relying on a system mute instead of a proper power sequence; muting does not replace correctly powering amplifiers up and down"], "scenario_contexts": ["Engaging the system mute during a fire alarm so the PA is instantly silent", "Using the system mute while patching so accidental signal does not blast the room"]}, "c193efa0-a868-46ea-9ebe-6cd48e9292c0": {"definition": "An audio crew member responsible for building, cabling, and maintaining the loudspeaker system on site — deploying and connecting speakers, amplifiers, and processing, and assisting the system engineer with alignment and troubleshooting throughout setup and the show.", "plain_english": "A systems technician builds and looks after the main speaker system. They set up the speakers, amps, and cables, and fix faults.", "purpose_function": "It provides the hands-on work of assembling and maintaining the PA, so the system is deployed correctly and stays working during the performance.", "practical_application": "During load-in the systems technician stacks the subwoofers, connects the amplifier racks, and checks each loudspeaker before tuning begins.", "category": "Crew Roles", "related_terms": ["System engineer", "System build", "Amplifier rack", "Line array", "Front of house engineer"], "common_mistakes": ["Confusing the systems technician with the front-of-house engineer; the technician builds and maintains the PA rather than mixing the show", "UNSAFE: Stacking or flying loudspeakers without checking rigging and rated load limits, risking a fall or dropped speaker"], "scenario_contexts": ["A systems technician cabling amplifier racks and testing each loudspeaker during load-in", "A systems technician tracing and fixing a dead loudspeaker circuit during the show"]}, "1283c964-e9a1-4147-9903-849bf8beffbf": {"definition": "A junior audio crew member who operates the recording or playback machines during a session or show, setting up, monitoring, and logging record and playback passes under the direction of the lead engineer. Historically the entry-level studio role was responsible for the tape machine; the title persists for the person running multitrack capture, virtual-soundcheck playback, or show archiving on modern digital systems.", "plain_english": "The crew member who runs the recording gear. They start and stop the recorder, watch the levels, and keep track of each take.", "purpose_function": "It frees the lead engineer to focus on the mix by handing recording and playback duties to a dedicated operator, and it trains newcomers in signal flow and session discipline.", "practical_application": "On a live tour, the tape operator captures every show to a multitrack drive so the band can review mixes or run a virtual soundcheck the next day.", "category": "Crew Roles", "related_terms": ["Front-of-house engineer", "Assistant engineer", "Multitrack recording", "Virtual soundcheck", "Pro Tools operator"], "common_mistakes": ["Forgetting to arm tracks or press record, so a take or a whole show is lost.", "Mislabeling or failing to log takes, which makes files hard to find later.", "Assuming the role is only historical; digital multitrack capture still needs a dedicated operator."], "scenario_contexts": ["Capturing a concert to a multitrack drive for later mixing.", "Running playback for a virtual soundcheck before the band arrives.", "Logging and backing up session files after a studio tracking date."]}, "b556fc1c-e47d-46f7-b929-f22eba4c6997": {"definition": "The dismantling of a production's equipment after a performance: striking the stage, coiling cables, and packing gear into road cases in preparation for load-out and transport. It is the reverse of the build or setup and is largely synonymous with 'strike' and the load-out phase.", "plain_english": "Taking everything apart after the show. The crew packs the gear into cases so it can be loaded onto the truck.", "purpose_function": "It returns all equipment to its cases quickly and safely so the show can leave the venue on schedule and gear arrives undamaged at the next stop.", "practical_application": "As soon as the audience clears, the crew begins tear-down, coiling cables and casing consoles so the trucks can be packed and rolled to the next city.", "category": "Load-in / Load-out", "related_terms": ["Strike", "Load-out", "Load-in", "Road case", "System build"], "common_mistakes": ["Rushing tear-down and skipping cable coiling or case labeling, which causes damage or lost gear.", "UNSAFE: Starting overhead rigging tear-down before the area below is cleared of crew, risking falling objects.", "Confusing tear-down of the touring rig with striking the venue's own installed systems."], "scenario_contexts": ["Breaking down a festival stage at the end of the night.", "Packing a touring PA into cases immediately after the encore.", "Reversing a corporate AV build once a conference session ends."]}, "1fe88c5b-6bfa-455a-a2ae-8410c738a905": {"definition": "A production role responsible for planning, budgeting, and coordinating the technical elements of a live event or broadcast (audio, video, lighting, staging, and crew), translating the creative producer's or director's vision into a deliverable technical plan and overseeing its execution on site.", "plain_english": "The person who plans and runs the technical side of an event. They make sure the sound, lights, video, and crew all come together on show day.", "purpose_function": "It provides a single point of technical ownership that bridges the creative team and the crew, so technical needs are budgeted, scheduled, and delivered without gaps.", "practical_application": "For a corporate keynote, the technical producer builds the equipment list and schedule, hires the crew, and directs the technical calls during the show.", "category": "Crew Roles", "related_terms": ["Production manager", "Technical director", "System engineer", "Stage manager", "Production supervisor"], "common_mistakes": ["Confusing the technical producer with the creative producer, who owns content rather than technical delivery.", "Assuming the role only plans; the technical producer also supervises execution during the event.", "Overlooking budgeting and scheduling as core parts of the role."], "scenario_contexts": ["Planning the audio, video, and lighting package for a conference or product launch.", "Coordinating crew and vendors for a live-streamed event.", "Overseeing technical setup and show calls for a televised awards show."]}, "8a5086dc-ca54-4447-9aca-1b7fff86f68a": {"definition": "Informal crew names for the mixing console: the central control surface where input signals are routed, level-balanced, processed with tone and dynamics, and combined into the output mixes. 'Board' is common North American usage and 'desk' the British equivalent for the same device.", "plain_english": "The mixing console. It is the big control surface with faders and knobs where the engineer blends all the sounds together.", "purpose_function": "It gives the engineer one place to control level, tone, routing, and effects for every source, so many inputs can be balanced into the mixes a show needs.", "practical_application": "A front-of-house engineer runs the board at the back of the room, riding faders and shaping each channel throughout the performance.", "category": "Console", "related_terms": ["Mixing console", "Front-of-house engineer", "Channel", "Fader", "Console setup"], "common_mistakes": ["Assuming 'board' and 'desk' are different devices; they are two names for the mixing console.", "Confusing the audio board with the lighting or video console.", "UNSAFE: Making patch or power changes at the board without muting outputs, which can send a loud transient into the PA and damage speakers or hearing."], "scenario_contexts": ["An engineer setting up channels at the board before soundcheck.", "A monitor engineer building mixes on a separate board at the side of the stage.", "A crew member asked to power up the board during system build."]}, "d397f0f1-0d05-4716-a3b1-007a62228787": {"definition": "In theatre, the orchestra pit: a lowered area immediately in front of or partly beneath the stage where musicians perform below the audience's direct sightline. In concert touring, 'the pit' also denotes the barricaded zone between the stage front and the front-of-house barrier, occupied by security, photographers, and crew.", "plain_english": "A sunken space in front of the stage. In theatre it holds the musicians. At concerts it is the fenced area where security and photographers stand.", "purpose_function": "It keeps musicians (theatre) or security and media (concerts) close to the stage front while separating them from the audience and preserving sightlines and safety.", "practical_application": "At a concert, crew build the barricade to form the pit, where security face the crowd and photographers shoot the first few songs.", "category": "Stage Geography", "related_terms": ["Barricade", "Front-of-house", "Downstage", "Orchestra pit", "Stage"], "common_mistakes": ["Assuming 'the pit' always means the orchestra pit; in touring it usually means the barricade area.", "UNSAFE: Overcrowding the pit or blocking its exit gaps, which creates a crush and escape hazard at the barrier.", "Confusing the security and photo pit with the general-admission floor behind the barrier."], "scenario_contexts": ["Musicians tuning in the orchestra pit before a musical begins.", "Security taking positions in the pit as doors open at a concert.", "Photographers entering the pit to shoot the first three songs."]}, "38f2bf52-0cf2-44d1-9ce4-71548e153cdb": {"definition": "A road (flight) case or portable chest used to store, organise, and transport a crew member's or department's hand tools, hardware, and small consumables between venues on a tour or production.", "plain_english": "A tool case is a strong box that holds a crew's tools. It keeps them tidy and safe while travelling from show to show.", "purpose_function": "It keeps tools together, protected, and easy to find, so crew can quickly build and service gear during load-in, the show, and load-out.", "practical_application": "A technician pulls the tool case during load-in to build and fix rigging, cabling, and backline, then restocks and repacks it for the next city.", "category": "Cases & Storage", "related_terms": ["Flight case", "Road case", "Load-in", "Backline", "Consumables"], "common_mistakes": ["Leaving tools loose in the case so they are damaged in transit or hard to find under pressure", "Not restocking consumables like tape, batteries, and cable ties before the next show", "Sharing one tool case without returning tools, so items go missing on the road"], "scenario_contexts": ["A technician pulling the tool case during load-in to build the rig", "Inventorying and repacking the tool case before load-out"]}, "d76c49b4-f621-43b7-bf0d-e29e7c171416": {"definition": "In a live-sound loudspeaker system, the tops are the main mid-high or full-range enclosures that reproduce the upper frequency range, mounted on stands, flown, or stacked above the subwoofers; the term distinguishes them from the 'subs' that handle low bass.", "plain_english": "In a PA system, the tops are the main speakers that play the mid and high sounds. They sit above the subwoofers, which handle the deep bass.", "purpose_function": "They cover the mid and high frequencies that carry vocals and most instruments, working with the subs to give full-range coverage across the audience.", "practical_application": "A crew flies or pole-mounts the tops above the subs, then sets a crossover so each cabinet handles only its part of the frequency range.", "category": "Loudspeakers", "related_terms": ["Subs", "Crossover", "Line array", "PA system", "Monitor wedge"], "common_mistakes": ["Confusing tops with stage monitors; tops face the audience while monitors face the performers", "Running the tops full range while using subs instead of setting a crossover, which muddies the low end"], "scenario_contexts": ["Pole-mounting the tops on top of the subs for a small club gig", "Flying the tops as a line array above the stage for a large concert"]}, "72f447b7-377c-42e4-a20a-fac5d926b518": {"definition": "The tour manager is the senior touring staff member responsible for the day-to-day running of a concert tour, coordinating travel, accommodation, schedules, budgets, and show settlements and acting as the main link between the artist, crew, promoters, and venues so each show happens on time and on budget.", "plain_english": "The tour manager runs the daily life of a tour. They handle travel, hotels, schedules, and money. They keep the artist, crew, and venues working together.", "purpose_function": "It gives the tour a single leader who organises logistics and finances, so the artist and crew can focus on performing and running the show.", "practical_application": "The tour manager sets the day's schedule, advances upcoming shows with venues, handles the post-show settlement, and solves problems on the road.", "category": "Crew role", "related_terms": ["Production manager", "Tour accountant", "Settlement", "Advance", "Promoter", "Touring crew"], "common_mistakes": ["Confusing the tour manager, who runs logistics and money, with the production manager, who runs the technical show", "Assuming the tour manager makes creative or musical decisions, when the role is organisational and administrative"], "scenario_contexts": ["Advancing the next city's show details with the venue and promoter", "Running the post-show settlement with the promoter", "Coordinating the crew's travel and hotels between cities"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"3541eec4-3b93-4e28-bd8e-51b2157de0c1": {"definition": "The touring crew is the team of technicians and staff who travel with an artist or production from venue to venue, building, operating, maintaining, and striking the show's audio, lighting, video, staging, and backline at each stop.", "plain_english": "The touring crew is the team that travels with a show. They set up, run, and pack down the gear in every city.", "purpose_function": "It provides a consistent, skilled team that reproduces the same production reliably at each venue, rather than relying on different local crews everywhere.", "practical_application": "The touring crew loads in each day, builds and line-checks their department's systems, runs the show, then strikes and loads out for the next city.", "category": "Crew role", "related_terms": ["Local crew", "Tour manager", "Production manager", "Load-in", "Touring front-of-house engineer"], "common_mistakes": ["Confusing the touring crew, who travel with the show, with the local crew hired at each venue", "Assuming every role travels; some departments use local crew to save cost"], "scenario_contexts": ["A touring crew rebuilding the identical show in a new city each day", "Touring crew directing local hands during load-in"]}, "5aed5155-69fd-4c88-9e22-fed2ad546d94": {"definition": "The touring front-of-house engineer is the audio engineer who travels with an artist and mixes the main sound heard by the audience from the front-of-house position, tuning the system to each venue so the show's mix stays consistent across different rooms and PA systems.", "plain_english": "This is the sound engineer who travels with the band. They mix the sound the audience hears, from a desk out in the crowd.", "purpose_function": "It ensures the artist's audience mix sounds consistent every night, because the same engineer who knows the show tunes it to each new room and PA.", "practical_application": "Each day the touring FOH engineer soundchecks, tunes the system to the room, then mixes the performance from the front-of-house console during the show.", "category": "Crew role", "related_terms": ["Front of house", "Monitor engineer", "System tech", "Sound check", "Touring crew", "PA system"], "common_mistakes": ["Confusing the front-of-house engineer, who mixes for the audience, with the monitor engineer, who mixes for the performers", "UNSAFE: Mixing at excessive levels night after night without hearing protection or monitoring sound-pressure level, risking permanent hearing damage to the engineer and audience"], "scenario_contexts": ["Tuning the PA to a new room before each show on tour", "Mixing the audience sound from the front-of-house console during the performance", "Recreating a consistent show mix across venues with different PA systems"]}, "f995862f-5103-4776-a8e5-97853ce28899": {"definition": "A touring package is the self-contained set of production equipment — typically the sound, lighting, video, and staging systems — assembled and carried by a tour so the show can be reproduced consistently at each venue, independent of what any individual house provides.", "plain_english": "A touring package is the full set of gear a show carries with it. It lets the tour put on the same production in almost any venue.", "purpose_function": "It gives a tour a known, consistent rig it controls, so the production does not depend on the varying equipment installed at each venue.", "practical_application": "A production manager specs a touring package of PA, consoles, lighting, and staging that fits the trucks and can be rebuilt the same way in every city.", "category": "Production Equipment", "related_terms": ["Backline", "PA system", "Production manager", "Truck load", "Load-in", "Touring crew"], "common_mistakes": ["Confusing the touring package, which the tour carries, with the house system installed at the venue", "Speccing a package too large for the booked trucks or venues, driving up transport cost and load times"], "scenario_contexts": ["Speccing a touring package sized to fit the tour's trucks and stages", "Carrying a full touring package so a festival slot does not rely on house gear"]}, "d4f55e0a-9902-4fbf-b125-228d49603513": {"definition": "A truck call is the scheduled time at which crew must report to load or unload the tour's trucks, marking the start of load-in or load-out; it is one of the fixed times listed on the day's schedule or day sheet.", "plain_english": "A truck call is the time the crew must arrive to load or unload the trucks. It is written on the day's schedule.", "purpose_function": "It sets a clear start time for moving gear, so enough crew are present together to load or unload the trucks safely and on schedule.", "practical_application": "The day sheet lists a truck call time; crew arrive then to push cases off the truck and start building the show.", "category": "Scheduling", "related_terms": ["Load-in", "Load-out", "Day sheet", "Call time", "Truck load", "Touring crew"], "common_mistakes": ["Confusing the truck call with doors or downbeat; it is the crew's load time, not a show time", "Arriving without the agreed crew count, so unloading runs late and delays the build", "UNSAFE: Rushing a truck call by moving heavy cases without safe lifting technique, ramps, or enough hands, risking crush and back injury"], "scenario_contexts": ["An early-morning truck call to unload before a one-day festival build", "A late-night truck call to load out after the show"]}, "a0c8fc1e-409b-44ba-8005-80b420a76a96": {"definition": "A truck load is the quantity of equipment that fills one transport truck, used to size a production (for example, 'a two-truck show'); the term also refers to the packed, secured arrangement of cases within a truck for safe and efficient transport.", "plain_english": "A truck load is how much gear fills one truck. Crews also use it to describe how the cases are packed inside.", "purpose_function": "It measures a production's gear in whole trucks, which helps plan transport, crew, and load times, and it describes how cases are packed tightly and safely.", "practical_application": "A production manager works out how many truck loads a show needs, then the crew packs each truck in a set order so it is full, balanced, and secured.", "category": "Transport", "related_terms": ["Truck call", "Load-in", "Load-out", "Touring package", "Flight case"], "common_mistakes": ["Confusing a truck load, a full truck of gear, with the truck call, the time crew report", "Packing a truck loosely so cases shift and gear is damaged in transit", "UNSAFE: Loading a truck unevenly or beyond its rated capacity so it exceeds axle limits or shifts in transit; stay within rated load and secure the cargo"], "scenario_contexts": ["Calculating how many truck loads a tour's gear will fill", "Packing a truck load in order so it is full, balanced, and secured"]}, "a91f1408-8b3a-4846-b635-372fa723adda": {"definition": "The planned arrangement of road cases, rolling stock, and gear inside a tour truck or trailer, and the act of loading them in that order. A good truck pack uses the available space efficiently and loads in reverse of the unload sequence, so the first-needed cases come off first.", "plain_english": "A truck pack is the plan for how all the cases fit inside the tour truck. Crews load them in a set order so the gear needed first comes off first.", "purpose_function": "It ensures the equipment fits securely in the available space and comes off in the order the crew needs, saving time and preventing damage in transit.", "practical_application": "A crew chief directs the truck pack at load-out, telling loaders which cases go on first and how each stack is arranged.", "category": "Load-in / Load-out", "related_terms": ["Truck unload", "Load-out", "Load-in", "Road case", "Crew chief"], "common_mistakes": ["Packing cases in the wrong order, so first-needed gear is buried at the nose of the truck", "Leaving gaps that let cases shift and get damaged during transport", "UNSAFE: stacking heavy cases high or unsecured so they can topple onto crew during unload"], "scenario_contexts": ["A crew chief planning the truck pack so the PA cases unload first at the next venue", "Loaders following a truck pack diagram to fit a full production into one trailer"]}, "53d70793-820b-4abc-b79c-52d39438ebd2": {"definition": "The load-in task of removing cases and equipment from the tour truck and moving them to their staging or setup positions in the venue. It is normally the first physical step of a load-in.", "plain_english": "Truck unload is taking all the gear out of the tour truck at the venue. It is usually the first job of the day at load-in.", "purpose_function": "It gets the production's equipment off the truck and into the building so each department can begin building its systems.", "practical_application": "Local crew and touring loaders form a line to unload the truck, rolling cases to marked staging areas sorted by department.", "category": "Load-in / Load-out", "related_terms": ["Load-in", "Truck pack", "Road case", "Local crew", "Staging area"], "common_mistakes": ["Dropping cases at random spots instead of the marked staging areas, causing confusion later", "UNSAFE: jumping down from the truck bed or dock edge instead of using steps or a ramp", "UNSAFE: lifting a heavy case alone rather than rolling it or using a team lift"], "scenario_contexts": ["A stagehand rolling amp racks off the truck to the stage-left staging area at load-in", "A crew chief assigning half the local crew to truck unload while the rest start the build"]}, "20c23138-b715-4019-b16f-de613656d6de": {"definition": "To remove a piece of equipment from its rack or rack case, typically by unbolting the front rack ears from the rails and sliding the unit out. It is the opposite of racking a device.", "plain_english": "To unrack means to take a piece of gear out of its rack. You unscrew it from the rails and slide it out.", "purpose_function": "It lets a technician pull a unit out for service, replacement, or transport separately from the rack.", "practical_application": "A tech may unrack a failed amplifier or processor to swap in a spare during a show day.", "category": "Road Cases", "related_terms": ["Rack", "Road case", "Rack ears", "Rack unit", "Amp rack"], "common_mistakes": ["Sliding a unit out without supporting its weight, so it drops once the rear clears the rails", "Forgetting to disconnect and label the cables before pulling the unit out", "UNSAFE: unracking a live device instead of powering it down and disconnecting mains first"], "scenario_contexts": ["A tech unracking a faulty power amp to install a spare between sets", "Unracking heavy units before a fly date to lighten cases for air freight"]}, "1e561720-0b41-4aff-9e2b-07571d2f8225": {"definition": "US is the standard stage-geography abbreviation for upstage, the area of the stage farthest from the audience. The term comes from historically raked stages that sloped upward toward the back, so moving upstage meant moving toward the higher, rear edge. It is used with DS (downstage), SL (stage left), and SR (stage right) as the reference terms crews use to place gear and describe positions from the performer's point of view.", "plain_english": "US is short for upstage, the part of the stage farthest from the crowd. The name comes from old stages that sloped up toward the back. Crews use US along with DS, SL, and SR to say where gear goes.", "purpose_function": "It gives the crew a short, shared word for the rear area of the stage, so gear placement and cues can be described quickly and without confusion.", "practical_application": "A stage plot may mark a drum riser or backline as US, telling the crew to set it toward the back of the stage.", "category": "Stage Geography", "related_terms": ["DS", "Stage left", "Stage right", "Stage plot", "Riser"], "common_mistakes": ["Reading US as toward the front, when upstage is actually the back, farthest from the audience", "Confusing stage directions with the audience's view; US, DS, SL, and SR are always from the performer's view facing the crowd", "Treating US as one exact spot rather than the whole rear zone of the stage"], "scenario_contexts": ["A stage plot marking the drum riser US center", "A stage manager telling crew to move the backline further US", "Setting a riser US and the guitar amps DS during load-in"]}, "4c0fa8b0-8671-416c-95dc-72ea80488014": {"definition": "A versatile crew role assigned to general support rather than one fixed department, covering whatever help a production needs — moving gear, running cables, spotting, or backing up a department head. On a touring or stage crew it functions as a flexible extra hand.", "plain_english": "A utility is a crew member who helps wherever needed instead of doing one set job. They move gear, run cables, and back up other crew.", "purpose_function": "It gives a production a flexible pair of hands to cover extra tasks and fill gaps that do not belong to a specific department.", "practical_application": "A crew chief may assign a utility to shadow the audio team at load-in, then move to help staging or wardrobe as needs shift.", "category": "Crew role", "related_terms": ["Crew chief", "Stagehand", "Local crew", "Runner", "A2"], "common_mistakes": ["Assuming a utility needs no skills, when the role often calls for broad cross-department knowledge", "Treating the utility as a fixed department member instead of a floating support role"], "scenario_contexts": ["A tour hiring one utility to float between audio, backline, and lighting as needed", "A utility running a spare cable to front of house when a channel fails mid-show"]}, "38789c96-e95f-4045-9a11-33d64503c686": {"definition": "A road case or box that holds general-purpose supplies and consumables shared across a production — items such as gaffer tape, cable ties, adapters, hand tools, batteries, and spare hardware. It is a common grab box rather than department-specific gear.", "plain_english": "A utility box is a road case full of general supplies. It holds things like tape, adapters, tools, and spare parts that any crew member can grab.", "purpose_function": "It keeps common consumables and small spares in one known place, so any crew member can find them fast during setup or a show.", "practical_application": "A stagehand grabs gaffer tape and a cable adapter from the utility box while dressing cables at load-in.", "category": "Road Cases", "related_terms": ["Road case", "Utility", "Gaffer tape", "Spares", "Work box"], "common_mistakes": ["Not restocking the utility box, so consumables run out partway through a tour", "Letting the box become a dumping ground, so nothing can be found quickly"], "scenario_contexts": ["A crew grabbing spare XLR adapters from the utility box during line check", "Restocking the utility box with tape and batteries at the start of a tour leg"]}, "a86e2907-9ccf-48b8-98eb-c807f8d49d57": {"definition": "A document, published by a venue or gathered by a touring production, that details a venue's technical and physical characteristics — stage dimensions, rigging points and load limits, available power, house PA and lighting, loading access, and crew provisions. It lets a production plan its setup before arrival.", "plain_english": "A venue specification is a document listing what a venue offers and its limits. It covers stage size, power, rigging, and load-in access, so a tour can plan ahead.", "purpose_function": "It gives touring crews the facts they need to plan the show and confirm the venue can safely support the production's gear and power demands.", "practical_application": "A production manager checks the venue specification to confirm rigging load limits and available power before advancing the show.", "category": "Specifications", "related_terms": ["Advance", "Production manager", "Rider", "Load-in", "Rigging points"], "common_mistakes": ["Relying on an outdated venue specification instead of confirming current details during the advance", "UNSAFE: assuming listed rigging or power figures without verifying them on site before loading points or connecting power"], "scenario_contexts": ["A production manager reviewing the venue specification during the advance to plan rigging", "Comparing the venue specification against the show's rider to spot missing power or access"]}, "47549700-91a2-43c3-9173-31a7fbe04ae2": {"definition": "The department on a touring or event production responsible for the video system — cameras and camera operators, the video director, LED walls and projection screens, media servers, and video signal routing — so that live and pre-recorded imagery reaches the audience displays and any broadcast feed.", "plain_english": "The video crew runs all the screens at a show. They handle the cameras, the big LED walls, and the video gear.", "purpose_function": "It plans, builds, and operates the imagery side of a production, giving the audience clear big-screen views and playback that support the performance.", "practical_application": "On show day the video crew rigs the LED wall, patches stage cameras to the switcher, and the video director cuts live shots to the screens.", "category": "Crew Roles", "related_terms": ["Front of house", "Lighting crew", "Media server", "Video director", "LED wall"], "common_mistakes": ["Assuming the video crew only operates cameras; they also run LED walls, projection, media servers, and video routing", "Confusing the video crew with the lighting crew, which handles fixtures and dimmers rather than imagery"], "scenario_contexts": ["A touring video crew rigging an upstage LED wall and patching stage cameras before doors", "A video director and camera operators cutting live close-ups to the screens during a concert"]}, "0eb5b5bd-7b91-4736-b56e-c9ddb1a485a3": {"definition": "A soundcheck performed by playing a multitrack recording of the band's inputs back through the console and PA in place of the live musicians, letting engineers set gains, EQ, and mixes without the artists on stage. Also called a virtual soundcheck.", "plain_english": "A virtual check plays a recording of the band through the mixing desk. Engineers can tune the sound without the musicians being there.", "purpose_function": "It lets the sound team refine mixes and system tuning when the band is unavailable, saving stage time and keeping musicians off the stage.", "practical_application": "An engineer records one show's multitracks, then plays them back the next day to dial in the console before the band arrives.", "category": "Audio Operations", "related_terms": ["Sound check", "Line check", "Multitrack recording", "Front of house", "Digital console"], "common_mistakes": ["Believing a virtual check can replace a live check of stage sources; microphones, DIs, and monitors still need a real line check", "Forgetting that playback bypasses the stage, so input gains and mic placement are not tested by the virtual check alone"], "scenario_contexts": ["A festival engineer using yesterday's multitracks to pre-tune the mix before the band arrives", "A monitor engineer building in-ear mixes from a virtual soundcheck on a day with no rehearsal"]}, "9e697498-6bb9-40b3-b546-916e45591fa3": {"definition": "A producer who specialises in capturing and shaping vocal performances — coaching the singer, selecting and comping takes, guiding phrasing and pitch, and directing the recorded sound — to deliver the strongest possible lead or backing vocal for a track.", "plain_english": "A vocal producer helps a singer give their best take. They guide the performance and pick the strongest parts to keep.", "purpose_function": "It focuses expert attention on the vocal, the most exposed part of most songs, so the lead voice is expressive, in tune, and well recorded.", "practical_application": "In a session the vocal producer runs the singer through takes, marks the best lines, and comps them into one strong lead vocal.", "category": "Production Roles", "related_terms": ["Producer", "Comping", "Pitch correction", "Take", "Tracking"], "common_mistakes": ["Confusing a vocal producer with the recording engineer; the producer guides the performance while the engineer runs the gear", "Thinking vocal production is only tuning, when take selection, coaching, and comping matter just as much"], "scenario_contexts": ["A vocal producer coaching a singer through several takes of a chorus in the studio", "A vocal producer comping the best phrases from many takes into a final lead vocal"]}, "30c0c02d-ece8-400b-9d30-b4ed106399ef": {"definition": "A dense, powerful, full-range body of sound built from many layered elements. In record production it names Phil Spector's technique of massed, overdubbed instruments and heavy reverb; in live sound it also names the Grateful Dead's 1974 large-scale behind-the-band PA, an early landmark in high-power concert sound.", "plain_english": "'Wall of sound' means a big, thick, powerful sound. It can be a studio recording style or a huge concert speaker system.", "purpose_function": "As a production style it fills a mix with rich, layered energy; as a PA design it aimed to deliver loud, clear sound to a large crowd from behind the band.", "practical_application": "An engineer might layer many tracks with reverb to chase a wall-of-sound texture, or study the Grateful Dead's system when learning large PA design.", "category": "Sound Concepts", "related_terms": ["Overdub", "Reverb", "Line array", "PA system", "Mix"], "common_mistakes": ["Using 'wall of sound' to mean simply 'too loud'; it describes density and layering, not just high volume", "Assuming it refers only to Phil Spector; it also names the Grateful Dead's landmark live PA system"], "scenario_contexts": ["A producer layering many overdubs and reverb to build a wall of sound in a mix", "A student studying the Grateful Dead's Wall of Sound as an early large-scale concert PA"]}, "7f1e68e3-a228-4f92-83bc-377b144bd960": {"definition": "A status call reporting that a stage, venue, or system is dark — not operating: powered down, blacked out, or with no performance running. In touring and theatre, 'dark' denotes a venue or production that is closed or not currently in show mode.", "plain_english": "'We are dark' means nothing is running right now. The stage or venue is off, closed, or not in show mode.", "purpose_function": "It gives the crew a quick, shared status that the stage or system is not live, so no one expects signal, light, or a performance until that changes.", "practical_application": "A crew chief may radio 'we are dark' to confirm the stage is powered down for work, or that the venue has no show that night.", "category": "Show Status", "related_terms": ["Dark", "Show ready", "Blackout", "Doors", "Power down"], "common_mistakes": ["Hearing 'dark' as only 'lights off', when it can mean the whole venue or production is not operating", "UNSAFE: assuming 'dark' means mains power is isolated; always verify and lock out before touching live circuits"], "scenario_contexts": ["A stage manager confirming the venue is dark tonight, with no performance scheduled", "A crew reporting 'we are dark' after powering down the stage for maintenance"]}, "cc07d5b5-946b-442e-be38-dba98d51e3f1": {"definition": "A comms confirmation that audio signal is present and passing correctly through the system — for example, that a source, feed, or channel is now producing sound where it previously was not — verified during checks or troubleshooting.", "plain_english": "'We have audio' means the sound is working now. Signal is passing through the system as it should.", "purpose_function": "It confirms to the crew that an audio path is live and working, closing out a check or a fault before the show depends on it.", "practical_application": "During a line check an engineer says 'we have audio' once a channel shows signal and is heard through the monitors or PA.", "category": "Audio Operations", "related_terms": ["Line check", "Sound check", "Signal", "Front of house", "Mute"], "common_mistakes": ["Reporting 'we have audio' from meter movement alone, without listening to confirm it is the correct source", "Assuming 'we have audio' means the level and quality are right, when it only confirms signal is present"], "scenario_contexts": ["An engineer confirming 'we have audio' after re-patching a dead channel", "A broadcast operator reporting 'we have audio' when the program feed starts passing sound"]}, "1302f2cc-1603-4872-b212-3153c3744c66": {"definition": "The maximum load a component, structure, vehicle, or lifting assembly is rated to bear safely, set by the relevant standard below the item's failure point by a design (safety) factor. In production it applies to rigging points and hardware, truss and staging, and transport vehicles.", "plain_english": "A weight limit is the most weight something can safely hold. It is set well below the breaking point to leave a safety margin.", "purpose_function": "It prevents overload failures — dropped rigging, collapsed structures, or overweight vehicles — by defining a safe ceiling that keeps loads far from the breaking point.", "practical_application": "Before flying a line array, a rigger checks that the total load stays within the rated weight limit of the point, hardware, and truss.", "category": "Rigging Safety", "related_terms": ["Working load limit", "Rigging point", "Truss", "Design factor", "Rigging"], "common_mistakes": ["UNSAFE: treating the working load limit as the breaking strength; the limit already includes a safety margin and must never be exceeded", "UNSAFE: adding only fixture weights and ignoring rigging hardware, cable, and dynamic (shock) loads when checking the limit", "Confusing a vehicle's payload with its gross vehicle weight rating (GVWR), which includes the weight of the truck itself"], "scenario_contexts": ["A rigger verifying a flown speaker array stays within the rated weight limit of each point", "A crew loading a truck so its axle and gross vehicle weight limits are not exceeded"]}, "86bc117d-5e25-427d-8efc-ea9568b3c35d": {"definition": "In the entertainment and events industry, a wet hire is the rental of equipment supplied together with a trained operator or crew to run it, as opposed to a dry hire, which supplies the equipment alone. Under a wet hire the rental company remains responsible for operating, and often maintaining, the gear for the duration of the booking.", "plain_english": "A wet hire means you rent the gear and the people to run it. The rental firm sends staff to operate the equipment. A dry hire gives you just the gear, with no crew.", "purpose_function": "It lets a client use equipment they cannot operate themselves, so the rental company provides skilled operators and takes on responsibility for running the gear correctly.", "practical_application": "A promoter books a wet hire of a PA system so the rental company also sends an engineer to set up, operate, and strike the rig.", "category": "Hire & Rental", "related_terms": ["Dry hire", "Backline", "Production manager", "Technical rider", "Load-in"], "common_mistakes": ["Confusing a wet hire with a dry hire, then finding no operator arrives with the equipment", "Assuming a wet hire covers every crew role, when the contract may supply only one operator", "Not agreeing who is liable for the gear during a wet hire, which matters if it is damaged"], "scenario_contexts": ["A festival booking a wet hire of a lighting rig so the supplier sends a technician to run it", "A corporate event choosing a wet hire because the client has no in-house AV crew"]}, "1973c24c-fe14-457e-986c-cb8bad2ddf2f": {"definition": "A wireless technician (RF technician) is the crew member responsible for the reliable operation of a production's radio-frequency equipment — wireless microphones, in-ear monitor (IEM) systems, and RF intercom — including frequency coordination, antenna placement, gain and battery management, and interference troubleshooting. The role plans a set of compatible, licence-compliant frequencies and monitors RF performance throughout the show.", "plain_english": "A wireless technician keeps radio mics and in-ear monitors working. They pick clear radio channels so signals do not clash. They set up antennas and swap batteries. During the show they watch for interference and fix it fast.", "purpose_function": "It puts one specialist in charge of all radio-frequency gear, so wireless mics and in-ears run on clean, legal, non-clashing frequencies without dropouts during a show.", "practical_application": "A wireless tech scans the local RF spectrum, coordinates frequencies in software such as Wireless Workbench, places and distributes antennas, and monitors signal and battery levels from a dedicated RF rack.", "category": "Crew Role", "related_terms": ["Frequency coordination", "In-ear monitor", "Wireless microphone", "Antenna distribution", "RF spectrum"], "common_mistakes": ["Confusing the wireless tech with the monitor engineer; the wireless tech manages the RF links, not the monitor mixes", "Assuming any unused frequency is safe, instead of coordinating to avoid intermodulation between transmitters", "Transmitting on frequencies reserved for licensed broadcast or public-safety users, which is illegal and risks interference and fines"], "scenario_contexts": ["Coordinating dozens of wireless mic and IEM channels for a festival with limited clean spectrum", "Troubleshooting a wireless mic dropout mid-show by checking antenna placement and RF levels", "Managing battery changes and frequency plans across a multi-band touring rig"]}, "5865371d-efb2-4388-9606-d60cd8bdb759": {"definition": "A workbox is a wheeled road (flight) case fitted out as a mobile workshop and storage unit, typically containing drawers, shelves, and a hinged or lift-off lid that doubles as a worktop, used by touring crew to transport and access tools, spares, consumables, and paperwork. Departments such as audio, lighting, and stage commonly each carry their own workbox.", "plain_english": "A workbox is a rolling road case built like a toolbox. It has drawers for tools, spares, and tape. The lid often opens out into a workbench. Each crew department usually has its own.", "purpose_function": "It keeps a department's tools and spares organised, protected, and mobile, giving crew a single rolling station to work from and store consumables through load-in, show, and load-out.", "practical_application": "A stage tech rolls the workbox to the work area, opens the lid as a bench, and pulls tape, tools, and spare connectors from its labelled drawers.", "category": "Cases & Transport", "related_terms": ["Road case", "Flight case", "Load-in", "Consumables", "Backline"], "common_mistakes": ["Confusing a workbox with a plain equipment road case; a workbox is set up as a tool and workshop station", "Leaving the workbox disorganised, so crew waste time hunting for tools during a fast turnaround", "UNSAFE: Rolling a heavy, tall workbox down a ramp or incline without control, so it can tip or run away and injure crew"], "scenario_contexts": ["An audio crew carrying a drawered workbox with spare cables, tools, and tape to every show", "Opening a workbox lid as a bench to repair a connector during load-in"]}, "12592229-0a35-470e-9925-b9aeccd21cc1": {"definition": "A Y cable (Y-cord) is a cable with a single connector at one end that splits into two connectors at the other, forming a Y shape, used either to split one signal to two destinations or to sum two sources into one input. In audio it appears as insert cables, output or headphone splitters, and channel combiners, and its safe use depends on whether the junction meets a low-impedance output or a high-impedance input.", "plain_english": "A Y cable splits into two ends, like the letter Y. It can send one signal to two places, or join two signals into one. A common use is a headphone splitter so two people listen at once.", "purpose_function": "It lets one connection feed two, or two feed one, without extra equipment, so a technician can split or combine signals quickly using a single passive cable.", "practical_application": "An engineer uses a Y cable to send one playback output to two devices, or as a console insert cable carrying send and return on one plug.", "category": "Cabling", "related_terms": ["Insert cable", "Splitter", "Balanced signal", "Impedance", "Multicore"], "common_mistakes": ["Using a Y cable to tie two outputs together into one input, which can load down or damage the source outputs; sum signals through a mixer instead", "Confusing a Y insert cable's tip-send and ring-return wiring with a stereo cable, so the insert does not work", "Assuming a Y cable adds isolation; it does not, so splitting one output to many inputs can drop level or add noise"], "scenario_contexts": ["Splitting a single headphone output so two people can monitor at once", "Wiring a console channel insert with a TRS Y cable for an outboard compressor", "Sending one playback source to two recorders with a Y splitter"]}, "a72dfd4c-f3f9-4d37-b92c-3e549625a2a3": {"definition": "An acoustic door is a heavy, gasketed door assembly engineered to block airborne sound between spaces, rated by its Sound Transmission Class (STC). It achieves isolation through a dense, often multi-layer core, perimeter compression seals, and an automatic drop seal or sealed threshold that closes the gap at the floor, so the installed assembly performs close to its rated STC.", "plain_english": "An acoustic door is a thick, tightly sealed door that keeps sound from passing through. Its heavy core and edge seals stop noise leaks. Studios and venues use it so a loud room and a quiet room do not disturb each other.", "purpose_function": "It exists to maintain sound isolation at a doorway, which is otherwise a weak point in a wall's rated performance. The heavy core and seals stop sound leaking through gaps and through the door panel itself.", "practical_application": "A technician checks that an acoustic door's perimeter seals and drop seal close fully, since even a small gap can wreck the isolation between a control room and a live room.", "category": "Building element", "related_terms": ["Sound Transmission Class (STC)", "Sound lock (vestibule)", "Isolation", "Gasket seal", "Fire door", "Control room"], "common_mistakes": ["Assuming any solid or fire-rated door gives good sound isolation, when only a sealed, STC-rated assembly does.", "Leaving the automatic drop seal misadjusted, so a floor gap leaks sound and lowers the effective STC.", "Propping the door open or ignoring worn gaskets, which destroys the isolation the door was installed to provide.", "UNSAFE: Blocking, wedging, or disabling an acoustic door that is also a rated fire or egress door, defeating its life-safety function."], "scenario_contexts": ["Separating a control room from a live room so monitoring is not contaminated by studio sound.", "Fitting a broadcast booth or voiceover room so outside noise stays out.", "Isolating a rehearsal room or club so amplified music does not disturb neighbours."]}, "693fbc71-bef4-4251-bc77-856d6d3538d0": {"definition": "The acting area is the portion of the stage or performance space within which the performers move and the action takes place, as distinct from the wings, backstage, and audience areas. In stage lighting and blocking practice it is often subdivided into a grid of smaller acting areas, each of which can be separately lit and referenced when planning movement.", "plain_english": "The acting area is the part of the stage where the actors actually perform. It does not include the hidden side and back areas. Lighting and staging plans often split it into a grid of smaller zones.", "purpose_function": "It defines the usable performance zone so directors can plan movement and designers can plan lighting and sightlines. Dividing it into smaller areas lets each zone be lit and controlled on its own.", "practical_application": "A lighting technician focuses instruments so each acting area is evenly covered, letting the operator light exactly where the action moves.", "category": "Performance space", "related_terms": ["Stage", "Proscenium", "Wings", "Sightline", "Blocking", "Apron"], "common_mistakes": ["Confusing the acting area with the whole stage, which also includes wings, crossovers, and backstage.", "Forgetting to light the edges where acting areas meet, leaving dark gaps as performers cross.", "Assuming the acting area is fixed, when its size and shape change with the set and staging."], "scenario_contexts": ["Planning a lighting plot so each acting area has even coverage.", "Directing blocking by referencing numbered acting areas onstage.", "Setting sightlines so every acting area is visible from the seats."]}, "e9ef6bbc-89b9-45b2-b745-afb7d7a9bd80": {"definition": "An aisle is a designated circulation path within a seating area that provides access to seats and forms part of the required means of egress. In assembly occupancies its width, slope, stepping, and connection to exits are governed by building and life-safety codes (such as the IBC egress provisions and NFPA 101), which set minimum widths and limit dead-end and travel distances so occupants can leave quickly in an emergency.", "plain_english": "An aisle is a walkway between or beside rows of seats. People use it to reach their seats and to leave the building. Safety codes set how wide aisles must be and keep them clear so crowds can exit fast.", "purpose_function": "It exists to let audiences reach their seats and, critically, to evacuate safely; aisle width and layout are sized to the number of people served. Keeping aisles clear preserves the building's rated exit capacity.", "practical_application": "A technician routes cables, cases, and gear so they never cross or narrow an aisle, keeping the full code-required egress path open during a show.", "category": "Circulation", "related_terms": ["Means of egress", "Exit", "Vomitory", "Cross-aisle", "Seating capacity", "Occupancy load"], "common_mistakes": ["UNSAFE: Running cables, road cases, or gear across an aisle, which creates a trip hazard and blocks a required exit path.", "UNSAFE: Adding chairs or standees in an aisle, exceeding the seating plan and violating egress capacity.", "Confusing an aisle within the seating with a cross-aisle or corridor, which have their own width rules.", "Assuming a wider aisle is optional, when its minimum width is set by the number of occupants served."], "scenario_contexts": ["Taping down and ramping any cable that must cross near an aisle to protect egress.", "Confirming aisle widths and clearances during a pre-show safety walk.", "Keeping aisles clear of equipment and standees during a sold-out event."]}, "e97bba9b-2dfd-406e-a631-b4aeeeada511": {"definition": "An amphitheater is a performance venue with tiered seating that rises around or in front of a central or frontal performance area; historically it was the free-standing Roman oval enclosing a central arena, while in modern usage it most often means an open-air venue with raked or bowl seating facing a stage. Its stepped seating provides sightlines, and outdoor forms rely on distance, rake, and sound reinforcement rather than enclosed-room acoustics.", "plain_english": "An amphitheater is a venue with rows of seats that climb upward around a central space. The Romans built oval stone ones for large crowds. Today the word usually means an open-air venue with sloped seats facing a stage.", "purpose_function": "The rising, stepped seating gives many people a clear view of the performance, and surrounding forms pack a large audience close to the action. Outdoor forms trade room acoustics for open air and sound reinforcement.", "practical_application": "At an outdoor amphitheater a sound crew designs coverage and delay speakers for a raked, uncovered audience, and plans for long throw distances and weather.", "category": "Venue type", "related_terms": ["Arena", "Auditorium", "Rake", "Sightline", "Bowl (seating)", "Delay tower"], "common_mistakes": ["Using 'amphitheater' only for the Roman oval, when today it usually means an open-air raked venue.", "Expecting indoor-style acoustics outdoors, where there is little reverberation and sound falls off with distance.", "UNSAFE: Planning egress and crowd flow for the fixed seat count only, ignoring code occupancy limits for lawn or standing areas."], "scenario_contexts": ["Designing a line-array and delay system for a large open-air amphitheater.", "Setting sightlines and seat rake for a steeply banked venue.", "Planning weather protection and crowd egress for an outdoor show."]}, "7c212368-7161-48f3-a661-90c77f1aca7a": {"definition": "An antiphonal position is a performance location deliberately separated in space from the main performing forces, so that a second group—an organ division, choir, or brass ensemble—can answer or alternate with the main body for a spatial, call-and-response effect. In pipe-organ practice the antiphonal division is typically installed remote from the main organ, often in a rear gallery or at the opposite end of the room.", "plain_english": "An antiphonal position is a spot for a second group of players, or an extra set of organ pipes. It is placed far from the main group. The two sides take turns or answer each other. This makes the music seem to move around the room.", "purpose_function": "It exists to create spatial contrast and call-and-response between separated ensembles, adding width and drama a single stage position cannot. Separation lets the audience hear music arrive from different directions.", "practical_application": "A sound or organ technician provides power, control, and sometimes reinforcement at an antiphonal position so a remote division or brass choir stays in time and balance with the main group.", "category": "Performance space", "related_terms": ["Antiphonal organ", "Gallery", "Choir loft", "Organ chamber", "Reverberation", "Stage position"], "common_mistakes": ["Treating an antiphonal position as just spare seating or storage, not a purpose-built performance location.", "Ignoring the sound delay caused by the distance, so the two groups drift out of time for the audience.", "Assuming it needs no services, when a remote position often needs power, cue, and monitor feeds."], "scenario_contexts": ["Placing a brass choir in a rear gallery to answer the orchestra during a large work.", "Installing or voicing an antiphonal organ division at the opposite end of a church.", "Coordinating timing between separated ensembles for a spatial effect."]}, "7be75c10-171f-4c3c-916d-41afe01c0487": {"definition": "An arena is a large venue built around a central performance floor with tiered seating surrounding it on all or most sides, giving very high audience capacity with in-the-round or near-in-the-round sightlines. The term also names the arena (in-the-round) stage format, in which the audience encircles the performance area.", "plain_english": "An arena is a big venue with a central floor and seats rising all around it. This puts a large crowd close to the action on every side. Concerts and sports both use arenas.", "purpose_function": "Surrounding the floor with seating maximises capacity and brings the whole audience near the performance. The all-around layout suits sports, large concerts, and in-the-round staging.", "practical_application": "For an arena concert a sound crew often flies a 360-degree or end-stage line-array rig and plans coverage and delays for seating that wraps around the floor.", "category": "Venue type", "related_terms": ["Amphitheater", "Auditorium", "In-the-round", "Bowl (seating)", "Vomitory", "Rigging grid"], "common_mistakes": ["Confusing the venue (arena building) with the arena stage format, where the audience is on all sides.", "Assuming end-stage coverage works for a full bowl, when wrap-around seating needs added fills and delays.", "UNSAFE: Overlooking rated rigging capacity and occupancy limits when hanging large arrays over a packed floor crowd."], "scenario_contexts": ["Designing a flown PA and delays for a wrap-around arena bowl.", "Rigging a center cluster for in-the-round staging.", "Planning crowd egress and rigging safety for a sold-out arena show."]}, "de90b4e7-4618-4a7c-94d1-5034ab9a74c5": {"definition": "An artist entrance (stage door) is a separate, access-controlled entrance to a venue reserved for performers, crew, and staff, kept apart from the public front-of-house entrances and leading toward dressing rooms, backstage, and technical areas. It provides privacy and security and separates artist and production circulation from the audience.", "plain_english": "The artist entrance, or stage door, is a private way in for performers and crew. It is kept separate from the doors the audience uses. It leads to the backstage, dressing rooms, and work areas.", "purpose_function": "It separates artist and crew movement from the public, giving security, privacy, and a clear path to backstage and dressing rooms. It also keeps production traffic out of front-of-house areas.", "practical_application": "Crew load in through or near the artist entrance and use it to reach the stage without crossing audience areas during a show.", "category": "Access", "related_terms": ["Stage door", "Backstage", "Dressing room", "Green room", "Loading dock", "Front of house"], "common_mistakes": ["Confusing the artist entrance with the public entrance or the loading dock, since each serves a different flow.", "Assuming it is unsecured, when access control at the stage door is a normal security measure.", "Routing audience or deliveries through the artist entrance, mixing flows it is meant to keep apart."], "scenario_contexts": ["Crew reaching the stage from the artist entrance without crossing the house.", "Managing performer arrivals and security at the stage door.", "Separating production traffic from the audience at load-in."]}, "f1324402-0f48-4000-a250-e67b0a6e82c7": {"definition": "The auditorium is the part of a theatre, concert hall, or venue that accommodates the audience—the seating area and the volume of space serving it, also called the house—as distinct from the stage and backstage. Its shape, seating rake, materials, and volume are primary determinants of sightlines and of room acoustics such as loudness, clarity, and reverberation.", "plain_english": "The auditorium is the part of a venue where the audience sits, also called the house. It does not include the stage or backstage. Its size and shape affect both the view and the sound the audience gets.", "purpose_function": "It houses the audience and, through its shape, size, and materials, largely sets sightlines and the acoustic experience of a performance. Good design balances capacity, viewing, and sound.", "practical_application": "A sound engineer places and aims the PA for even coverage across the whole auditorium and tunes the system to that room's acoustics.", "category": "Audience space", "related_terms": ["House (front of house)", "Stage", "Sightline", "Reverberation time", "Seating rake", "Proscenium"], "common_mistakes": ["Using 'auditorium' for the whole building, when it strictly means the audience area, the house.", "Ignoring how auditorium volume and surfaces set reverberation when planning sound.", "Assuming even coverage from one speaker position, when balconies and rake need added fills."], "scenario_contexts": ["Aiming and tuning a PA for even coverage across a raked auditorium.", "Assessing a hall's reverberation time before a classical concert.", "Checking sightlines and seat count when planning an event."]}, "6066f657-05c5-4678-a352-ff641fd7a441": {"definition": "Backline storage is a dedicated area or room at a venue for holding backline—the on-stage instruments and amplification such as guitar and bass amplifiers, drum kits, and keyboards—when it is not set on stage. It keeps this bulky, valuable gear secure and organised, and clear of circulation and egress paths, between load-in, changeovers, and load-out.", "plain_english": "Backline is the gear a band plays on stage, like amps, drums, and keyboards. Backline storage is a room to keep that gear safe when it is off the stage. It stays out of the way between setup, band changes, and pack-out.", "purpose_function": "It gives a secure, organised place for heavy stage gear so it does not clutter the stage, wings, or exit paths. This speeds changeovers and protects valuable equipment.", "practical_application": "During a multi-band show, crew stage each act's gear from backline storage and return it there at the changeover to keep the stage and aisles clear.", "category": "Support space", "related_terms": ["Backline", "Load-in", "Changeover", "Loading dock", "Stage", "Wings"], "common_mistakes": ["Confusing backline (the band's stage gear) with the front-of-house PA and monitors provided by the venue.", "UNSAFE: Storing backline in corridors, wings, or aisles, which blocks egress and creates trip hazards.", "Leaving heavy cases unsecured or badly stacked, risking damage or injury."], "scenario_contexts": ["Staging each band's gear from backline storage during festival changeovers.", "Securing valuable amps and instruments between soundcheck and showtime.", "Keeping the stage and exit routes clear by returning gear to storage."]}, "e0be8a29-2bab-43d6-bd95-9d11154e74de": {"definition": "A raised, often modular or demountable, section of stage or floor built to elevate a band, orchestra, or ensemble above the surrounding level, improving sightlines, projection, and separation of the performers from the audience or dance floor.", "plain_english": "A band platform is a raised stage section that lifts musicians up. It helps the crowd see and hear the band better.", "purpose_function": "It raises performers so audiences can see and hear them clearly, and it groups the band into one defined, often portable, performance area.", "practical_application": "Crews assemble modular platform sections to set the stage height, then run power and audio to the elevated band before soundcheck.", "category": "Stage Structures", "related_terms": ["Riser", "Stage", "Bandstand", "Sightlines", "Deck"], "common_mistakes": ["Confusing a band platform with a fixed stage; it is often a portable, demountable structure", "UNSAFE: Loading a modular platform beyond its rated capacity, or leaving unguarded edges and drops, creating a collapse or fall hazard"], "scenario_contexts": ["Building modular risers into a band platform in a hotel ballroom for a function band", "Setting a drum and keyboard platform to raise a band above a dance floor"]}, "9ff09364-0d24-41fd-90e3-f9dff142d380": {"definition": "An offstage route located in the basement or under-stage level that lets performers and crew pass from one side of the stage to the other unseen by the audience, used when no crossover exists behind or above the acting area.", "plain_english": "A basement crossover is a path under the stage. Actors use it to cross to the other side without being seen.", "purpose_function": "It gives a hidden connection between stage-left and stage-right when the set or building blocks a direct backstage route, keeping entrances and exits concealed.", "practical_application": "During a show, an actor exits one wing, takes the stairs to the basement crossover, and re-enters from the opposite wing on cue.", "category": "Backstage Circulation", "related_terms": ["Crossover", "Understage", "Trap room", "Wings", "Backstage"], "common_mistakes": ["Assuming every stage has an upstage crossover; sometimes the only concealed route is through the basement", "UNSAFE: Leaving the basement crossover unlit or cluttered, creating trip and fall hazards for performers moving in the dark"], "scenario_contexts": ["An actor using the under-stage basement crossover during a scene with a full-width set", "Running comms and a running light along a basement crossover so crew can move safely"]}, "49464e8b-f1c6-4f09-b887-31fb5be4044d": {"definition": "A simple, flexible performance space consisting of a single room, usually with matte-black walls, floor, and ceiling, an open floor plan, and no fixed stage or seating, so the stage-to-audience relationship can be reconfigured for each production.", "plain_english": "A black box is a plain room painted black for performances. Its stage and seats can be moved into any layout.", "purpose_function": "Its neutral black surfaces and open floor let a company arrange stage and audience freely, supporting experimental and low-cost staging in one adaptable room.", "practical_application": "Technicians rig lights and speakers from an overhead grid and set up seating risers to create the chosen stage layout for each show.", "category": "Venue Type", "related_terms": ["Black-box theater", "Studio theatre", "Flexible seating", "Lighting grid", "Thrust stage"], "common_mistakes": ["Thinking the walls are black only for looks; the matte-black finish also controls stray light and reflections", "Assuming a black box has a fixed stage; the layout is meant to be changed for each production"], "scenario_contexts": ["Setting up an in-the-round seating layout in a university black box", "Rigging a lighting grid in a black box for a small experimental play"]}, "e88e48b4-9636-4d7a-a475-1334ea4b5f42": {"definition": "A theatre venue built as a large, adaptable black-walled room without a permanent stage or fixed seating, allowing the stage-to-audience configuration (end-on, thrust, in-the-round, or traverse) to be arranged differently for each production.", "plain_english": "A black-box theater is a venue that is one big black room. The stage and seats can be set up in many shapes.", "purpose_function": "It gives companies a single reconfigurable venue for varied staging formats, trading a grand fixed auditorium for flexibility, intimacy, and lower cost.", "practical_application": "Staff reconfigure seating risers, the lighting grid, and control positions to match each show's chosen stage format before a run opens.", "category": "Venue Type", "related_terms": ["Black box", "Studio theatre", "Thrust stage", "Theatre-in-the-round", "Flexible seating"], "common_mistakes": ["Confusing a black-box theater with a proscenium theatre, which has a fixed stage and audience relationship", "Underestimating the labour and time needed to reconfigure seating and rigging between formats"], "scenario_contexts": ["A studio black-box theater switching from end-on to in-the-round between productions", "Planning sightlines and rigging for a thrust layout in a black-box theater"]}, "ac99e46c-12f8-4f1a-8105-a52ce3e508ba": {"definition": "A dedicated control or production room in a house of worship, equipped for audio, video, and streaming production, from which worship services are mixed, recorded, and broadcast or streamed to television, radio, or online audiences.", "plain_english": "A broadcast ministry room is a control room in a church. Staff use it to record and stream services to viewers at home.", "purpose_function": "It centralises the audio, video, and streaming gear needed to capture a service and send it to remote audiences, keeping broadcast production separate from the in-room mix.", "practical_application": "A technician in the broadcast ministry room runs the streaming encoder, video switcher, and broadcast audio mix while the front-of-house engineer handles the live room.", "category": "Production Spaces", "related_terms": ["Control room", "Front of house", "Broadcast mix", "Streaming encoder", "House of worship"], "common_mistakes": ["Confusing the broadcast mix with the front-of-house mix; the broadcast feed usually needs its own separate mix", "Assuming the room's monitoring reflects what viewers hear; broadcast and stream levels must be checked on the delivered feed"], "scenario_contexts": ["Streaming a Sunday service to online viewers from a church broadcast ministry room", "Recording a televised worship program from a dedicated broadcast ministry control room"]}, "4820fcbf-62eb-442b-b588-5ccd670d4fde": {"definition": "In venue terms, a performance space or seating format in which the audience is seated at small tables, usually with food and drink service, arranged around or facing a low stage, giving an intimate, informal setting for close-up entertainment.", "plain_english": "Cabaret is a venue setup where people sit at small tables to watch a show. They can eat and drink while performers play close by.", "purpose_function": "It creates an intimate, social atmosphere by seating the audience at tables near a small stage, suiting music, comedy, and variety acts rather than large-scale productions.", "practical_application": "For a cabaret layout, crews set small tables and chairs facing a low stage, then place compact PA and monitors for close, even coverage.", "category": "Seating Layout", "related_terms": ["Cabaret seating", "Supper club", "Thrust stage", "Sightlines", "Capacity"], "common_mistakes": ["Confusing cabaret seating capacity with theatre-row capacity; tables seat far fewer people per square metre", "Placing loud speakers too close to tables, overpowering the intimate, conversational setting"], "scenario_contexts": ["Setting a cabaret table layout in a jazz club for a vocal act", "Planning power and coverage for a cabaret night with table seating and a small stage"]}, "a34e5732-3397-41d7-a24d-7b21328ef079": {"definition": "A dedicated space, room, or system of racks, reels, and hangers where audio, data, and power cables are coiled, labelled, and stored when not in use, keeping them organised, protected, and ready for deployment.", "plain_english": "Cable storage is where a venue keeps its cables when not in use. Coiling and hanging them neatly stops damage and tangles.", "purpose_function": "It keeps cables coiled, labelled, and off the floor so they last longer, stay easy to find, and do not create clutter or trip hazards.", "practical_application": "During load-out, crew coil cables using the over-under method, then hang or reel them in the cable store, sorted by type and length.", "category": "Technical Storage", "related_terms": ["Over-under coiling", "Cable reel", "Multicore", "Load-out", "Amp room"], "common_mistakes": ["Coiling cables tightly around the elbow, which twists the conductors and shortens cable life; use the over-under method", "UNSAFE: Stacking heavy cable reels or coils where they can fall, or blocking an exit route with stored cable"], "scenario_contexts": ["Coiling and racking cables into a dedicated cable store during load-out", "Labelling and hanging multicores in cable storage so they are ready for the next event"]}, "fd56357a-1e62-459d-bdc6-f963a1b611fc": {"definition": "The stage manager's control position from which a performance is 'called' — cues given to technical departments and performers — typically fitted with a prompt copy, cue lights, production intercom, show relay, and paging, and located in the prompt corner, a wing, or a control room with a view of the stage.", "plain_english": "The call desk is the stage manager's control station. From it they give the cues that tell crew and performers what to do.", "purpose_function": "It gives the stage manager one position with the comms, cue lights, and show relay needed to time and trigger every technical and performer cue during a show.", "practical_application": "From the call desk, the stage manager reads the prompt book and calls lighting, sound, and fly cues over comms as the show runs.", "category": "Stage Management", "related_terms": ["Prompt corner", "Cue light", "Prompt book", "Production intercom", "Show relay"], "common_mistakes": ["Confusing the call desk with an operator's console; the stage manager calls cues, the operators execute them", "Placing the call desk without a clear view of the stage or reliable comms and show relay"], "scenario_contexts": ["A stage manager calling a musical's cues over comms from the prompt-corner call desk", "Fitting a call desk with cue lights and intercom during a venue technical fit-up"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"d323bee8-031c-46ae-bd15-dc564705919e": {"definition": "In church architecture, the chancel is the part of a church near the altar, at the liturgical east end beyond the nave, reserved for clergy and often the choir; it may contain the sanctuary around the altar and the choir stalls, and is frequently raised and set apart from the congregation.", "plain_english": "The chancel is the front part of a church around the altar. Clergy and often the choir stay there, apart from the congregation.", "purpose_function": "It sets apart the area for clergy and choir near the altar, and its raised, often reverberant space shapes where worship sound and singing originate.", "practical_application": "For worship audio, technicians place choir and lectern microphones in the chancel and manage its reflections to keep gain below feedback.", "category": "Worship Spaces", "related_terms": ["Nave", "Sanctuary", "Altar", "Choir", "House of worship"], "common_mistakes": ["Confusing the chancel with the nave; the nave holds the congregation, while the chancel holds clergy and choir", "Overlooking chancel reflections and reverberation, which raise feedback risk on choir and lectern microphones"], "scenario_contexts": ["Miking a choir positioned in the chancel of a stone church", "Treating chancel reflections to control feedback during a spoken service"]}, "6db21609-0ebe-4e19-9eef-5050fac4b83a": {"definition": "A small place of Christian worship, either freestanding or a subsidiary room within a larger church or institution such as a hospital, school, airport or funeral home, seating a modest congregation and used for services, prayer or ceremonies.", "plain_english": "A chapel is a small room or building used for worship. It seats fewer people than a full church and often sits inside a bigger building.", "purpose_function": "It provides an intimate, dedicated space for prayer, small services and ceremonies where a full-size sanctuary is unnecessary or unavailable.", "practical_application": "A technician usually fits a chapel with a compact, low-profile speech and playback system, treating its short reverberation and small volume differently from a large sanctuary.", "category": "Worship venue", "related_terms": ["Sanctuary", "Nave", "Church sound booth", "Reverberation time", "Choir loft", "Speech intelligibility"], "common_mistakes": ["Assuming a chapel needs the same large PA as a full church, when a small, even system usually suits its size.", "Overlooking the room's hard reflective surfaces, which raise reverberation and hurt speech clarity.", "Confusing a chapel, a small worship room, with a sanctuary, a church's main worship hall."], "scenario_contexts": ["Installing a compact speech PA in a hospital chapel.", "Micing a wedding ceremony held in a college chapel.", "Setting reverberation-aware EQ for spoken word in a small stone chapel."]}, "e602cb3a-2b6a-47c9-85e1-bf27eeb1ac47": {"definition": "The designated part of a worship space or platform occupied by the singing choir; in traditional churches this is the chancel section between the nave and the altar, while in modern rooms it is the platform zone assigned to the choir.", "plain_english": "The choir area is the spot where the singers stand or sit. In older churches it is near the front, between the seats and the altar.", "purpose_function": "It groups the singers together in one location so they can be seen, directed and covered by microphones as a unified section.", "practical_application": "A technician places choir mics, often overhead or hanging condensers, to cover the choir area evenly and sets monitor coverage for that zone.", "category": "Worship space", "related_terms": ["Choir loft", "Chancel", "Nave", "Choir microphone", "Sanctuary", "Overhead miking"], "common_mistakes": ["Miking individual singers instead of covering the whole choir area with a few overhead mics.", "Placing choir mics too far away, so the area picks up more room reverberation than voice.", "Confusing the choir area, where the singers are, with the congregation seating."], "scenario_contexts": ["Hanging choir microphones above the choir area for a Sunday service.", "Balancing a choir area against a praise band in the mix.", "Setting up floor monitors for singers in the choir area."]}, "c9d5b18f-3b41-4768-a91a-5018e208e5e5": {"definition": "An elevated gallery or balcony, typically at the rear or side of a church and often housing the organ, where the choir is positioned above the main floor.", "plain_english": "A choir loft is a raised balcony where the singers stand. It lifts the choir above the crowd, often at the back near the organ.", "purpose_function": "Raising the choir improves its sightlines to the director, projects sound over the congregation and frees floor space at the front.", "practical_application": "A technician runs mic and monitor lines up to the loft and aims hanging mics from the loft, watching for organ bleed and long cable runs.", "category": "Worship space", "related_terms": ["Choir area", "Balcony", "Pipe organ", "Choir microphone", "Gallery", "Church sound booth"], "common_mistakes": ["Forgetting the extra cable length and signal loss on long runs up to a rear loft.", "UNSAFE: Leaning over or overloading a loft railing while rigging mics instead of using proper fall protection and rated anchor points.", "Letting organ pipes in the loft overpower choir mics because the mics are placed too close to the pipes."], "scenario_contexts": ["Aiming hanging choir mics down from a rear choir loft.", "Coordinating choir loft monitors with a front-of-house praise team.", "Planning cable runs from the stage up to a balcony choir loft."]}, "545bdc77-a2f3-4ea7-a521-919973fb2111": {"definition": "A tiered block of seating rising behind or around the orchestra platform in a concert hall, characteristic of vineyard and surround layouts, provided for a chorus in choral works and often sold as audience seating when no chorus performs.", "plain_english": "A choir terrace is stepped seating that rises behind the stage. A choir sits there for big choral pieces, and it becomes normal audience seats otherwise.", "purpose_function": "It seats a large chorus close to and facing the same way as the orchestra, and adds the wrap-around early reflections typical of terraced halls.", "practical_application": "For choral concerts a technician mics the chorus on the choir terrace and manages the tricky sightlines and reflections of singers seated behind the orchestra.", "category": "Choral seating", "related_terms": ["Vineyard seating", "Choir area", "Early reflection", "Concert platform", "Reverberation time", "Auditorium"], "common_mistakes": ["Assuming the choir terrace is only audience seating and forgetting it must serve a full chorus.", "Miking a terrace chorus from the front and capturing mostly orchestra spill instead of voices.", "Confusing a choir terrace, a concert-hall stepped seating block, with a church choir loft."], "scenario_contexts": ["Micing a symphony chorus seated on the choir terrace behind the orchestra.", "Selling the choir terrace as behind-stage audience seats for an orchestral concert.", "Planning reflection control for singers on a vineyard-hall choir terrace."]}, "af12c244-17bb-4b35-bf54-42d3945ae384": {"definition": "A large communal dressing and preparation room provided for the chorus or ensemble members of a production, offering shared mirrors, counters and costume space with quick access to the stage, as distinct from smaller principal (star) dressing rooms.", "plain_english": "A chorus dressing room is a big shared room where the cast gets ready. Many performers use it at once, unlike the small private rooms for lead actors.", "purpose_function": "It lets many ensemble performers change, apply makeup and warm up together near the stage, using space efficiently for large casts.", "practical_application": "An audio technician fits chorus dressing rooms with a paging and show-relay feed so performers hear the stage and calls while getting ready.", "category": "Backstage space", "related_terms": ["Green room", "Stage manager", "Show relay", "Paging system", "Principal dressing room", "Backstage"], "common_mistakes": ["Forgetting to feed show relay and paging to the chorus dressing room, so the ensemble misses calls.", "UNSAFE: Blocking the dressing-room exit or corridor with costume rails and cases, obstructing the required means of egress.", "Assuming one small room fits a large chorus, when communal space and mirrors must scale to the cast."], "scenario_contexts": ["Wiring show-relay speakers into a chorus dressing room for an opera.", "Setting up paging so the stage manager can call the chorus.", "Managing a large musical's ensemble in a shared chorus dressing room."]}, "8a5f2ded-891e-44b3-8d63-3519bdde460d": {"definition": "The dedicated mix and control position in a house of worship, often a raised or partly enclosed booth at the rear or side of the room, where the front-of-house console, playback and sometimes lighting or video are operated with a view of the platform.", "plain_english": "A church sound booth is the spot where the sound operator works. It holds the mixing board and gives a clear view of the stage.", "purpose_function": "It centralizes the console and operators in one location with good sightlines and representative acoustics, so the mix matches what the congregation hears.", "practical_application": "The operator mixes the service from the booth, so its location and any glass front strongly affect how well the mix translates to the room.", "category": "Mix position", "related_terms": ["Front of house", "Mixing console", "Choir area", "Monitor mix", "Sightline", "House of worship"], "common_mistakes": ["Placing the booth under a balcony or in a corner, where the operator hears an unrepresentative mix.", "Enclosing the booth behind closed glass, so the operator mixes to a sound the congregation never hears.", "UNSAFE: Powering console and gear from daisy-chained power strips instead of properly rated, grounded branch circuits."], "scenario_contexts": ["Mixing a Sunday service from the rear church sound booth.", "Relocating a booth out from under a balcony for a truer mix.", "Training a volunteer to operate the console in the church sound booth."]}, "d778df9c-23ae-4be0-8ea3-a81d97e3a9c1": {"definition": "A performing-arts theater wholly or partly owned or subsidized by a municipality, typically a larger multipurpose venue serving a city with touring shows, resident companies and community events, as opposed to a purely commercial house.", "plain_english": "A civic theater is a theater owned or paid for by a city. It hosts many kinds of shows for the whole community, not just one group.", "purpose_function": "It gives a city a publicly supported venue for professional touring productions, local groups and civic events under shared municipal management.", "practical_application": "A technician at a civic theater supports many incoming acts, so they maintain a flexible house system and adapt patching and rigging for each show.", "category": "Performance venue", "related_terms": ["Community theater", "Auditorium", "Proscenium", "House system", "Road show", "Multipurpose hall"], "common_mistakes": ["Confusing a civic theater, city-funded and often professional or touring, with a community theater run by local amateurs.", "Assuming its house system is fixed, when a multipurpose civic venue must reconfigure for each act.", "Ignoring the wide range of events, from concerts to conferences, a civic theater must serve."], "scenario_contexts": ["Patching a touring band into a civic theater's house system.", "Reconfiguring a civic theater from a play to a graduation ceremony.", "Coordinating a local dance recital in a municipally run civic theater."]}, "3bd48286-3d45-4ed7-acab-38b3ca97663f": {"definition": "A small commercial live-entertainment space such as a nightclub or music club, typically with a low stage, standing or mixed floor, bar service and a modest fixed or portable PA, hosting bands or DJs for close-range audiences under assembly-occupancy limits.", "plain_english": "A club venue is a small bar or nightclub where bands or DJs play. The crowd stands close to a low stage, and the room holds far fewer people than a big theater.", "purpose_function": "It offers an intimate, high-energy space for live music or DJ sets with the audience close to the performers and integrated bar service.", "practical_application": "A technician in a club runs a compact PA and small monitor rig in a loud, reflective room, fighting feedback and stage volume in tight quarters.", "category": "Performance venue", "related_terms": ["Stage monitor", "Feedback", "PA system", "Front of house", "Occupant load", "Nightclub"], "common_mistakes": ["UNSAFE: Exceeding the room's posted occupant load or blocking exits and exit signage to fit more patrons.", "UNSAFE: Ignoring hearing protection and safe noise-exposure limits in a small, extremely loud room.", "Overpowering a small reflective room with an oversized PA, causing feedback and a harsh mix."], "scenario_contexts": ["Setting up a compact PA and monitors for a band in a small-capacity club.", "Ringing out monitors to control feedback on a tight club stage.", "Checking that exits stay clear and occupancy is not exceeded during a sold-out club show."]}, "d067a2b3-fdbd-4103-87de-f99063d05008": {"definition": "A noncommercial, locally based theater, usually run by volunteer or amateur participants, and the often modest or multipurpose venue it uses to stage productions for and by the local community.", "plain_english": "A community theater is a local group of volunteers who put on plays. It usually performs in a small or shared space for people in the area.", "purpose_function": "It provides an accessible outlet for local, mostly amateur performers and audiences, emphasizing participation over commercial profit.", "practical_application": "A technician at a community theater often works with a small budget and volunteer crew, so they keep systems simple, robust and easy to operate.", "category": "Performance venue", "related_terms": ["Civic theater", "Auditorium", "Proscenium", "House system", "Black box theater", "Multipurpose hall"], "common_mistakes": ["Confusing community theater, a local amateur group, with civic theater, which is city-funded and often professional.", "Specifying gear too complex for volunteer operators to run reliably.", "Assuming a professional-grade budget and crew rather than the limited resources common to community theater."], "scenario_contexts": ["Designing a simple, volunteer-friendly sound system for a community theater.", "Running sound for an amateur musical at a local community theater.", "Training volunteers to operate the console at a community theater."]}, "a58d6348-4dd2-4507-9025-4aa3f0a4d10e": {"definition": "A large auditorium designed primarily for the unamplified performance of orchestral and other acoustic music, in which architectural form, volume, and surface treatment are shaped to support natural reverberation, loudness, and clarity for the audience. Its performance is characterised by room-acoustic parameters such as reverberation time, early-decay time, and clarity, measured per ISO 3382.", "plain_english": "A concert hall is a big room built for live music without microphones. Its shape and hard surfaces let the sound of an orchestra fill the room and reach every seat.", "purpose_function": "It provides an acoustic environment tuned so that acoustic ensembles project naturally to the audience, with the right balance of reverberation, loudness, and clarity, and without electronic reinforcement.", "practical_application": "A technician in a concert hall respects its live acoustics, placing recording or reinforcement microphones to capture the natural room sound rather than fight it.", "category": "Performance Venue", "related_terms": ["Concert platform", "Reverberation time", "Auditorium", "Acoustic shell", "Early reflections", "Concertmaster position"], "common_mistakes": ["Assuming a hall's long reverberation can be corrected with EQ instead of acoustic design or absorption", "Treating a live concert hall like a dead studio and adding heavy reinforcement that muddies the natural sound", "Confusing a concert hall built for acoustic music with a multipurpose or amplified arena"], "scenario_contexts": ["Miking a symphony orchestra for a live recording in a concert hall", "Deciding whether a spoken-word event needs speech reinforcement in a highly reverberant hall", "Measuring reverberation time to document a hall's acoustic condition"]}, "9e47efa9-81b1-4d71-a709-4a92149986ae": {"definition": "The raised performance area of a concert hall on which musicians sit or stand, typically an open platform without a proscenium or fly tower, often fitted with tiered risers and a reflective canopy or orchestra shell to aid ensemble hearing and projection to the audience.", "plain_english": "The concert platform is the raised stage where the musicians sit or stand. It is open to the room, and often has step-like risers so players can see, hear, and be heard.", "purpose_function": "It groups the performers together as an ensemble and, with reflectors and risers, helps them hear one another while projecting sound out to the house.", "practical_application": "Crew set the platform with risers, chairs, stands, and an acoustic shell, then place spot or area microphones for reinforcement or recording.", "category": "Performance Spaces", "related_terms": ["Concert hall", "Acoustic shell", "Riser", "Concertmaster position", "Orchestra pit", "Auditorium"], "common_mistakes": ["Confusing a concert platform with a proscenium stage that has wings and a fly tower", "Forgetting that risers change sightlines and microphone placement for the back rows", "Positioning an acoustic shell so it no longer projects sound toward the audience"], "scenario_contexts": ["Setting risers and chairs for an orchestra on a concert platform", "Positioning an orchestra shell to reflect sound to the audience", "Rigging overhead microphones above the platform for a live broadcast"]}, "935a07e3-dea3-4bb8-9689-3eeee785a723": {"definition": "The seating location of the concertmaster (the orchestral leader, or principal first violin) at the front of the first-violin section, immediately to the conductor's left and nearest the audience; the reference point from which the orchestra tunes and takes ensemble cues.", "plain_english": "This is where the lead violinist, called the concertmaster, sits. It is at the front left of the orchestra, next to the conductor, and the players tune to this spot.", "purpose_function": "Placing the leader here gives a fixed, visible point for tuning and for relaying the conductor's intentions to the string sections.", "practical_application": "For recording or reinforcement, engineers reference this position when placing the first-violin spot microphone and when planning the orchestra layout on stage.", "category": "Stage geography", "related_terms": ["Concert platform", "Concert hall", "Spot microphone", "Orchestra pit", "Riser"], "common_mistakes": ["Confusing the concertmaster, who is a player, with the conductor", "Assuming the concertmaster sits on the conductor's right instead of the left", "Placing the first-violin spot microphone without accounting for the leader's forward position"], "scenario_contexts": ["Drawing an orchestra seating plan for a stage layout", "Placing a spot microphone on the first violins near the leader", "Coordinating the tuning A with the leader before a performance"]}, "ec2c53da-3ba8-4ee0-bb7e-765b54990897": {"definition": "An enclosed operating room, usually at the rear of the auditorium with a viewing window to the stage, from which lighting, sound, and/or projection are controlled during a performance.", "plain_english": "A control booth is a small enclosed room, usually at the back of the audience. Operators sit here behind a window and run the lighting, sound, or video during the show.", "purpose_function": "It gives operators a clear sightline to the stage and a fixed, protected place for control consoles, kept separate from the audience.", "practical_application": "Lighting and projection operators run the show from the control booth, though a sound engineer often mixes from an open front-of-house position to hear the true room sound.", "category": "Technical Spaces", "related_terms": ["Front-of-house position", "Followspot booth", "Auditorium", "Sound booth", "Proscenium"], "common_mistakes": ["UNSAFE: Blocking or overcrowding a booth exit so operators cannot evacuate quickly in an emergency", "Mixing front-of-house sound from a closed booth, which hides the real room sound from the engineer", "Assuming the booth window passes sound accurately when the glass changes tone and level"], "scenario_contexts": ["Running lighting cues from the control booth during a play", "Operating projection from a rear booth", "Deciding whether to mix sound in the booth or at an open house position"]}, "629b643a-6ae8-4059-9c6d-5de35d91f2a9": {"definition": "A production workroom where stage costumes are designed, built, fitted, altered, laundered, and maintained, typically equipped with sewing and cutting stations, storage, laundry/dye facilities, and fitting areas.", "plain_english": "The costume shop is the workroom where a show's clothes are made and repaired. It has sewing machines, cutting tables, and space to fit costumes to the actors.", "purpose_function": "It supplies and maintains all the costumes a production needs, and provides a dedicated space for fittings and repairs during the run.", "practical_application": "Audio crew coordinate with the costume shop to fit and conceal wireless body microphones and transmitter pouches in performers' costumes.", "category": "Production Spaces", "related_terms": ["Wardrobe", "Dressing room", "Green room", "Wireless microphone", "Crew room"], "common_mistakes": ["Confusing the costume shop, where costumes are built, with wardrobe or dressing rooms, where they are worn and stored during shows", "Fitting a body microphone without involving the costume shop, which causes rustle or visible packs", "UNSAFE: Leaving irons, steamers, or dye chemicals unattended, creating burn or fire hazards"], "scenario_contexts": ["Rigging a lavalier microphone into a costume with the wardrobe team", "Building costumes ahead of a production in the shop", "Making quick costume repairs between performances"]}, "f4636c2e-7e89-4cc3-8664-84470bc65898": {"definition": "A backstage staff room set aside for the technical crew to rest, take breaks, store personal belongings, and receive briefings between calls; a welfare and support space rather than a performance or production area.", "plain_english": "The crew room is a backstage break room for the technical staff. Crew rest here, keep their things, and get briefed between jobs during a show.", "purpose_function": "It provides the technical crew a dedicated welfare space so they can rest and regroup without cluttering working areas backstage.", "practical_application": "Between scene changes or during long runs, sound and stage crew use the crew room for breaks, meal relief, and pre-show briefings.", "category": "Facility Spaces", "related_terms": ["Green room", "Dressing room", "Crossover corridor", "Costume shop", "Control booth"], "common_mistakes": ["Confusing the crew room, for technical staff, with the green room, a shared space often used by performers", "Using the crew room to store live equipment instead of as a welfare and break space", "Placing a crew room so poorly that overflow blocks backstage walkways"], "scenario_contexts": ["Holding a pre-show crew briefing", "Taking a meal break during a long load-in", "Storing crew personal gear away from the stage"]}, "39bc6dc7-0de4-4b84-be38-d7242c0fd296": {"definition": "An aisle running transversely across an auditorium, perpendicular to the seating rows, that connects the ends of the longitudinal (row) aisles and channels occupants toward the exits; a means-of-egress component regulated for minimum width and capacity under assembly-occupancy codes (IBC Chapter 10 / Section 1029 and NFPA 101 Assembly Occupancies).", "plain_english": "A cross aisle is a walkway that runs sideways across the seating. It links the up-and-down aisles and guides the audience toward the exits, so it must stay clear.", "purpose_function": "It ties the seating aisles together and adds exit capacity, letting an audience leave quickly and safely in an emergency.", "practical_application": "Technicians keep cross aisles clear of cable, cases, and loudspeakers, and never park gear that narrows the required egress width.", "category": "Audience Circulation", "related_terms": ["Aisle", "Means of egress", "Exit sign", "Auditorium", "Vomitory"], "common_mistakes": ["UNSAFE: Running cable, placing cases, or parking gear in a cross aisle, which reduces the required egress width and blocks escape", "UNSAFE: Assuming a cross aisle can be narrower than code allows because it looks wide enough", "Confusing a transverse cross aisle with the longitudinal aisles that run between seat rows"], "scenario_contexts": ["Planning FOH cable runs so they never cross an audience cross aisle at floor level", "Checking that a temporary seating layout keeps cross aisles clear for egress", "Inspecting exit paths before doors open to the public"]}, "b297fec1-d8e5-45f4-9c84-0131bc0e85e0": {"definition": "A backstage passage that lets performers and crew move from one side of the stage to the other, out of the audience's sight and hearing, either behind the upstage wall or backdrop or via a route around or beneath the auditorium.", "plain_english": "A crossover is a hidden backstage passage. It lets actors and crew get from one side of the stage to the other. They do not have to cross the stage or be seen.", "purpose_function": "It allows quick, unseen moves from stage-left to stage-right and back, which many entrances, exits, and scene changes require.", "practical_application": "Crew keep the crossover clear of cable and scenery, and keep it dark and quiet so passing traffic never leaks light or noise to the audience.", "category": "Backstage Spaces", "related_terms": ["Wings", "Crew room", "Proscenium", "Concert platform", "Control booth"], "common_mistakes": ["Blocking the crossover with stored scenery, cases, or cable, stranding performers on the wrong side", "Allowing light or noise from the crossover to spill onto the stage or into the house", "Confusing a backstage crossover corridor with a public cross aisle in the auditorium"], "scenario_contexts": ["Planning a fast character crossover during a blackout", "Keeping the crossover clear during a scene change", "Routing a quiet cable path that does not obstruct the crossover"]}, "89822ba9-8bc2-48db-912d-fe2ea8a82022": {"definition": "A small, acoustically isolated room, usually glazed and located at the rear or side of a worship space, cinema, or auditorium, from which parents with infants or restless children can see and hear the event through a window and a relayed loudspeaker feed without disturbing the main audience.", "plain_english": "A cry room is a small soundproofed room with a window at the back of a church or theatre. Parents with crying babies can watch and hear the event there without disturbing others.", "purpose_function": "It lets families with young children stay part of the event while keeping their noise from reaching the main audience.", "practical_application": "Audio crew feed a cry room from a dedicated loudspeaker zone so the room gets clear program sound behind its glass and closed door.", "category": "Audience Spaces", "related_terms": ["Cry-room feed", "Zone feed", "Auditorium", "Sound isolation", "Distributed loudspeaker"], "common_mistakes": ["Forgetting to send a dedicated audio feed, so the isolated room has no usable sound", "Assuming the glass passes enough sound, when the room actually needs its own loudspeaker", "Confusing a cry room with a plain nursery that has no view or feed of the event"], "scenario_contexts": ["Setting a loudspeaker zone level for a church cry room", "Commissioning the cry-room feed during a system check", "Isolating a rear room so infant noise does not reach the congregation"]}, "58ed8a7d-200e-4fa6-b20c-4fd2b40b57d7": {"definition": "In stage geography, CS abbreviates Center Stage, the central acting area of the performance space, midway between the wings and between the downstage edge and the upstage wall. All such position references are given from the standing performer's viewpoint facing the audience.", "plain_english": "CS is short for Center Stage. It is the middle of the acting area. Performers face the audience, so all stage positions are named from the actor's point of view.", "purpose_function": "It gives directors, performers, and crew a shared, unambiguous label for a fixed zone of the stage, so blocking, focus, and equipment placement can be communicated precisely.", "practical_application": "A technician uses CS to spot a center microphone, focus a follow spot, or mark a set piece on the stage plan and confirm its spike-tape position on the deck.", "category": "Stage Geography", "related_terms": ["DSC", "DSL", "DSR", "Downstage", "Upstage", "Stage left"], "common_mistakes": ["Reading stage-left and stage-right from the audience's viewpoint instead of the performer's, which reverses them.", "Confusing center stage with the auditorium's center line or the front-of-house mix position.", "Assuming center stage is a single point rather than a zone spanning the middle of the acting area."], "scenario_contexts": ["Marking spike tape for a vocalist's center-stage microphone during a blocking rehearsal.", "A stage manager cueing a performer to move to center stage.", "Placing a center-stage wedge monitor referenced from the stage plan."]}, "ddadb541-3f0e-49e4-bd89-20d4ee78abd5": {"definition": "A dance club (nightclub) is a commercial entertainment venue built around a dance floor, a high-output sound system, and lighting, where recorded or live music is presented, usually by a DJ from a dedicated booth. In venue design it is an assembly occupancy engineered for high sound-pressure levels and heavy low-frequency energy rather than critical listening.", "plain_english": "A dance club is a nightspot built around a dance floor. It has a loud sound system, lighting, and usually a DJ. The room is designed for high volume and strong bass, not quiet listening.", "purpose_function": "It provides a space designed for social dancing to amplified music, so its sound, lighting, and layout are engineered for high levels, strong low end, and crowd movement.", "practical_application": "A technician tunes and level-limits the club's system, positions subs and fills around the dance floor, and protects patrons' hearing and the equipment from sustained high output.", "category": "Performance Venue", "related_terms": ["DJ booth", "Dance floor", "Subwoofer array", "House sound system", "Hearing exposure limit"], "common_mistakes": ["UNSAFE: Running the system at damaging levels for long periods without hearing protection or level limiting; sustained high sound-pressure levels risk permanent hearing loss under recognised occupational exposure limits.", "UNSAFE: Blocking or obstructing marked exits and egress paths with gear, cabling, or crowding, which violates assembly-occupancy life-safety codes.", "Treating a club like a concert hall and chasing flat, critical-listening response instead of robust, high-headroom low end.", "Underestimating how a packed, absorptive crowd changes the room's acoustics compared with an empty soundcheck."], "scenario_contexts": ["Commissioning and tuning a nightclub's main and subwoofer system before opening.", "Setting a system limiter to protect hearing and comply with venue sound limits.", "Positioning the DJ booth and monitors so the DJ can hear over the dance floor."]}, "dfe92ce6-8291-4dbd-ab27-b0e8578b5bcd": {"definition": "A delay-tower position is a downfield location in a large audience area, typically on a ground-supported tower or mast, where supplementary loudspeakers are placed and electronically time-delayed to re-align with the sound from the main system, extending intelligible coverage to distant listeners. The delay is set so the reinforcement supports the main PA and preserves front-to-back localization rather than smearing it.", "plain_english": "A delay tower is a stand holding extra speakers partway back in a big crowd. Its sound is delayed by a fraction of a second. That way it lines up with the main speakers instead of causing an echo.", "purpose_function": "It keeps sound loud and intelligible for distant listeners in large or outdoor venues, and time-delaying it preserves clarity and the impression that the sound still comes from the stage.", "practical_application": "A system tech measures the distance from the main array to the tower, sets the delay time (about 2.9 ms per metre, or 0.88 ms per foot, often plus a small offset), then aligns level and timing with an analyzer during soundcheck.", "category": "Loudspeaker Position", "related_terms": ["Delay speaker", "Time alignment", "Line array", "Speed of sound", "Coverage pattern"], "common_mistakes": ["Omitting the extra precedence-effect offset that keeps the audience localizing the sound to the stage.", "Aligning to the wrong main source or measuring the distance inaccurately, which smears clarity.", "UNSAFE: Rigging or ballasting the tower inadequately for wind and load; ground-supported outdoor structures must be assembled, guyed or ballasted, and rated per the manufacturer and recognised temporary-structure standards to prevent collapse.", "Overlooking that delay speakers add level that can push total exposure beyond safe limits without limiting."], "scenario_contexts": ["Deploying delay towers halfway back on a large outdoor festival field.", "Time-aligning a delay position to the main line array with a measurement system during soundcheck.", "Adding delay fills under a deep balcony the main array cannot reach."]}, "25d8ea0e-00f3-412a-8b6e-ae90fcb3621a": {"definition": "A DJ booth is a dedicated station or enclosure in a club or event space from which a disc jockey operates playback and mixing gear (turntables or media players, a DJ mixer, monitors, and headphones) to control the music program. It is positioned, and often partly isolated, so the DJ can monitor cleanly and cue tracks over the dance-floor level.", "plain_english": "A DJ booth is the DJ's workstation in a club. It holds the decks, mixer, headphones, and monitor speakers. It is placed so the DJ can hear the music clearly over the loud dance floor.", "purpose_function": "It gives the DJ a fixed, protected place to store and operate equipment and to monitor accurately, so mixes and cues stay tight despite high levels on the floor.", "practical_application": "A technician wires the booth's mixer, media players, monitors, and headphone feed, sets booth monitor level separately from the mains, and manages grounding to avoid hum.", "category": "Venue Feature", "related_terms": ["Dance club", "DJ mixer", "Stage monitor", "Turntable", "Ground loop"], "common_mistakes": ["Feeding the booth monitor at the same level as the mains, so the DJ cannot judge cues accurately.", "UNSAFE: Leaving loose cabling and gear around the booth that creates trip hazards or blocks egress in a crowded venue.", "Ignoring ground-loop hum between the booth's playback gear and the house system.", "Placing the booth where the DJ hears mostly dance-floor reflections instead of a true monitor mix."], "scenario_contexts": ["Installing and wiring a permanent DJ booth in a nightclub.", "Setting up a temporary DJ booth and monitor for a mobile or event gig.", "Troubleshooting hum caused by ground loops between booth players and the house system."]}, "bef004ee-6162-41d7-95dd-63eceeb45c85": {"definition": "A dressing room is a backstage support space where performers change costume, apply makeup, warm up, and wait before and during a performance. In venue design it is part of the back-of-house accommodation, fitted with mirrors, lighting, and seating, and typically served by a show-relay/paging feed so occupants can follow the performance and hear calls.", "plain_english": "A dressing room is a backstage room for performers. They change clothes, do makeup, and get ready there. It usually has mirrors, lights, and a speaker that plays the show's audio so they know their cues.", "purpose_function": "It gives performers a private, equipped place to prepare and wait, and it carries a show-relay and paging feed so backstage staff can call them to the stage on cue.", "practical_application": "A technician installs and checks the dressing-room show-relay and paging speaker, the program-monitor feed, and any intercom, so calls and the on-stage audio reach performers reliably.", "category": "Backstage Space", "related_terms": ["Green room", "Backstage", "Show relay", "Paging system", "Intercom"], "common_mistakes": ["Forgetting the dressing-room show-relay and paging feed, so performers miss their calls.", "UNSAFE: Blocking corridors, doors, or exits from dressing rooms with cases and racks, obstructing the egress required by life-safety codes.", "Setting show-relay level too low to hear over conversation, or so high it disturbs preparation."], "scenario_contexts": ["Commissioning show-relay and paging speakers in the dressing rooms before opening night.", "A stage manager paging performers from the prompt desk to their dressing rooms.", "Running an intercom or monitor feed for a quick-change area near the stage."]}, "1e66b44c-3811-45a7-82a7-7ac304c056dc": {"definition": "DSC abbreviates Downstage Center, the acting position at the front-center of the stage, nearest the audience along the stage centerline. 'Downstage' denotes the area toward the audience, a convention inherited from historically raked stages that sloped down toward the front.", "plain_english": "DSC means Downstage Center. It is the front-middle of the stage, closest to the audience. The word 'downstage' comes from old sloped stages that tilted down toward the crowd.", "purpose_function": "It labels the most prominent, audience-nearest spot on the centerline, letting staff place performers, microphones, and set pieces there without ambiguity.", "practical_application": "A tech references DSC to set a lead vocal microphone, position a front monitor, or spike a solo performer's mark at the front of the deck.", "category": "Stage Geography", "related_terms": ["CS", "DSL", "DSR", "Downstage", "Upstage", "Proscenium line"], "common_mistakes": ["Thinking 'downstage' means the back of the stage; it is actually the edge nearest the audience.", "Reversing left and right by using the audience's viewpoint rather than the performer's.", "Confusing the stage centerline with the auditorium's center line."], "scenario_contexts": ["Placing a lead singer's microphone at downstage center for a concert.", "A lighting tech focusing a special on the downstage-center solo position.", "Spiking a downstage-center set piece on the deck."]}, "13b4092d-7d73-45d7-bb02-31524f6bdc8f": {"definition": "DSL abbreviates Downstage Left, the front area of the stage toward the audience and to the performer's left, which is the audience's right. Left and right in stage geography are always taken from the standing performer's viewpoint facing the house.", "plain_english": "DSL means Downstage Left. It is the front of the stage, on the performer's left side. Remember: left and right always follow the performer's view, not the audience's.", "purpose_function": "It pinpoints one front quadrant of the stage from the performer's orientation, giving crew an unambiguous location for performers, microphones, and gear.", "practical_application": "A technician uses DSL to place a monitor wedge, run a mic cable, or spike a performer's entrance mark on the audience-right front corner of the stage.", "category": "Stage Geography", "related_terms": ["DSR", "DSC", "CS", "Stage left", "Downstage", "Upstage"], "common_mistakes": ["Confusing stage left with the audience's left; stage left is the audience's right.", "Assuming downstage-left is at the rear; downstage is toward the audience.", "Reading DSL as 'digital subscriber line'; in stage geography it means downstage left."], "scenario_contexts": ["Positioning a side-fill or wedge monitor at downstage left.", "A stage manager cueing a performer to enter from downstage left.", "Labeling channels on a stage plan for a downstage-left performer."]}, "5699f1c7-ced5-497b-9c2d-e0f7376beaaf": {"definition": "DSR abbreviates Downstage Right, the front area of the stage toward the audience and to the performer's right, which is the audience's left. As with all stage directions, right is taken from the standing performer's viewpoint facing the audience.", "plain_english": "DSR means Downstage Right. It is the front of the stage, on the performer's right side. From the audience, that spot is on their left. Right always follows the performer's view.", "purpose_function": "It pinpoints one front quadrant of the stage from the performer's orientation, giving crew an unambiguous location for performers, microphones, and gear.", "practical_application": "A technician uses DSR to place a monitor wedge, run a mic cable, or spike a performer's entrance mark on the audience-left front corner of the stage.", "category": "Stage Geography", "related_terms": ["DSL", "DSC", "CS", "Stage right", "Downstage", "Upstage"], "common_mistakes": ["Confusing stage right with the audience's right; stage right is the audience's left.", "Assuming downstage-right is at the rear; downstage is toward the audience.", "Reversing left and right by using the audience's viewpoint rather than the performer's."], "scenario_contexts": ["Positioning a side-fill or wedge monitor at downstage right.", "A stage manager cueing a performer to enter from downstage right.", "Labeling channels on a stage plan for a downstage-right performer."]}, "db30bd24-5477-486a-827f-9e1f702ae708": {"definition": "An equipment marshalling area is a designated space, often near the loading dock or get-in, where gear, cases, and staging equipment are received, sorted, staged, and organized before being moved to their working positions, and where they are collected again for load-out. It keeps the flow of equipment orderly and separate from active performance and audience areas.", "plain_english": "A marshalling area is a spot near the loading dock where gear is sorted and staged. Crews organize cases here before moving them onstage. At the end, gear comes back here to be packed for load-out.", "purpose_function": "It gives the crew a controlled place to stage and track equipment during load-in and load-out, so the get-in stays clear and setup and strike run efficiently and safely.", "practical_application": "A technician stages amp racks, cases, and cabling in the marshalling area, checks them against the packing list, and moves them to position in the planned setup order.", "category": "Load-in Space", "related_terms": ["Loading dock", "Get-in", "Load-out", "Backstage", "Road case"], "common_mistakes": ["UNSAFE: Staging cases and cabling so they block fire exits, egress routes, or the loading-dock path, violating life-safety requirements.", "UNSAFE: Stacking road cases too high or unstably, or leaving trip hazards, in a busy staging area.", "Failing to stage gear in setup order, forcing extra handling and slowing the get-in.", "Losing track of cases without checking them against a packing or inventory list."], "scenario_contexts": ["Staging incoming trucked gear in a marshalling area during a festival load-in.", "Organizing cases by department before moving them to stage positions.", "Consolidating equipment in the marshalling area for a fast, tracked load-out."]}, "fd63f32b-7526-4e24-8884-34480326af48": {"definition": "A dedicated room or area in a venue set aside for the secure, organised storage of technical equipment - loudspeakers, cabling, microphones, stands, cases, and spares - when not in use, kept accessible and clear of performance and egress spaces.", "plain_english": "Equipment storage is a room or area for keeping gear when it is not in use. It keeps speakers, cables, and stands safe, tidy, and easy to find.", "purpose_function": "It protects valuable gear from damage and theft and keeps working areas and exit routes clear by giving equipment a fixed home.", "practical_application": "Technicians return cased gear, cable, and stands to storage after a show, labelling and organising items so they can be found quickly next time.", "category": "Technical Spaces", "related_terms": ["Freight elevator", "Holding area", "Loading dock", "Crew room", "Load-in door"], "common_mistakes": ["UNSAFE: Storing gear or cases in corridors, stairwells, or exit routes instead of the storage room, blocking the means of egress", "Stacking heavy cases or loudspeakers unstably so they can topple onto someone", "Failing to label or inventory stored equipment, so items are lost or damaged"], "scenario_contexts": ["Returning cased loudspeakers and cable to storage after a load-out", "Organising a store so exit paths and walkways stay clear", "Retrieving spare microphones from storage before a show"]}, "354897ff-8db7-431c-8aa7-7c3fe57d100c": {"definition": "A large multipurpose room within a church or place of worship, used for meals, meetings, classes, and social gatherings rather than for the main worship service; typically a flat-floor space with hard, reflective surfaces and a small stage or platform served by a portable or modest installed sound system.", "plain_english": "A fellowship hall is a big all-purpose room in a church. People use it for meals, meetings, and events, not for the main service.", "purpose_function": "It gives a congregation a flexible space for community activities and overflow, kept separate from the sanctuary used for worship.", "practical_application": "Technicians often set up a portable PA and microphones in a fellowship hall for events, working around a flat floor and hard, reflective surfaces that harm speech clarity.", "category": "Worship Spaces", "related_terms": ["Sanctuary", "Narthex", "Nave", "Cry room", "Multipurpose room"], "common_mistakes": ["Confusing the fellowship hall with the sanctuary, the room used for the main worship service", "Ignoring the hard, reflective surfaces of a flat multipurpose hall, which cause echo and poor speech clarity", "Assuming the room's installed sound is adequate for a large event without checking coverage"], "scenario_contexts": ["Setting up a portable PA for a church supper in the fellowship hall", "Mixing speech for a meeting in a reverberant multipurpose room", "Running a projector and audio for a class held outside the sanctuary"]}, "c89e7829-c9e9-4fa1-a0e7-2c2692c655f3": {"definition": "A reference line marked on the stage floor directly beneath the travel path of the proscenium fire safety curtain, showing where the descending curtain lands; the zone along this line must be kept clear of scenery, equipment, and cable so the curtain can fall fully and seal the proscenium opening in a fire.", "plain_english": "The fire-curtain line is a mark on the stage floor. It shows where the theatre fire curtain drops down. This spot must stay empty so the curtain can seal off the stage in a fire.", "purpose_function": "It marks the drop path of the fire safety curtain so crew keep it clear, letting the curtain close completely and separate the stage from the audience during a fire.", "practical_application": "Technicians never store scenery, cases, or run cable across the fire-curtain line, and they confirm it is clear before every performance.", "category": "Stage geography", "related_terms": ["Fire curtain", "Proscenium", "Plaster line", "Smoke pocket", "Fly rail"], "common_mistakes": ["UNSAFE: Storing scenery, cases, or running cable on or across the fire-curtain line, which can stop the curtain from fully closing in a fire", "UNSAFE: Leaving the fire safety curtain tied off, blocked, or disabled because it is rarely used", "Confusing the fire-curtain line with the plaster line or setting line used for scenic layout"], "scenario_contexts": ["Checking the fire-curtain line is clear during a pre-show safety inspection", "Planning scenery placement so nothing lands on the curtain's drop path", "Routing stage cable so it never crosses the fire-curtain line"]}, "e2515c88-a76a-47e6-bfaf-0e67dd1dfc9c": {"definition": "A performance space with a neutral, open plan - typically a black box - whose stage-to-audience relationship is not fixed, allowing the seating, staging, and technical elements to be reconfigured (end-stage, thrust, in-the-round, or promenade) for each production.", "plain_english": "A flexible theatre is an open, plain room, often painted black. The stage and seats can be moved around, so each show can set them up in a new way.", "purpose_function": "It lets a company change the shape of the stage and audience for each production, instead of being locked into one fixed layout.", "practical_application": "Technicians rig lighting and loudspeakers from an overhead grid and re-place them for each configuration, since there is no fixed stage or front-of-house position.", "category": "Performance Venue", "related_terms": ["Black box theater", "Thrust stage", "Theater in the round", "Proscenium", "Tension grid"], "common_mistakes": ["Confusing a flexible theatre with a fixed proscenium house that has one permanent stage position", "Assuming loudspeaker and control positions from a previous layout will work after the room is reconfigured", "UNSAFE: Reconfiguring the seating without confirming exits and aisle widths still meet egress code"], "scenario_contexts": ["Re-rigging lighting and speakers for an in-the-round staging", "Planning a sound system with no fixed front-of-house position", "Reconfiguring seating from thrust to end-stage between productions"]}, "e5c934f5-525e-4b4f-a8ea-e5e43a1f31a8": {"definition": "The operating position of a theatrical flying (rigging) system - a rail carrying the rope locks and lock rail of a counterweight or hemp line-set system - from which an operator raises and lowers battens, scenery, lighting, and drapery above the stage; located at stage level or on an elevated fly gallery, usually to one side of the stage.", "plain_english": "The fly rail is where an operator works the ropes and locks. These raise and lower scenery and lights above the stage. It sits at the side of the stage.", "purpose_function": "It gathers the rope locks and controls of the flying system into one operating position so a trained operator can move loads over the stage in a controlled, safe way.", "practical_application": "The fly operator stands at the fly rail to release locks and haul line sets, moving lighting bars, scenery, and drapes in and out on cue.", "category": "Rigging Systems", "related_terms": ["Counterweight system", "Line set", "Batten", "Fly gallery", "Grid"], "common_mistakes": ["UNSAFE: Releasing a rope lock on an unbalanced line set, letting the batten run away and drop or fly up", "UNSAFE: Standing under a moving batten or in the load path instead of clear of the fly system", "UNSAFE: Operating the fly rail without training, a load check, or clear communication with the deck", "Confusing the fly rail operating position with the grid or with the battens themselves"], "scenario_contexts": ["Flying in a lighting bar from the fly rail on a cue", "Balancing counterweight before moving a loaded line set", "Coordinating a scenery move between the fly rail and the stage deck"]}, "43095b6b-4845-47f7-b6e4-e212ef3e391f": {"definition": "An elevated operating position - often a small enclosed room or open platform high at the rear or side of the auditorium - from which followspot operators run followspots, throwing a controllable beam that tracks a moving performer.", "plain_english": "A followspot booth is a high spot at the back or side of the audience. Operators stand here to aim spotlights that follow a performer around the stage.", "purpose_function": "It gives followspot operators a high, clear sightline to the whole stage so their beams can track performers accurately.", "practical_application": "Followspot operators work from the booth on headset, picking up and following performers on cue as called by the stage manager.", "category": "Technical Spaces", "related_terms": ["Followspot", "Control booth", "Front-of-house position", "Auditorium", "Lighting position"], "common_mistakes": ["Confusing the followspot booth with the control booth, where sound, lighting, and projection are run", "Placing a booth with a poor sightline, so operators cannot see parts of the stage", "UNSAFE: Blocking or overcrowding the booth so operators cannot exit quickly in an emergency"], "scenario_contexts": ["Running a followspot to track a lead singer during a concert", "Coordinating followspot pickups over headset with the stage manager", "Positioning operators for full stage coverage from a rear booth"]}, "ab9d39d9-7613-4b3f-8a1d-f6d81746d648": {"definition": "A power elevator designed and rated to carry heavy goods and equipment rather than passengers, used in venues to move staging, scenery, cases, and technical gear between load-in level and the stage, storage, or upper floors; built and inspected to ASME A17.1/CSA B44 with a posted rated load capacity.", "plain_english": "A freight elevator is a strong lift built to carry heavy gear, not people. Crews use it to move cases, scenery, and equipment between floors.", "purpose_function": "It moves heavy production equipment safely between levels, sparing crews from carrying loads up stairs and protecting both the gear and people.", "practical_application": "Crew move flightcased loudspeakers, consoles, and scenery on the freight elevator during load-in and load-out, staying within its posted weight limit.", "category": "Access and Circulation", "related_terms": ["Loading dock", "Load-in door", "Equipment storage", "Holding area", "Get-in"], "common_mistakes": ["UNSAFE: Overloading the freight elevator beyond its posted rated capacity", "UNSAFE: Riding a freight elevator that is not rated or permitted to carry passengers", "Blocking the elevator doors or landing with staged cases, stalling the load-in"], "scenario_contexts": ["Moving flightcased gear from the loading dock to stage level", "Checking a case load against the elevator's rated capacity", "Scheduling load-in traffic around a single freight elevator"]}, "bc358fa0-7ee1-4e60-a460-8e46ae65c968": {"definition": "The row of audience seating nearest the stage or performance area; the closest listening position to the performers and, in reinforced systems, often the loudest for stage sound and the earliest arrival for direct loudspeaker coverage, so it commonly needs front-fill loudspeakers to fill the gap below a main array.", "plain_english": "The front row is the line of seats closest to the stage. It is the nearest spot to the performers, so it often gets the loudest, earliest sound.", "purpose_function": "It provides the closest seats to the performance and serves as a near-field reference when designing loudspeaker coverage and setting level.", "practical_application": "When designing coverage, technicians check the front row for excessive level and for gaps below the main arrays, often adding front-fill loudspeakers.", "category": "Audience Spaces", "related_terms": ["Front fill", "Auditorium", "Orchestra pit", "Cross aisle", "Coverage"], "common_mistakes": ["Ignoring the front row when a main array shoots over it, leaving those seats with weak or uneven sound", "Overpowering the front row with too much level from nearby stage or fill loudspeakers", "Assuming the front row is the best seat acoustically, when it can have poor balance and imaging"], "scenario_contexts": ["Adding front-fill speakers to cover the front rows under a flown array", "Checking front-row level so it is not painfully loud", "Setting a mix reference while weighing the nearest and farthest seats"]}, "c0ae4eb2-efeb-4328-8e1a-cebca9f4b8fa": {"definition": "A designated space in or near a venue where performers, crew, participants, or equipment are marshalled and wait before moving to the stage, set, or their next position, allowing large groups or gear to be staged in an orderly way without crowding working or performance areas.", "plain_english": "A holding area is a waiting space near the stage or set. Performers, crew, or gear wait here in order before they are needed.", "purpose_function": "It keeps people and equipment organised and out of the way until they are needed, so backstage and stage areas stay clear and safe.", "practical_application": "Wireless-mic'd performers wait in a holding area, where audio crew can run final microphone checks before they go on.", "category": "Production Spaces", "related_terms": ["Green room", "Wings", "Crossover corridor", "Dressing room", "Equipment storage"], "common_mistakes": ["Confusing a holding area, a temporary waiting space, with a green room used for longer relaxation", "UNSAFE: Overcrowding a holding area or letting it block an exit route or corridor", "Placing the holding area too far from the stage, causing missed or late entrances"], "scenario_contexts": ["Running final wireless microphone checks on performers in a holding area", "Marshalling a large chorus before an entrance", "Staging equipment in a holding area during a fast changeover"]}, "f4a39b5b-2b76-4237-96a5-4de657494157": {"definition": "A staging arrangement in which the performance area is surrounded by audience seating on all sides, with performers entering and exiting through aisles or vomitories that pass between the seating blocks; also called arena staging or theatre-in-the-round.", "plain_english": "In the round means the stage sits in the middle with the audience seated all around it. Performers enter through gaps in the seating, so everyone gets a close view.", "purpose_function": "It puts the audience close to the action on every side for an intimate, shared feel, but it removes the fixed backdrop and wing space of an end-on stage.", "practical_application": "Sound and lighting crew must cover every viewing angle and hide loudspeakers, cable, and fixtures overhead, because there are no wings or back wall to conceal them.", "category": "Stage Configuration", "related_terms": ["Arena stage", "Thrust stage", "Proscenium", "Vomitory", "Wings", "Auditorium"], "common_mistakes": ["Confusing theatre-in-the-round with a thrust stage, which still has an audience-free back wall", "Placing loudspeakers or scenery that block sightlines for one side of the audience", "UNSAFE: Running cable across the vomitory entrances that the audience and performers use to enter and exit"], "scenario_contexts": ["Designing an overhead loudspeaker rig for an in-the-round concert", "Hiding microphone cable on an arena stage that has no wings", "Planning performer entrances through the seating vomitories"]}, "61c13785-fe98-4c3e-bc11-a050e829b327": {"definition": "A low, often portable platform placed on a stage to raise a musician, section, or instrument above the surrounding stage level, improving sightlines, ensemble hearing, and the projection of that instrument to the audience.", "plain_english": "An instrument riser is a low platform that lifts a player or instrument above the stage floor. It helps players see and hear each other and be seen by the crowd.", "purpose_function": "It elevates specific performers, such as a drummer or a brass section, so they are visible over players in front and can hear and project better.", "practical_application": "Crew build risers to a set height, then run and dress the drummer's or section's microphone and monitor cables neatly up onto the platform.", "category": "Staging", "related_terms": ["Riser", "Concert platform", "Stage monitor", "Backline", "Spot microphone"], "common_mistakes": ["Confusing a low instrument riser with a full stage or concert platform", "UNSAFE: Overloading a riser or leaving gaps and unsecured edges, creating a trip or collapse hazard for performers", "Forgetting that raising an instrument changes microphone and monitor placement"], "scenario_contexts": ["Setting a drum riser and dressing its cables before a show", "Raising a brass section on risers for better projection", "Adjusting monitor sends after a player moves onto a riser"]}, "dd343a39-e8f8-42e8-bcd8-552026a1602f": {"definition": "A dedicated backstage or ancillary room used to store musical instruments securely when not in use, often climate-controlled and fitted with racks, cases, or lockers to protect instruments from damage, theft, and swings in temperature and humidity.", "plain_english": "This is a backstage room for keeping musical instruments safe when they are not being played. It is often kept at a steady temperature so the instruments are not damaged.", "purpose_function": "It protects valuable instruments from theft, physical damage, and harmful changes in temperature and humidity between rehearsals and performances.", "practical_application": "Technicians store and sign out instruments and related gear here, keeping them organised and protected until they are needed on stage.", "category": "Storage Spaces", "related_terms": ["Instrument riser", "Backstage", "Loading corridor", "Crew room", "Green room"], "common_mistakes": ["Confusing an instrument storage room with a general prop or scenery store", "Ignoring humidity and temperature control, which can warp or crack wooden instruments", "UNSAFE: Blocking a corridor or exit with instrument cases pulled from the store"], "scenario_contexts": ["Storing an orchestra's instruments overnight between concerts", "Keeping a venue's backline gear secure between events", "Signing instruments in and out of a controlled store"]}}$ape$::jsonb)) d WHERE g.id=d.id;
COMMIT;
